-- 경기도의회 행정사무감사 회의록(경기연구원 관련) 이관 데이터 (자동 생성: tools/import_audit.py)
-- 게시판 코드 audit. 여러 번 실행해도 중복되지 않습니다.
insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
create unique index if not exists posts_legacy_idx on public.posts ((attachments->>'legacy_id')) where attachments ? 'legacy_id';
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2001.11.26. 월요일] 경기개발연구원, 감사관실 — 기획위원회 2001년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 2001년도 행정사무감사(2001. 11. 21. ~ 2001. 11. 30.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4588" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2001년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제4호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원, 감사관실
</p>
<p><hr /></p>
<p>일  시 : 2001년 11월 26일(월)
</p>
<p>장  소 : 경기개발연구원회의실, 기획위원회
</p>
<p><hr /></p>
<p class=''ar''>(10시38분 감사개시)
</p>
<p><b>○ 위원장 김강선 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의하여 경기개발연구원에 대한 2001년도 행정사무감사 실시를 선언합니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분!  그리고 원장님을 비롯한 연구원 임직원 여러분!  안녕하십니까?  기획위원회 감사위원장 김강선입니다.  오늘은 우리 위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  연일 계속되는 감사일정으로 노고가 많으신 위원님들께 심심한 위로와 감사의 말씀을 드리며 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것인 만큼 심도있는 감사가 이루어질 수 있도록 위원 여러분의 적극적인 의정활동을 당부드립니다.  아울러 수감준비를 위하여 애쓰신 연구원 임직원 여러분께도 감사와 격려의 말씀을 드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기개발연구원장 및 실부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2001년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알려드립니다.  그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (기   립)
</p>
<p style="padding-left:1.2em">  먼저 증인 출석여부를 확인하겠습니다.  경기개발연구원장 나오셨습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 사무처장 나왔습니까? 
</p>
<p><b>○ 사무처장 유지준 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 기획조정실장 나왔습니까? 
</p>
<p><b>○ 기획조정실장 조응래 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 도시경영연구부장 나왔습니까? 
</p>
<p><b>○ 도시경영연구부장 김동성 </b> 네, 나왔습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 도시지역계획부장 나왔습니까? 
</p>
<p><b>○ 도시지역계획부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 지우석 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 환경연구부장 나왔습니까? 
</p>
<p><b>○ 환경연구부장 이양주 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 지식산업연구부장 나왔습니까? 
</p>
<p><b>○ 지식산업연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 사회개발연구부장 나왔습니까? 
</p>
<p><b>○ 사회개발연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 다음은 선서의 요령을 설명드리겠습니다.  선서는 증인을 대표해서 경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 오른손만 들어주시면 되겠습니다.  그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항, 경기도의회행정감사및조사에관한조례 제2조의 규정에 의하여 소관업무에 대한 2001년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4제5항과 경기도의회행정사무감사및조사에관한조례 제18조 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로를 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''>2001년 11월 26일 증인 경기개발연구원장 노춘희.
</p>
<p><b>○ 위원장 김강선 </b> 자리에 앉아주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (착   석)
</p>
<p style="padding-left:1.2em">  그러면 경기개발연구원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 위원장님!  감사합니다.  존경하는 김강선 위원장님과 위원님 여러분!  바쁘신 의정일정에도 우리 연구원을 찾아주시어 금년도 저희 업무추진사항과 내년도 연구사업계획을 보고드리게 된 것을 기쁘게 생각합니다.  보고에 앞서 저희 연구원의 간부를 소개드리고 유인물 중심으로 보고를 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 조응래 기조실장님을 소개올립니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 유지준 사무처장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 김동성 도시경영연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이상대 도시지역계획부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 지우석 교통정책연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 이양주 환경연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음은 김군수 지식산업연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  끝으로 김흥식 사회개발연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  소개를 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  지금부터 저희 연구원의 주요업무보고를 드리겠습니다.  먼저 배부해 드린 유인물을 바탕으로 일반현황, 재정운용, 2001년도 연구사업 추진사항, 2002년 연구사업계획, 2000년 행정사무감사 지적사항 조치결과를 보고드리는 순서로 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 유인물 1페이지가 되겠습니다.  저희 연구원은 ''96년에 개원하여 이제 개원한 지 6년이 되었으며 여러 위원님들의 성원과 특별한 애정으로 저희 연구원이 계속 발전하고 있습니다.  연구원의 주요기능으로서는 도정의 비전제시와 31개 시·군의 개발계획 및 관리운영연구와 우리나라 지식기반 중심지역 형성을 위한 정책개발을 위하여 기획조정실을 중심으로 도시경영연구부 등 6개 연구부가 경기도 수요에 맞게 다양하고 깊이 있는 전문적인 연구를 수행하고 있습니다.  보다 자세한 사항은 배부해 드린 유인물을 참고해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  2페이지가 되겠습니다.  본원의 기구는 1실 1처 6연구부로 구성돼 있습니다.  현재 인력은 박사급 연구직이 27명 포함하여 44명이 재직하고 있습니다.  참고로 연구직은 해외학위취득이 59% 16명, 국내학위가 41% 11명입니다.  전공분야별로는 도시 및 지역계획 관련분야가 10명, 환경분야 7명, 행정분야 3명, 경제과학분야 3명이 계십니다.  그 외에 관광사회개발분야로 나누어져 있습니다.  연구에 필요한 전문분야를 골고루 갖추고 있어 어느 정도 종합적인 연구업무를 수행하고 있습니다.  부족한 전문수요분야는 초빙연구원이나 비상임연구원 등 외부전문인력을 위촉하고 있으며 특히 전반적인 연구의 자문을 위하여 분야별 460명의 인력풀을 별도로 관리하고 있어 보다 더 충실한 연구결과를 생산하고 있습니다.   3페이지가 되겠습니다.  3페이지는 시설 및 물자현황이므로 유인물을 참고해 주시면 대단히 감사하겠습니다. 
</p>
<p style="padding-left:1.2em">  4페이지가 되겠습니다.  4페이지 재정운용현황에 대하여 보고드리면 먼저 올해 일반회계 예산규모는 전년도 대비 14억 4,400만원이 증가한 83억 9,900만원입니다.  주요 세입재원으로는 전입금이 11억 2,000만원, 수탁용역이 4억 9,000만원, 도비보조가 46억 4,000만원, 환급금이 3억 7,000만원, 이월금이 17억 1,000만원으로 돼 있습니다. 
</p>
<p style="padding-left:1.2em">  주요세출항목으로는 연구사업비가 전체 60%인 50억원입니다.  청사구입비 12억원을 포함하여 청사유지관리비가 17%인 14억 2,000만원이 됩니다.  기관운영비는 10억 9,000만원이 되겠습니다.  예산집행에 있어 충실한 연구가 수행될 수 있는 여건지원에 중심을 두어 내실있는 운영을 할 수 있도록 최선을 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 5페이지, 기금운용에 관한 운용사항을 말씀드리겠습니다.  총 기금조정액은 216억, 그중 64%인 137억원이 도에서, 나머지 19%인 39억원을 시·군에서 출연하였으며 나머지는 2개 은행의 출연금과 자체적립금으로 구성돼 있음을 말씀드립니다.  기금예치현황을 보게 되면 우선적으로 기금의 안정성을 감안하고 이자율 및 예금의 종류를 고려하여 분산예치를 원칙으로 운영하고 있습니다.  표에서 보시는 바와 같이 기금 214억원, 4개 은행 16종의 상품으로 적립돼 있으며 앞으로도 기금의 안정을 최우선으로 고려하여 관리하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  이어서 6페이지부터 7페이지까지에는 2001년도 연구사업 추진현황 중 연구사업의 성과를 보고드리겠습니다.  먼저 도정수요에 능동적으로 대응하여 실천성이 높은 정책대안을 개발하기 위하여 과밀부담금 확대부과에 따른 대응방안을 수립하고 광역교통시설부담금의 지역간 차등부과적용기준을 마련하여 정책방향에 기여를 하였습니다.  그리고 지방경제살리기특별조치법안의 합리적인 대체방안을 제시하였고 세계도자기엑스포 운영지표 및 사후 활용방안과 경기도광역도시계획 수립 및 도로정비방안을 제시했으며 경기2020비전과 전략 수정계획을 수립 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 수도권의 새로운 환경변화에 따른 남북협력과 서해안시대를 선도하는 정책을 수립하기 위하여 경기도접경지역계획을 수립하여 도의 정책방향을 제시하였고 경기도의 서해안전략 개발계획과 남북경협에 대비한 경기북부지역의 개발전략 등을 수립 중에 있으며 경기도를 포함한 서해안 개발을 위해 서해안시대의 전개·개발방향에 관한 제1회 서해안포럼을 저희 연구원과 인천, 충남, 광주, 전남, 전북 경제사회연구원이 공동으로 개최하였으며 향후 3, 4차례 추가 개최할 예정입니다. 
</p>
<p style="padding-left:1.2em">  또한 경기도는 제4차 국토종합개발계획에 2020년까지 지식기반 중심지역으로 지정된 바 지식기반산업육성전략을 개발·연구하기 위하여 벤처기업 유치 촉진방안을 제시하였고 판교신도시 개발정책을 위한 TF팀을 구성·운영하여 판교개발에 관한 논거를 마련하였으며 판교지역의 R&D단지 조성방향에 대한 연구를 수행 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 대외 협력강화를 위한 연구원 위상을 제고하기 위하여 도, 시·군은 물론 감사원, 건설교통부, 환경부 등의 중앙부처로부터 지방재정운용의 건전성과 효율성 분석기법 개발 등의 수탁과제를 수행한 바 있습니다.  또한 지식정보교류 활성화를 위한 지식의 시너지 효과와 연구역량을 강화하고 경기도의 경쟁력있는 정책개발을 도모하기 위한 관내 대학 중 경원대학, 아주대학, 명지대학, 경희대학과 학·연 네트워크 협정을 체결한 바 있습니다.  그리고 재경부의 지방균형발전법에 대응하기 위해 지방경제회생 및 균형발전을 위한 정책토론회를 한국도시행정학회와 개최한 바 있으며 경기도와 시책이 중앙정부에 반영하도록 여론화되는 데 크게 기여하였습니다. 
</p>
<p style="padding-left:1.2em">  향후에도 경기북부지역 개발 등 주요 도정현황을 주제로 한 전문가, 주민초청 정책토론회를 개최할 예정입니다.  한편 2001년 11월 10일까지 약 16억원의 신규수탁과제 22건을 수행하는 등 적극적인 수주활동을 통하여 연구원의 운영비를 확충한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 8페이지에서는 2001년의 연구사업총괄표가 되겠습니다만 유인물로 참고해 주시면 대단히 감사하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 각 연구사업의 세부추진사항을 9페이지부터 17페이지까지 간략하게 보고드리겠습니다.  먼저 9페이지의 기본연구과제는 부서장의 도정지원활동 강화 및 경기2020비전과 전략수정, 보완과제의 원활한 참여를 위해 당초 계획보다 6과제가 축소된 21과제를 수행하였습니다.  도로유지관리비의 합리적인 배분방안 등 13개 과제를 완료하였고 지방정부의 정책주도권에 관한 연구 등 8과제를 연구 중에 있음을 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 11페이지까지는 수탁연구과제 추진사항을 전년도에서 이월된 21개 과제와 금년도 신규로 위탁받은 22개 과제를 포함한 43건 중 경기도접경지역계획수립 등 20건을 완료했습니다.  그리고 경기도서해안전략적개발계획 등 23건을 현재 추진 중에 있다는 것을 말씀드립니다.  그리고 12페이지 정책연구과제는 전년도에 이월된 2건과 금년도에 신규로 요청받은 25건을 포함한 27건 중 지방경제살리기특별조치법에 관한 합리적인 대체법안연구 등 15건을 완료했습니다.  그리고 중앙권한의 지방이양확대 연구 등 8건을 수행하고 있음을 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  13페이지에는 위탁연구과제로서 수도권 집중으로 인한 외부효과, 추정분석 등 11개의 위탁연구 중에서 영국의 지역정책방향과 우리나라의 수도권 정책에 관한 시사점 등 2건을 완료했습니다.  나머지 9건은 금년 안에 완료할 예정입니다.  다음 지역연구과제는 연천군지역 연구는 완료했고 남양주지역 연구는 금년 12월말까지 완료할 예정입니다. 
</p>
<p style="padding-left:1.2em">  이어서 14페이지의 정기간행물발간사업은 연구원이 발행하고 있는 경기연구 등 7건 중 경기논단 등 6건은 정기적으로 발행하고 있으며 경기연구는 연말에 발간할 예정입니다.  특히 알기쉬운 경제지표는 경기도 및 정보제공지로서 금년 8월에 창간하였음을 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  다음 15페이지의 번역사업은 도의 정책개발에 도움이 될 수 있는 외국의 주요도서 중 환경가치, 경제정책 그리고 지속가능성을 완료하였고 일본수도권백서를 비롯한 5종의 번역사업을 연말까지 완료할 예정입니다.  그리고 정책세미나 및 워크숍을 현재까지 11건, 세미나 1건, 포럼 2건을 개최한 바 있으며 자세한 내용은 16페이지의 개최사항을 참조해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 GIS연구사업은 인력과 장비를 확보하고 우리 연구원내 DB를 구축하고 있으며 경기도 GIS구축 기본계획연구서는 연말까지 수행하고 이를 근거로 한 2002년도의 웹 GIS 2단계사업 등을 수행하여 도정 및 연구활동을 지원할 계획으로 있습니다.
</p>
<p style="padding-left:1.2em">  다음 17페이지 연구사업 연도별 수행현황 유인물로 참조해 주시면 감사하겠습니다.
</p>
<p style="padding-left:1.2em">  18페이지에서부터 30페이지까지의 2002년도 연구사업계획을 행정사무감사 유인물로 제출하였으며 간략히 보고드리도록 하겠습니다.  내년도의 연구사업계획의 기본방향은 먼저 남북교류협력시대, 지식기반사회, 서해안시대 도래에 따른 관련 정책연구개발기능을 계속 강화하고 장기간의 연구가 필요한 핵심과제를 수행하고 연구기간의 적정성을 확보하여 연구의 질을 제고할 계획입니다.  그리고 도정수요에 탄력적, 효율적인 대응을 위한 도 실무부서 및 의회 상임위원회 간담회를 개최하고 현안과제를 적극적으로 수행할 계획입니다.  또한 보다 실효성있는 연구결과 도출을 위한 GIS 등 연구인프라를 확충할 것이며 대내외 협력 활성화를 통한 연구원 위상을 강화하는 데 계속 노력하겠습니다.  연구자문위원의 기능 강화를 통해 경쟁력있는 도정정책을 개발할 수 있도록 하겠습니다.  한편 연구사업결과의 평가를 통한 실효성을 확보할 수 있도록 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  이러한 기본방향의 구현을 위한 금년도 연구사업계획을 총괄적으로 말씀드리면 우선 연구과제사업은 올해와 같이 총 100건을 수행할 계획입니다.  기본과제는 내부 워크숍을 통해 도출된 과제를 경기도청과 제2청의 각 실·국 및 도의회사무처와 협의한 후 선정한 과제를 연구원 1인당 1과제인 26과제를 수행할 계획입니다.  수탁연구과제는 내년도의 신규수탁연구과제를 부서당 3과제인 총 21과제를 수행하고 전년도에 이월된 과제 11건을 포함하여 약 30건을 수행할 예정입니다. 
</p>
<p style="padding-left:1.2em">  위탁연구과제는 학·연 네트워크협정대학의 공동연구 5건, 학회 등 6건의 아웃소싱을 통하여 연구원의 외부 노하우를 활용할 계획이며, 경기도로부터 긴급요청 및 시의성이 있는 과제와 연구원이 중요하다고 판단되어 자체 추진하는 정책연구과제는 올해와 같이 부서당 7과제 내외 총 40과제를 수행할 계획입니다. 
</p>
<p style="padding-left:1.2em">  지역연구과제는 특정지역이 발생하고 있는 경기도내의 시·군을 대상으로 6개월에 1건씩 2건을 추진할 예정입니다.  또한 정기간행물사업은 올해 7종의 간행물 중 기업경기조사를 경기도 경제활동과 전망에 포함하여 발간하며 경기 이코노미를 월간, 계간으로 축소하여 발간하고 나머지 경기연구 1회, 경기논단 4회, KRI 뉴스레터 12회, 알기쉬운 경제지표 12건을 올해 발행할 계획입니다.  알기쉬운 경기도 경제지표는 작년도 격년으로 발간해서 연구원내의 책자로 발간할 예정으로 있습니다.
</p>
<p style="padding-left:1.2em">  그리고 연구도정사업은 경기도정에 도움이 될 수 있는 최신 외국도서 5종 번역사업을 추진하고 당면문제 및 학술적 성격의 대내외적 여론 선도적 사업으로 13회 정책세미나와 워크숍 등을 추진할 계획입니다.  특히 경기도 지역정보 및 지리정보체계구축을 지원하여 지역정보체계의 응용개발을 위한 정보기술의 도입과 활용기법을 연구하고 경기도 공간정보 구축과 공급 및 활용을 위한 GIS팀을 계속 운영할 예정입니다.   2002년도의 구체적인 세부사업계획은 배부해 드린 유인물 19페이지부터 30페이지까지를 참고하여 주시면 대단히 감사하겠습니다. 
</p>
<p style="padding-left:1.2em">  끝으로 31페이지 2000년도 행정사무감사 처리요구사항 조치결과를 보고드리겠습니다.  지난 2000년 11월 23일 행정사무감사시 처리요구사항은 5건이었습니다.  현재까지 4건은 조치완료되었고 1건은 2002년도 기본연구과제로 수행할 계획임을 말씀드립니다.  구체적인 조치결과는 배부해 드린 유인물 37페이지를 참고해 주시면 대단히 감사하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 2001년도 주요업무보고를 모두 마치겠습니다.  대단히 감사합니다.
</p>
<p><br /></p>
<p>(업무보고서는 끝에 실음)
</p>
<p><br /></p>
<p><b>○ 위원장 김강선 </b> 경기개발연구원장님 수고하셨습니다.  이어서 감사 질의순서가 되겠습니다.  감사의 원활한 진행을 위하여 질의·답변은 일괄질의후 일괄답변하는 것으로 진행하도록 하겠습니다.  그럼 질의하실 위원께서는 거수로 신청하여 주시기 바랍니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 일괄질의 일괄답변이요?  일문일답이 아니고?
</p>
<p><b>○ 김효정 위원 </b> 일문일답으로 해야지.
</p>
<p><b>○ 위원장 김강선 </b> 일괄질의하고 일괄답변하고 보충질의하고 이렇게…….
</p>
<p><b>○ 윤동욱 위원 </b> 그럴 시간이 될까요?
</p>
<p><b>○ 위원장 김강선 </b> 한 20분만 그렇게 달라고 하셔서, 답변준비를 위해서.
</p>
<p><b>○ 윤동욱 위원 </b> 그냥 일문일답으로 해서 종결을 짓는 게 나을 것 같은데요.
</p>
<p><b>○ 노시범 위원 </b> 일문일답으로 하되 원장께서 답변 못하시는 부분은 실무선에서 하는게 낫지 않겠어요?
</p>
<p><b>○ 위원장 김강선 </b> 그러면 위원님들의 의견에 따라 질의·답변은 일문일답 식으로 진행하도록 하겠습니다.  질의하실 위원께서는 거수로 신청하여 주시기 바랍니다.  유영록 위원 질의하시기 바랍니다. 
</p>
<p><b>○ 유영록 위원 </b> 유영록 위원입니다.  현재 정원이 57명으로 돼 있는데 현원은 44명이시거든요?  연구부서 이런 부서는 상당히 정원에 못 미치고 있는데 그 이유가 왜 그러신지 말씀해 주시고요.  그 다음에 초빙연구원하고 관계돼서, 그래서 초빙연구원이 있기 때문에 현원을 적게 잡으신 건지 거기에 대해서 말씀해 주시고요.  그 다음에 수탁용역사업수입이…….
</p>
<p><b>○ 위원장 김강선 </b> 아니, 일문일답이니까요.  답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 위원님이 지적해 주신 사항은 저희들이 고민하는 분야입니다, 질의 잘 해 주셨는데.  저희가 계선조직이 아니기 때문에 계선조직에 관한 것은 규정에 의해서 모집을 그때그때 필요에 의해서 공채를 할 수 있습니다만 이게 연구직이기 때문에 연구의 질이나 여러 가지 성품이나 이런 것을 측정해서 뽑으려고 몇 번씩, 신문에 공고를 세 번씩 내고 공고해서 뽑습니다.  뽑는데 저희들이 바로, 죄송합니다만 제품을 바로 쓸 수 있는 제품이 있어야 되는데 수는 많은데 그 수가 저희들이 쓸만한 제품이 아니기 때문에 그것이 계속 연기되고 있는 겁니다.  그래서 저희가 초빙연구원으로, 그러면 우리 구미에 맞는 상품이 금방 없으니까 어떤 식으로 해서든지 우리가 훈련을 시켜서라도 그것을 쓸만한 제품을 만들어야 되지 않느냐.  그래서 초빙연구원제도가 있는 겁니다. 
</p>
<p><b>○ 유영록 위원 </b> 그러면 초빙연구원은 향후 경기개발연구원에서 연구원으로 하려는 그런…….
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 가능성이 있는 분들을 쓰고 있는 거지요.  저희에 접근할 수 있는.
</p>
<p><b>○ 유영록 위원 </b> 그래서 초빙연구원이 상당히 많은 부분을 차지하는 거군요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것뿐만 아니라 초빙연구원이 늘어나는 것은 저희가 6개부가 있습니다만 경기도 수요라는 것이 엄청나게 다양하기 때문에 박사님을 확보하기가 어렵습니다.  정규직으로 전부 월급을 주고.
</p>
<p style="padding-left:1.2em">  그래서 그때그때 필요에 의해서 밖에 있는 분들을 초빙해서 3개월이면 3개월, 6개월이면 6개월 아웃소싱을 해서 보고서를 받아서 운영하고 있기 때문에 또한 초빙 연구원 수가 많이 있습니다.
</p>
<p><b>○ 유영록 위원 </b> 알겠습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그 다음 수탁과제를 말씀하셨는데.
</p>
<p><b>○ 유영록 위원 </b> 수탁용역사업 수입, 2001년도 수입지출 내역을 보면 4억 9,500만원으로 되어 있는데 지금 경기도에서 위탁하는 것도 용역비를 받나요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 받는 것이 있습니다. 
</p>
<p><b>○ 유영록 위원 </b> 그런데 올 업무보고하신 것 보면 수탁연구과제 43건에 약 56억원이라고 되어 있는데 이게 ''99년 이월과제, 2000년 이월과제 있고 신규과제가 있는데 이중에서도 경기도의 일선 시·군이나 또 경기도에서 요청한 것도 있는데 경기도에서 요청한 것은 용역비 없이 요청한 것도 많이 있나요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그런 건 없습니다.  용역비가 대부분 장기과제는 용역비가 있고 단기과제는 용역비가 없습니다.  수시로 문의한 것이라든지 자문받는 것은 없지만 정책과제라는 것이 있어 정책과제예산을 세우게 됩니다.  그래서 매년 한 가지씩 기본적으로 정책과제 외에 하는 일이 그와 같은 수탁과제 내용이 되겠습니다.  그런데 31개 시·군에서 요구하는 것을 저희들이 다 수용 못하는 이유는 아까 말씀드린대로 저희들의 능력이나 여러 가지 공간이나 사람, 활동하려면 그런 정기적인 사람이 없기 때문에 외부에 있는 전문가를 초빙해서 해결하고 있습니다. 
</p>
<p><b>○ 유영록 위원 </b> 잘 알겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 수고하셨습니다.  김효정 위원 질의하시기 바랍니다.
</p>
<p><b>○ 김효정 위원 </b> 김효정 위원입니다.  우선 기금에 대해서 질의하겠습니다.  업무보고 4페이지, 5페이지에 보면 기금조성이 214억원인데 현재 214억원이 있다는 얘기겠죠?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그렇습니다. 
</p>
<p><b>○ 김효정 위원 </b> 원래 목표는 얼마까지 하려 했던 목표입니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 목표는 원래 제가 오기 전에 잡아놓은 것이 370억원, 약 400억원정도 잡아놨었는데 그때 이자율이 낮아지고 그래서 지금 214억원도 결국은 이자율 때문에, 아마 이자율이 높았을 때 400억원정도 잡은 것이 그걸 가지고 운영비를 쓸 수 있지 않겠나 해서 그렇게 잡아놨던 것 같습니다. 
</p>
<p><b>○ 김효정 위원 </b> 그래서 그것이 변경됐습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 아직도 그거는 지금 진행중에 있는 겁니다. 
</p>
<p><b>○ 김효정 위원 </b> 400억원을 목표로 기금을 조성해 나가고 관리해 나가고 있는 도중이라는 얘기죠?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 김효정 위원 </b> 그런데 기금조성된 내용을 보니까 ''98년도에 경기도에서 50억원이 들어오고는 그뒤에는 자체 적립으로만 되어 가고 있는 겁니까?  그게 사실입니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네, 저희들이 수탁사업에서 벌어가지고 적립하고 있습니다.  
</p>
<p><b>○ 김효정 위원 </b> 그런데 보니까 그 이자수입 중에서 8억원은 적립했고 11억 400만원을 전입시켜서 쓰셨는데 그렇게 되다 보면 이 기금 목표를 달성하기는 막연한 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그러니까 현재 IMF 이후에 이자율이 낮아져서 적립금가지고 도저히 안 되고 또 기금을 더 받아내기도 서로 어려운 입장이고 기금을 내겠다는 사람도 없고.
</p>
<p><b>○ 김효정 위원 </b> 그러니까 본 위원이 지금 질의하고자 하는 내용은 결국 도비보조 46억 4,400만원을 받아가지고 연구비로, 거의 연구비하고 그 액수가 맞아떨어지니까 결국 연구비는 도비보조를 받아서 하고 있다고 볼 수 있겠네요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 김효정 위원 </b> 그렇게 볼 수 있다면 이 기금이라는 당초의 목적이 지금 훼손되고 있고 기금을 할 이유가 없어지는 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그렇지는 않습니다.  이 연구원이라는 것은 우선 펀딩이 기초이기 때문에 자체…….
</p>
<p><b>○ 김효정 위원 </b> 방금 말씀하시기를 IMF 이후에 금리가 낮아져 가지고 기금이 400억원 목표가 달성된다 하더라도 그 이자 가지고 자체운영은 도저히 불가능하다는 것으로 예측한다 이런 얘기 아닙니까?  그렇다면 기금을 세울 이유가 없다는 이유와 마찬가지네요.  결국은 도비보조 46억 4,400만원이 됐든 50억원이 됐든 30억원이 됐든도비보조를 받아가지고 연구할 수밖에 없는 형편이다.  그렇게 보는 거죠?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그렇기 때문에 그 기금계획이 새로 이루어져야 된다고 저는 봅니다. 
</p>
<p><b>○ 김효정 위원 </b> 본 위원도 같은 생각입니다.  그래서 원장님 생각이 그러신가 하고 질의해 보는 건데 이 기금 자체를 경기도에 다 반납해 버리고 아예 경기도에서 추경으로 연구원을 관리하는, 보조하는 그런 방향으로 가야지 기금은 기금대로 갖다 묵혀놓고 또 예산은 해마다 연구비로 지급해야 하고 이것은 경제적인 관리 모순입니다.  그래서 경기도 자체에서 기획위원회에서 이 예산을 세울 때 기금을 차라리 회수해라.  경기도에서 회수해서 경기도에서 기금을 어떻게 관리가 되든 하고 경기개발연구원에 대한 연구용역 연구비는 지원을 46억원이 됐든 50억원이 됐든 그때그때 필요한 대로 예산 세워서 줘야 될 것이 아니냐 하는 것이 본 위원의 생각인데 어떻습니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그래서 IMF 때문에 국가가 구조조정을 한 것과 마찬가지로 원래는 이게 없을 때 제가 와 보니까 시·군에서 기금을 받았습니다.  그래서 시·군에서 기금을 받아가지고 형성된 것인데 그때 당시 이자만 가지고 운영할 수 있을 것으로 생각하고 세웠던 것 같아요.  그런데 상황이 바뀌었으니까 아까 말씀하신대로 저희가 이것을 앞으로 운영하려면 기금을 가지고 운영하든지 그렇지 않으면 보조금만 가지고 운영하든지…….
</p>
<p><b>○ 김효정 위원 </b> 그렇지.  둘 중에 하나가 돼야 되거든요.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 또 한 가지 있습니다.  자율적으로 경영하든지 그래서 자율적으로 경영할 수 있는 법을 만들었습니다.  시·도연구원법입니다.  조례가 아닙니다.  법에 의해서 할 수 있는 문을 열어놨기 때문에 세 가지 중에서 어느 것으로 저희들이 연구를 해야 되지 않겠느냐.  그때 여러 위원님께서 도와주셔야 합니다. 
</p>
<p><b>○ 김효정 위원 </b> 무언가 어떤 새로운 방법으로 개발해서 운영방침을 바꿔야지 본 위원이 생각할 때 214억원이라는 기금을 놔두고 거기에서 이자가 발생되기는 19억400만원정도, 20억원정도 되는 것 같은데 8억원만 적립시키고 기금쪽으로 보내고 11억 400만원은 일반회계로 돌려서 쓴 것인데 그렇다면 기금은 수백 년이 가야 아마 400억원이 되지 않을까, 앞으로 수십 년 해도 어려운 얘기이고 그렇다면 기금조성의 계획은 백지화시키고 기금을 반납하든지 어떻게 해서 백지화시키고 자체운영계획을 새로 세워야겠다는 것이 본 위원의 지적입니다.  그렇게만 아시고 좋은 방법으로 개선책을 연구해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 고맙습니다.
</p>
<p><b>○ 김효정 위원 </b> 또 한 가지 말씀드릴 것은 이것은 자료를 보시면 되겠습니다.  감사요구자료의 44페이지 본 위원이 요구했던 자료를 참고하시면 됩니다.  2000년도에 기본연구과제 25건, 정책연구과제가 23건, 수탁연구가 28건해서 76건의 연구과제를 하셨고 2001년도 현재까지 기본과제 21건, 정책연구 24건, 수탁연구 18건, 지역연구과제2건 해서 65건을 하셨는데 연간 대략 70여건의 연구과제를 소화하신다는 얘기입니다. 그런데 지금 6개의 연구부가 있고 연구직은 27명인데 현 연구부 인원은 24명이라고 보고하신 것 같은데 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 김효정 위원 </b> 지금 25분의 연구하시는 박사님들이 이 과제를 다 소화시키시는 거죠?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.  
</p>
<p><b>○ 김효정 위원 </b> 본 위원이 생각할 때에는 제가 모자라서 그런지 몰라도 박사님들이 아무리 머리가 좋아도 25명이 1년에 70여건의 연구과제를 풀어낸다는 것은 꼭 누에고치에서 명주실 뽑듯 막 뽑아내는 것 같고 거미가 거미줄 뽑듯 막 뽑아내는 것 같은 느낌이 있습니다.  한 사람이 한 과제를 갖고 1년내 연구해도 과연 질적으로 연구가 효과적인, 정말 가치있는 연구가 되겠느냐 하는데 25명이 70여건을 하신다는 것은 최소한도 2∼3건 정도를 그냥 산술적으로 계산했을 때.  이것은 그래서 문제가 있지 않나 보고 또 보면 기본연구과제라는 게 과연 기본적으로 연구해야 될 과제인가, 결국은 정책과제로 꼭 흘러간다는 얘기입니다.  예를 들어서 45페이지 열일곱 번째 보면 대련시 세계 유수투자가 유치 벤치마킹 그런 것이 과연 기본연구과제에 해당될 수 있는가, 대련에 대한 구체적인 외자유치에 세계 유수기업들이 들어가는 것에 대한 연구를 하신 것 같은데 그것 뿐만 아니라 여러 가지 있습니다.  벤처기업유치 촉진방안 그런 것도 그때그때 따라서 IMF가 왔다든지 또 아니면 경기가 다시 좋아졌다든지 시대변화에 따라서 이것은 그때그때 맞도록 연구가 돼야지 기본연구과제를 타이틀을 짜놓은 것이 연구과제가 되겠느냐 거의 기본연구과제를 보니까 정책연구과제로 가야될 과제가 기본연구과제로 가지 않았나.  그래가지고 오히려 일거리만 더 많아지는 게 아닌가 이런 생각이 드는데 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 김 위원께서 좋은 지적해 주셨는데 기본연구과제와 정책연구과제라든지 이런 걸 아까 말씀드린대로 그게 저희들이 결정한 게 아니고 연말에 다 받았습니다.  의회나 집행부에서 내년도 사업을 어떤 것을 했으면 좋겠느냐 이걸 다 받아가지고 그걸 가지고 또다시 논의해서 우선순위를 매겨서 기본과제를 정합니다. 
</p>
<p><b>○ 김효정 위원 </b> 본 위원 질의의 본뜻은 이 과제를 줄이는 게 좋지 않겠느냐 하는 뜻에서 말씀드립니다.  이렇게 너무 많은 건을 소화하려고 하지 마시고 진실로 딱 우리 현실에 필요한 것, 지금 경기도가 꼭 필요로 하는 그러한 정책방향에 대한 연구, 실질적으로 우리 도의원이 책자를 받아와서 볼 때도 이건 정말 값어치있는 연구였다, 이런 건 꼭 해야 될 거다 이렇게 연구과제 선정 과정에서부터도 가치있는 걸로 잡아서 아주 밤을 새워가면서 열심히 여러분의 머리를 짜내서 가치있는 연구의 결과를 내줬으면 좋겠다는 뜻입니다.  그렇게 해서 양보다는 질로 갈 생각은 있으신지 모르겠습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그래서 저희가 이번에는 핵심과제, 장기과제, 단기과제로 나누려고 합니다.  그건 무슨 얘기냐 하면 모든 연구라는 것이 기초가 없습니다.  기초를 연구하려면 장기적으로 1년이나 2년을 연구하고 그 다음에 정책과제나 기본과제는 현재 현업에서 수요를 충족해주는 겁니다.  그렇기 때문에 금년부터 그걸 이원화할 계획입니다.  그렇게 해야 앞으로 장기적인 과제는 박사님 혼자 또는 둘이 하든지 해서 1년을 연구하든지 기본과제를 해결하고 그게 질을 높이는 것입니다.  기본적으로 중요한 것만 하고 나머지, 쉽게 말씀드리면 소방차 같이 문제에 해가 되는 것은 전부 그때그때 해결하는 방법 그래서 이원화하려고 금년에는 계획하고 있습니다.  그렇게 하더라도 김 위원님께서 걱정하시는 것이나 제가 걱정하는 것이나 마찬가지인데 기본적으로 다른 연구원의 인력하고 저희 인력하고 비교해 보면 지금 서울시 시정개발연구원이 52명입니다.  저희는 아까 말씀드린대로 25명, 27명입니다.  반밖에 안 되는데.  그러다 보니까 일거리는 계속 서울시보다 땅덩어리가 20배 넓은 것과 마찬가지로 일도 계속 늘어납니다.  그래서 하중을 받아가지고 다른 연구원에서는 한 건을 하는데 저희들은 네 건, 다섯 건씩 합니다.  그래서 이건 아니다.  제가 그렇게 얘기하는 거죠.  그건 함량문제가 생기니까 그렇게 해서는 안 된다.  그래서 인원을 늘리든지 일을 줄이든지 해야 하는데 일을 줄일 수는 없지 않습니까, 인원을 늘려야죠.
</p>
<p><b>○ 김효정 위원 </b> 좋습니다.  인원을 늘리는 방법도 하나의 방법이겠습니마는 그건 또 예산이 뒤따라야 되고 여러 가지 여건이 있으니까 늘릴 때 늘리더라도 본 위원이 얘기하는 네 가지 과제 중에 기본연구과제와 정책연구과제, 수탁연구과제, 지역연구과제 중에 수탁연구과제는 할 수 없는 거니까, 이거 연구해 주십시오 하고 매달리는 것이고 지역연구과제도 여주하면 여주에 대한 걸 부탁하니까 이 두 가지는 지금 하시는 대로 가되 기본연구과제하고 정책연구과제를 지금 말씀하신대로 그렇게 분류하시든지 해서 복합되지 않도록, 절실히 필요한 것으로 숫자를 줄여서 알차게 그렇게 해 주실 것을 부탁드리고 다음 질의하겠습니다.
</p>
<p style="padding-left:1.2em">  끝으로 간행물에 대한 말씀드리겠습니다.  도 의원이 오늘 이 자리에서 이런 말씀드리는 것이 속기록에도 기록됩니다마는 괜찮을지 모르겠습니다.  소포를 받는데 제가 지식이 모자라서 그런지 몰라도 이런 연구도 있나.  무슨 논단, 동향 계속 날아오는데 뭐가 이렇게 많은지 지금 보니까 아홉 가지가 나오네요.  경기논단, 경제동향, 번역서, 위탁연구, 이코노미, 자체보고서, 정책연구, BSI 경제지표 이렇게 해서 간행물이 9종이 나오는데 예산은 1억 9,300만원, 한 2억원정도 쓰시는데 예산이 많다는 것보다도 절약도 해야 되겠고 이렇게 광활하게 간행물을 만들게 아니라 비슷한 내용인 것을 한데 묶어서 간행물이 많아야 서너 가지가 나와야지 아홉 종류의 간행물이 발행된다는 것은 예산의 낭비이고 오히려 분산이 되기 때문에 집중적이지 않아서 가치성이 떨어지지 않느냐.  한 권을 만들어도 알차게 볼만하게 만들어서 누가 봐도 이 간행물은 보관해서 봐야겠다는 값어치가 있어야 되는데 이것을 쪼개서 여러 군데로 분산시키니까 개개적으로 볼 때 별가치가 없어 보이는 면이 있지 않나 하고 생각하는데 어떻게 생각합니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것은 제가 생각하기에는 지금 시대가 지식정보사회가 됐습니다.  굉장히 다양화되고 수요가 굉장히 늘어납니다.  그리고 개인주의로 성향이 흐르고 간행물도 점점 더 많아지는 추세입니다.  지식정보라는 것이 사회가 세분화되기 때문에 통합하는 것이 언젠가는 있어야 되겠지만 언젠가는 지식정보사회가 끝나는 시대에 가서는 통합이 되겠습니다만 앞으로는 계속 세분화되고 늘어나는 추세입니다.  그래서 간행물이 아까 지적해 주신대로 저희가 교보문고에 한 달에 한 번씩 들릅니다.  경기도에 경기개발연구원의 간행물이 제일 많습니다.  그리고 수요가 제일 많고.  그래서 이것이 판매가가 계속 올라갑니다. 
</p>
<p><b>○ 김효정 위원 </b> 정가가 있는 겁니까? 
