<p><b>○ 김효정 위원 </b> 그렇다면 바람직한 일이고 자료만 요청하고 질의 마치겠습니다.  아홉 가지 간행물의 부수라든지 배부처라든지 거기에 들어가는 예산, 판매수익 그런 것을 서면으로 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 김효정 위원 수고하셨습니다.  원장님께 당부의 말씀드리겠습니다.  위원님들의 질의에 대한 답변을 좀더 상세하게 하시기 위해서는 다른 증인 즉 처장이나 실장, 각 부장이 답변할 수 있습니다.  다른 증인이 답변할 때에는 직책과 성명을 대고 답변해 주시면 되겠습니다.  그럼 이어서 다른 위원 질의하시기 바랍니다.  윤동욱 위원 질의하시기 바랍니다. 
