<p><b>○ 윤동욱 위원 </b> 남양주 출신 윤동욱 위원입니다.  방금 김효정 위원이 간행물에 대해서 질의를 드렸습니다.  그런데 자료를 보면 작년보다 올해 오히려 판매실적이 부진합니다.  그리고 금년에는 아직 12월이 지나지 않아서 그런지 11건밖에 되지 않았습니다.  이게 연구하는 보람을 느끼고 판매실적이 많을 때 이것을 염두에 둔 모든 희망하는 사람들이 많이 보고 우리 경기개발연구원에서 연구한 과제를 그 사람들이 알았을 때 바로 연구한 보람을 느끼시리라고 생각됩니다.  그런데 해를 거듭할 수록 원장님께서 늘어난다고 답변하셨는데 그렇지 않은 사항이 이 자료에 나타나 있습니다.  앞으로 더 많은 판매가 될 수 있는 계획은 어떤 걸 가지고 계신지 말씀해 주십시오.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 지금 윤 위원님께서 지적해주신 대로 연말이 돼야 그것이 나오고 지금 떨어지는 분야가 정기간행물에서 조금 떨어지고 저희들이 단행본, 정기간행물, CD-ROM이 있습니다.  회원이 있습니다.  회원이 있고 그런 데서 보면 단행본에서는 계속 늘어납니다.  그 단행본이라는 것이 수시로 연구하는 보고서입니다.  그래서 지금 연말이 되면 아마 위원님이 걱정하시는 문제는 해결될 것으로 생각합니다.  앞으로 간행물에 관해서는 저희가 긍지를 가지고 계속 수요가 늘기 때문에 간행물 계획을 저희들은 다시 할 생각을 가지고 있습니다. 
