<p><b>○ 경기개발연구원장 노춘희 </b> 양 위원님과 윤 위원님께서 말씀하신 것을 다시 말씀드리면 그것이 저희로서 참 중요한 사항이기 때문에 저희가 연구하는 사람 입장에서 기본적으로 두 가지 문제가 있다고 봅니다.  하나는 연구하는 것이 갑과 을이 있습니다.  아까 도시지역계획부장님이 말씀한 대로 저희는 그 사업에 관한 을입니다.  저희가 을이었었다는 것이 그 사업에 관한한 앤더슨이 을이 됐고 저희는 아무 것도 아니었었거든요.  그런데 도가 갑이 된 겁니다, 거기서 발주했기 때문에.  그래서 갑에서 자료 같은 것을 저희 연구원에서 전체 자료를 가지고 가서 언제든지 줄 수 있습니다.  저희가 연구한 거니까.  그래서 지난번의 그런 일이 앞으로는 안 나기 위해서 저희가 장치를 해놨습니다.  무슨 장치인가 하니 기본적으로 저희가 애써서 만들어 준 작품 중에서도 보고서가 나가야 될 부분과 보고서가 안 나갈 것을 간행물위원회라는 것을 만들어서 앞으로 철저하게 관리하려고 합니다.  옛날에는 그것이 관리가 안 돼서 그런 문제가 생겼기 때문에.  그래서 보고서안에도 수록할 게 있고 수록 안 할 것이 있습니다.  그래서 기준을 이번에 만들어서 그런 일이 없도록 강구해 놨습니다.  옛날에는 그런 것이 없었기 때문에.  그래서 쉽게 말씀드리면 앞으로는 그런 자료가 대외적으로 우리가 공부해서, 도민의 세금을 받아서 우리가 연구한 과제가 바깥의 용역회사가 거져 먹기 식으로 가져가는 것은 없을 겁니다.  그런 장치를 해놨기 때문에.  그래서 지난 일은 과거의 제도적인 것이 없었기 때문에 일어났지만 이제는 그런 것을 저희 내부적으로도 자료를 관리하는 시스템을 만들어 놨기 때문에 그런 일이 없을 것으로 생각합니다. 
