<p style="padding-left:1.2em">  본 위원이 요구한 자료 7쪽에서 10쪽을 보면 경기개발연구원에서 2000년도 한해 동안 기본연구과제를 포함한 70여건이 넘는 연구실적이 있는 것으로 자료에 나타났는데 이 연구과제 중에서 2001년도에 경기도 실적에 반영된 연구과제가 있는지에 대해서 상세하게 답변해 주시기 바라겠습니다. 
