<p><b>○ 경기개발연구원장 노춘희 </b> 지금 2000년도에는 광역도시구역설정문제, 접경지원법시행령 이것은 완료된 겁니다.  접경지원법시행령까지 완료됐습니다.  또 경기도지식기반산업발전전략, 또 경관관리기본계획 이거 다 끝났습니다.  복지시설평가제도 이와 같은 것은 문제가 해결돼서 기여도가 있다고 평가를 받았습니다.  한강수계의 물이용부담금 효과라는 것은 여러분이 익히 알고 계시는 바와 같이 지금까지 서울시나 물을 쓰는 사람들이 비용을 부담 안 했는데 이것을 법으로 만들어서 지금 물이용부담금을 받고 있습니다.  이와 같은 것은 100% 기여를 했다고 저희들은 자신합니다.  그래서 구체적인 것을 몇 %까지 기여도가 있느냐 그것은 전체를 끝난 것만, 또 지금 계속해서 금년말까지 끝나는 것을 저희들이 끝나는 대로 서면으로 보고드리겠습니다. 
</p>
<p><b>○ 노시범 위원 </b> 오해는 하지 말고 들어주십시오.  앞에서도 위원님들이 지적했다시피 한정된 연구원, 박사님들을 가지고, 인력을 가지고 그 많은 과제를 연구하기에는 너무 역부족이다라는 지적들이 상당히 많이 나오고 있거든요.  작년부터도 저희들이 행정사무감사를 하면서도 지적했던 거고 오늘 이 자리에서도 나왔었고.  그런데 그 자료를 보신 많은 분들 이야기가, 제 얘기가 아니고 많은 분들이 제 귀에다 대고 하는 얘기가 그렇기 때문에 짜깁기 형식으로 갈 수밖에 없다라는 지적들이 나오고 있다는 현실을 저는 이 자리에서 지적해 드리고 싶습니다.  그래서 여기에 대한, 아까 원장님께서도 그런 고민을 하셨지만 정말 양질의 연구과제가 나올 수 있도록 연구원 나름대로의 어떤 대응이 나와야겠다라는 생각을 하는 겁니다.  그래서 현재 거기에 대한 어떤 대응책은 있으세요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 아까 윤 위원님, 양 위원님께서 걱정해 주신 것과 똑같이 저희가 제도운영방법을 바꾸려고 하는 것은 장기과제만은 틀림없이 이것은 장기적으로 연구해야 될 과제명을 선택해서 그것도 저희들이 혼자 선택할 것은 아닙니다.  여러분 의회나 도의 집행부하고 이런 것을 장기적으로 1년을 연구하려고 하는데 어떠냐, 어떻습니까 물어가지고 그것을 선택해서 장기적인 질 높은 연구로 갈 거고, 그리고 아까 속되게 말씀드렸습니다만 단기, 수시로 정책과제나 도정에 필요한 수요를 충족해 주는 방법, 그것도 아까 말씀드린 대로 지금 도비를 받아가지고 저희들이 하기 때문에 그 기여도가 어느 것이 높으냐?  그 우선순위를 정해서 그런 연구를 집중적으로 해야 되지 않겠나 해서 이원화로 운영방법을 개선하려고 생각하고 있습니다. 
