<p><b>○ 경기개발연구원장 노춘희 </b> 그래서 저도 처음에 와 보니까 그게 이상한 것 같아서, 왜 돈을 가지고 수익성 있는 이자율이 높은 데로 해서 운영하는 게 어떠냐 그랬더니 그것이 어렵답니다.  왜냐하면 감사의 지적을 받고 또 오늘 노시범 위원님이 지적해 주셨는데 이자율이 높은 데를 우선 줘야 된다.  그럼 이자율이 높은 신탁 같은 데 주면 어떠냐?  그런 얘기까지도 해봤습니다만 신탁은 위험해서 줄 수 없습니다 그런 얘기지요.  그래서 건전성과 이자율이 높은 데를 그날그날 입금을 할 때 그때마다 받아가지고 최선의 방법으로 그런 식으로 운영하다보니까 다양하게 나옵니다. 
