<p><b>○ 노시범 위원 </b> 그러면 제가 하나만 예를 들어볼게요.  여기 한미은행 수원지점에 더모아확정예금으로 2001년도 2월 8일에 예치했는데 6.5%의 이율로 예치한 게 있고 그 밑에 바로 보면 2001년도 두 달후에 3월 14일에 예치한 것은 6.1%다 말이지요.  이런 부분들은 왜 이율이 낮은 데로 예치하셨어요?
