<p><b>○ 재정지원과장 강윤구 </b> 재정지원과장 강윤구입니다.  저희가 기금을 예치할 때는 당일에 6개 시중은행 정도에 이자율조사를 합니다.  아침 10시경에 하는데 그날따라 최고금리를 받을 수 있는 은행을 선정해서 가게 됩니다.  그래서 지금 잘 아시는 바와 같이 매일매일 고시이율이 달라집니다.  그런데 실제적으로 저희가 받을 수 있는 건 지점장의 가산금리라는 게 있습니다.  0.3% 이내입니다.  그것을 받느냐 못 받느냐에 따라서 결정되는데 대략은 그 날짜에 결정되기 때문에, 저희가 만기되는 시점에 그 날짜 아침에 조사합니다만 그 시점에 조사했을 때 6.5와 6.1이라는 숫자가 나오게 되는 겁니다.  그래서 저희가 1년간을 쭉 조사해 보면 타 기관보다 1.05% 정도의 수익을 올린 것으로 저희가 자료를 가지고 있습니다.  그것은 예치시점 때문에 그런 거니까…….
