<p><b>○ 노시범 위원 </b> 본청에서도 우리가 감사할 적에 똑같은 답변이 나오는데 실제적으로 답변에서는 그렇게 나오는데 자료를 받아보면 은행의 로비에 의해서 좌우되는 현실도 상당히 있었다는 점을, 저는 여기서 그렇다는 것이 아니라 그렇게 확인된 사실이 있었다는 점을 말씀드리고요.  이 자료하나 요구하겠습니다.  그날 받아보신 타은행권하고 현재 예치시켜 놓은 은행의 상품권하고 비교해서 이것은 자료를 분명히 주시기 바랍니다. 
