<p><b>○ 노시범 위원 </b> 본 위원이 보기로는 상당히 저조하거든요.  왜냐하면 몇 개 시·군을 묶어서 할 적에 원장님 말씀하신 대로 예를 들어서 동두천에서 한다 그러면 동두천 의원들은 다 온다 말이지요.  그런데 인근 시·군 의원들은 안 와요.  그런 것을 확인하셨지요?  그런데 왜 그런지 아시겠어요?  파악 좀 안 해보셨어요?  왜 도의원들의 참석현황이 저조한가?
