<p><b>○ 노시범 위원 </b> 본 위원이 오늘 분명하게 지적하겠습니다.  기획위원회 소관은 경기개발연구원하고 상당히 밀접된 위원회예요.  그런데 막상 참석을 해보면 도의원인지도 모르고 기획위원인지도 모르고 실무자들이 일하고 있어요.  지난번에 어디라고는 제가 지적을 안 하겠습니다만 우리 기획위원회 몇몇 위원들이 참석했는데 기획위원이 누군지도 모르고 집행부 도지사, 부지사만 따라다니면서 의전을 하더라.  어느 위원이 제 옆구리를 치면서 우리 가십시다 그래요.  어디 가서 앉아야 되는지, 우리가 어떻게 처세를 해야 되는지도 몰라요.  그 다음에 또 중요한 것은 원장님 말씀을 한 가지만 드릴게요.  원장님이 축사를 하시든지 무슨 인사말을 하신단 말이에요.  거기에 도의원의 "도"자도 안 들어가요.  시장·군수, 시의회의장은 감사하다고 인사하신단 말이지요.  그러면 도의원들이 그 행사장을 회피할 수밖에 없어요.  가서 망신 당하는데요.  그러니까 참석했던 주민들이 "아, 도의원들 아무 것도 아니구나." 있으나 마나한 형태로 본단 말이지요.  그러니까 시의원들, 국회의원들, 시장만 있는 것으로 오인한단 말이지요.  이것은 저희가 제자리를 찾기 위해서 하는 것이 아니라 분명히 이것은 이루어져야겠더라.  현실이 시·군에 나가서 워크숍을 하든 공청회를 하든 세미나를 하는데 도의원들하고 가장 밀접한 기관에서 그렇게 도의원들을 푸대접하고 있더라 이거지요.  그래서 이러한 부분들은 6대 후배 도의원들이 들어오더라도 분명히 정립이 돼야 되겠더라.
</p>
<p style="padding-left:1.2em">  도의원들의 자리가 철저히 돼야 되겠더라.  그래서 도정에 경기개발연구원에서 하는 모든 공청회, 워크숍에 도의원들이 자진해서 참석할 수 있는 분위기가 마련돼서 함께 고민하는 자리가 돼야겠다는 생각들을 여러 번 제가 했었던 경험이 있었기 때문에 지적해 드리는 겁니다. 
