<p><b>○ 위원장 김강선 </b> 노시범 위원 수고하셨습니다.  장시간 수고 많으셨습니다마는 시간관계상 보충질의가 있으시면 계속해서 보충질의로 들어가겠습니다.  보충질의하실 위원님 계십니까?  유영록 위원 질의하시기 바랍니다.
</p>
<p><b>○ 유영록 위원 </b> 유영록 위원입니다.  경기개발연구원이 2000년, 2001년도 연구원이라든지 관리직이라든지 임용현황이 있을 겁니다.  임면이나 면직하거나 임용한 현황을 해 주시고 특히 연구위원님들은 임용하셨을 때 박사급이면 어디 학교의 뭐로 학위를 받으셨는지 그것까지 자료 제출해 주시고요.  그 다음에 지금 최근 이사회에서 행정직장을 사무처장직으로 명칭을 바꾼 것으로 알고 있는데 사무처장의 역할이 무엇인지, 최근에 그만 두신 사무처장도 도의 공보관으로 있다가 여기 와서 몇 달 안 있다가 그냥 가는, 어떻게 보면 거쳐가는 그런 것으로 알고 있거든요.  그래서 지금 원장님께서 사무처장 임용기준이 무엇인지, 그 다음에 사무처장을 특채하는데 제가 그래서 경기개발연구원 정관하고 규정집도 봤는데 특별채용하는 기준이 무엇인지, 그리고 이번에 채용하셨을 때 어떠한 형식으로 채용했는지 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 사무처장이라는 건 행정실장으로 옛날에 제가 와서 만들어 놨었어요.  행정실장이라는 것은 행정지원하는 것이 행정실장이다.  사무처로 바뀐 것은 저희 기구가 자꾸 커집니다.  행정뿐만 아니라 대외적인 일이 많게 됩니다.  그래서 아하! 사무처가 맞겠구나 그래서 사무처로 바꾸었고 이 사무처장의 역할을 말씀드리면 사무처장은 저희 연구원과 도와 또 의회와 대외적인 홍보활동이나 여러 가지 일이 많기 때문에 행정만 하는 것이 아니기 때문에 사무처장으로 바꿨다고 말씀드리고 또 사무처장을 특채하는 것은 꼭 특채만 하는 것은 아니고요 공모해서 모집도 합니다.  그래서 아까 말씀드린대로 도정과 저희 연구원과 유기적인 관계를 이룰 수 있는 그러한 자질을 가지신 분, 그런 분이 사무처장으로 오셔서 일을 하시기 때문에 꼭 신문에 내서 하는 것이 아니고 인터넷이나 혹은 아는 사람들끼리 전문가적인 능력있는 사람 수소문해서 몇 사람을 보고 거기에서 우리에게 가장 적합한 사람을 사무처장으로 임용하게 됩니다.  그런데 그것을 제가 임용하는 것도 아니고 그것은 이사장님이 하시니까, 이사장님이 지사님입니다.
</p>
<p><b>○ 유영록 위원 </b> 인사위원회 열어서.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 인사위원회는 저희들이 여는 게 아니고 이사회에서 대부분 그런 얘기를 하고 이사장님이 임명하시게 됩니다. 
</p>
<p><b>○ 유영록 위원 </b> 이번 경우에는 공개를 했나요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 공개를 했습니다. 
</p>
<p><b>○ 유영록 위원 </b> 경기개발연구원 홈페이지에 공개합니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 홈페이지에다는 저희들이 안 하고 대부분 도정하고 저희 연구원하고 관계가 깊기 때문에 거기 전문가가 누구냐 그런 식으로 해서 특채를 하게 합니다. 
</p>
<p><b>○ 유영록 위원 </b> 제가 염려하는 부분들이 지방공사 사장 임명 그런 것과 관련해서 도에 출연하는 기관에 임용할 때 이게 사실 공개되고 투명해야 되거든요.  이런 측면에서 앞으로는 또 사무처장의 직위가 예전하고는 달라졌다고 생각합니다.  연구파트는 사실 연구만 신경 쓰셔야 되고 그밖에 모든 운영이나 대외홍보 또 앞으로 사무처장님께서 우리지역 뿐만 아니라 대국회, 경력을 보니까 국회보좌관으로 계셨던 것으로 아는데 그런 측면에서 적극적으로 하기 위해서는 사무처장이 왔다갔다 하는 자리가 아니라 정말 도민의 복리증진과 도의 발전을 위해서 그런 의식을 가지신 분들이 해야 되겠다.  이번에 잘 임용했으리라 생각합니다.  그래서 원장님께서도 처장 임용에 관해서는 특별히 임시방편으로 하실 게 아니라 적어도 임용되면 원장님 임기와 같이 가든지, 3∼4년 정도 돼야지 그냥 직위에 따라서 이사장님이 이번에 누구를 했으면 좋겠다 그렇게 하시면 안 된다는 것을 말씀 올리고 싶습니다.  이상입니다.
</p>
<p><b>○ 위원장 김강선 </b> 유영록 위원님 수고하셨습니다.  김효정 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 김효정 위원 </b> 김효정 위원입니다.  145페이지 감사자료 내용에 보면 초빙연구원이 15명, 비상임연구원이 27명 이렇게 있는데 그것은 지금 연구부에 있는 25명과 합친다면 67명이 연구한다는 얘기입니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 초빙연구원과 비상임연구원은 아까 말씀드린대로 비상임은 저희들 사무실 공간을 쓰지 않고 연구과제를 줘서 대학이면 대학, 밖에서 연구결과물만 가지고 오시는 분들이 비상임연구원입니다.
</p>
<p><b>○ 김효정 위원 </b> 일거리를 그리 주는군요.  하청 주듯이 주면 자기 사무실에서 연구해 가지고 가져온다?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 김효정 위원 </b> 그런 데도 연구책임자는 따로 없네요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 연구책임자는 어디든지 있습니다.  저희들이 하게 됩니다.
</p>
<p><b>○ 김효정 위원 </b> 25명 연구부 그분들이 책임자가 돼서 그분들이 따로 연구하는 것도 있지만 위촉을 해 가지고 비상임연구원 주기도 하고 또 초빙연구원은 아까 얘기한 대로 여기 사무실을 쓴다고…….
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 여기 사무실을 쓰는 분도 있고 그분 중에도 안 쓰는 분도 있습니다. 
</p>
<p><b>○ 김효정 위원 </b> 결론적으로 25명이 연구하는 게 아니라 따지고 보면 전체를 합치면 67명의 연구원이 일을 한다고 봐야 되겠네요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 아니죠.  제가 아까 말씀드리기를 저희가 작년에 보니까 다양하기 때문에 저희가 전공이 없어서 밖에 분들을 모셔서 한 것이 전부하면 총 126명쯤 됩니다.  
</p>
<p><b>○ 김효정 위원 </b> 일거리에 따라서 그때그때 한다.  그러면 필요한 이유는 여기 있는 25명의 연구직에 계신 분의 능력으로는 그 연구를 소화할 수 없어서 주는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 능력이라기보다는 전공이 안 맞는 분들이 많죠.  전공이 있어도 너무 과제가 과중하니까 그걸 밖으로 줍니다. 
</p>
<p><b>○ 김효정 위원 </b> 과제가 과중하니까 내보낸다.  여러 가지 보면 내가 머리가 모자라서 그런지 몰라도 당장 쓸 것 같지도 않고 필요한 같지도 않은 연구과제가 많은데 꼭 필요하기 때문에 외부 분한테 맡길 정도로, 초빙해서 연구해야 될 정도로 시급합니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그런 문제가 도에서 그때그때 필요에 의해서 해달라고 자꾸 오니까 그걸 안 줄 수 없습니다.  저희는 도를 위해서 있는 기관이기 때문에.
</p>
<p><b>○ 김효정 위원 </b> 그럼 임용절차는 어떤 식으로 합니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 초빙연구원이나 정규직은 이사회에서 결정해야 됩니다. 
</p>
<p><b>○ 김효정 위원 </b> 비상임연구원도?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 비상임연구원은 저희들이 원에서 필요하면 씁니다.
</p>
<p><b>○ 김효정 위원 </b> 비상임연구원에서 여기서 원장님 재량권으로.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 460명의 풀을 가지고 있습니다.  그 중에서 해당되는 사람을 저희들이 활용합니다. 
</p>
<p><b>○ 김효정 위원 </b> 임용기간은 얼마입니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 3개월도 되고 2개월도 되고 그건 과제에 따라 다릅니다. 
</p>
<p><b>○ 김효정 위원 </b> 그러면 보수도 과제에 따라서 얼마로 계약합니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 아닙니다.  그것은 보수금액이 정해져 있습니다. 
</p>
<p><b>○ 김효정 위원 </b> 어떻게 정해져 있습니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 직급별로 박사한 지 10년이다, 그 과제실적이 얼마가 있다, 그 기준에 의해서 보수가 나갑니다.
</p>
<p><b>○ 김효정 위원 </b> 그럼 과제별로 보수가 다 다른가요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 임용자격이 기간도 있고 과제도 있습니다.  
</p>
<p><b>○ 김효정 위원 </b> 담당자가 설명해 보세요.  어떻게 임용하고 어떻게 대우하고 보수는 어떻게 계산하는지, 기간을 뭘 가지고 정하고.
</p>
<p><b>○ 기획조정실장 조응래 </b> 기획조정실장 조응래입니다.  저희 연구원에 초빙연구원, 비상임연구원 등 운영규칙이 있습니다.  그래서 초빙연구원 같은 경우는, 먼저 비상임연구원 말씀드리겠습니다.  직급이 가·나·다급 이런 식으로 구분해 가지고 있습니다.  그래서 해당 박사학위 소지자로서 6년이상 해당분야에 경력이 있는 사람들 이래서 비상임연구원 중 수석연구위원은 100만원 그리고 연구원급은 60만원입니다.  그래서 그 사람의 자격기준에 맞춰서 60만원부터 100만원 사이의 금액을 월별로 줍니다.  그래서 그분한테 이런 분야에 대해서 연구를 부탁해서 연구결과에 대해서는 연구책임자가 감독하게 되어 있습니다.  그리고 그러한 비상임연구원이나 초빙연구원을 활용하는 것 자체가 저희는 모든 게 연구계획에 의해서 이루어지기 때문에 자체연구심의라든지 용역사업심의위원회에 이런 데서 초빙연구원으로 어떤 사람을 왜 쓰는지 자체적으로 심의하고 있습니다.  그리고 금액은 얼마를 주는지까지도 거기서 논의가 됩니다. 
</p>
<p><b>○ 김효정 위원 </b> 아까 원장님 말씀은 비상임연구원은 그런 식으로 가는데 초빙연구원은 이사회에서 다…….
</p>
<p><b>○ 기획조정실장 조응래 </b> 초빙연구원은 답변중에 아마 정규직 박사를 말씀하시면서 이사회 말씀하셨고요.  초빙연구원도 마찬가지입니다.  대부분 비상임이라는 것은 상임이 아니기 때문에 외부에서 근무하시는 분들을, 초빙연구원은 연구원내에서 근무를 하시는 그런 내용이 되겠습니다. 
</p>
<p><b>○ 김효정 위원 </b> 그럼 초빙연구원도 과제에 따라서 1개월 있을 수도 있고 2개월 있을 수도 있고 기간이 다르겠네요?
</p>
<p><b>○ 기획조정실장 조응래 </b> 과제마다 틀립니다.  과제별로 모두 초빙이 되기 때문에.
</p>
<p><b>○ 김효정 위원 </b> 그러면 어차피 초빙연구원을 풀로 쓰신다니까 40여명은 정해져 있군요.  그분들 중에서 필요할 때마다 모셔다가.
</p>
<p><b>○ 기획조정실장 조응래 </b> 그게 40명이 아니라 400여명입니다.  그러니까 각 대학교수님들부터 시작해 가지고 이렇게 돼 있기 때문에 저희 전공분야가 여성이라든지…….
</p>
<p><b>○ 김효정 위원 </b> 그럼 인적자원은 충분하다는 얘기네요.  연구원에서 가지고 있는 25명 있고 그외에 아웃소싱할 수 있는 400여분이 있으니까, 알겠고요.  그러면 지금문제는 여러 위원님들도 감사하면서 항상 생각이 되는 게 이 연구결과가 과연 도정에 얼마나 효과적으로, 얼마나 필요하게 쓰여지느냐인데 연구한 결과가 도정에 직접 반영된 프로테이지가 있을 것 아닙니까?  쉽게 얘기해서 10개를 연구했으면 그중에 하나 정도는 반영됐다든지 그런 게 나온 게 있습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것이 완전히 끝난 것도 있고 아까 말씀드린대로 100% 반영된 것이 있고 지금 진행중인 것이 있고 그것이 연말이 되면 전부 퍼센트에.
</p>
<p><b>○ 김효정 위원 </b> 작년에는 어땠습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 작년에도 역시 분석해 보니까 완전히 반영된 것이 있고 지금 계속 이월해서 계속사업으로 넘어간 것이 있습니다.  그건 서면으로 저희들이 자세하게 보고를 드리겠습니다. 
</p>
<p><b>○ 김효정 위원 </b> 알겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 김효정 위원 수고하셨습니다.  노시범 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 노시범 위원 </b> 하나만 확인하겠습니다.  아까 지적된 경기개발연구원에서 연구한 과제물을 짜깁기한 사건에 대해서 고발조치한 거 있어요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 고발조치보다 시정을 저희들이 했습니다. 
</p>
<p><b>○ 노시범 위원 </b> 본 위원이 알고 있기로는 예를 들어서 어느 교수가 논문을 발표했는데 그 논문을 무단 사용했을 경우에는 지적재산권 침해 그런 걸로 고발당하고 매장 당하잖아요.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것이 교수가 자기 논문을 다른 사람이 표절한 것과, 이건 용역회사입니다.  용역회사는 법적으로 설립된 법인입니다.  그래서 조금 개인의 지적재산권하고 법인으로 설립된 컨설팅 회사하고는 다릅니다.  그래서 고발하는 것이 아니고 정정을 하고 보고서를 다시 수정해서 내라.  그래서 수정작업…….
</p>
<p><b>○ 노시범 위원 </b> 법적대응 한계가 시정을 해달라고 할 수밖에 없다는 말씀인가요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그렇습니다.  컨설팅 회사이기 때문에 개인이 아니고.
</p>
<p><b>○ 노시범 위원 </b> 그 법인을 상대로 고발이 안 된다는 겁니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 법인이기 때문에 컨설팅 회사라는 자체가 그런 걸 연구하는 회사입니다.  그래서 지적소유권이라는 것이 한계가 있어서 거기서 이런 걸 우리가 인용했다, 참고했다 이런 각주만 달아주면 됩니다. 
</p>
<p><b>○ 노시범 위원 </b> 그렇다면 그러한 법적인 허점을 이용해서 법인을 설립해 놓고 마구잡이로 짜깁기를 해도 대응책이 없다는 말씀입니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그렇기 때문에 저희가 아까 말씀드린대로 정보관리를 위해서 앞으로 나갈 것만 유인물로 하고 안 나갈 것은 별도로 유인 안 하겠다는 얘기가 그래서 간행물을 이원화해서 운영하겠다는 얘기입니다.  방지하기 위해서.
</p>
<p><b>○ 노시범 위원 </b> 알겠습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 윤동욱 위원 질의하시기 바랍니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 한 가지만 질의하겠습니다.  번역사업을 하고 계신데 똑같은 걱정이 돼서 그렇습니다.  원본을 우리말로 번역하지 않습니까?  15쪽에 보면.  이 번역사업을 할 때 저자에게 승인을 받고 번역하십니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네, 받습니다.
</p>
<p><b>○ 윤동욱 위원 </b> 승인받을 때 보수나 주는 것 없습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 보통 세일즈의 관례가 10%를 내놓으라고 합니다.  그러면 저희가 "10% 내놓고는 하지 않는다.  그래서 번역을 하겠으니 허가를 해달라" 해 가지고 보통 6개월, 1년이 걸립니다, 외국기관이기 때문에.  그래서 저희들이 번역료라든지 그런 세일즈를 안 내는 부분 그런 것만 번역해서 쓰고 있습니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 만일에 이것을 저자들한테 승인을 받지 않고 지금과 같은 행위가 이루어졌을 때 경기개발연구원이 저자한테 당할거란 말이에요. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 저작권 관계는 저희들이 그 보고서가 경기도가 정말 필요하다.  만약 예를 들면 Management Report가 뉴욕시에서 나왔습니다.  그런 것은 한 30불 주고 번역했습니다.  달라고 하기 때문에.  안 주고 저희가 하게 되면 정말 지적재산권으로 세계적인 문제가 되기 때문에 국제적인 문제를 피하기 위해서 저희들이 방지하고 있습니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 그래서 본 위원이 아까 자료를 요청할 때 ''96년도에 경기개발연구원에서 7개월에 걸쳐서 연구를 하셨다고 했습니다.  그러면 그때 연구하신 연구원은 물론, 박사님은 물론 토론회도 하고 보고회도 했는데 몇 월에 어디서 어떻게 했다.  그런데 경기도의 집행부에 있는 참석자 공무원은 누구누구였었는지 이것도 구체적으로 자세히 해서 자료를 제출해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 알겠습니다.  서면으로 답변해 드리겠습니다.
</p>
<p><b>○ 위원장 김강선 </b> 윤동욱 위원님 수고하셨습니다.  더 질의하실 위원 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시므로 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치도록 하겠습니다.  위원 여러분께서 장시간 열의를 갖고 감사에 임해주신 데 대해 감사의 말씀을 드리며 아울러 노춘희 연구원장을 비롯한 연구원 관계자 여러분께도 행정사무감사를 위한 자료준비와 위원님들의 질의에 성실히 답변해 주신 데 대해 감사드립니다.  오늘 여러 위원님들께서 감사시에 지적해 주신 사항은 도민의 뜻이니만큼 이를 겸허하게 받아들여서 연구원 업무에 적극 반영될 수 있도록 최선의 노력을 다해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 노춘희 원장님을 비롯한 연구원 임직원 여러분!  수고 많이 하셨습니다.  그러면 이상으로 경기개발연구원에 대한 2001년도 행정사무감사 종료를 선언합니다. 
</p>
<p class=''ar''>(12시28분 감사중지)
</p>
<p class=''ar''>(14시36분 감사계속)
</p>
<p><b>○ 위원장 김강선 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의하여 감사관실에 대한 2001년도 행정사무감사 실시를 선언합니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 감사관을 비롯한 관계 공무원 여러분!  안녕하십니까?  기획위원회 감사위원장 김강선입니다.  연일 계속되는 감사일정으로 노고가 많으신 위원님들께 심심한 위로와 감사의 말씀을 드리면서 도민을 대표하여 집행부의 도정전반에 대해 감사하는 것이니만큼 심도있는 감사를 당부드립니다.  아울러 수감준비를 위하여 애쓰신 집행부 관계 공무원 여러분들께도 위로와 격려의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 감사관께서는 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에경기도의회가 2001년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알려드립니다.  그러면 선서의 요령을 설명드리겠습니다.  선서는 감사관이 발언대로 나오셔서 오른손을 들고 선서문을 낭독하시면 되겠습니다.  그러면 선서를 해 주시기 바랍니다. 
</p>
<p><b>○ 감사관 이진호 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 소관업무에 대한 2001년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4 제5항과 경기도의회행정사무감사및조사에관한조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.  2001년 11월 26일 증인 감사관 이진호.
</p>
<p><b>○ 위원장 김강선 </b> 다음은 업무보고 순서가 되겠습니다.  감사관 나오셔서 업무보고 해 주시기 바랍니다. 
</p>
<p><b>○ 감사관 이진호 </b> 감사관 이진호입니다.  평소 존경하는 김강선 기획위원회 위원장님과 여러 위원님을 모시고 오늘 2001년 감사관실 소관 주요업무보고를 드리게 된 것을 매우 뜻깊게 생각합니다.  아울러 항상 저희 감사관실 소관 업무에 대해 많은 관심과 애정을 가지시고 지도편달과 성원을 아끼지 않으신 위원님들께 깊은 감사의 말씀을 드립니다.  앞으로도 위원님들의 고견을 참고하여 알차고 내실있는 감사업무를 수행해 나갈 것임을 다짐드립니다.  업무보고에 앞서 저희 감사관실 간부를 소개해 드리겠습니다.  장두석 감사기획담당입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  윤항덕 감사2담당입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김일수 감사3담당입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김호겸 조사담당입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박성권 감사1담당은 현재 건설교통부에서 주관하는 도로건설반 과정의 교육중에 있음을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그러면 지금부터 감사관실 소관 2001년도 업무계획과 그간의 추진사항을 보고드리겠습니다.  보고드릴 순서는 일반현황과 감사목표 및 방향 그리고 주요 업무추진 사항 순으로 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 3쪽 일반현황과 4쪽 감사목표 및 방향은 위원님들께서 양해해 주신다면 유인물로 갈음하여 보고드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  5쪽 2001년 주요업무 추진사항입니다.  2001년 주요업무 추진사항에 대한 보고는 내실있는 감사실시, 일상감사제 운영, 부실방지 기동감찰반 운영, 공직기강확립을 위한 감찰활동, 부조리 신고·진정 등 조사처리, 감사역량제고, 공직자 재산등록심사 순으로 보고드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  6쪽 내실있는 감사실시입니다.  2001년도 감사방향은 기존의 합법성 감사를 정책감사 위주로 전환하여 감사의 효율성을 제고해 나감은 물론 엄정한 감사활동과 집행으로 공직분위기를 쇄신하고 불합리한 제도와 관행을 발굴·개선하여 행정의 능률성을 도모하였으며 지적·처벌보다는 예방지도 감사를 강화하여 생산적인 감사로 피감사가 이에 수긍할 수 있는 합리적인 감사를 실시해 왔습니다.  금년에는 총 61개 감사대상기관 중 17개 시·군에 대한 재정투·융자사업, 경영수입 관련사업 등의 추진사항 전반에 걸쳐 정책감사를 실시하였고 시·군 및 소방서 등 34개 기관에 대해서는 국·도정 등 주요시책 추진실태와 민원처리사항, 불합리한 제도의 발굴·개선 등에 중점을 두고 일반감사를 실시한 바 있습니다.  그리고 감사개시전 감사일정을 인터넷에 공개하여 사전에 주민의견을 수렴하고 대학교수, 환경단체 등 민간전문가를 참여시켜 감사활동의 객관성과 신뢰도를 제고시켜 왔습니다. 
</p>
<p style="padding-left:1.2em">  다음 8쪽입니다.  일상감사제 운영에 대하여 보고드리겠습니다.  사후감사로는 치유가 어려운 주요사업에 대하여 사전감사를 실시함으로써 시행착오에 대한 문제점을 도출하여 행정력과 예산낭비 등 부조리 요인을 사전에 제거하기 위하여 금년에는 도 본청, 직속기관 및 사업소에 도급액 50억원이상의 공사와 5억원이상 책임감리용역, 3억원이상 조사설계용역인 사업 22건에 대해 일상감사를 실시하여 행·재정상 조치를 취한 바 있습니다.  아울러 대규모 사업의 추진상 오류와 시행착오에 대한 개선대책강구, 공사의 안전성과 기술적 타당성 등을 검토, 완벽한 시공이 될 수 있도록 조치하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 9쪽입니다.  부실방지 기동감찰반 운영에 대하여 보고드리겠습니다.  공사장인 사업장을 대상으로 시공 및 안전관리상태와 설계의 적정여부 등에 대하여 현장감사를 실시하여 시공자로 하여금 성실시공에 대한 인식을 전환하도록 하겠습니다.  감사대상은 도 및 시·군에서 발주한 도급액 50억원이상 대형공사로써 안전점검기동반 인력과 외부 민간전문가와 합동으로 16개 공사현장에서 공사시공의 적정성과 품질관리, 공사현장 안전관리실태, 감리업무 수행 실태 등을 중점적으로 감사를 실시한바 있으며 앞으로도 불법 및 부실시공을 예방하기 위하여 최선의 노력을 다하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 10쪽입니다.  공직기강확립을 위한 감찰활동입니다.  공직내부의 부조리 관행을 타파하고 잔존 부조리를 척결하여 공직기강을 확립하고 깨끗한 공직 분위기를 조성해 나가기 위해 지속적인 감찰활동을 전개한 결과 불법행위방치, 민원서류 지연처리 행위 등 직무태만과 직무 관련 금품수수행위 등 복무기강해이 사례 14건을 적발하여 처분 조치한 바 있으며 앞으로 취약인물과 기관 등에 대하여 책임관리제를 실시하여 공직기강이 해이해질 우려가 있는 명절, 휴가철 등 취약시기에는 집중적으로 감찰활동을 강화해 나가고 건축, 세무, 환경, 위생 등의 취약분야와 무사안일, 보신주의, 복지부동 등의 행태에 대한 지속적인 감찰활동을 실시하여 부조리관행을 타파하는 데 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 11쪽입니다.  부조리신고, 진정 등 조사 처리가 되겠습니다.  주민불편사항의 신속한 처리로 생활민원을 해소하고 민원 부조리의 시정·개선으로 행정신뢰도를 제고해 나가기 위해 부조리신고창구를 개설 운영하고 있습니다.  부조리신고창구는 도민 모두가 아무 때나 제보할 수 있도록 연중 운영하고 있으며 누구나 쉽고 편리하게 제보할 수 있도록 경기넷 홈페이지상에 "도지사에게 바란다", "공직자부조리신고", "수신자부담전용전화"를 지속적으로 운영한 결과 총 150여건이 접수되어 12명에 대해 신분상 조치를 취한 바 있습니다.  앞으로도 부조리 신고사항에 대하여는 진정 및 이해 관계인의 면담과 현지조사를 실시하여 민원을 적극적으로 해결하는 데 역점을 두고 지속적으로 관리해 나가는 한편 제보로 인한 불이익처분을 받지 않도록 철저한 보안을 유지하겠으며 음해성신고로 확인된 경우에는 진정인에게 충분히 설명하여 진정에 대한 오해의 소지를 불식해 나가고 해당 공무원이 보호되도록 노력해 나가겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 12쪽, 감사역량 제고에 대해서 보고드리겠습니다.  감사요원의 전문화와 정예화로 감사책임제를 확행해 나가는 동시에 감사능력 배양과 감사의 질적 수준향상을 도모하기 위해 도 및 시·군 감사공무원 110명을 대상으로 감사교육원 및 경기도지방공무원교육원 등 전문기관에 위탁교육을 실시한 바 있으며 금년 12월중 감사인의 자세와 사명감을 고취하기 위한 의식교육과 새로운 감사기법 개발을 위해 직무연찬회를 실시할 계획입니다.
</p>
<p style="padding-left:1.2em">  또한 감사행정의 전산화를 도입하여 종합감사시 지적된 각종 민원처리 실태와 인사, 세무 등 통계화가 가능한 분야는 전산화하여 감사의 효율성을 기하고 감사결과 비위발생 기관별, 양정별, 유형별로 분석하여 감사활동이 체계적으로 관리되도록 감사통계전산화를 추진하는 한편 반복 지적사항과 모범사례를 수립하여 감사사례집을 발간, 일선공무원의 업무수행에 도움이 되도록 조치할 계획입니다. 
</p>
<p style="padding-left:1.2em">  다음은 13쪽, 공직자재산등록심사에 대하여 보고드리겠습니다.  공직자 재산등록대상자에 대한 부동산 및 금융거래조회 등 재산등록심사를 강화하여 공직을 이용한 부정한 재산증식을 방지하고 엄정한 공직윤리를 확립하기 위해 공직자재산등록심사를 하고 있습니다.  금년도에 재산등록대상자는 공개대상자 102명과 비공개대상자 1,588명으로 총 1,690명입니다.  지난 1월말 재산등록 및 변동신고사항 접수를 완료하고 심사를 마친 상태이며 공개대상자 재산등록사항은 지난 2월 28일 경기도보에 공개한 바 있습니다.  앞으로 전산장비 서버구입 및 프로그램을 설치토록 하여 재산등록업무를 전산화하여 공직자 재산등록업무에 만전을 기하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  끝으로 14쪽 2000년 행정사무감사시 시정 및 건의사항 처리결과를 보고드리겠습니다.  2000년 행정사무감사시 위원님들께서 시정 7건, 건의 2건 등 총 9건에 대하여는 모두 조치완료하였음을 보고드리며, 처리결과에 대하여는 양해해 주신다면 유인물로 보고를 대신토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 감사관실 소관 2001년도 업무계획과 추진사항에 대한 보고를 모두 마치겠습니다.  이상입니다.
</p>
<p><br /></p>
<p>(업무보고서는 끝에 실음)
</p>
<p><br /></p>
<p><b>○ 위원장 김강선 </b> 감사관 수고하셨습니다.  다음은 감사 질의순서가 되겠습니다.  감사관은 발언대에 그대로 서주시기 바랍니다.  감사의 원활한 진행을 위하여 질의 및 답변은 일문일답으로 진행하도록 하겠습니다.  그럼 감사관실 소관사항에 대하여 질의하실 위원께서는 거수로 신청하여 주시기 바랍니다.  안 계십니까?  노시범 위원 질의하시기 바랍니다. 
</p>
<p><b>○ 노시범 위원 </b> 본 위원은 감사자료를 요구 안 했기 때문에 보고해 주신 내용에 대해서 몇 가지만 질의하겠습니다.  6쪽에 보면 정책감사 해가지고 재정투·융자사업 추진실태를 파악하셨는데 그 부분에 대해서 평가를 해주세요.  투·융자심사를 거쳐서 지금 시·군에서 하고 있는 사업들 중에서 어떻게 진행되고 있는지?
</p>
<p><b>○ 감사관 이진호 </b> 저희가 감사요구 자료에 그 동안 실시했던 정책감사에 대한 요약분을 자료로 제출하였습니다.  여기에 보면 각 시·군에서 특히 지금 노 위원님께서 말씀하신 재정투·융자사업에 있어서 10억원이상이면 재정투·융자사업심의위원회 검토를 받아서…….
</p>
<p><b>○ 노시범 위원 </b> 그러니까 요약해서 투·융자심사를 받은 사업들이 진행이 잘 되고 있느냐 아니면 부진하냐 거기에 대해서만 답을 해주세요.
</p>
<p><b>○ 감사관 이진호 </b> 시·군에서 전체적으로 봤을 때는 큰 무리없이 진행되고 있는 것으로 보이나 몇몇 시·군에 있어서는 문제가 좀 발생되는 것으로 이번 감사에 지적됐습니다.  그래서 그런 사항은 저희가 전부 해당 시·군에 처분했고 그런 부분에 대해서는 시장·군수들이 재검토할 수 있도록 저희가 조치한 바 있습니다. 
</p>
<p><b>○ 노시범 위원 </b> 지금 투·융자심사를 거쳐서 하고 있는 사업들이 대부분 잘 되고 있다라고 대답을 해주셨는데 우리가 정책기획관실 감사할 적에 두드러지게 나온 내용이지만 지지부진한 사업들이 상당히 많다 말이지요.  그래서 그것 때문에 질의했는데 감사관은 제대로 되고 있다라는 평을 해주셨는데 실제적으로 위원들이 파악하기에는 잘 안 되는 것으로 돼 있단 말이에요.  그래서 결론이 어떻게 났느냐?  투·융자심사 자체가 잘못되고 있는 게 아니겠느냐라고 결론이 났는데 감사관실에서 잘 되고 있다라고 답한다면 어떤 답이 맞는 거예요?
</p>
<p><b>○ 감사관 이진호 </b> 물론 전체가 다 잘못됐다라고 보기는 힘들고 저희가 지적한 사항이 금년도에 17개 시·군에 대해서 정책감사를 실시했습니다.  그 중에 저희가 여러 가지 지적한 바도 많습니다.  예를 들어서 군포시, 수원시, 안산, 평택, 이천, 가평, 화성, 광주에 대해서는 감사가 끝나서 저희가 결재까지 받았는데 그 중에 지금 말씀하신 각 시에서, 전체가 다 그렇다는 것은 아니고 저희가 지적된 사항이 여러 분야가 있습니다.  그래서 그 부분은 위원님께서 요구하시면 저희가 자료로써, 특히 재정투·융자사업에 대한 문제있는 사업 같은 것을 저희가 제출해 드리겠습니다. 
</p>
<p><b>○ 노시범 위원 </b> 그러면 13쪽에 공직자재산신고건에 대해서 하나 질의를 하겠는데 여기 결과를 보면 불성실신고자로 분류돼서 과태료를 부과한 사람이 2명이 된단 말이지요?
</p>
<p><b>○ 감사관 이진호 </b> 그렇습니다.
</p>
<p><b>○ 노시범 위원 </b> 누가 어떤 내용으로 부과되었는지 설명을 해주세요.
</p>
<p><b>○ 감사관 이진호 </b> 그 부분 명단공개는 관련법에 의해서 저희가 공개하기가 곤란한 부분입니다. 
</p>
<p><b>○ 노시범 위원 </b> 자료를 요구해도 공개 안 되요?
</p>
<p><b>○ 감사관 이진호 </b> 이 관련법이요…….
</p>
<p><b>○ 노시범 위원 </b> 그러면 됐고요.  어떤 내용이었어요? 
</p>
<p><b>○ 감사관 이진호 </b> 금융재산 누락시킨 부분이 2건 있습니다. 
</p>
<p><b>○ 노시범 위원 </b> 과태료는 얼마 정도 부과가 됐나요?
</p>
<p><b>○ 감사관 이진호 </b> 100만원하고 200만원입니다.
</p>
