<p><b>○ 연동현 위원 </b> 연천출신 연동현 위원입니다.  김효정 위원의 질의에 유사한 걸 질의토록 하겠습니다.  우리가 그동안 수해로 인해서 국가나 도로부터 수해복구에 관한 지원으로 개개인의 통장에 입금된 사례가 있지 않습니까?  그런데 그 당시에 보니까 A라는 사람한테 입금되어야 할 것이 전혀 관계없는 B나 C로 입금되는 사례가 있었어요.  그런데 그 당시에는 입금된 걸 모르고 인출을 안 했으니까 그렇지 알고서 인출해서 썼을 경우 그건 법적으로 어떻게 됩니까?  그 사람이 자기한테 입금되지 말았어야 되는 걸 썼으니까 다시 환원해야 되는 겁니까, 어떻게 되는 겁니까, 그런 사례는?
</p>
<p><b>○ 감사관 이진호 </b> 제 상식적인 생각으로는 잘못 입금된 금액에 대해서는 다시 회수조치하는 것으로 하고 본인이 그것을 알았을 경우는, 왜냐하면 엉뚱한 돈이 수천만원들어왔을 경우 쓰지 말아야 되는 걸 원칙으로 알고 있습니다.  나중에 본인이 썼더라도 저희가 회수조치할 수 있는…….
</p>
<p><b>○ 연동현 위원 </b> 법적으로 그렇게 되어 있습니까?  상식적인 생각으로 될 일이 아니죠.  그런 사례가 있었어요.
</p>
<p><b>○ 감사관 이진호 </b> 그거는 점유이탈물 횡령죄로 취급한다고 들었습니다. 
</p>
<p><b>○ 연동현 위원 </b> 그러면 알고서 썼으니까 그렇다 치더라도 그 통장이 자동이체통장으로 인해서 각종 세금이나 이런 게 모르고 빠져나갔을 경우 그런 경우는 어떻게 됩니까? 
</p>
<p><b>○ 감사관 이진호 </b> 그것은 정상참작이 되지 않을까요?
</p>
<p><b>○ 연동현 위원 </b> 물론 감사관실이니까 그걸 모를 수도 있지만 법무담당관실 때 그걸 했었어야 됐는데 지금 어차피 얘기가 되니까.  이게 우스운 얘기면서도, 예를 들어서 수해로 인해서 각종 시름에 빠져있는 사람이 이것저것 모르고 또 쓰고 났다고 환원된다는 얘기가 굉장히 어려운 얘기입니다.  감사를 다니면서 그런 사례를 적발한 경우는 없습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 그런 건은 적발한 사례가 없습니다. 
</p>
<p><b>○ 연동현 위원 </b> 왜냐하면 모르겠어요.  수해지역에서 그런 사례가 많았습니다.  앞으로 그런 일이 있으면 안 되겠지만 수해가 또 났을 경우 그해에 정책감사나 일상감사 나갔을 때 그런 부분에도 관심있게 봤으면 좋겠어요.
</p>
<p><b>○ 감사관 이진호 </b> 알겠습니다.  위원님 말씀대로 감사할 때 중점적으로…….
</p>
<p><b>○ 연동현 위원 </b> 그게 굉장히 민감한 부분이면서도, 아니 세상에 수해로 인해서 다 망가진 상태에서 그 돈이 들어와서 물론 알고 썼으면 지금 그런 사례도 저도 상식적으로는 있어서는 안 되겠지만 입금되는 통장이 공교롭게 각종 세금이나 이런 걸로 해서 자동으로 이체돼서 나갔을 경우에는 문제가 됩니다.  본인도 모르게 인출해 나간단 말이에요.  그럼 그거는 국가가 손해를 보든지 도가 손해를 보든지 해야지 개개인이 무슨 잘못이 있겠어요.  그 다음에 공무원 문책 재심청구현황에 대해서 자료요청한 게 있는데 2000년도에는 4건으로 공무원들의 문책이 재심청구가 됐어요.  거기에 대한 처리결과가 잘됐습니다마는 2001년도에도 정책감사나 일상감사가 상당히 많았습니다.  거의 31개 시·군을 다 한 걸로 되어 있고 그리고 일전에 감사관실 업무보고때도 제가 자료를 요구했던 것이 현재까지 감사는 행하고 왔지만 아직까지 처리중에 있기 때문에 자료가 안 나와서 못 받은 것도 있겠지만 제가 명단이 되어 있으면 명단을 지워서라도 어떠어떠한 사례로 인해서 각 시·군에 감사를 받은 이런 걸 서면으로 요구한 사례가 있거든요.  그 부분을 오늘 지금 당장은 필요없고 그 사례를 자료로 주시기 바라고 2001년도는 현재까지 재심청구한 사례가 없단 말입니다, 자료로 봐서는.  그런데 올해 감사는 상당히 많이 하셨어요.  공무원들이 당연하여 자기가 죄를 인정하는 겁니까?  경징계, 중징계도 많이 받았는데.
</p>
<p><b>○ 감사관 이진호 </b> 올해 감사를 많이 한 것은 사실인데요.  작년에 비해서 우선 상반기 감사보다도 수해·한해 때문에 하반기로 연기된 감사가 많았습니다.  그래서 9월부터 지금까지 계속 연이어서 감사를 하고 있는 관계로 아직 취합 정리가 안 된 부분이 많고 그래서 저희 처분요구라든지 안 한 부분이 있기 때문에 조금 그런 부분이 있을 것으로 저희가 이해가 되고요.  그리고 작년에 4건인데 올해는…….
</p>
<p><b>○ 연동현 위원 </b> 자료에는 올해가 없어요.
</p>
<p><b>○ 감사관 이진호 </b> 올해는 없습니다.
</p>
<p><b>○ 연동현 위원 </b> 그만큼 우리 감사관실에서 감사를 잘하신 걸로 볼 수밖에 없는데, 좋습니다.  다음 업무보고에 보면 감사기법을 개발하고 감사원교육원에서 교육도 많이 실시하고 하셨는데 우리가 관급공사 나갔을 때 입찰을 통해서 공무원들과 건설업자하고 뭔가 멘트가 돼가지고 보통 관급공사가 선급이 몇 %입니까?  1차 선급이.
</p>
<p><b>○ 감사관 이진호 </b> 50%가 선급금으로 지급됩니다. 
</p>
<p><b>○ 연동현 위원 </b> 선급이 50%입니까?  더 이상도 줄 수 있는 경우도 있죠?
</p>
<p><b>○ 감사관 이진호 </b> 요구하면 70%까지 줄 수가 있습니다. 
</p>
<p><b>○ 연동현 위원 </b> 입찰자가 요구하면요?
</p>
<p><b>○ 감사관 이진호 </b> 네.
</p>
<p><b>○ 연동현 위원 </b> 무슨 상위법에 되어 있는 겁니까, 건설법에?
</p>
<p><b>○ 감사관 이진호 </b> 건설기술관리법에 명시된 사항입니다. 
</p>
<p><b>○ 연동현 위원 </b> 70%까지 줄 수 있는데 보통 50%선에서 선급을 준다.  그러면 예를 들어서 70%까지 되어 있는데 50% 준다 그러면 20% 갭이 약간의 문제가 공무원과 업자하고 간에 뭔가 있을 수 있지 않겠어요?  그런 감사적발사항은 없습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 그런 사항은 아직 없습니다. 
</p>
<p><b>○ 연동현 위원 </b>  예를 들어서 70%까지인데 공무원이 업자한테 뭔가 약간의 로비성을 받기 위해서 내가 너 얼마까지 해줄테니까 어떻게 하라 그런 정도도 있을 수 있단 말입니다.  물론 의심을 해서는 안 되겠지만 그런 방향의 감사에 지적된 사례가 전혀 없다는 게 좀 그런데요.
</p>
<p><b>○ 감사관 이진호 </b> 50%에서 70%, 20% 더 주는 것은 명확한 나름대로의 인정할 수 있을 만한 근거라든지 확실한 뭔가 있어야 20%를 더 주지 그냥 50% 주는 건 아닌 걸로 알고 있거든요.  그래서 그런 사항에 대해서 위원님 말씀대로 저희가 차기감사 때 중점적으로…….
</p>
<p><b>○ 연동현 위원 </b> 예를 들어서 예산이 지출되고 그러면 그 부분이 몇 % 선급을 줬다라는 것까지 기재되어 있지 않습니까?  그러면 이것도 제가 건의드리는 거예요.  감사 나갔을 때 지금 맥시멈이 70%까지로 되어 있는데도 50%를 줄 수도 있고 30% 줄 수 있다는 얘기입니다.  그죠?
</p>
<p><b>○ 감사관 이진호 </b> 네.
</p>
<p><b>○ 연동현 위원 </b> 그러면 나름대로의 지금 관청의 용도계장이라고 합니까, 용도담당이라고 합니까? 
</p>
<p><b>○ 감사관 이진호 </b> 계약담당입니다.
</p>
<p><b>○ 연동현 위원 </b> 그럼 그 친구들이나 그쪽 측근 섹터에서 로비성 차원에서 충분히 있을 수 있습니다, 완력싸움에.  입찰은 어차피 공개입찰을 통해서 되지만 자기가 희망하는 사람이 아니고 이상한 사람이 됐을 때 이쪽에서 괴롭혀라 이럴 수도 있습니다, 속된 말로.  그러면 이 친구가 참 자기도 입찰에는 됐지만 자기가 이 사업성에, 물론 재무구조 다 보고 입찰자가 공개입찰에 응하겠습니다마는 자꾸 공무원하고 저기가 되면 다음에 2순위가 될 수도 있잖아요.  몰라요, 제가 나쁜 쪽으로 자꾸 생각해서 그런지 몰라도 분명히 그럴 수도 있다는 얘기지.
</p>
<p><b>○ 감사관 이진호 </b> 저희 감사관실도 부정적인 측면에서 접근해야 되는 건 당연하거든요.  그래서 우선 위원님 말씀대로 70% 준 사례가 시·군에 어느 정도 있는지 확인해 보고 감사시 저희가 참고사항으로 그런 부분을 중점적으로 보겠습니다. 
</p>
<p><b>○ 연동현 위원 </b> 이건 참고사항이 아니라 아주 민감하게 접근하고, 물론 자꾸 지적한다고 해서 될 일은 아니겠습니다마는 그런 걸 사전에 뿌리 뽑아줘야, 여기도 나와 있지만 성실시공이 그런 쪽에서 안 되는 거라고 거기서 빠지고 뭐 빠지고 그러면 되겠습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 알겠습니다.
</p>
<p><b>○ 연동현 위원 </b> 일단 현재 우리가 정책감사를 실시한 데도 그런 부분에 뭔가 멘트를 해 가지고 저한테 서면으로 주세요.
</p>
<p><b>○ 감사관 이진호 </b> 실태를 파악해서 자료 나오면 위원님께 보고드리겠습니다. 
</p>
<p><b>○ 연동현 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 연동현 위원 수고하셨습니다.  또 질의하실 위원 계십니까?  윤동욱 위원 질의하시기 바랍니다.
</p>
<p><b>○ 윤동욱 위원 </b> 남양주 출신 윤동욱 위원입니다.  간략하게 내가 질의한 사항을 가지고 몇 가지 질의하겠습니다.  감사자료 107쪽에 보면 다수민원에 대한 관련사항입니다.  2000년도에는 311건에서 2001년도에는 225건으로 줄어들었습니다.  이것은 굉장히 다행한 일이라고 생각되는데 그런데 이것은 뭐냐하면 그 일부 해결됐거나 해결불가로 처리된 사항이 전체 31%나 됩니다, 처리 안 된 것이.  이것은 여기에 종사하는 공무원들의 적극적인 해결 의지가 없거나 또는 미흡한 원인도 추인한 결과로 판단되는데 그 안 된 구체적인 사유가 뭡니까?  거기에 대한 답변 좀 해주십시오.
</p>
<p><b>○ 감사관 이진호 </b> 윤 위원님께서 말씀하신 다수민원에 대한 해결되지 않은 사례를 말씀하셨는데 저희가 사유를 분석해 봤습니다.  대부분이 수도권 지역의 택지개발사업 및 쓰레기소각장, 매립장, 장례시설 등 혐오시설 건설과 관련해서 들어온 지역이기주의 현상의 민원이 많습니다.  그래서 저희가 복잡 다양해져 가는 행정수요에 일일이 대처해 가는 것이 당연하겠지만 서로 첨예하게 대립되는 부분이라든지 아니면 지역이기주의적인 사항 때문에 저희가 못해주는 경우, 해결이 안 되는 경우가 종종 있었고요.  특히 이런 것을 위해서 저희가 공청회를 개최해 가지고 안 된다고 해서 무조건 안 되는 건 아니고 해결할 수 있는 방안을 여러 가지로 모색하고 있습니다.  그래서 그중에 안 되는 부분, 도저히 안 되는 부분을 저희가 불가로 분류했습니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 그런데 처리결과에 224건이 이송됐다고 자료에 나와 있는데 224건을 이송만 하는 걸로 임무가 다 끝나는 겁니까? 
</p>
<p><b>○ 감사관 이진호 </b> 이것은 시·군에 해당되는 사항은 물론 이제 도에서 처리할 것은 저희가 직접 처리하되 지역적인 사항이라든지 시장·군수 인허가사항 이런 것은 도에서 처리하기가 쉽지 않기 때문에 시장·군수한테 이송하고 또 타 기관에 관련되는 사항, 복합민원 이런 것은 타 기관에 이송해서 처리하고 있습니다.  그래서 이것은 저희가 이송이 되더라도 그냥 이송으로 끝나는 게 아니고 저희가 지속적으로 관리합니다.  다수민원대장이 있거든요.  추적해 가지고 계속 관리하고 있습니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 보고된 자료를 보면 이송하는 것으로 종료된 기분이 듭니다.  그런데 이게 사후추진을 어떻게 하는 것인지 이 내용을 구체적으로 듣고 싶어요.
</p>
