<p><b>○ 윤동욱 위원 </b> 그러니 경기도지사가 껍데기가 된단 말이야.  이것은 방금 건의를 하고 촉구를 한다니까 이러한 불필요한 위원회는 구성만 하고 활용 안 할 바에는 차라리 폐지시키는 게 낫다고 생각돼서 질의했습니다.  이것은 앞으로 빠른 시일내에 정말로 위촉했으면 위촉인이나 위촉받은 위원들이 일을 할 수 있는 여건을 조성해 주는 것이 바람직하다고는 생각에서 질의했고 또 한 가지 질의할 것은 행정소송을 제기하죠.  그러면 거기서 승소를 했어요.  그러면 공무원들이 잘못을 했기에 행정소송을 제기한 사람이 승소를 했을 경우 그 피해사항이 있단 말입니다.  행정소송을 제기하기까지 오는 동안 그 민원인은 굉장히 심적이나 재정적으로 많은 피해를 입고 있어요.  그런데 행정소송에서 승소를 했어요.  그러면 그 승소한 사람이 무엇 때문에 왜 여기까지 왔는지, 행정소송을 제기하게 됐는지 그 사항을 감사요구하면 감사를 해 주십니까?  내가 실례를 들을 게요.  어느 지역에서 가스충전소 허가를 해당 시·군에 제출했어요.  그랬더니 해당 시·군에서는 서류를 심사한 결과 내일모레 허가를 해 드리겠소 이렇게 구두로 약속을 받았어요.  그랬더니 2∼3일후에 허가는커녕 민원인 때문에 허가를 해 줄 수가 없다.  허가를 안 해줬어요.  그 내용을 알고 봤더니 같은 관내에 있는 업자가 해당공무원에게 압력을 가하는 거야.  그리고 그 지역동민들을 포섭해 가지고 방해적인 그런 공작을 했어요.  이 사람이 하도 답답하니까 행정소송을 제기해서 승소를 했어요.  이럴 경우에 어떻게 처리가 됩니까? 
