<p><b>○ 양태흥 위원 </b> 경기도가 감사를 많이 받는만큼 하급기관인 각 시·군에서도 감사를 많이 받을 것 아닙니까?  우리가 쉽게 청와대로부터 지방의회 감사까지 줄잡아 엄청납니다.  그래서 어떤 공직자하고 얘기를 하면 감사만 줄어들어도 일을 해먹겠다고 합니다.  감사관께서는 이 많은 감사 때문에 하급기관에서 업무를 보는데 지장을 초래할 수 있다라는 생각은 안 갖습니까? 
