<p><b>○ 감사관 이진호 </b> 저희는 시·군에 직접적으로 감사할 수 있는 차상급기관이기 때문에, 광역자치단체이기 때문에 저희는 기 계획된 감사라든지 취약시기에 감찰이라든지 활동을 줄이는 것은 조금 어려움이 없지는 않으나 특히 상급기관에서 시·군 단위까지 나와 가지고 감사·감찰한다는 것은 여러 가지 무리가 있고 지금 말씀하신 중복감사라든지 그 많은 감사를 하는데 시·군에서 소화시키기가 상당히 어려운 것은 사실입니다.  그래서 그런 부분은 저희가 상급기관하고 협의를 해서 가급적 줄여보려고 노력하고 있습니다. 
