<p><b>○ 감사관 이진호 </b> 보통 한 달 전부터, 물론 그전부터 준비는 하겠지만 한 달 전부터는 굉장히 비상이 걸리지 않을까 하는 생각이 듭니다.  저희도 12월 3일부터 행자부 감사를 받는데 한 달 전부터 계속 준비를 하고 있거든요.
