<p><b>○ 양태흥 위원 </b> 1년 365일 중에서 하급기관은 청와대 감사부터 불시감사, 각 단체감사까지 하려면 연중 감사준비하는 그런 부서가 따로 있어야 되지 않겠어요?
</p>
<p><b>○ 감사관 이진호 </b> 그런데 저희가 실시하는 정기감사는 그렇게 준비를 하더라도 나머지 감사원이라든지 청와대, 행자부에서 내려온 감사는 정기감사는 아니고 불시에 나와서 불시감사를 많이 하거든요, 그때그때 필요에 의해서.  
</p>
<p style="padding-left:1.2em">  그렇기 때문에 그렇게 준비과정은 많이 소요는 안 되고, 그렇지만 감사받는 기간만 따지더라도 상당한 부분이 감사를 받고 있습니다.  위원님 지적하셨듯이…….
</p>
<p><b>○ 양태흥 위원 </b> 제가 왜 이 말씀을 드리냐면 저는 시·군에 있어 봤습니다.  있으면서 감사도 해봤습니다만 민원인이 찾아왔을 때 해당 공직자가 많은 짜증을 냅니다.  "또 감사야 또, 이거 끝나면 또 있어" 그러니까 민원 대하는 데 신경질적으로 대한다 이거지요.  그래서 우리가 부르짖는 것은 "민원인한테 친절하게 하자, 품질좋은 행정서비스를 하자" 말로는 부르짖습니다.  실제 담당자는 그렇게 하고 싶어도 중복된 업무 때문에 할 수 없는 게 현실입니다.  그래서 이런 것들을 고칠 수 있는 길이 있어야 될 텐데 지금 감사관님 말씀대로라면 줄일 수 있는 방법이 없으면 이거 큰 일 아닙니까? 
</p>
<p style="padding-left:1.2em">  그리고 아까 지적하신 대로 제2청 소관을 제외한 나머지 21개 시·군의 감찰활동결과를 각 시·군별로 뽑아서 자료로 제출해 주시기 바랍니다.  이상입니다.
</p>
<p><b>○ 위원장 김강선 </b> 양태흥 위원 수고하셨습니다.  더 질의하실 위원 계십니까?  유영록 위원 질의하시기 바랍니다.
</p>
<p><b>○ 유영록 위원 </b> 유영록 위원입니다.  재산망실훼손사고처리건에 대해서 김포시 것이 3건이 있는데요…….
</p>
<p><b>○ 감사관 이진호 </b> 죄송하지만 다시 한 번 말씀해 주시겠습니까?
</p>
<p><b>○ 유영록 위원 </b> 재산망실훼손사고 처리한 건, 자료집 127쪽이요.
