<p><b>○ 감사관 이진호 </b> 네.
</p>
<p><b>○ 유영록 위원 </b> 이게 김포시 자체감사에서 지적사항이 돼서 처리한 건가요?  아니면 도에서 했나요?
</p>
<p><b>○ 감사관 이진호 </b> 해당 시·군에서 자체감사한 겁니다. 
</p>
<p><b>○ 유영록 위원 </b> 지금 이게 감사원에 망실통보가 되면 김포시에서 경기도로 올라오면 경기도에서는 그냥 경유만 시켜서 감사원으로 보내는 겁니까?
</p>
<p><b>○ 감사3담당 김일수 </b> 저희들도 의견을 붙여서 보냅니다. 
</p>
<p><b>○ 유영록 위원 </b> 대개 자체감사한 것에 대해서 크게 하는 건 없지요?  해당 공무원들이 이 건과 관련해서 저한테 민원을 많이 얘기했거든요.  사건이 종료되고 난 이후에, 감사원에 통보되고 난 이후에 했는데 이 양반들 얘기 들어보면 대체적으로 시에서 자체감사할 때 여기 관여했던 공직자들 의견은 거의 묵살하다시피 하면서 자체감사한 것으로 나와 있거든요.  그래서 자기 의견들은 반영 안 하고 감사부서에서 무조건 자기네들한테 책임을 지우는 형식으로 해서 올렸다는 그런 의견을 많이 얘기해요.  그런 것들이 개별 공무원에게는 상당히 엄청난 재산피해가 되는 건데 그런 것도 도에서 담당공무원들하고 얘기해 본 적이 있나요?  이렇게 올라왔을 때.  특히 재산망실훼손사고처리건에 대해서.  담당하시는 계장님…….
</p>
<p><b>○ 감사관 이진호 </b> 이 부분은 감사원에서 징계처분시에는, 특히 변상망실 같은 경우에는 자체 감사원에서 심의를 하고 있습니다.  이 부분에 변상조치할 것인지 아니면 징계를 중징계로 할 것인지 경징계로 할 것인지는 감사위원회에서 자체적으로 할 때 본인들, 지금 말씀하신 해당 공무원들에 대한 심의도 하는 것으로 제가 알고 있습니다. 
</p>
<p><b>○ 유영록 위원 </b> 중앙감사위원회에서…….
</p>
<p><b>○ 감사관 이진호 </b> 네.  하는 것으로 알고 있습니다. 
</p>
<p><b>○ 유영록 위원 </b> 담당공무원들 불러다가…….
</p>
<p><b>○ 감사관 이진호 </b> 불러다가 하든지 아니면 서류로 받든지 받는 것으로 알고 있습니다.  왜냐하면 금액 자체가 몇억 원씩 들어가고 이런 부분을, 그리고 이의신청도…….
</p>
<p><b>○ 유영록 위원 </b> 만약 감사원에서 망실통보가 결정돼서 해당자한테 통보가 될 거 아니예요?
</p>
<p><b>○ 감사관 이진호 </b> 네, 그렇습니다.
</p>
<p><b>○ 유영록 위원 </b> 그러면 그게 다시 해당 공무원들이 이의신청도 할 수 있는…….
</p>
<p><b>○ 감사관 이진호 </b> 이의신청도 가능합니다. 
</p>
<p><b>○ 유영록 위원 </b> 그것도 감사원에다 해야 될 것 아니예요?
</p>
<p><b>○ 감사관 이진호 </b> 그렇지요.  결정권한이 감사원에 있기 때문에 감사원에다 한 거지요.
</p>
<p><b>○ 유영록 위원 </b> 네, 알겠습니다.  이상입니다. 
