<p><b>○ 위원장 김강선 </b> 유영록 위원 수고하셨습니다.  이진용 위원 질의하시기 바랍니다. 
</p>
<p><b>○ 이진용 위원 </b> 대통령이 외유시에는 무슨 비리가 더 많이 일어납니까?  집무해태가 더 많이 일어납니까? 
</p>
<p><b>○ 감사관 이진호 </b> 아무래도 좀 해이해지지 않겠습니까?  저희도 지사님 나가신다고 그러면 공무원들이 자기도 모르게 해이해지는 그런 경우가 있거든요.  그래서 대통령 나가시면 공무원들의 기강이 해이해지지 않겠나 그런 생각이 들어서…….
</p>
<p><b>○ 이진용 위원 </b> 그럼 감사관님의 경우에 대통령이 외유할 때 해이해지는 그런 걸 느꼈습니까?  마음으로부터 솔직하게 말씀하시면.  제가 이런 질의를 드리는 의도는 대통령의 외유가 우리 도청이나 시·군 공무원들과는 별 관계가 없을 것 같은데 업무보고에 올라와서 형식적인 보고가 아닌가 이런 생각이 들어서…….
</p>
<p><b>○ 감사관 이진호 </b> 지금 감찰에 대해서 말씀하시는 거지요?  그런데 통상적으로 대통령 외유시에는 행자부에서 저희한테 특별지시가 내려옵니다.  그런 부분에 대해서는 감찰활동을 중점적으로 하고 처리결과를 자기네들한데 보고해 달라는, 위원님 말씀대로 시·군 공무원들이 대통령께서 외유하신다고 특별히 기강이 해이해지는 것은 없겠지만 나름대로…….
</p>
<p><b>○ 이진용 위원 </b> 이 내용은 지금 말씀하신 대로 별로 관계가 없는데 중앙에서 요구하니까 업무보고에 올라온 것 같은데 실제로 그런 경우가 있나 궁금해서 여쭙는 건데 그렇지는 않은 것 같네요. 
</p>
<p style="padding-left:1.2em">  해마다 업무보고시에 새로운 감사기법을 도입하고 개발한다는 이런 말씀이 있으셨는데 올해의 경우에 어떻습니까?  새로운 감사기법을 도입한 경우가 어떤 경우가 있었는지 아니면 우리 도 자체적으로 개발한 감사기법이 있었습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 올해 특별한 것은 우선 정책감사하면서 그 동안 해오지 않았던 부분을 저희가 시행함에 있어서 여러 가지 물론 시행착오라기보다도 어려운 점이 없지 않았고 그런 부분에 대해서 17개 기관에 대해서 정책감사를 하면서 여러 가지 저희가 많은 것을 배웠습니다.  그래서 정책감사를 어떤 차원에서 해야 가장 효과적이고 시·군에 부담도 덜어주면서 권고차원에서 시·군을 도와줄 것이냐, 소위 말해서 시·군에 나가서 지적하고 징계 주는 이런 차원보다도 실제적으로 시·군이, 물론 자기네들 입장에서 보는 차원하고 도에서 보는 차원이 틀리기 때문에 그런 부분을 저희가 알려줌으로 해서 긍정적인 효과도 들었다고 보고, 그 다음에 제가 와서는 가급적이면 고의성이 없으면 공무원들 징계하는 게 조금 문제가 있지 않느냐.  왜냐하면 직원들이 열심히 일하다 보면 과실도 있을 수 있고 그리고 또 자기네들이 하는 과정에 있어서 놓치는 경우도 있는데 그런 것을 일일이 다 잡아서 징계하면 공무원들을 결국 복지부동화시키지 않겠느냐 해가지고 과감히 관용하는 차원에서 고의성이 없는 부분은, 그 대신 고의성이 있다든지 하면 저희가 끝까지 추적해서 어떠한 경우라도 문책하는, 그것은 하나의 마인드지요.  생각전환, 그런 부분을 하고 있습니다. 
</p>
<p><b>○ 이진용 위원 </b> 제가 다음에 질의드릴 내용을 미리 답변해 주신 것 같아요.  지금 말씀하신 것은 감사방향을 그렇게 정책감사부분으로 중심을 옮겨가겠다는 말씀이시고 제가 여쭤보는 것은 이렇게 내놓을 만한 새로운 감사기법을 도입한 사례가 있는지 아니면 도 자체적으로 개발한 감사기법이 있는지를 여쭤봤는데 지금 자료가 있으시면 말씀해 주시지요.  없으시면 "없지만 앞으로 그렇게 해나가겠다" 이렇게 말씀해 주시면 됩니다.  
</p>
<p><b>○ 감사관 이진호 </b> 알겠습니다.  그렇게 하겠습니다.  노력을 지속적으로 하겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 지금 현 정부 들어와가지고 공공, 금융, 노사, 기업의 4대 부분의 개혁을 추진해 왔는데 그 가운데 공공부분의 개혁은 그 목적이 작고 효율적인 정부로 새로 태어나서 업무효율도 제고하고 또 대외적으로는 행정서비스를 제고해서 국민의 행정에 대한 만족도를 높이겠다는 그런 의도로 해왔습니다만 오히려 구조조정을 해오면서 공무원들은 사기가 떨어지고 행정서비스는 질적인 저하를 가져오지 않았나 이런 생각이 듭니다.  특히 감사와 관련해서는 비리가 고도화되고 또 정밀화되고 그 다음에 고액화되는 그런 경향이 주민들 사이에서 많이 얘기되고 있거든요.  그렇기 때문에 감사관실에서는 적은 인원 가지고 그런 부분에 대처하기 위해서는 새로운 감사기법을 많이 개발하고 도입해야 된다고 생각합니다.  깊이 생각해서 그런 방향으로 추진해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 감사관 이진호 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 조금 전에 말씀하셨습니다만 감사의 방향이 정책감사 쪽으로 중심이동이 되고 있습니다만 올해 처음 시도하셨잖아요?
</p>
<p><b>○ 감사관 이진호 </b> 네.
</p>
<p><b>○ 이진용 위원 </b> 그런데 그와 관련해서 정책감사만 해서 정책적인 방향만 제시하고 또 그 효율만 높이는 데 노력할 것이 아니라 그 효과를 거두기 위해서는 공직기강감찰이 같이 수반돼야 한다고 생각합니다.  그래서 일벌백계주의로 그렇게 나가지 않으면 이 비리는 계속해서 되풀이되지 않나 싶은데 지금 비리공무원들 징계양정을 보면 그런 효과를 거두기에 부족하지 않나 싶습니다.  자료에 보면 공직기강감찰이 2000년도에 중징계는 없고 경징계 17명, 그 다음에 훈계나 경고가 76명, 2001년도에는 중징계 3명, 경징계 14명, 훈계나 경고가 65명 이렇게 나왔거든요.  그런데 징계공무원 현황을 보면 ''99년도에 561명에서 작년에 354명으로 줄었고 올해 전반기까지 집계한 것이 62명으로 나왔습니다만 최근 자료가 어떻게 되지요?  최근에 올해 징계공무원이 몇 분이나 됩니까?  10월말까지 자료가 있으면 얘기해 주시지요.
</p>
<p><b>○ 감사관 이진호 </b> 2001년도 상반기가…….
</p>
<p><b>○ 이진용 위원 </b> 상반기는 62건으로 나와 있습니다만…….
</p>
<p><b>○ 감사관 이진호 </b> 아까 제가 서두에 잠깐 말씀드렸습니다만 3분의 2이상 감사가 전부 하반기에 쏠려있어서 아직 취합 정리되지 않은 부분이 상당수가 있습니다. 
</p>
<p><b>○ 이진용 위원 </b> 자료를 저희가 요구했을 때 최근자료를 주셨으면 감사하는 데 도움이 많이 됐을 텐데 전반기까지 나왔기 때문에 단순비교는 어려울 것 같습니다.  다만, 추정을 한다고 그러면 근 3년간 상당히 대폭적으로 공무원이 징계받은 수가 줄어들은 것으로 봐서는 공직풍토가 상당히, 공직기강이 확립되어가고 있지 않나 이런 것을 추정할 수가 있는데 이 효과를 좀더 확실하게 시급히 도민들의 요구에 부응하기 위해서는 아까 말씀드린 대로 일벌백계로 정말 다시 근무할 수 없을 정도의 일을 저지른 분들은 그렇게 따끔하게 혼을 내서 공직풍토를 개선해 나가는 효과를 확실하게 거뒀으면 좋겠습니다.  지금 금품수수의 경우도 ''99년도에 85명에서 2000년도에 33명, 2001년도에 8명으로 아주 대폭적으로 줄어들고 있습니다.  이것은 여러분들이 그 동안 감사활동을 열심히 하고 있다는 증거로 생각합니다.  그러나 그 효과를 좀더 확실하게, 시급하게 거두기 위해서는 말씀드린 그런 부분들을 참고해 주셨으면 좋겠다는 이런 건의를 드립니다.  
</p>
<p><b>○ 감사관 이진호 </b> 알겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그 다음에 팔당상수원관련 감사가 1999년도에 있고 2000년도, 2001년도에는 없었는데 감사가 없어진 겁니까?  아니면 다른 부분으로…….
</p>
<p><b>○ 감사관 이진호 </b> 그때는 7개 기관에 그게 지속적으로 감사한 게 아니라 부분감사로 저희가 한 것으로 기억합니다.  정기감사가 아니고……. 
</p>
<p><b>○ 이진용 위원 </b> 그런데 작년하고 올해는 그런 부분에 비슷한 감사도 없었습니까, 상수원 관련해서요?
</p>
<p><b>○ 감사관 이진호 </b> 없었습니다. 
</p>
<p><b>○ 이진용 위원 </b> 제가 상수원지역에 있는데 규제의 정도로 봐서는 어느 정도 감사가 필요하지 않았나 싶은데 어떻게……. 
</p>
<p><b>○ 감사관 이진호 </b> 필요에 의해서 저희가 만약에 위원님께서 지적해 주신 대로 그런 부분이 필요하다면 부분감사를 실시하겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 지금 필요성을 느끼지 않을 정도로 그 지역에서 잘 하고 있다는 소리네요, 지역주민들이.
</p>
<p><b>○ 감사관 이진호 </b> 그리고 참고로 말씀드리면 저희도 마찬가지지만 감사원에서 지속적으로 하고 그 다음에 환경감시원이 발족돼서 계속, 하여튼 저희도 한번 판단해 보겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 아니, 하라는 말씀은 아닌데 지금 말씀 들어보면 한강환경감시대가 상당히 역할을 하고 있는 것 같네요, 시·군하고.  그렇게 해서 도에서까지 감사할 필요를 최근에 느끼지 못했다 이렇게 정리하면 되겠지요? 
</p>
<p><b>○ 감사관 이진호 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이진용 위원 </b> 광주시를 감사하면서 한강수계관리기금 주민지원사업 추진실태를 조사하셨는데 광주시 감사자료가 없어요, 여기 자료에 보면.  어떻게 사용되고 있습니까, 주민지원사업비가? 
</p>
<p><b>○ 감사관 이진호 </b> 팔당상수원기금 말씀하시는 겁니까? 
</p>
<p><b>○ 이진용 위원 </b> 네.  담당하시는 분 계시면…….  감사자료에 그 부분이 빠져 있습니다. 
</p>
<p><b>○ 감사관 이진호 </b> 그 부분은 저희가 정책감사한 자료가 있습니다.  그래서 만약에 필요하시면 저희가 그 자료를…….
</p>
<p><b>○ 이진용 위원 </b> 감사하면서 답변을 바로바로 주셔야 감사가 되지 끝난 다음에 자료 주시면 감사가 되나요?
</p>
<p><b>○ 감사관 이진호 </b> 이게 아까 잠깐 말씀드렸다시피 너무 많이 밀려있다보니까 취합 정리가 덜 돼서 제출할 당시에는 결재가 안 나서……. 
</p>
<p><b>○ 이진용 위원 </b> 간단하게 말씀해 주시지요, 어떻게 사용되고 있는지.  또 그 법에 어긋나게 사용되고 있는 경우가 어떤 건지. 
</p>
<p><b>○ 감사관 이진호 </b> 우선 한강수계관리기금 운용실태에 있어서 지원사업이 주는 소득증대사업, 복지증진사업, 육영사업, 오염물질정화사업, 직접지원사업 등에 지원해 주게 돼 있습니다.  그래서 2001년도 예산액이 총 128억 2,200만원을 저희가 지원을 해줬습니다.  소득증대사업, 아까 말씀드린 그런 사업에 했는데 위원님께서 지적하신…….
</p>
<p><b>○ 이진용 위원 </b> 구체적으로 어떤 부분에 사용됐다, 위법적인 경우는 어떻게 어떻다 
</p>
<p>간략하게 얘기해 주십시오. 
</p>
<p><b>○ 감사관 이진호 </b> 예를 들어서 말씀드리겠습니다.  소득증대사업의 경우는 이게 원래는 마을공동의 소득증대사업으로 이것을 지출해야 됨에도 불구하고 개인별로 비닐하우스 설치 활용하는 데 쓰는 사례가 있고요.  이것은 이번에 나가서 지적했고요.  그 다음에 복지증진사업 같은 경우는 마을회관, 사회복지회관을 건립하는 데 있어서 시장·군수 명의로 소유권을 해야 됨에도 불구하고 새마을회 명의로 이걸 건립하는 그런 사례도 저희가 지적했고요.  육영사업 같은 경우는 예를 들어서 복지증진사업으로 유선 설치, 수세식 화장실 설치, 집적지원사업인 주택개량 등으로 수해를 입은 경우가 있는데 이런 부분이 주민간 형평성이 결여된 부분을 저희가 발견했습니다.  그밖에 직접지원사업으로 해서 눈·비로 인한 누전 등 이런 부분에서 사후관리가 매우 미흡하게 기금지출한 경우도 있고 심야보일러를 부당하게 설치해서 지원받은 경우도 있고, 그 다음에 면사무소와 협의없이 선시공하고 대금은 그 후에 지급하는, 부적정하게 회계시설을 설치하는 경우가 다수 발생됐습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그렇게 돼서 부적정하게 사용된 경우에는 어떻게 조치했습니까?  그 첫 번째 사례의 경우 개인적인 용도로 사용했다고 했나요?  
</p>
<p><b>○ 감사관 이진호 </b> 개인적으로 한 것은 저희가 회수조치하는 것으로 시·군에 통보했습니다.  그 다음에 아까 지적한 그런 사항을 도 환경국장하고 광주시장 등에게는 추후에 시정조치하고 이런 사례가 발생치 않도록 저희가 조치했습니다. 
</p>
<p><b>○ 이진용 위원 </b> 네, 알겠습니다.  위법적인 사례로 보통 어떤 경우에 사용됐는지 자료로 제출해 주시기 바랍니다. 
</p>
<p><b>○ 감사관 이진호 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그 다음에 주민감사청구제가 청구한 내용이 없잖아요?
</p>
<p><b>○ 감사관 이진호 </b> 그렇습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그 이유가 감사청구요건 중 공익을 현저히 해야 한다는 말이 구체적인 기준이 되지 못해서 그랬다고 하셨고 그 다음에 청구연서명 주민수가 비현실적으로 많기 때문에 그랬다고 했는데 그런 부분에 대해서는 어떻게 대처하고 계십니까?  시간을 줄이기 위해서 제가 직접 질의를 여쭙겠습니다.  공익을 현저히 해야 한다는 부분에 대해서 개선요청을 한 적이 있습니까?  법 개정이나 아니면 지침을 개정한다든지 해서 기준을 구체적으로 하려는 노력이 있었습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 금년도 5월 3일 지금 말씀하신 그런 부분에 대해서 행자부에 저희가 건의를 하였습니다. 
</p>
<p><b>○ 이진용 위원 </b> 답변을 어떻게 해왔습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 답변은 아직 오지 않았습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그러면 5월 30일, 너무 시간이 오래 걸렸으니까 다시 한 번 촉구해서 그런 구체적인 기준을 마련하도록 하시고요.  그 다음에 주민수가 과천시 경우에는 100명이니까 충분히 그정도면 될 거라고 생각되는데 다른 시·군의 경우에는 몇백 명씩 되니까 하지 못하고 있잖아요?  주민들이 주민감사청구의 필요성을 느끼지 못하기 때문에 그럴 수도 있지만 필요성이 있는데도 불구하고 비현실적인 제도 때문에 그럴 수 있는데 이런 부분들은 어떻게 지도를 한 적이 있습니까?  
</p>
<p><b>○ 감사관 이진호 </b> 그래서 이것은 말씀하신 그 인원수에 대해서는 시·군조례가 정하는 주민수 이상으로 연서를 해야 되는 그런 부분이 있기 때문에 저희가 지금 위원님 말씀대로 그런 전반적인 사항은 지금 말씀하신 과천 100명, 포천 1,000명 이렇게 돼 있는데 그것을 전체적으로 검토를 해보겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 정책감사가 그런 부분에 대해서 지도가 있어야 되니까 제가 볼 때는 감사원실에서 신경을 쓸만한 일이 아닌가 싶습니다. 
</p>
<p style="padding-left:1.2em">  다음에 민간인 감사참여 현황과 효과에 대해서 자료에 쭉 나왔습니다.  2000년도부터 2001년까지 정책감사하고 17개 시·군 감사, 또 평택호수계감사 등에 민간인들이 참여했는데 현황은 여기 자료에 나와있고 효과는 어떻습니까?  또 향후에 계속 더 늘려나갈 방침인지 그런 대책에 대해서 말씀해 주십시오. 
</p>
<p><b>○ 감사관 이진호 </b> 특히 정책감사 이번에 상당히 많은 도움을 받았습니다.  그리고 특히 도움을 많이 받은 부분은 저희는 하나의 실적으로 나타난 현상에 대해서 접근하지만 그 사람들은 나름대로 하나의 이론 플러스 저희하고 접목시키니까 그 부분에 대해서 상당히 효과가 컸는데 추후에도 앞으로 민간인부분에 대해서는 확대를 해서 저희가 도움을 많이 받을까 생각하고 있습니다. 
</p>
<p><b>○ 이진용 위원 </b> 알겠습니다.  질의는 끝났고 부탁드리고 싶은 것은 현재 4대부분의 개혁에 대해서는 그 필요성을 우리 국민들이 그 동안 계속 느껴왔던 거거든요.  한 20∼30년 동안 그런 부분에 대한 개혁의지가 국민들 사이에 팽배했었는데 그런 것들이 정작 시행이 되다보니까 여러 가지 문제점들이 생겨서 그 효과를 충분히 내지 못하고 있는 것 같습니다.  우리 감사관실에서 그런 개혁의 효과가 도민들에게 돌아갈 수 있도록 감사의 방향에 참고해 주시기를 각별히 부탁드리면서 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 이진용 위원 수고하셨습니다.  더 질의하실 위원 계십니까?  유영록 위원 질의하시기 바랍니다. 
</p>
<p><b>○ 유영록 위원 </b> 유영록 위원입니다.  징계공무원 현황이 자료집 116쪽부터인데 2000년, 2001년도 보면 금품수수, 횡령, 유용 이런 건들은 도 자체감사에서 발견한 겁니까 아니면 검찰이나 경찰의 사법 당국에 의해서 수사결과상 발견된 겁니까? 
</p>
<p><b>○ 감사관 이진호 </b> 이게 전부 모든 걸 취합해서 시·군, 자체, 도, 검찰 전체적으로 취합해서 나온 통계치입니다. 
</p>
<p><b>○ 유영록 위원 </b> 전체, 분류별로는 없고요?  주로 무슨 무사안일이나 업무부당 이런 것들은 일선 시·군감사실이나 아니면 도 감사관실에서 하는데 특히 금품수수, 횡령, 유용한 부분도 상당 부분 자체감사나 경기도 감사에서 적발이 됐나요?
</p>
<p><b>○ 감사관 이진호 </b> 특히 횡령, 유용 같은 경우는 저희가 회계감사를 하면서 많이 적발되는 부분입니다.  그리고 금품수수 같은 경우는 별도의 기동감찰이나 특별감찰활동시에, 보통 정기감사시에는 금품수수가 발견되는 사례는 거의 드물고 특별감찰활동시에 지적되는 경우가 많습니다. 
</p>
<p><b>○ 유영록 위원 </b> 그럼 그거에 대한 시·군감사에서 몇 %하고 분류해서 자료로 제출해 주시고요.
</p>
<p><b>○ 감사관 이진호 </b> 분류해서 드리겠습니다. 
</p>
<p><b>○ 유영록 위원 </b> 그 다음에 올해 저희가 감사하는데 정책감사하고 시민단체나 민간인들 감사할 때 도입한 그 부분에 대해서 경기도 감사관실에서 특별히 새로운 감사방법이었다 이렇게 평가되는데 지금 저희도 행정사무감사를 하고 있지만 경기도 감사관실에서도 앞으로 감사를 효율적으로 또 능동적으로 대처하기 위해서 연찬회 같은 것을 많이 갖고 있는데 지난번에도 제가 말씀드렸듯이 선진지, 선진외국의 감찰활동에 대한 계획이 있는지?  그것은 아직 없습니까? 
</p>
<p><b>○ 감사관 이진호 </b> 지난번에 말씀을 주셔서 저희가 이번 예산에 2002년도에 생각을 안 해 본 것은 아닌데 그래서 저희는 매년 1, 2회 정도는 감사담당관 아니면 감사부서 직원, 관련부서 직원들 연찬회를 하거든요.  물론 그렇게 되면 선진지에 대한 그런 것을 도입하기에 어려운 부분은 없지 않겠지만 저희가 한번 고려를 해보겠습니다. 
</p>
<p><b>○ 유영록 위원 </b> 이게 다른 부서별로는 그런 것들이 많은데 감사부분에 대해서는 그런 것이 전혀 없는 것 같아요.  또 우리나라 여건상 감사부분이 집행부의 직속기관으로 돼 있기 때문에 다른 어떤 선진국의 감사실태를 우리가 보는 것도 아마 저는 특별히 도움이 되리라고 생각합니다.  그래서 이런 것도 감사관실에 여태까지는 한 번도 없었는데 그런 것들은 전향적으로 검토할 필요가 있고 우리 위원회에서도 전향적으로 검토를 하겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 수고하셨습니다.  다음 질의하실 분 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시므로 이상으로 감사관실 소관사항에 대한 질의와 답변을 마치도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분께서 장시간 열의를 갖고 감사에 임해 주신 데 대하여 감사드리며 아울러 집행부 관계공무원 여러분께도 행정사무감사를 위한 자료준비와 위원님들의 질의에 성의를 다해 답변해 주신 데 대해 감사드립니다.  오늘 여러 위원님들께서 감사에 지적해 주신 사항은 도민의 뜻이니 만큼 이를 겸허하게 받아들여 도정에 적극 반영토록 하고 개선요구사항에 대하여는 조속히 시정될 수 있도록 최선의 노력을 다해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분!  그리고 관계공무원 여러분!  수고하셨습니다.  그러면 이상으로 감사관실에 대한 2001년도 행정사무감사 종료를 선언합니다. 
</p>
<p class=''ar''>(16시15분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>김강선유영록김효정연동현윤동욱이진용양태흥노시범</p>
<p><b>○ 행정사무감사보조공무원
</b></p>
<p><p class=''em15''>전문위원 오태철지방행정주사 조한경지방행정주사보 엄지영</p>
<p><p class=''em15''>지방기능8급 김혜련지방기능8급 정지연</p>
<p><b>○ 출석공무원
</b></p>
<p><p class=''em15''>감사관 이진호</p>
<p><b>○ 출석증인
</b></p>
<p><p class=''em15''>경기개발연구원장 노춘희기획조정실장 조응래사무처장 유지준</p>
<p><p class=''em15''>도시경영연구부장 김동성도시지역계획부장 이상대교통정책연구부장 지우석</p>
<p><p class=''em15''>환경연구부장 이양주지식산업연구부장 김군수사회개발연구부장 김흥식</p>
                <!--// 회의록내용 --> 

            <p class="skip">맨위로 이동</p>

            <div','경기도의회',false,'{"legacy_id": "audit-4588", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4588"}'::jsonb,'2001-11-26'::date,'2001-11-26'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4588');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2000.11.23. 목요일] 경기개발연구원 — 기획위원회 2000년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 2000년도 행정사무감사(2000. 11. 21. ~ 2000. 11. 30.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4643" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2000년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제3호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2000년 11월 23일(목)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시35분 감사개시)
</p>
<p><b>○ 위원장 김강선 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례 제2조 규정에 의하여 경기개발연구원에 대한 2000년도 행정사무감사 실시를 선언합니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분!  안녕하십니까?  기획위원회 감사위원장 김강선입니다.  오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  
</p>
<p style="padding-left:1.2em">  여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2001년도 예산안 심사를 위한 자료로 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기를 바랍니다. 
</p>
<p style="padding-left:1.2em">  감사위원 여러분께서도 연일 계속되는 감사일정으로 노고가 많으십니다마는 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부문별로 심도있게 질의하시어 소기의 성과를 거둘 수 있게 되기를 당부드리면서 원활한 감사진행을 위하여 많은 협조가 있으시기를 바라겠습니다.  끝으로 행정사무감사 준비를 위하여 애써 주신 연구원 임직원 여러분께도 감사와 격려의 말씀을 드립니다.  
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기개발연구원장 및 실·부장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2000년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.
</p>
<p style="padding-left:1.2em">  만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만원이하의 과태료가 부과될 수 있음을 알러드립니다.  그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (기    립)
</p>
<p style="padding-left:1.2em">  먼저 증인출석 여부를 확인하겠습니다.  경기개발연구원장 나오셨습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네, 나왔습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 행정실장 나오셨습니까? 
</p>
<p><b>○ 행정실장 심무섭 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 기획조정연구부장 나오셨습니까? 
</p>
<p><b>○ 기획조정연구부장 양기용 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 도시경영연구부장 나오셨습니까? 
</p>
<p><b>○ 도시경영연구부장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 도시지역계획부장 나오셨습니까? 
</p>
<p><b>○ 도시지역계획부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 교통정책연구부장 나오셨습니까? 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 지식산업연구부장 나오셨습니까? 
</p>
<p><b>○ 지식산업연구부장 이기영 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 사회개발연구부장 나오셨습니까? 
</p>
<p><b>○ 사회개발연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 환경연구부장 나오셨습니까? 
</p>
<p><b>○ 환경연구부장 성현찬 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 다음은 선서의 요령을 설명드리겠습니다.  선서는 증인을 대표해서 경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 오른손만 들어주시면 되겠습니다.  그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법시행령 제16조제1항 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 소관업무에 대한 2000년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령 제17조의4제5항과 경기도의회행정사무감사및조사에관한조례 제16조의 규정에 의하여 양심에 따라 숨김과 보탬없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''>2000년 11월 23일 증인 경기개발연구원장 노춘희.
</p>
<p><b>○ 위원장 김강선 </b> 자리에 앉아 주시기 바랍니다.  
</p>
<p style="padding-left:2.4em">    (착    석)
</p>
<p style="padding-left:1.2em">  그러면 경기개발연구원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다.  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 안녕하십니까?  경기개발연구원장 노춘희입니다.  존경하는 김강선 위원장님과 위원 여러분!  연일 계속되는 바쁘신 의정활동에도 불구하시고 우리 연구원의 금년도 주요업무 추진상황과 내년도 연구사업계획을 보고드리게 된 것을 감사하게 생각합니다.  우리 연구원의 간부를 먼저 소개해 드리면 유인물을 중심으로 보고드리겠습니다. 
</p>
<p style="padding-left:1.2em">  우선 유훈 상임고문님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  다음 심무섭 행정실장님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  다음 양기용 기획조정부장님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  다음 신원득 도시경영연구부장님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  이상대 도시지역계획부장님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  조응래 교통정책연구부장님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  성현찬 환경연구부장님.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  이기영 지식산업연구부장님. 
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 김흥식 사회개발연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  지금부터 우리 연구원의 주요업무보고를 드리겠습니다.  먼저 유인물을 바탕으로 일반현황, 재정운용, 2000년 연구사업추진상황 및 2001년도 연구사업계획을 보고드리고 위원님들이 양해해 주시면 저희 연구원에서 중점적으로 추진하고 있는 연구사업을 기획조정부장인 양기용 박사님께서 프로젝트를 이용하여 보고드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  유인물 1페이지 일반현황에서 저희 연구원은 ''95년에 개원하여 이제 개원한 지 5년이 되었습니다.  그 동안 여러 위원님들의 성원으로 ''99년 11월 25일 현 독립청사를 마련하였습니다.  금년 1월 10일 지방자치단체출연연구원의설립운영에관한법률과 7월 10일 동법시행령이 공포되어 저희 연구원의 설립근거가 도 조례에서 특별법으로 격상 운영하게 되었습니다.  이는 그간 지방자치단체 제도의 발전을 위하여 여러 위원님들께서 음양으로 도와 주신 덕으로 지방연구원이 국책연구원과 동등하게 경쟁할 수 있는 제도적 기틀을 마련하게 되었습니다.  연구원의 주요기능으로서는 도정의 비전제시와 지식기반정책 개발을 위하여 도시연구 등 7개 연구가 다양하게, 깊이 있는 전문적인 연구를 수행하고 있으며 보다 자세한 사항은 유인물로 참고해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 2페이지입니다.  본원의 기구는 표에서와 같이 7연구부 2개과로 구성되어 있습니다.  현재 인력으로서는 박사급 연구원 25명을 포함해 44명이 재직하고 있습니다.  참고로 연구직은 해외 학위취득이 14명, 국내 학위취득이 11명이 되겠습니다.  전공분야별로는 도시 및 지역계획 관련 분야가 8명, 환경분야 6명, 행정학분야 5명, 경제학분야가 3명, 그외 관광, 사회복지 등 분야가 되겠습니다.  연구에 필요한 전문분야를 골고루 갖추고 있어 어느 정도 종합적인 도정연구업무를 수행 가능하게 하고 있습니다.  부족한 전문수요 분야에는 초빙연구원이나 비상임연구원 등 외부 전문가를 위촉 활용하고 있습니다.  특히 전반적인 연구의 자문을 위하여 분야별로 460명의 두뇌핵부를 별도로 관리하고 보다 더 충실한 연구결과물과 생산이 되도록 노력하고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 3페이지의 시설 및 물자현황을 보고드리겠습니다.  먼저 본 청사는 대지 894평에 건평 823평으로 앞에서 보고드린 바와 같습니다.  지난 해 한국지방행정연구원으로부터 45억원에 3년 분할 상환분으로 매입하였습니다.  내년도에 12억원을 지급하면 청사구입 비용을 완납하게 됩니다.  연구에 필요한 장서는 1만 6,000권 정도를 보유하고 있으며 주로 최신 국내외 전문서적 및 경기도 관련자료로 구성되어 있습니다. 
</p>
<p style="padding-left:1.2em">  또한 저희 연구원의 자료실은 일반시민, 학생, 공무원은 물론 사계 전문가에 이르기까지 언제든지 방문하여 이용이 가능하도록 개방되어 있으며 본원 홈페이지를 통해서 소장자료에 의한 검색뿐만 아니라 신간자료에 대한 정보를 제공하고 있습니다.  정보지식의 공유를 확대하고 보다 질 높은 서비스를 제공하고 있습니다.  앞으로도 보다 다양한 정보서비스를 제공하여 경기도 연구의 메카가 될 수 있도록 노력하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 4페이지 재정운용현황을 보고드리겠습니다.  먼저 일반회계 예산규모는 전년대비 8억 7,600만원이 감소한 69억 5,500만원입니다.  주요세입 재원으로는 전입금이 11억 1,100만원이고 환급금이 4억 8,600만원, 이월금이 11억 100만원, 수탁용역사업수입이 2억 5,700만원, 도비보조가 39억원입니다.  주요세출항목은 연구사업비가 전체 60%인 41억원, 청사구입 13억원을 포함하여 청사유지비가 15억 7,000만원입니다.  기관운영비가 8억 9,400만원으로 되어 있습니다.  예산집행에 있어서는 알찬 연구가 수행될 수 있는 여건조성으로 내실있는 운영을 할 수 있도록 최선을 다하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 5페이지의 기금운용현황을 말씀드리겠습니다.  총 기금조성액이 206억원이고 그중 67%인 1,037억원을 도에서, 나머지 39억원은 시·군에서 출연하였으며 2개 은행에 출연금과 자체적립금으로 구성되어 있습니다.  기금예치현황은 우선적으로 기금의 안전성을 감안하여 이자율 및 예금의 종류별로 분산예치를 원칙으로 하고 있습니다.  표에서 보시는 바와 같이 현재 기금 206억원은 5개 은행 15개종의 상품으로 적립되어 있습니다.  앞으로 기금의 안전을 최우선적으로 고려하여 관리하도록 하겠습니다.  
</p>
<p style="padding-left:1.2em">  이어서 6페이지부터 14페이지까지 2000년도 연구사업추진 현황을 총괄적으로 보고드리겠습니다.  우선 금년도 연구사업의 중점 추진사항별로 보면 도정수요에 능동적으로 대응하여 실천성 높은 정책대안을 개발하기 위해 광역도시권 설정과 함께 경기도의 계획고권을 확보하고 접경지원법 시행령 초안 및 평택항 관세자유지역 지정요건 완화 방안을 수립하여 정책에 반영하였습니다.  그리고 일찍이 먼저 지식기반산업의 육성을 위한 비전과 실천전략을 제시하여 경기도 지식기반산업 발전전략 등의 수립을 위한 도 정책방향을 바로 잡아가고 있습니다.  도민의 삶의 질을 위해 환경, 복지정책 개발을 위해 경기도 경관관리 기본계획과 복지시설 평가제도 도입에 따른 운영개선 방안 등을 수립하였습니다. 
</p>
<p style="padding-left:1.2em">  또한 대외협력강화를 위한 연구원의 위상을 제고하기 위해 도, 시·군은 물론 감사원, 총리실, 건교부 등의 중앙부처로부터 개발제한구역제도와 조정기준의 문제점 및 대책 등의 수탁사업을 연구하였습니다.  특히 국책연구원 및 시·도 연구원간의 수도권광역도시계획 등의 공동연구과제를 수행하여 상호간의 공동협력을 증진함으로써 연구원의 위상을 제고하였습니다.  나아가서는 국제적인 공동연구기관으로서 영국의 이 CURS와 미국의 RPA, APA, ICMA, 캐나다의 캐나다연구원 그리고 물관계에 관해서는 블란서의 VIVIND, 네덜란드의 DHV, 벨기에의 IMDC 등 여러 연구기관과 공동연구를 하고 있다는 것을 말씀드립니다.  한편 금년 10월 30일까지 약 16억원의 신규 수탁과제 22건을 수주하는 등 적극적인 수주활동을 통하여 연구원의 운영비를 확충하고 있습니다. 
</p>
<p style="padding-left:1.2em">  연구원의 연구사업별로 추진사항을 보고드리면 자체연구사업은 경기도와 도의회로부터 추천받은 과제를 중심으로 경기도환경산업육성방안 등 25개의 기본과제를 수행하고 있으며 수탁연구과제는 ''99년도 이월된 17건을, 금년도에 신규위탁사업으로서 22건을 포함한 39건 중 음식물 감량화기 적정성 분석 등 18건을 완료했고 경기도 도로정비계획 등 21건을 추진 중에 있습니다.  긴급한 도정현황에 관련된 단기정책 연구과제는 ''99년도에 이월된 2건과 금년도에 신규 의뢰받은 21건을 포함한 23건이 연구 중이며 접경지역지원법시행령 제정방안 등 15개를 완료했습니다. 
</p>
<p style="padding-left:1.2em">  그리고 평택항 관세자유지역 지정방안 등 8건을 수행 중에 있습니다.  또한 경기도내 소하천 관리를 위한 기초연구용역 등 12개의 위탁연구 중에서 지식기반산업단지 공간계획부문 기술용역 등 2건을 완료했고 나머지 10건은 금년도에 완료할 예정입니다.  평택시 및 가평군을 대상으로 하는 지역연구는 금년말에 마무리할 예정입니다.  연구원이 발행하고 있는 경기연구 등 6종의 정기간행물 중 경기논단 등 5종의 간행물을 정기적으로 발행하고 있으면 경기연구는 연말에 발간할 예정입니다. 
</p>
<p style="padding-left:1.2em">  그리고 도의 정책개발에 도움이 될 수 있는 외국의 중요도서 중 지방정부의 전략적 계획을 비롯한 4종의 번역사업을 추진 중입니다.  그리고 21세기 장기비전 세미나 등 도정의 현안과 관련된 정책세미나 및 워크숍을 16회 개최하였습니다. 
</p>
<p style="padding-left:1.2em">  이와 같은 연구원의 중요사업을 연도별로 비교 분석하여 보면 자체연구사업은 1998년부터 평균 25건이상을 수행하였으며 향후에도 25건이상을 계속 연구할 예정입니다.  수탁 연구과제는 1995년부터 금년까지 총 94개, 수탁금액은 90억원으로 1건당 평균 수탁금액은 약 1억원이었습니다.  현재까지 연평균 수탁건수는 15건, 연평균 수탁금은 15억원 정도되며 기금적립이 가능한 전출금은 연평균 약 2억 4,000만원이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  지난 해부터 수탁 연구과제가 현격히 증가하게 되어 ''99년의 수탁건수는 28건, 수탁금액은 28억원으로 3억 3,000만원의 수익이 있었고 금년도에는 10월 기준으로 수탁건수는 22개, 수탁금액은 16억원으로 예년에 비해 2배 정도인 6억원 정도의 수익이 발생하였다고 생각합니다.  향후에도 수탁과제의 적극적인 수주를 통해 연구원의 자주재원을 확충하는데 노력하고자 합니다.  
</p>
<p style="padding-left:1.2em">  단기 정책연구과제는 연평균 15건수인데 반해 금년에는 21건을 수행 등 도정현안과 관련된 연구과제의 필요성이 상당히 증가하고 있으며 향후에도 계속적인 증가가 예상되어 내년도에는 화급한 도정현안에 대한 태스크 포스를 운영하는 등 단기정책과제에 순발력 있는 해결의 노력을 기울이려고 합니다. 
</p>
<p style="padding-left:1.2em">  끝으로 금년도의 연구사업을 총괄적으로 보고드리면 당초 연구과제사업 88건, 정기간행물 45회, 연구조성사업 9건 총 146건을 계획하였던 바 금년에는 연구과제사업 101건, 정기간행물사업 43건, 연구조성사업 21건 등 총 165건의 수행이 예상됩니다.  금년도 사업계획 대비 약 116%가 무난히 달성될 것으로 판단됩니다.  구체적인 연구사업 추진내역에 관해서는 7페이지부터 16페이지를 참조해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  이어서 15페이지부터 30페이지까지 2001년도 연구사업계획을 보고드리겠습니다.  내년도 연구사업계획의 기본방향은 국토종합개발계획 2020년까지 경기도는 지식산업 중심 지역으로 지정을 받았습니다.  그래서 수도권의 새로운 패러다임에 따른 정책연구개발 기능이 강화되기 위하여 남북협력과 서해안시대를 선도하는 정책연구와 경기도의 지식기반산업 육성전략을 개발하여 지역경쟁력 향상을 위한 공간구조계획을 수립할 계획입니다. 
</p>
<p style="padding-left:1.2em">  또한 도정수요에 탄력적으로 대응하기 위한 단기정책과제 및 현안사항의 효율적인 대응을 위하여 특정 도정현안 사항에 대해서는 각종 태스크 포스를 운영할 예정입니다.  그리고 상시적인 연구부담 경감과 적정 연구수준을 유지하여 시급한 도정연구를 해결하기 위하여 적정량의 연구과제는 수행하도록 하겠습니다.  기본과제 연구기간도 지난 해에는 10개월에서 5개월 내외로 탄력적으로 조정하였습니다.  이러한 기본방향의 구현을 위한 금년도 연구사업계획을 총괄하면 우선 연구과제사업은 총 100건을 수행할 계획입니다.  기본연구과제는 경기도청 및 제2청 각 실·국, 도의원님들께서 주신 것과 유관기관을 대상으로 적정과제 추천의뢰한 총 68건을 추천받아 연구원 1인당 1과제 총 27개 과제를 수행할 계획입니다. 
</p>
<p style="padding-left:1.2em">  수탁 연구과제는 내년도에 신규수탁 연구과제를 부서별 2.5과제인 총 15개 과제를 수행하고 2000년도에서 이월된 과제 10건을 포함하면 약 25건이 되겠습니다.  위탁연구과제는 대학과 연구소 등에 16개 과제를 위탁하므로 아웃소싱을 통한 연구원 외부의 노하우를 활용할 계획입니다.  
</p>
<p style="padding-left:1.2em">  경기도가 요청하는 단기정책과제는 내년도 연구사업의 중점관리 대상 사업으로 추진하고 현안사항에 따라서는 원내외 전문가로 태스크 포스를 구성 추진하여 금년대비 2배이상의 부서당 7개 과제내외가 되어 총 40개 과제를 과제당 특성에 맞게 편성 수립할 계획입니다.  지역연구과제는 특정현안이 발생하고 있는 경기도내 시·군을 대상으로 6개월에 1건씩 2건을 추진할 예정입니다.  
</p>
<p style="padding-left:1.2em">  또한 정기간행물 사업은 금년과 같이 6종, 정기간행물 총 35회 발간예정이며 전문학술논문집 경기연구, 도내 기업의 정보제공지 등이 경기도기업 경기조사를 2회, 특집주제 중심 논문집으로 경기논단, 주력산업분석지 경기 이코노미를 분기별로 각각 4회, 연구원의 소식지 KYDI 뉴스레터와 경제동향분석지 경기도 경제동향과 전망을 매월 각각 12회 발간할 예정입니다.  그리고 연구조성사업은 경기도정에 도움이 될 수 있는 최신 외국도서 5종의 번역사업을 추진하고 당면문제 및 학술적 성격의 대내외 여론 선도적 사업을 위해 6회 정책세미나와 워크숍 등을 추진할 예정입니다.  
</p>
<p style="padding-left:1.2em">  특히 경기도 지역정보 및 지리정보체계 구축을 지원하며 지역정보 체계의 응용개발을 위한 정보기술의 효율과 활용기법을 연구하여 경기도 공간정보 구축과 공급 및 활용을 위해 GIS를 운영할 예정입니다.  2001년도의 구체적인 연구사업 추진사업은 배부해 드린 16페이지부터 30페이지를 참고해 주시면 고맙겠습니다.  
</p>
<p style="padding-left:1.2em">  마지막 순서가 되겠습니다.  이어서 31페이지 ''99년도 행정사무감사 처리요구사항 개최결과를 보고드리겠습니다.  ''99년 11월 17일 행정사무감사시 처리요구사항은 7건이었으며 현재 7건 모두 조치하였습니다.  구체적인 조치결과는 배부해 드린 유인물 31페이지에서 33페이지를 참고해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 저희 연구원의 2000년도 주요업무보고를 마치고 지금부터 중점연구사업에 대하여 양기용 기획조정부장님께서 보고를 드리는 순서가 되겠습니다.  대단히 감사합니다.
</p>
<p><br /></p>
<p>(업무보고는 끝에 실음)
</p>
<p><br /></p>
<p><b>○ 위원장 김강선 </b> 경기개발연구원장님 수고하셨습니다.  그러면 계속해서 보고를 받도록 하겠습니다.  그러면 보고에 앞서서 회의장 정리를 위하여 한 5분간 감사를 중지하겠습니다. 
</p>
<p class=''ar''>(11시03분 감사중지) 
</p>
<p class=''ar''>(11시09분 감사계속)
</p>
<p><b>○ 위원장 김강선 </b> 좌석을 정돈해 주시기 바랍니다.  감사를 계속 하겠습니다.
</p>
<p style="padding-left:1.2em">  그러면 양기용 기획조정부장님 나오셔서 업무보고를 해주시기 바랍니다.  
</p>
<p><b>○ 기획조정부장 양기용 </b> 연구원 기획조정부장을 맡고 있는 양기용입니다.  지금부터 저희 연구원에서 2000년도에 중점적으로 추진한 여러 가지 연구사업에 대해서 간략히 스크린을 통해서 말씀드리겠습니다.  진행순서는 저희 2000년도 추진실적과 주요전략사업에 대해서 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  좀전에 원장님께서 말씀드렸듯이 저희는 기본적으로 기본과제와 수탁과제, 정책과제, 세 과제를 중점과제로 삼고 있습니다.  그래서 2000년도에 환경산업육성방안 등 25건의 기본과제를 수행한 바 있으며 역시 25건의 수탁용역과제를 통해서 대안제시 및 자체재원 충당에 노력하고 있습니다.  경기도와 시·군은 물론 건교부, 감사원 등 중앙부처의 수탁을 받아서 연구용역을 수행한 바 있으며 연구용역을 수행하면서 국토연구원, 해양수산개발원 등 국책연구원과 시정개발연구원의 공동연구를 진행 중에 있습니다.  
</p>
<p style="padding-left:1.2em">  그리고 아울러 현안문제에 대해서 여러 가지 대응논리 개발과 도, 도의회에 대한 지원사업도 추진하고 있습니다.  첫 번째로 말씀드릴 게 금년 초에 접경지역지원법시행령 초안을 제시해서 행자부와 공동노력으로 경기도의 의견 특히 시·군의 의견이 반영될 수 있는 안을 마련하도록 많은 노력을 기울인 바 있고요.  평택항 관세자유화지역 지정요건을 완화해서 선적물량 500만t을 300만t으로 완화했고요.  그 다음에 1,000만t 규모의 총 물량은 3개년으로 나눠서 할 수 있게끔 하는 조건으로 관세자유지역 예정지구라는 제도 도입을 통해서 경기도의 정책반영에 노력한 바 있습니다.  아울러 총 21건의 정책과제 수행을 통해서 도정현안에 대안을 제시하고 있습니다.
</p>
<p style="padding-left:1.2em">  특히 수도권정책 및 난개발방지를 위한 여러 가지 대응논리와 기초자치단체가 추진하고 있는 광역도시화에 대한 경기도 공동화현상을 우려하는 입장에서 대응논리를 개발한 바 있습니다.  아울러 광역교통시설부담금 설치 등 각종 정책대안에 대해서 검토와 의견제시를 하고 있고요.  작년도와 올해도 역시 대통령 업무방문시 업무보고 준비를 하는 과정에서 수도권정책 현안 및 지역경쟁력 강화 논리를 제시하고 있습니다. 
</p>
<p style="padding-left:1.2em">  도 의회와의 협력을 위해서는 의원세미나 및 정당토론회에서 연구원 박사들이 지원, 참여, 주관하는 노력을 기울이고 있고요.  남북 협력구상 등 16회의 워크숍과 세미나를 개최해서 현안에 대응하는 작업을 진행 중입니다. 
</p>
<p style="padding-left:1.2em">  2000년도에 중점적으로 추진하는 연구사업 방향은 다섯 가지로 정리될 수 있습니다.  첫 번째는 수도권의 새로운 환경변화에 대응할 수 있는 도 정책기능을 지원하고 연구하는 것을 하나의 방향으로 설정했고요.  다음으로는 접경지역개발, 서해안개발 등 남북협력과 서해안시대에 대응하는 연구를 수행하는 작업이 되겠습니다.  이러한 여러 가지 도정수요에 보다 탄력적으로 대응하고자 단기정책과제를 상당히 많이 강조한 바 있고요.  중앙부처 국책연구원과의 공동노력으로 연구원의 대외협력 및 위상강화를 추진하였습니다.  끝으로 기본과제 선정시 도의회가 도에서부터 많은 추천과제를 추천받아서 선정했고 추진과정도 역시 해당 실·국과의 정기적인 간담회를 통해서 상호간의 의견을 교환하는 유기적인 협력관계를 유지하고 있습니다. 
</p>
<p style="padding-left:1.2em">  저희 연구원의 올해 주요 전략사업은 세 가지 방향을 말씀드릴 수 있습니다.  첫 번째는 경기도 공간구조 개편과 인프라 구축을 위한 과제로서 대표적으로 수도권 광역도시계획수립, 수도권 종합교통체계 및 경기도 도로정비계획 그리고 아까 말씀드린 대로 평택항 자유관세지역 지정방안 등입니다.  이러한 연구를 위해서 자족과 연계기능을 갖춘 거점개발에 우선적으로 노력했고요.  여러 가지 새로운 도로망계획과 수도권의 유기적인 교통망 체계를 유지하려는 정책의 기대효과를 도모하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 지역특성을 반영한 균형적 지역개발에 관한 연구를 상당부분 많이 진행하고 있습니다.  대표적으로는 경기도 지식기반 발전계획, 북부지역의 친환경산업단지 조성계획 그리고 접경지역계획 아울러 경기도 서해안권의 전략적 개발계획 등 지역 균형개발을 위한 나름대로의 연구과제를 수행하고 있고요.  이러한 과제를 통하여 지식산업 혁신거점을 개발하고 북부지역의 균형적인 발전, 그리고 접경지역의 체계적인 보전과 개발방향을 형성하고 앞으로 추후 진행될 남북 협력사업에 대응하고자 합니다.  특히 평택항과 서해안지역 개발도 저희가 관심있게 추진하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 환경보전과 환경친화적 개발사업입니다.  개발뿐만 아니라 환경에 친화적인 그러한 환경보전과 개발방향을 설정하기 위해서 경기도 경관관리 기본계획과 효율적인 수자원관리방안, 그리고 북부지역의 임진강 수질보전 및 활용방안을 연구하고 있고요.  이러한 환경관련 연구를 통하여 난개발 방지를 위한 제도를 정립하고 상수원 수질보전과 대체 상수원개발, 임진강 수질보전대책 및 남북협력을 통한 수해방지대책을 마련하고자 노력하고 있습니다.  보다 구체적으로 살펴보겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 경기도 공간구조 개발에 관한 연구는 세 가지 과제로 설명드릴 수 있습니다.  첫 번째는 수도권 광역도시계획 수립입니다.  수도권 광역도시계획 수립은 그 동안 각 시·군 또는 시·도별로 단절되고 단편적으로 추진되는 수도권의 밑그림을 건교부, 국토연구원, 시정개발연구원, 저희 연구원, 인천발전연구원 등 4개 기관이 서로 공동연구를 통해서 수도권 공간구조와 각 지역의 기능 그리고 산업정책, 환경 및 도로기반시설 등 여러 가지 계획들을 통합적으로 하는 경기도의 밑그림을 그리는 작업입니다.  일전에 건교부가 요구하는 광역도시권 설정범위를 저희 연구진의 노력으로 경기도 전역으로 확대함으로써 경기도가 경기도의 계획고권을 발휘해서 나름대로 공간구조의 큰 틀을 마무리할 수 있도록 제도적 기반을 마련한 바 있습니다.  아울러 개발제한구역 조정기준안을 마련해서 지역의 개발수요와 민원을 반영할 수 있는 노력을 기울이고 있습니다.  도면을 통해서 자세히 설명드리겠습니다. 
</p>
<p style="padding-left:1.2em">  공간구조 기본골격은 크게 나눌 수가 있습니다.  첫 번째는 그 동안 서울중심의 일구체제에서 벗어나서 파주, 동두천, 남양주 그리고 수원, 이천, 평택 등 거점도시 개발을 핵심적인 관점으로 생각하고 있습니다.  그래서 이러한 거점개발을 통해서 수도권의 자족적인 기능을 확립하고 그에 따른 교통망, 환경시설 계획을 마련하고자 노력하고 있고요.  특히 이번 광역도시계획에서는 개발뿐만 아니라 환경분야를 강조하고 있습니다.  그래서 저희가 가지고 있는 녹지축으로서 비무장지대 그리고 광덕산에서부터 팔당상수원 그리고 서운산으로 이어지는 그 수직적인 골격 녹지축을 중심으로 그에 따라 펼쳐지는 세 갈래의 수평녹지축을 가장 우선적으로 보전하는 그런 계획을 수립하고 있고요.  아울러 서해안권의 갯벌을 보전하는 서해안권 환경벨트 역시 광역도시계획을 수립하면서 환경을 우선하는 그러한 작업으로 노력하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 수도권 종합교통체계 및 경기도 도로정비 기본계획입니다.  아까 말씀드린 대로 6개의 거점도시 그리고 지역간 연계망은 도로나 기타 기반시설로 서로 연계되어야만 나름대로의 자족기능을 발휘할 수 있고 경기도 전체의 지역경쟁력을 향상시킬 수 있을 겁니다.  그에 따라서 종합교통체계 및 경기도 도로정비 기본계획에서는 수도권의 교통수요의 예측 및 관리방안을 구축하고 거점지역을 연계하는 광역교통망의 수립과 교통행정체계를 재정립하는 그런 방향을 연구내용으로 하고 있습니다.  따라서 주요 도로의 운영, 관리계획, 도로투자계획, 재원조달방안을 강구하는 내용을 연구내용에 포함시키고 있습니다. 
</p>
<p style="padding-left:1.2em">  광역도로계획에 잠깐 설명드릴 것이 기존의 서울중심의 방사선형태로 가는 도로보다는 서울, 경기도의 거점을 연결시킬 수 있는, 저희가 흔히 말하는 더블링이라는 두 개의 순환도로망을 구축하는 것을 우선적으로 생각하고 있습니다.  아울러 강화와 해주로 연결되는 고속도로, 그 다음에 의정부, 동두천, 연천으로 이어지는 고속도로망을 제안한 바 있고요.  현재 서울과 문산으로 이어지는 도로망에 대해서는 건교부에서 예비 타당성조사를 하고 있습니다.  아울러 평택항으로부터 평택시로 연결되는 산업철도의 조기완성을 수도권교통체계와 도로망 계획에서 건의하고 있으며 건교부에서.  저희가 만든 여러 가지 도로망계획을 반영하는 노력을 가시적으로 기울일 것을 기대하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 아까 말씀드린 대로 평택항 관세자유지역 개발입니다.  평택항은 경기만을 중심으로 하는 핵심 물류항만기지로 건설하는 게 도의 방침이고 저희 나름대로도 평택항 관세자유지역을 통해서 경기도내의 항만개발을 추진하고 있습니다.  아까 말씀드린 대로 500만t에서 300만t으로서의 선적물량을 완화하는 것을 관철시켰고요.  평택항의 시설확충, 컨테이너 항로개선은 언론에서 보도된 바와 같이 나름대로 추진되고 있고요.  평택항과 관련한 전담 법인설립 방안을 저희가 12월 말까지 연구개발 중입니다. 
</p>
<p style="padding-left:1.2em">  다음은 지역특성을 반영한 균형개발에 관련된 연구과제를 말씀드리겠습니다.  경기도 지식산업 발전계획은 경기도가 가지고 있는 지식잠재력을 충분히 활용하여서 지역혁신거점을 구축하고 이러한 지역혁신거점을 조성하고 지원하는 그러한 연구내용으로 하고 있고요.  특히 이러한 거점지역을 우선적으로 지원하는 특별법 제정을 추진하고 있습니다.  보다 구체적으로 설명드리겠습니다. 
</p>
<p style="padding-left:1.2em">  경기도는 제가 저번에 속초에서 말씀드렸던 바와 같이 전문인력, 연구시설, 관련 첨단제조업, 고속유통체계 그리고 우리가 흔히 말하는 도시기능, 아울러 벤처자본이 충분하게 마련되어 있는, 가장 지식산업을 육성할 수 있는 토양을 가진 곳이라고 평가될 수 있습니다.  따라서 이러한 지식산업 육성토양을 바탕으로 세 군데에 지식거점을 우선적으로 고려하고 있습니다.  첫 번째가 테크노벨리라 이름지어지는 과천지역의 개발로서 현재 과천 대공원과 경마장을 중심으로 한 그런 주변지역을 첨단정보산업 그리고 과천지역에 있는 화훼지구를 조성하고 아울러 상업지역, 멀티미디어센터를 조성하는 계획은 나름대로 구상단계에 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 또 하나의 지역은 수원, 기흥, 화성지역입니다. 이 지역은 이미 삼성반도체를 중심으로 해서 첨단산업 제조업체가 밀집되어 있고요.  그 다음에 기흥지역을 중심으로 해서 많은 연구기능이 밀집되어 있는 지역입니다.  따라서 화성 등 연관 산업단지, 영통의 택지개발지역, 서탄 택지개발지역 등 주변 배후도시가 설정되어 있기 때문에 이 지역을 활용한 첨단산업단지 및 연구개발기능을 강화하려는 연구를 진행 중입니다. 
</p>
<p style="padding-left:1.2em">  다음은 요즘 얘기가 되고 있는 판교단지입니다.  판교단지는 경기도와 성남시의 의견이 나누어지는 걸로 알고 있습니다마는 경기도의 의견은 이 지역은 기존의 배드타운화된 주거단지보다는 첨단산업 및 연구개발이 집중되어 있는 그러한 지역으로 육성할 계획입니다.  경부고속도로를 중심으로 왼편지역을 일단 첨단산업단지와 제조업기능을 충실히 수용하고 연구개발기능을 이 단지에 집중시키고 아울러 30%미만의 주거기능을 오른편에 조성할 계획을 가지고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 경기북부지역의 친환경산업단지 조성계획입니다.  이 계획은 현재 시작한 지 얼마 되지 않아서 구체적으로 안은 나오지 않았습니다마는 저희와 산업연구원, 외국의 컨설팅업체를 대상으로 해서 남북협력을 대비한 남북경협단지, 북부지역에 첨단 및 환경친화적인 산업단지를 조성할 계획을 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 경기접경지역계획 수립입니다.  역시 경기북부지역에 관련된 사업으로서 접경지역의 보전과 개발관련된 토지이용계획, 교통계획, 산업계획 그리고 환경보전기본계획 등 여러 가지 기본적인 틀을 마련하는 계획으로서 아울러 남북교류 협력사업을 구체적으로 경기도에 떨칠 수 있는 그런 사업을 구상할 예정입니다. 
</p>
<p style="padding-left:1.2em">  경기도접경지역계획은 저희가 ''99년도에, 아까 말씀드린 대로 접경지역법을 통과시켰고 올해 5월에 시행령을 통해서 경기도 의견을 많이 반영했습니다.  그래서 남방한계선 이남 20㎞범위 내외를 접경지역으로 설정했고요.  해당 읍·면·동의 특성을 반영해서 나름대로 조정한 결과가 접경지역으로 설정됐고요.  이 접경지역에서 주요 사업내용은 DMZ의 생태적 활용방안, 동두천이라든지 연천 중심의 환경단지조성, 포천, 가평 중심의 관광산업벨트, 파주의 생태공원 및 물류단지 기본계획 등 나름대로의 산업단지 개발계획과 도로망 계획들, 환경보전계획이 추가적으로 연구될 예정입니다. 
</p>
<p style="padding-left:1.2em">  다음 경기도 서해안권 전략적 개발계획입니다.  평택항 및 평택항만 배후지역 개발과 관리계획을 기본 내용으로 하고 있고 아울러 평택, 시화, 강화, 세 지역에 대한 전략적인 발전계획을 수립하는 것을 주요 내용으로 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  지금까지 진행 중인 평택항이 우선적으로 진행되기 때문에 간략히 설명드리면 평택항 지역을 관세자유지역으로 전환해서 물류유통단지로 조성하고 배후되어 있는 포승공단의 활성화계획, 그 배후에 기반시설, 안중, 기존 시가지 조성을 통해서 배후도시 기반시설을 확충하고 아울러 공단지역으로 나오는 대기오염과 환경방지시설을 설치하고 평택항과 평택역을 연결시키는 산업철도를 우선적으로 조기 착공하는 것을 주된 내용으로 삼고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 환경보전과 환경친화적 개발계획에 대한 설명입니다.  몇 번 말씀드렸습니다마는 경기도 경관관리기본계획을 통해서 개발과 환경이 조화롭게 이루어질 수 있는 계획을 세웠고요.  이러한 경관관리를 통해서 31개 시·군의 자연환경 자원을 수집해서 유형별로 보전되어야 할 가치와 개발되어야 할 지역을 나름대로 정립해 본 바 있습니다.  따라서 이러한 계획을 기반으로 해서 시·군의 도시계획 및 개발계획수립시 반드시 참조할 수 있는 지침과 방향을 제시하고자 합니다.  저희가 총 5개 권역에 대한……. 
</p>
<p><b>○ 김효정 위원 </b> 의사진행발언입니다, 위원장님!  자세한 내용은 업무보고때 듣기로 하고, 저번 세미나 때도 들은 내용인데 감사시간에 오히려 손실이 오니까 간략하게 주제만 설명하는 걸로 했으면 좋겠습니다.  이 시간을 다 뺏겨버리면 감사는 언제합니까? 
</p>
<p><b>○ 기획조정부장 양기용 </b> 5분내에 끝내겠습니다.  먼저 서북접경권을 보겠습니다.  서북접경권은 대부분 DMZ와 양호하게 보호되고 있는 자연생태계가 이 지역에 많이 보전되어 있습니다.  그리고 연천군으로부터 밑으로 내려진 녹지축이 마련되어 있습니다마는 나름대로 양주군, 동두천 등 경관관리대상, 약간의 핑크빛으로 나는 데가 경관관리 대상지역입니다.  그리고 파주시도 경관이 훼손되는 걸 나타나고 있습니다.
</p>
<p style="padding-left:1.2em">  동북산악권은 보시다시피 녹색으로 표시된 양호한 녹지축이 조성되어 있기 때문에 이 지역에 대한 개발은 가급적 관광지역이고 환경친화적으로 전환될 필요가 있습니다.  다만 양평군 지역의 수변지역을 따라서 상당한 난개발이 예상되고 있기 때문에 이 지역에 대한 중점관리사업이 필요하다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  동남평야권은 그 동안 상당히 많은 자연환경이 잘 보전되어 있었습니다마는 광주군, 용인시 그리고 안성시를 주변으로 해서 붉게 나타나는 지역이 상당히 난개발이 예상되는 지역이고 현재 진행되고 있는 지역입니다.  따라서 이 지역뿐만 아니라 장호원지역, 여주 일부 남한강변지역, 이천시 등 여러 지역들이 새로운 대상지역으로 나타나고 있습니다. 
</p>
<p style="padding-left:1.2em">  경기 서해안권지역은 이 해변선에 대한 갯벌보전이 우선적으로 거론되고 있고요.  녹지축은 중국에서부터 건너 오는 오염물질을 방지할 수 있는 좋은 자연환경이기 때문에 이 녹지축을 우선적으로 보전하는 것을 대안으로 제시하고 있습니다. 
</p>
<p style="padding-left:1.2em">  끝으로 서울인접권, 붉게 나타난 곳이 택지개발과 많은 지역이 이미 진행되어 있습니다.  따라서 각 도시들이 나름대로의 지역이미지를 제고할 수 있는 경관관리 방향을 유지해야 될 것을 제안하고 있습니다. 
</p>
<p style="padding-left:1.2em">  끝으로 수자원관리방안은 한강수계별 수질조사 분석을 통해서 대체상수원개발이 이루어진다면 경기도 북부, 특히 동북부지역에 대한 나름대로의 규제가 완화될 수 있는 방안을 고려하고 있고요.  임진강 지역은 임진강의 수질보전대책과 임진강의 수량조절을 통해서 남북한 협력사업을 유도할 예정입니다. 
</p>
<p style="padding-left:1.2em">  아울러 경기도 행정체제 그리고 산업정책을 위해서 나름대로 연구를 진행하고 있습니다.  중장기 조직운영방안과 자치권 확대방안, 외국인을 위한 지식정보 제공, 토지이용관련 해서 GIS팀을 운영해서 지리정보시스템을 제공하고 있습니다.  끝으로 사회적인 통합을 위해서 자활지원계획 및 공공묘지 공원화 사업 등을 추진하고 있습니다.  간략하게 보고를 마치겠습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 양기용 기획조정부장 수고하셨습니다.  화면 좀 정리해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사질의를 하도록 하겠습니다.  감사의 원활한 진행을 위하여 일괄질의후 일괄답변을 듣는 것을 원칙으로 하고 보충질의시에는 일문일답으로 진행하도록 하겠습니다.  그러면 질의하실 위원께서는 질의하여 주시기 바랍니다.  윤동욱 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 윤동욱 위원 </b> 남양주출신 윤동욱 위원입니다.  우리 경기개발연구원은 발족한 지 5년밖에 안 된 짧은 기간입니다마는 경기도의 싱크탱크로서 확고히 자리를 잡은 것은 바로 노춘희 원장님이하 여러분의 노력의 결과라고 생각이 됩니다.  그 동안 여러분 노고에 감사를 드립니다.  제출하신 연구실적 자료를 보면 경기도 중장기조직운영방안에 관한 연구와 자치경찰제 실시에 대한 지방자치단체의 대응방안, 지방정부의 자치권 확대방안이라는 과제가 있는데 이것은 앞으로 우리 경기도의 발전뿐만 아니라 국가적으로 상당한 영향을 미치는 중요한 문제라고 생각이 됩니다.  이 내용을 좀 구체적으로 설명을 해주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 경기개발연구원에서 개발과제로 추진한 사업 중 경기도에서 채택하여 시행중인 대표적인 사례 몇 가지만 밝혀 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 윤동욱 위원 수고하셨습니다.  다른 위원님, 김효정 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 김효정 위원 </b> 여주군출신 김효정 위원입니다.  여러 가지로 업무보고를 상세하게 잘 들었습니다.  수고 많으셨습니다.  제일 먼저 연구용역을 의뢰받을 때, 수입의 용역비를 결정할 때 어떤 절차와 어떤 기준을 가지고 용역 수입률을 결정하는지 그 기준과 절차를 좀 설명해 주시고.  다음은 보수입니다.  자료를 보니까 일반 공직자들하고는 많은 차이가 있는데 그 보수임금을 결정할 때 연봉계약으로 하는 건지 아니면 성과급으로 하는 건지 그 보수임금은 어떻게 결정하는가 아울러서 퇴직금제도가 과연 있는 건지 있다면 퇴직금은 평균임금에 근무연수를 곱하는 건지 아니면 최종임금에 어떻게 하는 건지, 비율이라든지 특별하게 퇴직금 지급절차를 설명해 주시고.
</p>
<p style="padding-left:1.2em">  다음은 직원을 임용하거나 면직시킬 때 임명권자가 누구고 어떤 방식으로 임명을 하는가에 대해서도 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  끝으로 하나 좀 복잡한 얘깁니다마는 경기개발연구원에서 감사자료를 주셨는데 55페이지를 보시면 본 위원이 제출 요구한 게 있습니다.  ''감사수감현황'' 감사받은 게 있으면 해달라 자료 요청했더니 "해당사항 없습니다" 이렇게 아무 것도 없이 왔는데, 제가 여기 가져왔습니다마는 감사관실 자료를 보면 경기개발연구원이 감사받아서 시정·주의한 게 무려 18건이나 있습니다.  18건의 감사받은 사실이 있는데도 불구하고 자료를 요청했더니 "해당사항 없습니다" 로 나왔는데 이게 뭐 도의회가 물렁물렁해서 그런 건지, 의장이 물렁물렁해서 그런지, 의회 자체를 무시하시는 건지, 굉장히 고등연구기관인데 이렇게 자료를 "해당사항 없습니다" 로 해서 내신다면 지방자치제도 자체를 거부하시는 건지, 하여간 제출에 누락된 이유를 설명해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 김효정 위원 수고하셨습니다.  다른 위원 계십니까?  양태흥 위원 질의하시기 바랍니다. 
</p>
<p><b>○ 양태흥 위원 </b> 구리출신 양태흥 위원입니다.  아까 설명을 잘 들었습니다.  먼저 비전문가가 전문가한테 질의를 한다는 게 어떻게 보면 문제가 있습니다마는 배우는 입장에서 질의한다고 생각하시고 성심성의껏 답변해 주시면 고맙겠습니다.  
</p>
<p style="padding-left:1.2em">  평택항의 관세지역 지정에 관해서 질의드리겠습니다.  5만t에서 3만t으로 하향을 해서 어제 감사해 보니 중앙부처에 건의해서 가능성 있다라는 답변을 들었습니다.  컨테이너나 그 외의 여러 가지 문제가 아직 많이 산적해 있는 걸로 알고 있습니다.  그런데도 관세자유지역으로 지정이 가능한지 말씀해 주시고요.  또 제출해 주신 내용 중에 보면 경기도 개발제한구역 관리계획 수립방안이 있습니다.  진도란을 보니까 최근에 시작했고 추진상황은 경기도 개발제한구역 관리계획안을 각 시·군에 송부를 완료했다 이렇게 돼 있습니다.  요즘 신문에 보면 개발제한구역을 완화한다고 해놓고 오히려 그전보다 더 강해져서 살기가 어렵다는 얘기가 빈번히 나돌고 있습니다.  그 부분에 대해서 간단하게 말씀해 주시고요.  
</p>
<p style="padding-left:1.2em">  어제 감사하면서 도비보조금에 대해서 질의했더니 "경기개발연구원에 용역을 줘서 연구 중입니다" 했습니다.  여기 와서 들으니 이미 연구가 다 끝난 걸로 돼 있습니다.  균형발전을 위해서 어떻게 연구해서 제출했는지 간단히 말씀해 주시고요.  그 다음에 공공묘지 연구에 관한 내용을 2000년 7월에 제가 책자를 받아봤습니다.  너무 고맙게 생각하고요.  그 내용 중에 여러 가지 모델이 있습니다마는 경기 양평군에 새로운 모델이 하나 발견되어서 그 내역을 제가 여기서 일일이 말씀드릴 수는 없고 비디오테이프를 제가 하나 가져 왔습니다.  감사 끝나고 드리고 갈 테니까 그것도 하나의 모델이 될 수 있는지 연구를 해보셨으면 좋지 않나 생각해서 말씀드립니다.  
</p>
<p style="padding-left:1.2em">  그 다음에 역시 정책관련입니다마는 어저께 감사를 하니까 도지사가 선거공약을 215개를 했습니다.  그게 임기내에 가능하냐, 혹시 개발원에 문의를 한 적이 있는지, 했으면 했다, 안 했으면 안 했다고만 간단하게 답변해 주시고, 그 내용 중에 부실 공기업을 민영화시키겠다는 내용이 들어 있습니다.  한 가지만 말씀드리겠습니다.  그 부분도 연구용역으로 받은 사실이 있는지, 없는지 그 부분만 말씀해 주시고, 아까 원장님이 설명하신 중에 도의원들의 의견을 받아서 연구한다고 했는데 혹시 도의회에서 어떤 문제를 제기해서 연구해 달라는 과제가 있었는지 그 부분에 대해서 말씀해 주시기 바라면서 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 양태흥 위원 수고하셨습니다.  이주석 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이주석 위원 </b> 포천출신 이주석 위원입니다.  간단하게 두 가지만 질의하겠습니다.  답변자료를 살펴보면 계약금액하고 전출금하고 상당한 차이가 있습니다.  차이가 많은 사유는 무엇인지 말씀해 주시고 그 다음에 수탁금액 중 차액은 어떻게 처리하시는지 말씀해 주시고 연구원의 연구수당은 어떻게 지급되는지 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음에 업무보고를 보니까 경기개발연구원 정원 58명 중 현원이 44명으로 14명이 부족합니다.  이중에도 연구부 12명이 부족한 것은 우리 경기도 발전관계에 상당한 지장이 초래된다고 보는데 이에 대한 원장님의 대책은 무엇인지 답변해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 이주석 위원님 수고하셨습니다.  노시범 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 노시범 위원 </b> 노시범 위원입니다.  ''99년도, 2000년도 경기개발연구원의 연구과제 중에 정책에 반영된 비율을 답변해 주시고 그 다음에 감사자료 103쪽을 보면 연구사업비 지출내역이 있는데 ''99년도하고 2000년도 대비해서 자료를 주셨는데 상당한 불용액이 나와 있습니다.  그 부분에 대해서도 답변해 주시고 마지막으로 139쪽에 경상예산 집행내역을 보면 차량비라는 과목이 있는데 차량구입비인지, 차량운영비인지 그 부분에 대해서도 답변해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 노시범 위원님 수고하셨습니다.  다음 질의하실 위원님 계십니까?  연동현 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 연동현 위원 </b> 연천출신 연동현 위원입니다.  먼저 일문일답식의 질의면 편할 텐데 일괄질의이기 때문에, 첫 번째 우리 도에서 ''99년도에 수도권정책컨설팅에 10억원이라는 용역비가 설정된 바 있습니다.  물론 정책기획관실 행정사무감사시에도 자료를 받은 바 있는데, 지금 자료상에 보면 아직까지도 용역을 주지 못하고 있는 게 있습니다.  보면 우리 경기개발연구원에서 협의한 차원에서 수도권정비계획 정책에 관한 전환, 이런 연구발표가 ''99년도에 있었는데요.  그렇다고 볼 때 우리 경기개발연구원에서 경기도로부터 이런 의뢰를 받은 사례가 있었는지 이것에 맞아 떨어져서 앞으로 우리 경기개발연구원에서 용역을 할 의향이 있는지, 당시 경기도에서 10억원이라는, 수도권정책컨설팅이라는 것을 예산편성할 시에 인근 인천과 충청도에 대외적으로, 국제적으로 공신력 있는 용역기구인 미쯔비시종합연구소, 노무라종합연구소 이런 쪽에서 관심을 갖고 있었던 것 같습니다.  이 부분을 우리 도와 그 동안 이야기가 있었던 것인지, 또 경기개발연구원에서 수도권정책전환이라는 연구발표가 있었는데 경기도가 경기개발연구원하고 사전에 이야기가 없었다는 것은 그렇습니다.  더더욱이 몇 개월 전에 일선 시·군이 1차적으로는 경기개발연구원에 의무적으로 용역을 의뢰해야 한다는 조례까지 있음에도 불구하고 도에서 등한시하고 있습니다.  그런 부분에 대해 연구원에서 구체적인 말씀을 해주시길 바라고 다음에 우리가 ''95년도부터 ''97년도에 일선 시·군, 그러니까 도비보조금을 주었을 때 행정사무감사를 취한 바 있습니다.  그래서 증인출석시 불참해서, 과태료를 부과했는데 100% 패소했습니다.  ''97년까지 그런 운영이 있었습니다.  이것은 왜 본 위원이 말씀드리냐 하면 어차피 이것은 정책차원에서 정책연구를 했으면 하는 바람에서 말씀드리는데 우리가 도비를 줬을 경우에는 그래도 예산집행하고 운영실태를 차기연도에 예산편성하는데 심의 내지는 보조예산의 시기성을 갖기 위해서 필요하다고 생각합니다.  그래서 이런 것을 우리 경기개발연구원에서 정책연구 차원에서 할 의향이 있는지 말씀해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음에 GIS 지리정보시스템에 관한 질의입니다.  2000년 7월에 경기개발연구원에서 연구원팀을 운영하고 계셨다고 말씀하셨는데 불교부단체인 시가 GIS를 계속 운영하고 있습니다.  그런데 본 위원의 생각은 이게 시별로 연구를 따로따로 하고 있다고 생각됩니다.  그 부분은 어떻게 생각하고 계시는지 말씀해 주시고 끝으로 뭐냐하면 여기 본 위원이 못 봤는데 우리 경기북부, 통일을 대비한 발전전략에 대한 것은, 물론 접경지역에 맞아서 연구한 사례는 있습니다마는 그 부분이 안 보입니다.  그래서 그 부분을 지금 연구 중에 계시는 건지 그것도 구체적으로 밝혀 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 연동현 위원님 수고하셨습니다.  다음 이진용 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이진용 위원 </b> 가평출신 이진용 위원입니다.  먼저 우리 경기도가 우리나라에서 차지하고 있는 중요성에 대해서는 제가 다시 말씀드리지 않더라도 연구원 관계자 여러분이나 저희나 이미 다 잘 알고 있는 주지의 사실입니다.  경기개발연구원에서 실제로 경기도의 발전을 저해하고 나아가서는 국가적인 발전의 발목을 잡고 있는 수도권정비법을 비롯한 여러 가지 규제를 타파하기 위해서 정책자료를 내놓고 연구에 열중하고 계신 것을 볼 때 이 자리를 빌어서 격려의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  오늘 행정사무감사를 맞아서 저는 질의를 연구원 운영에 관한 부분과 연구과제에 관한 부분으로 나누어서 간단하게 몇 가지씩 질의드리고자 합니다.  먼저 연구원 운영에 대해서는 지금 경제사정이 IMF이후로 좀 나아지는 듯하다가 다시 체감경제가 상당히 안 좋아지고 있고 대우, 현대건설을 비롯해서 전체적인 경제상황이 상당히 냉각되고 있습니다.  이럴 때일수록 연구원은 사실 재정적인 지원을 받기가 점점 어려워지고 또 외부의 수탁과제도 줄어들게 되어 있습니다.  사실은 이럴 때일수록 여러분들의 역할은 상당히 중요하게 인식되고 있음에도 불구하고 현실적으로 재원이 뒷받침이 되지 않기 때문에 뒤로 밀려날 수밖에 없는 아이러니컬한 상황에 있다고 하겠습니다.  그래서 연구원의 재정자립도는 상당히 중요하다고 생각하는데 ''95년 이후부터 2000년까지 연구원 자립도의 변화추이에 대해서 도표로 설명해 주시고 연구원 자립도는 수탁연구과제의 건수나 액수가 상당히 중요한 몫을 차지한다고 봅니다.  그래서 그 부분에 대해서 말씀해 주시고 다른 하나는 기금이 지금 206억원이 형성되어 있는데 ''98년도 행정사무감사시에, 유훈 고문님께서 원장으로 계실 때 약 500억원 정도를 목표로 해서 기금을 형성하고 있다가 중단되었다는 말씀을 하셨습니다.  지난 번 업무보고 때 노춘희 원장님께서 약 700억원에서 800억원 정도의 기금이 마련되면 연구원 운영에 무리가 없을 것 같다고 말씀하셨는데 기금의 운영현황과 향후 500억원에서 600억원 되는 차액에 대한 확보방안에 대해서 말씀해 주십시오. 
</p>
<p style="padding-left:1.2em">  그 다음에 이사회가 2000년 들어서 3회에 걸쳐 열렸었는데 심의결과 모든 안건이 원안의결 승인으로 결정되어 있어서 진지하고 현실적인 논의가 없었던 것이 아닌가 이렇게 생각되는데 제가 잘못 생각하는 것인지 이사회 심의 당시의 상황을 설명해 주십시오. 
</p>
<p style="padding-left:1.2em">  그 다음에 내부 위원회의 종류가, 기금운영위원회가 지금도 있습니까?  기금운영위원회하고 연구심의위원회, 두 가지가 생각나는데 내부 위원회가 어떤 종류가 있는지 회의횟수와 주요안건 내용들을 ''99년도와 2000년도에 대해서 말씀해 주십시오. 
</p>
<p style="padding-left:1.2em">  그 다음에 수도권 난개발에 대한 연구 또 도비보조금 운영제도개선에 대한 연구, 이 두 가지는 요즘 상당히 시급한 사회적인 문제로 떠오르고 있습니다.  그 동안의 연구경과와 결과를 어떻게 예측하고 있는지에 대해서 말씀해 주시고 한강수계 물이용부담금의 효과적인 운영방안, 팔당호 수질보존을 위한 오염총량관리제의 효율적인 시행방안에 대해서 그 동안의 연구결과를 가지고 원장님이 이러한 문제를 어떻게 해결할 것인가에 대한 견해를 밝혀 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 이진용 위원님 수고하셨습니다.  다음 질의하실 위원 계십니까?  유영록 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 유영록 위원 </b> 유영록 위원입니다.  1999년부터 경기개발연구원에 대한 운영을 기금에서 지금 도비지원 쪽으로 전환했습니다.  그래서 원장님께서 보시기에 향후 경기개발연구원이 더 발전하기 위해서는 어떤 형태로 운영되는 것이 바람직한지 그것에 대한 소신있는 답변을 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 제가 자료실을 잠깐 가 보니까 자료실 연간구입비가 한 6,000만원 정도라고 되어 있습니다.  그런데 지금 경기개발연구원 1년 예산이 69억원되는데 자료구입비가 6,000만원이면 1%가 안 되는 것인데 이것에 대한 판단이 어떤지, 너무 연구원에 비해서 자료실이 부족한 면이 있지 않나 본 위원이 이렇게 판단되는데 거기에 대한 원장님의 답변을 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 정원에 보게 되면 정원은 58명으로 되어 있고 현원이 44명으로 되어 있습니다.  특별히 연구부에 대한 부분이 12명이나 정원보다 적게 되어 있는데 왜 그런지, 그 다음에 초빙연구원 13명하고 비상임연구원 38명으로 되어 있습니다.  이분들의 연구활동에 대한 처우가 어떤지 그것에 대해서 말씀해 주시고,  그 다음에 2000년 직원 인건비 지출현황을 보면 연구직들은 연구수당에 대해서는 아무 것도 없습니다.  그런 면에 비해서 관리직들은 업무 및 연구수당이 있습니다.  연구원에 대해서는 왜 연구수당이 전액 책정이 안 되어 있는지 그것에 대해서 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 연구원이라면 연구실적이 보고서 형태로 나오는데 저희가 2000년도 세입·세출을 보면 정기간행물 사업에 무려 2억 2,000만원을 들여서 사업을 벌였는데 반해서 도서판매수입이 600만원밖에 안 잡혀 있습니다.  경기개발연구원에서 많은 연구를 하시고 연구실적들을 내는데 그런 연구실적들이, 저희 같은 경우 경기개발연구원에서 보내줘서 보지만 정기간행물 수입이 600만원밖에 안 된다는 것은 우리가 경기개발연구원의 업적들을 대외적으로 평가받지 못한다고 생각하거든요.  사실 연구업적이 있으면 그 업적들을 누구나 유가로 사서 보기를 원합니다.  그런 면에서 연구원에서 업적들을 너무 과소평가하지 않나, 그리고 관리파트 분야에서 연구업적들을 홍보하고 영업을 해야 되지 않느냐, 연구실적들을 가지고 대외적으로나 아니면 민간에 연구실적을 가지고 사업을 벌여야 할 필요가 있다고 생각합니다.  그런 면에서 원장님께서 평소 가지고 계신 면을 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 GIS 지리정보시스템에 대해서 아까 양기용 기획조정부장께서 말씀하셨는데 지금 저희 기획위원회에서 판단하기로는 아직 우리가 도본청에 대한 감사가 끝나지 않았는데 GIS시스템의 전반적인 것들이 일선 시·군과 도본청과 많은 괴리가 있다고 생각합니다.  정보통신담당관실 감사 때 집중적으로 할 감사조항인데 이것에 대한 경기개발연구원의 입장이 구체적으로 무엇이고 그것들이 31개 시·군을 포함해서 도정전체에 어떠한 영향력을 미치는지 그것에 대해서 말씀해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 유영록 위원님 수고하셨습니다.  더 질의하실 분 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 본인이 몇 가지만 질의하고자 합니다.  청사를 구입하는데 상당히 노고가 많았다고 생각이 듭니다.  금년 6월에 소유권 이전을 하시고 내년도에 이렇게 잔금을 완료하시는 것으로 자료에 있습니다마는 재원을 어떻게 마련하셨는지 그 내용을 밝혀 주시고 우리 경기개발연구원에는 각종 간행물이 많이 있습니다.  그것이 과연 우리 경기개발연구원에서 다 제작할 수 있는 시설이 갖추어져 있는지 그것에 대해서 명확히 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  지금 분당개발에 대해서 상당히 많은 논란이 있습니다, 도하고 성남시하고.  물론 우리 도에서 연구과제를 주셨는지 모르겠습니다마는 거기에 대한 경기개발연구원의 연구결과가 자세한, 앞으로 어떠한 개발이 제일 바람직한가 여기에 대한 원장님의 소신있는 답변을 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 49페이지에 보면 경기개발연구원 육성기금 운용현황에 있어서 예치은행이 한미은행에 상당히 편중되어 있습니다.  편중된 이유가 무엇이고 또 이자율에 차이가 많이 있습니다.  제가 왜 편중되었나 하고 말씀을 드리는 것은 제일은행 같은 데는 10억원을 출연한 기관입니다.  이런 것을 볼 때도 어느 정도 예탁금을 해줘야 되지 않겠느냐 이런 생각이 듭니다.  그런데 한미은행에 많이 치우쳐 있다, 또 이자율도 상당히 차이가 있다, 여기에 대해서 답변해 주시기 바랍니다.  이상으로 질의를 마치겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 위원장님!  자료하나만 요청하겠습니다.
</p>
<p><b>○ 위원장 김강선 </b> 네, 하십시오.
</p>
<p><b>○ 이진용 위원 </b> 경기개발연구원의 연구사업이 기본과제, 수탁과제, 정책과제 및 세미나와 공청회 이렇게 구분되어 있는데 연구원 설립이후에 분야별 과제현황하고 수탁과제용역의 계약현황을 자료로 제출해 주시기 바랍니다. 
</p>
<p><b>○ 위원장 김강선 </b> 이진용 위원님 수고하셨습니다.  더 질의하실 위원님 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  그러면 더 이상 질의하실 위원이 안 계시므로 답변준비와 중식을 위하여 오후 2시에 감사를 속개토록 하겠습니다.  감사를 중지합니다.
</p>
<p class=''ar''>(12시03분 감사중지)
</p>
<p class=''ar''>(14시19분 감사계속)
</p>
<p><b>○ 위원장 김강선 </b> 자리를 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  위원님들의 질의에 대한 답변을 듣도록 하겠습니다.  경기개발연구원장님 나오셔서 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 위원님들께서 질의하신 것을 항목별 혹은 질의내용별로 정리해서 답변을 드리겠습니다.  먼저 윤동욱 위원님께서 질의해 주신 중장기조직운영연구, 자치권 확대, 지방경찰제도에 대한 질의를 하신 것에 대한 답변을 드리겠습니다.  먼저 저희들이 진행 중인 경기도 중장기조직운영에 관한 연구내용에서 지역특성과 행정수요에 대응할 수 있는 조직운영을 기본바탕으로 설정해 놓고 연구를 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그러나 이것은 제도적인 문제이기 때문에, 행정자치부의 기준이 있기 때문에 현재 표준정원 산식 방법으로 실제 행정수요를 반영할 수 있도록 인구, 도시화율, 교통량, 사업체수, 규제지역면적 등을 면밀히 검토 반영하는 방안으로 연구를 하고 있습니다.  또한 경기도의 총 정원의 56%를 차지하고 있는 소방직을 일반행정직 총 정원과 분리하는 것으로 연구검토를 하고 있다는 것을 아울러 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  그리고 경기도내 70만이상 대도시의 행정수요, 인구증가 등을 고려하여 직급체제의 상향조정과 함께 점차 도시화가 급속도로 진행되고 있는 도시와 농촌의 복합수요가 제기되고 있는 군행정 기능을 강화할 필요가 있다고 생각합니다.  
</p>
<p style="padding-left:1.2em">  그리고 가장 중요한 시민수요 충족을 위한 경기도 본청의 경우 현재 상대적으로 사기가 저하되어 있는 6급과 7급 공무원에 대한 복지후생 차원의 사기진작과 과다한 업무편중을 시정하기 위한 탄력적인 인력운용 그리고 하부부서가 권한과 책임을 가지고 실제 주민에게 봉사할 수 있는 실질적인 권한이양 등이 필요함을 저희들이 연구하고 있는 중입니다. 
</p>
<p style="padding-left:1.2em">  그리고 자치경찰제의 연구진행사항을 말씀드리면 자치경찰제의 실시에 대한 지방자치단체의 대응방안을 연구하고 있으며 구체적으로는 경기도 등 자치단체의 입장과 요구를 충분히 반영하는데 그 목적을 두고 있습니다.  
</p>
<p style="padding-left:1.2em">  이에 따라 경찰기관 구성에 있어서 자치단체장이나 의원님들의 의견제시 문제, 국가경찰과 지방경찰의 기능배분 문제, 경찰재원의 조달방법 등에 대해 중점적인 연구를 하고 있습니다.  자치경찰제를 통하여 지역주민의 경찰서비스 복지증진에 기여하고자 하고 있습니다.  이를 위해 자치경찰제도가 먼저 실시되고 있는 미국이나 영국, 불란서, 일본 등 선진국의 사례를 면밀히 비교 분석 검토하고 있습니다. 
</p>
<p style="padding-left:1.2em">  끝으로 지방자치제의 자치권 확대방안과 관련한 연구내용을 보고드리겠습니다.  자치권의 수준을 진단하기 위하여 자치권한과 자치능력을 구분한 다음 자치권을 전체 자치단체에 해당되는 전체적인 자치권과 개별자치단체의 특성을 반영하는 개별자치권으로 나누어 연구를 하고 있습니다.  전체적인 자치권은 법, 제도, 지침과 지시, 기능배분, 재정통제, 조직인사 등으로 구분 고찰하고 있으며 개별적인 자치권은 중앙지침의 준수도, 정책다양성, 수요대응성, 자치단체의 주도권 등으로 나누어 고찰하고 있습니다. 
</p>
<p style="padding-left:1.2em">  자치능력 측면에서는 재정수요, 지방자치구조, 지방정부구조 등으로 나누어 객관적인 자치권 수준의 측정과 함께 고위직 공무원들이 주관적으로 느끼는 자치권을 측정하기 위한 6개 시·도와 6개 시·군의 공무원을 대상으로 설문조사를 실시하였습니다.  이러한 자치권 수준의 진단에 기초하여 자치단체의 자치권을 높이기 위한 정책방안으로 자치단체의 자율적인 통제와 책임확보장치, 자치단체의 자치능력에 상응하는 자치권한의 부여, 획일적인 중앙통제방식의 전환 등에 대하여 연구를 진행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  윤동욱 위원님과 노시범 위원님께서 연구실적 중 반영률이 전체가 어떻게 되는 거냐고 질의하신 것을 답변드리겠습니다.  먼저 연구결과에 대한 정책반영도를 객관적으로 명확하게 측정하기는 상당히 어려운 면이 있습니다.  그러나 사실 도 출연 연구기관으로서 정책지향적인 연구를 수행해야 한다는 것은 당위적인 요청이라고 생각하고 있으며 위원님들의 지적사항에 대하여 공감을 합니다.  현재 저희가 수행하고 있는 과정 중에서 정책과제는 경기도에서 구체적인 현안문제를 적시하여 그에 대한 연구를 요청하기 때문에 연구내용의 상당한 부분이 정책에 반영되거나 참고되고 있습니다.  수탁과제 역시 수탁을 부여한 기관의 요청에 따라 과제가 수행되며 수탁기관에서 수행을 지시하고 연구결과에 대해 검수하고 있기 때문에 상당부분이 그대로 반영된다는 것을 덧붙여 말씀드립니다.
</p>
<p style="padding-left:1.2em">  다만 기초자료조사와 중장기적인 검토사항을 위주로 수행되고 있는 기본과제의 경우 정책반영도가 상대적으로 떨어지는 것이 사실이나 이를 제고하기 위한 과제추천을 관련부서에 의뢰해 채택하고 있으며 연구를 심사하는 위원에 도의 담당공무원들이 참여하고 있습니다.  올해는 과제를 추천하시는 정운천 의원님께도 심사위원으로 활동하셨던 계기를 마련해 드린 바 있습니다.
</p>
<p style="padding-left:1.2em">  과제결과가 반영되어 현재 시행되고 있는 대표적인 사례로는 몇 가지만 말씀드리겠습니다.  1996년에 수행된 경기도 권역별 쓰레기소각장시설 설치에 관한 연구를 계기로 1시·군 1소각장 정책이 권역별 소각장시설 설치로 전환하는 정책으로 기틀을 잡아왔습니다.  그리고 행정서비스헌장제도를 연구한 1999년 연구결과에 따라 경기도청 및 각 시·군에 시민헌장제정의 기틀을 이미 마련한 바 있습니다.  그리고 1996년 실·국간의 경쟁력평가모형에 관한 연구결과에 따라 현재 경기도청의 각 실·과에 대한 평가가 이루어지고 있으며 1998년도에 수행한 팔당상수원 1급수를 위한 대책방안 연구결과에 따라 1999년에는 한강수계법이 제정되었으며 현재 물이용부담금제도의 기틀이 되었다고 생각합니다.  그리고 1999년도에 수행된 북부발전 연구결과는 접경지역지원법 제정과 시행령 제정의 기본방향과 법령안을 만든 바 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 김효정 위원님과…….
</p>
<p><b>○ 위원장 김강선 </b> 원장님!  부탁의 말씀을 드리겠습니다.  저희가 감사자료를 제출하고 경기개발연구원에서 자세히 자료를 주셨습니다.  그래서 우리 위원님들께서는 이미 자료에 의해서 많은 검토를 하시고 파악을 하고 계십니다.  답변에 있어서 좀 요점만 해주셨으면 하는 부탁의 말씀을 드리고 싶습니다.  계속 하십시오.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 요약을 해서 답변을 해드려야 되는데, 그럼 요약을 했을 때 위원님들께서 거기 누락되는 게 있다든지 보완을 하실 것이 있으면 지적을 해주시고, 양해를 먼저 구합니다.  
</p>
<p><b>○ 위원장 김강선 </b> 보충질의가 있습니다.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그래서 김효정 위원님과 이주석 위원님께서 수탁용역사업 계약금과 전출금 사이의 차액이 많이 생기는 사유와 처리방법에 대해서 말씀을 하셨습니다.  이는 저희가 수탁용역을 수주받으면 용역위원회를 개최합니다.  거기서 연구의 난이도라든지 연구실적이라든지 이런 것을 저희 규정 제4조 및 제10조 규정에 의해 용역심의위원회에서 심의받아서 20%∼30%의 수입금을 결정하고 차액 70%∼80%를 직접 연구과제에 투입을 합니다.  그리고 잔액이 발생할 때에는 연구원 수입으로 처리를 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 김효정 위원님께서 물으신 임금결정시 연봉인지 여부와 퇴직금제도 말씀을 하셨는데 연구직에 대하여는 2000년도부터 연봉제를 실시하고 있습니다.  지난 해에 퇴직금은 근속연수에 따라 누진제를 폐지하고 1년단위로 퇴직금을 지급하고 있습니다.  그리고 퇴직금은 1년이상 근속한 직원에 한하여 매월 12월말에 지급하는 걸로 되어 있고 최근 3개월간의 연봉 총액을 3으로 나눈 평균임금을 지급하고 있다는 것을 덧붙여 말씀드립니다.
</p>
<p style="padding-left:1.2em">  다시 연구직원의 임명절차를 물으셨는데 원장과 부원장, 상임고문은 이사회의 의결을 거쳐 이사장이 임명하고 있습니다.  행정실장과 연구직은 이사장이 임면하며 행정실장을 제외한 관리직원은 원장이 임면하고 있습니다.  그 다음에 감사요구자료 중에 상부기관에 감사제출 사유를 물으셨습니다.  위원님께서 요구하신 자료제출 목록에서 2000년도 상부기관의 수감사항으로 되어 있는 것은 사실 금년도에 수감실적이 없어서 제출치 못 했다는 것을 덧붙여 말씀드립니다.  참고로 저희 연구원은 ''99년 2월에 도 감사관실로부터 종합감사를 받고 그 조치결과를 지난 해 도의회에 제출한 바 있습니다.  양해해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음 양태흥 위원님께서 질의하신 평택항 자유지역 지정이 가능한지 물으셨습니다.  평택항은 지금 관세자유지역으로 지정되기까지 네 가지 요건이 필요하게 되어 있는데 세 가지 요건은 충족되고 한 가지는 아직 진행 중에 있다는 것을 덧붙여서 말씀드립니다.  그리고 문제의 연간 화물처리 능력입니다.  연간 화물처리능력이 1,000만t이상되어야 하나 현재는 695만t밖에 못하고 있습니다.  따라서 향후 평택항만의 활성화를 위해서 이 부분을 해결해야 한다고 생각합니다.
</p>
<p style="padding-left:1.2em">  그 다음에 양태흥 위원님께서 질의하신 개발구역관리계획 수립과제에 대해 물으셨습니다.  저희 원이 정책과제로 수행 중인 개발제한구역특별조치법 제10조에 근거하고 있으며 계획목적은 개발제한구역을 효과적으로 관리하기 위한 계획을 종합적으로 수립하고 개발제한구역 관리의 기본방향과 목표를 제시하고 주민생활불편을 최대한 하고 구역토지를 도시민에게 친화적인 여가공간으로 활용하기 위한 토지이용계획의 기본방향을 제시하고 있다는 것을 덧붙여서 말씀드립니다.  이와 같은 것이 기대되는 것으로는 개발제한구역의 조정후 조치는 대개 지역의 20호이상의 취락에 대한 정비 및 지원사업 등을 합리적으로, 관리계획으로 예산을 절감하는 방향으로 계획을 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 양태흥 위원님과 이진용 위원님께서 질의하신 도비보조금 운영제도의 개선방안에 대한 것을 말씀드리면 도비보조금 제도가 실제 운영과정에서 본래 취지를 제대로 살리지 못하고 있는 것을 지적 말씀드리며 도비보조금제도가 전략적 사업을 유도 추진하는 적극적인 정책유도·조정기능보다는 시·군의 일반적인 사업투자의 부족재원을 보완해 주는 소극적인 재원보전기능에 그친다는 것을 말씀드리겠습니다.  본 연구원의 이와 같은 문제를 직시하고 단기정책과제를 연구한 바 그 중요내용은 도비보조대상사업의 축소정리, 기준보조율 개편, 차등보조율 개편, 소규모 보조사업으로의 포괄적 보조확대, 표준화된 시설에 대한 정액보조 확대적용 등 현재 도에서 연구결과에 제시된 개선방향을 토대로 실행화를 적극적으로 검토하고 있다는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  또 도의회가 추천하여 채택한 연구 중에서 과제가 총 9건이며 그 내용은 생략을 하겠습니다.  9건이라는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그 다음에 이주석 위원님께서 연구수당의 지급이 어떻게 되느냐 물으셨는데 연구수당은 ''99년에 원장의 연구수당이 60만원, 상임고문 52만원, 선임연구원이 40만원, 연구원이 35만원, 책임연구원이 30만원, 연구원이 20만원으로 지급되고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 이주석 위원님과 유영록 위원님께서 말씀하신 정원 58명 중 현원이 44명이고 그중 연구직 결원이 13명인데 이에 대한 대책과 현재 위촉된 초빙연구원과 비상임연구원의 처우에 대해서 물으셨습니다.
</p>
<p style="padding-left:1.2em">  저희 연구원은 현재 연구직이 25명으로 정원 38명에 비해 13명이 결원인 것이 사실입니다.  향후 연구직의 지속적인 충원이 원칙적으로 필요하나 단순한 연구직의 충원이 아니라 꼭 필요한 연구분야에 대한 전문인력이 필요하므로 우수한 인력에 한정하여 충원해야 한다고 생각합니다.  그래서 2000년 하반기에 부족한 연구원 가운데 8명을 충원하기 위한 모집을 하였으나 연구원에서 연구과제 수행에 적합한 능력이 있다고 판단되는 사람 2명만 채용하여 지금 능력검증 중에 있다는 말씀을 드립니다.  그리고 부족한 전공분야의 초빙연구원제도 활용은 과제수행에 차질이 없도록 하겠으며 필수인력에 대하여는 우수인력 공급이 풍부한 2001년초에 신규모집을 할 계획입니다.  초빙연구원과 비상임연구원에 대한 처우는 초빙연구원은 원내 상근직으로 보수는 해당 연구분야의 전문경력과 학력별로 월 180만원에서 300만원까지 차등지급이 가능합니다.  기타 퇴직금 등을 지급하고 있습니다.  비상임연구원은 비상근직으로 보수는 연구경력과 학력별로 60만원에서 100만원까지 지급되고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 노시범 위원님께서 ''99년 불용액 발생사유 처리는 어떻게 하였는가 물으셨습니다.  ''99년의 불용액 총 규모는 9억 6,700만원으로 발생사유를 예산편성상 순서에 따라 보고드리면 기관운영비 예산에서 94%, 그 다음에 원장의 겸직발령 동안 미지급한 인건비, 당초 6개월에 편성된 청사유지관리 입주시기 지연으로 2개월 집행후잔액, 연구부운영 및 연구사업은 예산의 77%가 집행되었고 연구직 2명 이직 및 총정원 7명 중 4명만 충원되어 미집행된 인건비가 19% 남아 있습니다.  당초 28개 과제로 편성된 기본연구사업 중 27개 과제를 수행, 미선정과제가 있으며 과제별 예산집행률은 64%가 발생되며 총 27%를 집행한 바 있습니다.  경기지역연구사업 3회, 계획에 2회 수행하였습니다.  정기간행물 중 경기논단 사업량 축소, 6회에서 4회로 그래서 6.9%를 저희들이 수행하고 있으며 단기과제, 위탁과제 집행잔액은 2.7%, 기타 번역사업 등은 24%, 그래서 예비비가 8,404만 2,000원이 되겠습니다.  향후 적정예산편성을 위한 노력을 기울여 나가겠다는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그 다음에 ''99년도 경상예산에 차량비가 있는데 차량구입비인지 운영비인지 물으셨습니다.  경상예산에 편성된 차량비에는 차량의 유지 관리에 필요한 유류비, 수리비가 계상된 것으로 생각합니다.  따라서 차량비에는 차량구입비가 포함되어 있지 않다는 것을 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  연동현 위원님께서 물으신 수도권정책전환 10억원에 대한 용역관계 추진사항에 대하여는 지식기반산업전략 수도권정책전환방안을 위한 용역으로 도청에서 일반 경쟁방법에 의한 국제입찰협상계약방식에 의해서 처리되는 걸로 알고 있다는 것을 말씀드립니다.  
</p>
<p style="padding-left:1.2em">  다음 연동현 위원님과 유영록 위원님께서 물으신 경기도와 연구원의 GIS 활용을 위한 정책방향에 대해서 물으셨습니다.  경기도와 연구원의 GIS활용 극대화를 위한 정책의 기본방향으로 경기도의 경우 각 지자체별 GIS추진에 대한 조정과 기본방향 제시, 경기도 자체의 GIS관리 및 수요에 대한 정보파악, GIS의 종합적인 마스터 플랜을 수립하려고 하고 있다는 것을 말씀드립니다.  저희 원에서 기존 데이터 활용 및 GIS관련 교육실시, 원내 연구진에 대한 GIS 정보제공 및 유통, 경기도 GIS의 기본계획 수립을 위한 리딩그룹으로서 역할을 담당한다는 것을 말씀드리고 마지막으로 경기도 각 시·군, 저희 원과의 시스템통합 문제는 각 기관의 GIS수요와 목적이 다르므로 현 상태에서 시스템의 통합은 어려운 실정입니다.  다만 네트워킹을 통한 정보의 공유가 필요하다고 보며 경기도와 지자체, 연구원간의 데이터베이스를 원활히 공유하고 중복투자를 막기 위한 마스터플랜을 저희들이 만들려고 준비 중에 있다는 말씀드립니다.
</p>
<p style="padding-left:1.2em">  다음 연동현 위원님께서 말씀하신 도 보조기관의 증인출석 사안에 대한 연구에 관한 것을 말씀해 주셨는데 경기도의회행정사무감사및조사에관한조례 제11조에 의하면 증인·참고인으로서 의견진술을 요구할 때 경기도 조례에서 특별한 규정이 없는 한 이에 응해야만 하고 이에 응하지 않거나 증언에 거부한 사람에게는 제31조제1항의 기준에 의해 과태료를 부과할 수 있도록 되어 있습니다.  그럼에도 불구하고 지난 행정사무감사시 시장·군수들이 출석에 응하지 않아 과태료 처분을 하였으나 시장·군수들이 소송을 제기하여 경기도가 패소한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  연동현 위원님께서 북부지역 발전전략에 관한 것을 말씀해 주셨는데 저희 경기북부지역발전을 위해 현재 제2청의 용역의뢰로 경기북부지역 친환경산업단지 조성계획을 2001년 6월까지 끝내기로 되어 있습니다.  이 연구는 저희 연구원을 포함해서 산업연구원, 외국계 컨설팅회사 아더앤더슨사가 공동연구로 추진하고 있다는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  다음에 이진용 위원님께서 질의해 주신 2000년도 이사회가 3회에 걸쳐서 열렸고 모두 원안 의결된 것으로 되어 있는데 이사회 운영이 미흡한 것이 아니냐 물으셨습니다.  금년도 이사회는 3회이고 의결안건은 8건이었습니다.  금년 2월 1일에 개최된 제19차 임시이사회에서는 상임고문의 임기를 1년 단임에서 1년이내 범위내에서 연장할 수 있는 근거규정 개정과 동 상임고문이 이사 선임되었고 2000년 3월 10일에 개최된 20차 이사회에서는 선임직 이사 중 인사발령으로 교체된 도 기획관리실장을 새로이 이사로 선임한, 절차상 이행을 한 것뿐이라는 것을 말씀드립니다.  그리고 2000년 8월 4일에 개최된 21차에서는 비상임정책연구위원제를 신설하는 것을 이사회에서 결정하였습니다.  이사회 안건에 대해서는 이사회 개최 10여일전에 이사님들께 사전송부해 드리므로 충분한 검토가 이루어지고 있다는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  다시 이진용 위원님께서 말씀하신 연구원 내부위원회의 종류와 운영에 대하여 물으셨습니다.  현재 원내에 설치된 위원회는 단기정책과제의 선정, 연구범위를 심의·의결하는 자체연구심의위원회, 원내 규정 개정을 심의하는 규정심의위원회, 기금의 안정성 및 운영방안을 정하는 기금관리위원회, 수탁용역과제의 실행과 연구방향을 정하는 용역사업심의위원회, 연구직의 재임용을 심의하는 재임용심의위원회 등이 있습니다.  총 7개 위원회를 운영하고 있는 바 위원회 구성은 각 위원회의 설치 목적별로 원내 박사들을 위원으로 임명하여 운영하고 있습니다.  금년 원내 위원회의 개최실적은 자체연구심의위원회가 26회, 규제가 1회, 기금이 7회, 용역이 79회, 인사 5건이 있었고 간행물에는 7회가 개최된 것을 덧붙여 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  다시 수도권 난개발에 관련된 연구결과 정책방향은 그간 우리 연구원에서 수행한 연구과제는 1996년 대도시를 위한 농촌지역정비에 관한 연구, 1997년 수도권근교지역법·계획관리체제의 개선방안 연구, ''98년에 경기도 도농복합시 도시계획·관리모델 연구, 2000년에는 용인 등 수도권난개발방지 등 4개 과제에 있었고 경기도 등의 검토 의뢰를 받은 검토안은 ''98년에 1건, ''99년에 2건, 2000년에 1건 등이 있으며 특히 2000년 8월 30일에는 감사원 요청에 의한 검토결과를 회신한 바 있습니다.  이러한 연구결과와 검토안은 경기도 지역정책과 업무방침의 수립, 감사원의 난개발관련 감사보고서 작성에 반영됐고 이번 국토이용 및 도시계획에 관한 법률안 초안에도 반영된 바 있습니다.  우리 원이 생각하는 난개발에 대한 대책은 준농림지역에 대한 개발허가 기준강화를 위한 개발허가제를 조속히 시행하고 공동주택 개발시 교통시설과 공공시설의 설치를 위한 시설부담금 부과의 기준과 시행제도를 확립하고 개발이 예상되는 지역은 도시계획구역에 편입하여 도시기본계획을 수립, 종합적으로 관리하는 단기정책이라고 생각을 합니다.  오늘 아침에 이와 같은 것을 채택하여 건설부에서 종합계획에 관한 것을, 저희들이 안을 낸 것을 발표했습니다.  
</p>
<p style="padding-left:1.2em">  그 다음에 이진용 위원님께서 질의하신 ''95년과 2000년 자립도 변화추세와 향후 자주방안, 먼저 ''95년의 자립도 추이를 보고드리면 100%를 자체재원으로 충당하였으며 ''96년에 84%, ''97년에 81%, ''98년에 86%, ''99년에 57% 2000년에 와서 44%로 점차 자주재원 충당비율이 낮아지고 있습니다.  그 이유는 1996년에 수립한 경기개발연구원 중장기계획에 의해서 2000년도 연구원의 기금적립 목표액은 370억원이었습니다.  매년 경기도의 적극적인 기금출연 지원에 힘입어 목표가 순조롭게 달성되었으나 ''97년부터 IMF 경제위기로 도세수입이 대폭 감소됨에 따라 경기도에서 도비보조금을 통한 운영경비 지원방식으로 전환하게 되었습니다.  그래서 ''99년에 3억원, 2000년에 3억원만이 자체적립하여 현재의 기금규모는 206억원을 확보되어 목표의 55%를 달성하고 있다는 것을 말씀드립니다.  현재 재정여건으로는 기금조성을 위한 출연금지원이 어려운 상황이므로 연구원 자체적으로 수탁사업 수행시 내부 연구진의 투입비율을 높여 전출금 전출비율을 20%에서 30%로 확대, 자주재원을 확충하려고 노력하고 있다는 것을 덧붙여 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그리고 계속해서 2000년도까지 209억원인데 기금의 운용현황과 향후 확보방법을 물으셨기 때문에 이와 같은 것은 별도로 시간을 내서 자세히 설명을 드리고자 합니다.  그러나 분명히 말씀드릴 것은 자주재원 달성을 위해 추가출연금 확대 노력과 수탁사업 수주노력 등을 통한 재정자립을 위한 노력을 계속 기울여 나가겠다는 것을 말씀드립니다.  
</p>
<p style="padding-left:1.2em">  다음 이진용 위원님께서 한강수계 물이용부담금 제도의 효과적인 운영은 먼저 오염총량제에 대해 설명드린다면 환경부가 제시한 한강수계 오염총량관리제 시행은 이 제도의 기초라고 할 수 있으며 오염물질 관리목표 과다설정, 수계가 아닌 행정구역별 제도시행으로 파생되는 문제점 미극복 등의 이유로 현실화되기 어렵다는 것을 결론으로 말씀을 드립니다.  다음 한강수계 물이용부담제도의 효과적인 활용방법에 대해 물으셨습니다.  연구원에서는 그 동안 연구결과에 의하면 수변지역의 소유권과 관련하여 지자체 소유근거를 얻을 수 있었고 해당 지자체간의 지분설정의 어려움을 극복할 수 있는 이론적 뒷받침을 연구하고 있다고 말씀드립니다.  그리고 연도별 수탁과제 세부현황은, 저희 연도별 연구현황과 수탁과제는 첨부해서 다시 만들어드리겠다는 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  끝으로 유영록 위원님께서 말씀하신 ''99년도 출연금에서 보조금 지원방식으로 전환하는데 연구원이 발전하기 위해서는 어떤 형태가 바람직한지 원장의 소신을 물으셨습니다.  저의 소신은 ''99년 이전에는 시중금리가 두 자리를 유지하고 있었고 연구원의 당초 기금목표 370억원이 조성될 경우 연구원의 자립재정에는 문제가 없었습니다, 이자율이 높았기 때문에.  그러나 아시는 바와 같이 시중금리가 한 자리 숫자로 떨어졌기 때문에, 이와 같은 문제가 있었으므로 기금출연에 의한 재정자립은 한계가 있어서 도에서는 기존의 기금운영수입외에 보조금 형태의 추가적인 지원 방식으로 ''99년부터 방향을 전환하였습니다.  따라서 지속적인 보조금 지원은 연구원의 독립채산에 의한 자립의지를 약하게 할 수 있는 문제와 지속적인 도비지원의 증가는 어려운 실정이고 기본적인 재정자립 방향은 첫째 기금출연에 의한 이자수입 비중을 60%정도의 설정과 둘째 도, 시·군의 각종 용역 등의 적극적인 수주노력으로 용역수주에 의한 수입비중을 20%로 높이고 셋째 기금이자 수입과 용역수입에 의해 충당될 수 없는 나머지 부분 20%를 보조금으로 충당하는 방법을 고려하고 있다는 것을 말씀드립니다.  그리고 이 경우 도의 부담을 최소화하면서도 연구원의 안정적인 재정확보로 도 정책연구에 전념할 수 있는 기회를 만드는 것이라고 생각을 합니다.
</p>
<p style="padding-left:1.2em">  그 다음 도서비 구입이 너무 적게 책정된 것이 아니냐 말씀하셨는데 현재 도서비 구입은 6,400만원 맞습니다.  국내외 학술잡지 등 정기간행물 해서 1억 2,000만원의 예산이 책정되어 있습니다.  이러한 예산규모는 지난 5년에 비춰볼 때 현재 연구원의 연구수행에 필요한 자료를 차질없이 구입할 수 있는 적정수준이라고 생각은 합니다마는 시정연구원이나 지방행정연구, 국토연구원, 타 연구원에 비하여 봤을 때 저희 연구원의 자료구입비는 높은 수준에 있습니다.  정기간행물사업의 결과 6종의 정기간행물 중 판매하기에 적정하지 않다고 판단된 4종에 대해서는 비매품으로 배포하고 있기 때문에 전체 정기간행물 예산규모에 대비하여 판매수입이 적게 차지하는 것은 사실입니다.  그래서 앞으로 연구원의 간행물 내용은 주로 경기도 지역이 대상으로 되어 있기 때문에, 국책연구원의 경우처럼 전국을 대상으로 하는 것이 아니기 때문에 시장규모가 적다는 것을 말씀드리고 이와 같은 요인을 극복하기 위한 판매수입에 의존할 수 있을 정도의 노력을 해야 한다고 생각합니다.  그래서 ''97년 판매를 시행해서 저희가 지금까지 계속 판매수입금이 늘어가서 700만원∼800만원 늘어나고 있습니다.  내년도에는 1,500만원이나 1,600만원이 수입금으로 되지 않겠는가 생각합니다.  그리고 이와 같은 것을 말씀드린 것은 저희들이 앞으로 더욱 이 분야에 노력하겠다는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그 다음 마지막으로 위원장님께서 청사구입 재원내용에 대해서 물으셨습니다.  총 44억 9,690만원에 매입한 연구원청사 매입재원은 전액이 도비보조금입니다.  청사매입비 지급현황은 3년 분할했습니다.  그래서 ''99년에 계약금 4억원, ''99년 8월에 1차 중도금 15억원, 2000년 3월 17일 2차 중도금 13억원, 2001년에 잔금 11억 9,600만원이 남았다는 것을 말씀드립니다.  각종 간행물의 자체제작에 관한 것을 말씀드렸습니다마는 현 연구원의 시설로는 자체 제작시설을 가지고 있지 않습니다.  그래서 외부에 위탁을 하고 있다는 것을 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  이상 대강 제가, 누락된 것도 있는 것 같습니다만 지루할 것 같아서 요약해서 말씀드렸습니다.  그리고 연동현 위원님이 질의하신 것이 답변 누락돼서 추가되었습니다.  과태료 처분관계에 대해서 말씀해 주셨는데 아까 조금 설명드린 것과 같이 법원에 경기도가 소송을 제기해서 패소한 바 있다고 말씀드렸기 때문에 그걸로 대신하겠습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 경기개발연구원장님 수고하셨습니다.  다음은 보충질의에 들어가도록 하겠습니다.  보충질의는 일문일답으로 진행하도록 하겠습니다.  답변에 있어서 원장님께서는 안건에 따라 전문분야의 부장님이 답변을 해도 되겠습니다.  보충질의하실 위원 계시면 거수로 신청하여 주시기 바랍니다.  연동현 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 연동현 위원 </b> 방금 원장님께서 소상하게 말씀해 주셔서 고맙습니다마는 우리가 도비지원에 대한 시·군 증인출석에서 패소한 사항이 관련근거가 지방자치법 제20조2항하고 지방자치법시행령 제17조4항, 행정사무감사및조사에관한조례 제30조1항에 맞추어서 증인출석을 했는데도 불구하고 전체적으로 패소를 했습니다. 
</p>
<p style="padding-left:1.2em">  그래서 제가 정책과제 차원에서 우리 경기개발연구원에서 이러한 부분을 분명히 시행령과 조례에 있는 사항을 더욱이 일선 기초단체, 물론 단체장들도 민선이어서 어려운 사항이 있겠습니다마는 부단체장들을, 전문가들이 계시니까 우리 의회에서 어떻게 절차를 밟아서 정책과제로, 경기도의회가 앞으로 이러한 것을 규칙으로 삼아서 토대로 해서 자치법을 다시 개정할 수 있는 이런 것을 연구할 수 있겠느냐는 의도로 질의를 드렸습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 위계질서라는 것이 제가 법의 전문가는 아니지만 법이 있고 시행령이 있고 조례도 있고 규칙도 있는데 법을 고치려면 어려운 것은 아니지만 이 법은 행자부에서 고쳐줘야 합니다.  저희들이 앞으로 그런 문제들이 있다는 것을 의식했기 때문에 법을 고치는 것은, 법을 저희들이 5개이상 만들었습니다.  경험은 있는데 이와 같은 것은 연구원의 차원에서 어떻게 법을 고칠 수 있는 방법을 연구 검토해서 그것을 고치는 방향을 제시할 수 있습니다. 
</p>
<p><b>○ 연동현 위원 </b> 최대한 접근할 수 있는 연구과제가 저 개인적인 생각도 그렇고, 왜냐하면 목적에 도비를 보조했는데 불구하고 기초자치단체장들의 목적에 버금갈 수도 있고 거기에 대한 근거가 향후 기초자치단체 31개 시·군의 예산심의나 편성하는데도 굉장히 도움이 될 수 있다라고 생각되기 때문에, 물론 현재 여러 가지 같은 규칙과 시행령이 있음에도 지금 의회에서 기초단체장과 접근하기가 상당히 어렵습니다.  그래서 이것을 경기도의회에서 경기개발연구원에 정책과제로 제시하는 것으로 해서 연구해 주셨으면 하고 당부드리고 싶습니다.
</p>
