<p><b>○ 양태흥 위원 </b> 설명을 잘 들었습니다.  설명하신 중에 평택항에 관해서 말씀하셨는데 네 가지 중에 세 가지는 충족되었고 한 가지 부분이 미흡하다, 진행 중이다 이렇게 말씀하셨는데 어떤 근거를 갖춰야 관세자유지역으로 지정받을 수 있는지 네 가지 사항을 저희 기획위원회에다 서류로 제출을 부탁드립니다. 
