<p style="padding-left:1.2em">  아울러서 아까 제가 질의한 내용에 대해 답을 안 하셔서 다시 한 번 여쭙겠습니다.  도지사의 공약사항이 215개항이 있는데 임기내 공약을 지킬 수 있는지 그 다음에 그 내용 중에서 부실공기업의 민영화 추진계획이 있는데 두 가지 부분을 혹시 의뢰를 받은 적이 있는지, 있으면 있다, 없으면 없다라고 간략하게 답변해 주시면 되겠습니다.  이상입니다. 
