<p><b>○ 경기개발연구원장 노춘희 </b> 죄송합니다.  여기 구체적인 내용이 준비가 안 되었다는 점에 죄송하다는 말씀을 드리고 그것은 추후에 다시 보완해서 말씀드리겠습니다.  그런데 제가 느끼기에는 공약사항이 215개인데 저희들이 구체적으로 공약사항을 하나하나 따져가면서 그 중에서 몇 개나 했으며 그런 것을 물으신 것 같은데 저희들 연구원이라는 것은 경기도 전체의 도정을 위해서 필요하면 공약과 중복이 돼도 그런 연구를 저희들이 하는 것은 사실입니다.  그러나 공약사항 몇 항해서 저희들이 받은 적이 없습니다, 공약사항 구체적으로.  경기도 전체를 놓고 봤을 때 전체 발전을 위한 발전계획이라든지 이런 정책적인 자료이기 때문에 저희들이 전체를 놓고 연구를 하지, 어떤 개인이 공약을 했기 때문에, 오지도 않을 뿐만 아니라 저희들 판단할 때 그렇게 연구한다는 점을 말씀드립니다.
