<p style="padding-left:1.2em">  아!  여기 자료가 와 있습니다.  늦어서 죄송합니다.  도지사 공약사항 실현을 저희들이 연구용역을 실시한 적이 있는가, 없는가 물으셨는데 공약사항 실현을 위하여 연구원에 구체적인 실현방안 연구용역을 의뢰받은 바는 없습니다. 
