<p><b>○ 행정실장 심무섭 </b> 행정실장 심무섭입니다.  우리가 수탁과제나 여러 가지 용역과제는 당초에 연구사업계획에 의해서 짭니다.  그런데 그것이 지금 여기에 나타나는 게 물론 과정을 다 수행해서 완결했다 하더라도 그 연구과제를 집행하다 보면 남은 금액도 있을 수 있고 그 다음에는 모자라는 경우도 있습니다. 
