<p><b>○ 노시범 위원 </b> 오해는 하지 말고 들어주셔야 될 부분인데 지금 정원을 보더라도 연구를 해야 될 박사님들 T/O가 12명 적혀 있습니다.  그리고 밖에서 그런 얘기를 들었어요.  경기개발연구원에 용역이 너무 과중하다, 심하다 그러기 때문에 한 분이 몇 개 과제를 연구해서 발표해야 하는 과중한 업무 때문에 제대로 연구가 안 되는 부분들도 많이 있다, 이런 부분들을 인정을 하실지 안 하실지 모르지만 저는 이해를 합니다.  왜냐하면 한 가지 과제를 가지고 충분한 자료, 현장답사 등등 여러 가지 절차를 거쳐서 완벽한 연구자료가 나와야 되는데 업무가 과중하다 보니까 이 자료, 저 자료에서 짜집기 식의 어떤 연구자료가 나올 수 있다는 것은 이해를 합니다, 현실이 그렇기 때문에.  그럼에도 불구하고 이렇게 많은 예산을 세워놓고도 그 예산을 제대로 활용하지 못하고 있다, 이 부분은 예산을 편성하는데 문제가 있지 않느냐, 본 위원은 이렇게 생각하는데 동감하세요, 아니면 반론을 제기하시겠어요? 
