<p><b>○ 노시범 위원 </b> 그런데 여기 보면 인쇄비 정도가 아닙니다.  상당수 예산이 불용처리되었는데, 왜 이 말씀을 드리느냐 하면 지금 경기도의 재정이 어렵다고 해서 시·군에서 연차적으로 해야 할 사업도 중단상태에 있는 사업들이 상당히 많습니다.  그래서 예산편성을 할 때 제대로 된 예산편성을 해야겠고 기이 어떤 과목에 예산이 세워졌다라면 연구하는데 충분히 뒷받침이 되어서, 지금도 좋은 연구자료가 나오고 있습니다만 양질의 더 좋은 자료들이 많은 사람들에게 보급되었으면 좋지 않겠느냐 이런 생각을 가지고 질의를 드린 것입니다.  
