<p style="padding-left:1.2em">  그런데 지금 전체적으로 보면 연구사업 미지출 내역, 기본연구과제, 경기지역연구사업, 정책연구과제 다 불용이 심각하게 많이 생겼습니다, 액수적으로 볼 때.  그래서 이 부분에 문제가 있다는 지적을 분명히 해드립니다, 어떻게 받아들일지는 모르지만.
