<p><b>○ 행정실장 심무섭 </b> 여기는 사업비의 변경사항에서 나오고 또 인건비 관계 잔액이라든가 이런 것도 있는데 위원님이 말씀하신 사항은 개선해 나가도록 하겠습니다. 
