<p><b>○ 노시범 위원 </b> 그리고 아까 사적으로 잠깐 원장님께서 말씀해 주셨습니다마는 지금 연구직의 정원이 턱도 없이 모자라는 실정입니다.  왜 그런지 그 부분을 명쾌하게 답변해 주세요. 
