<p><b>○ 경기개발연구원장 노춘희 </b> 그것은 제가 답변을 드리겠습니다.  대개 인력이라는 것이 저희들이 우수인력을, 만약 국제무역이다, 국제무역을 전공한 사람을 뽑으려고 공고를 합니다.  공고를 하게 되면 사람들이 오기는 옵니다.  우수한 사람들을 뽑아놨는데 보수얘기가 나오면 그만둡니다.  그런 사람이 몇 사람이 와서, 지난 번에도 뽑을 때 그런 문제가 있었고 그래서 이게 경쟁이기 때문에 원천적으로 저희들이 좋은 작품을 만들려면 좋은 원자재가 있어야 하는데, 그래서 보수규정이 다른 데보다 높지 않으면 요즘 젊은 사람들은 왔다가도 그냥 갑니다.  그래서 박사들도 외국에서 많이 오고 지금도 시험보면 옵니다.  와서 제일 걸림돌이 되는 것이 보수를 가지고 잡습니다.  처음에 왔다 하더라도 갑니다.  그래서 저희들이 미쯔비시 같은 데 동경에서 사람을 모셔오다시피 했었습니다.  한 3개월 근무를 시켰는데 일본에 노무라라는 회사에서 데리고 갔습니다, 돈을 더 주고.  그러니 붙들어다 놨는데도 외국회사에서 돈을 더 주니까 가버립니다.  그래서 그것을 당장 저희들이 다른 데처럼 우리 도도 살림이 어려운데 이것을 갑자기 올려달라는 것은 아닙니다.  이제는 국책연구원과 비슷한 보수를 주라고 지사님이 말씀을 하셔서 조정작업을 하고 있습니다.  연봉 4,500만원 이렇게 해서 광고를 내서, 모집공고를 냅니다.  그렇게 하지 않는 한 왔다가도 없어지는, 사람이 몇 달 있다가 보수때문에 갑니다. 
</p>
<p><b>○ 노시범 위원 </b> 지금 보수문제에 대해서 연봉제 3,000만원이 되었건 4,000만원이 되었건 연봉제로 체결하고 나중에 박사님들이 과제를 맡을 것 아닙니까?  거기에 대해서 성과급은 없습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 성과급을 저희들이 하고 있습니다마는 제도를 바꾸려고 합니다.  심한 얘기는 제가 여기에 와서 외부수탁, 가만히 있어도 해달라고 시·군에서 자꾸 옵니다.  저희들이 못해요, 인력이 없기 때문에.  그래도 할 수 없어도 하는 것은 저희 인력을 바깥에 460명의 외부 풀을 만들어 놨는데 대학교수라든지, 필요하면 그 사람들한테 아웃소싱을 합니다.  아웃소싱을 하려고 해도 여기 누가 PM이 있어야 되는데 지배인이 없는 프로젝트가 없잖아요.  지배인이 하나라도 있어야 돼요, 기본적으로.  그것은 채워달라는 얘기지요.  그게 저희가 얘기하는 50명이 되어야 합니다.  50명이 되어야 매니저 하나씩이라도 있어서 아웃소싱할 수 있는 것이 없다는 것입니다.  그러니까 안 되고 있어요.
</p>
<p style="padding-left:1.2em">  그 기본은 어떻게든지 채워줘야 되지 않겠느냐는 것이 저희들이 안고 있는 문제입니다.  그래서 지난 번에 지사님이 알아들으시고 "그럼, 높입시다" 해서 조정작업을 하고 있습니다.  그래서 보완이 될 것으로 생각합니다. 
</p>
<p><b>○ 노시범 위원 </b> 제가 의정생활을 한 6년 동안 하고 있습니다만 경기개발연구원은 처음 업무를 가까이에서 지켜보는 모습인데 제가 오늘 와서 깜짝 놀란 게 있습니다.  정원의 50% 정도가 연구직이 모자라고 연구해야 될 과제는 상당수 많은 일들을 처리해야 하고 그러다 보니까 밸런스가 안 맞는 그런 모습들을 보면서 기 많은 예산을 투자해서 만들어 놓은 연구원이라면 제대로 가동될 수 있도록 모양새는 갖추어야 되지 않을까라는 생각을 합니다.  그래서 바로 이러한 감사자리에서 그러한 문제점이 있다라면 들추어내서 의회와 함께 고민하는 모습속에서 제대로 되게끔 만들어 내는 것도 우리들의 역할이 아니겠는가 생각합니다.  이상입니다.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그렇습니다.  하여튼 위원님들께서 많이 도와주셔야 합니다.  저희들이 힘이 어디에 있습니까?  위원님들께서 도와주십시오. 
</p>
<p><b>○ 위원장 김강선 </b> 노시범 위원님 수고하셨습니다.  다른 위원님 계십니까?  이진용 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이진용 위원 </b> 질의드리기 전에 자료취합이 되셨습니까?  사업연혁별로…….  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 죄송합니다.  준비가 늦어져서.
</p>
<p><b>○ 이진용 위원 </b> 팔당호 수질보전을 위한 오염총량관리제의 효율적 시행방안에 관해서 아까 원장님께서 말씀하셨는데 확실하게 어떻다는 것인지?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 구체적인 수치나 이런 것까지 우리 성 박사님이 연구하시니까 성 박사님이 답변하도록 하겠습니다.
</p>
<p><b>○ 이진용 위원 </b> 그렇게 하세요. 
</p>
<p><b>○ 환경연구부장 성현찬 </b> 환경연구부장 성현찬입니다.  
</p>
<p><b>○ 이진용 위원 </b> 간단하게 지금 연구가 어떻게 돼 가지고 결과가 어떻게, 70%정도 됐으니까…….   
</p>
<p><b>○ 환경연구부장 성현찬 </b> 지금 연구를 진행하고 있는 중입니다.  70%밖에 안 됐는데 지금은 결론나온 것은 없고 그 동안에 문제가 됐던 그 부분하고 합리적인 내부문제하고 그런 것을 연구 중에 있고 외국의 자료를 비교 분석해서 기존에 우리가 대응했던 문제점이 무엇이고 앞으로 어떻게 할 것인지 연구를 하고 있습니다.  그런데 이진용 위원님이 질의하신 것은 한 달 정도만 기다리면 결론이 나오는데 나오면 드리도록 하겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 알겠습니다.  원장님께 한 가지 요청하겠습니다.  도에서 경기비전2020에 의하면 권역을 역시 5개로 설정해 놨는데 연구원에서 정한 것하고 상당히 유사한데 부분적으로 틀린 부분이 있습니다.  남양주가 경기2020비전에는 동부내륙권으로 들어갔는데 경기개발연구원의 권역별로는 환상대도시권으로 들어가 있는데 이게 어떻게 연구원에서 제시하는 권역구분을 도에서 받아들여서 한 것인가, 아니면 근본적으로 출발이 틀렸습니까?  어떻게…….  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 2020을 연구하신 양기용 박사님이 계십니다.  양기용 박사님이 구체적인 답변을 해드리겠습니다.  후속은 제가 답변드리겠습니다. 
</p>
<p><b>○ 기획조정부장 양기용 </b> 경기개발연구원 기획조정부장 양기용입니다.  권역구분에 대해서는 아까 제가 보여드린 것은 경관관리 측면에서의 구분이었고 저희가 ''97년부터 시작한 2020계획에서는 권역은 그대로 유지하고 있습니다.  다만 경관측면에서, 그러니까 도시기능의 연계성하고 아까 보여드린 것은 경관녹지측을 중심으로 했기 때문에 약간의 차이는 있다는 것을 말씀드리겠습니다. 
</p>
<p><b>○ 이진용 위원 </b> 됐습니다.  
</p>
<p><b>○ 기획조정부장 양기용 </b> 그리고 아까 노시범 위원님께서 불용액 관계를 말씀하셨기 때문에 잠깐 제가 추가적으로 답변을 드리겠습니다.  기본연구사업에 상당히 많은 불용액이 있는 게 103쪽에 나오고 있습니다.  그런데 그 이유 중에 하나가 아까도 말씀드렸지만 많은 과제가 연단위로 진행되고 있고 연말에 가서 출간됩니다.  그래서 아마 위원님들에게 많은 자료를 드리지 못했는데 1월쯤이면 많은 자료가 갈 겁니다.  그래서 대부분의 출판비가, 인쇄비가 1억 5,000만원 가량이 연말에 집행되게 됩니다.  그 금액을 일단 감안해 주시고요, 마찬가지로 위탁연구과제도 저희가 연중에 집행해서 연말에 마무리하면서 마지막 완납금을 주게 됩니다.  그런 내용도 있고 연구조성사업의 번역률도 연말까지 저희들이 마무리하려고 합니다.  그것은 외부에서 위탁을 주고 번역을 받아오면 저희가 거기에 대한 대금을 지불하기 때문에 그런 측면에서의 잔액이 더 발생했다는 말씀을 드리고, 물론 노 위원님이 지적하신 대로 어느 정도의 불용액이 전혀 없다고 말씀드리지는 않습니다마는 현재 자료에 나타나는 2000년도의 불용액은 연말이 되면 어느 정도 소화가 될 것이라고 추가적으로 답변을 드리겠습니다. 
</p>
<p><b>○ 김효정 위원 </b> 아직 정산이 안 된 거지요?
</p>
<p><b>○ 기획조정부장 양기용 </b> 네, 정산이 아직 안 된 겁니다.  
</p>
<p><b>○ 노시범 위원 </b> 잠깐만요.  그 답변 중에 사실은 2000년도 게 9억원이 넘어요.  인쇄비 몇 억원이 빠졌다 하더라도 상당수 불용액이 생긴 거거든요.
</p>
<p><b>○ 기획조정부장 양기용 </b> 네, 그러니까 위원님이 지적하신 대로 연구과제가 좀 많고 그 다음에 충분히 연구사업을 통해서 완전히 그것을 활용하지 못했고, 저희가 올해 연구직을 말씀드린 대로 8명을 추가적으로 뽑으려고 했습니다.  연구직을 추가채용하면 그분들이 상당 부분 연구를 맡아서 예산을 사용할 계획을 세웠는데 말씀드린 대로 연구직 채용이 늦어졌고 또 주어진 연구직도 다 채용을 못했고, 이직한 분들을 충원 못했기 때문에 연구사업에 상당한 차질을 빚은 것은 사실입니다.  추가적으로 제가 보충설명을 드렸습니다. 
</p>
<p><b>○ 이진용 위원 </b> 제가 질의하는 도중이었으니까 마저 질의하겠습니다.  연구사업비와 관련한 것이기 때문에 답변하실 수 있으면 하세요.  다른 부분들은 지금 말씀하신 것이 어느 정도 이해가 가는데 경기지역 연구의 경우에는 집행률이 약 6%밖에 안돼요.  3,530만원에서 183만원 집행됐기 때문에 편차가 상당히 큰데…….  
</p>
<p><b>○ 기획조정부장 양기용 </b> 원래는 지역연구 계획을 네 군데를 잡았었습니다.  그런데 저희가 작년, 올해 수탁과제가 굉장히 많았기 때문에 소화를 못했습니다.  그래서 두 지역으로 줄여서 수행했고 다음에 평택지역연구는 여름에 시작해서 12월말에 마무리 지을 것이고 그런데 아직 거기도 원고료하고 인쇄비가 나가지 않았습니다.  그리고 가평지역연구도 저희가 10월에 발주해서 11월에 출장갔다 온 상태입니다.  그래서 그것을 12월까지 마무리할 예정입니다.  그래서 지역연구가 네 군데에서 두 군데로 줄었고, 하반기에 집행되었기 때문에 아직 인쇄비라든지 원고료가 나가지 않아서 경기지역연구의 예산집행이 상당히 저조한 실정입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 이진용 위원님 수고하셨습니다.  다른 위원 계십니까?  이주석 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이주석 위원 </b> 원장님, 답변하시느라고 수고 많으셨습니다.  간단하게 질의를 하겠습니다.  ''99년도하고 2000년도 연구건수를 보니까 1건을 연구하신 분이 12명, 2건이 8명, 3건이 1명, 4건이 2명, 5건이 2명입니다.  5건을 연구하신 분하고 1건을 연구하신 분 12명으로 차이가 나는데 이것은 연구사업에 따라서 달라집니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그게 연구과제의 성격에 따라서 질이라든지, 양이라든지 그것이 문제가 돼 가지고 어떤 것은 1년 연구하는 것도 있고, 2년 연구하는 것도 있기 때문에 그렇습니다. 
</p>
<p><b>○ 이주석 위원 </b> 그럼 아까 말씀하신 성과급도 연구과제에 따라 다릅니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 성과급은 연구과제에 따라서 현재는 상대적으로 운영되고 있습니다.  연구과제를 많이 한 사람은 많이 나가고 적게 한 사람은 적고 그것은 어느 정도 조화를 이루면서 운영하고 있습니다.  왜 그런고 하니 저희들이 경기도의 업무내용을 분석해 보니까, 전체 업무량의 55%가 도시문제입니다.  나머지가 환경으로 되기 때문에 연구과제가 많은 곳은 굉장히, 과제를 덜 맡게 되면 성과급이 적으니까 조율해서 형평성을 유지하고 있습니다. 
</p>
<p><b>○ 이주석 위원 </b> 그런데 아까 결원문제가 나오고 성과급 말씀도 있었지만 앞으로 결원을 적게 하기 위해서는 원장님께서 연구실적에 따라서 성과급을 많이 주는 방향으로 연구를 해보셔야 결원이 적을 것 같은데 원장님 생각은 어떠신지?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것이 맞습니다.  외국대로 한다면 성과급 중심으로 했어야 하는데 우리나라 정서로 봐서는 우리나라 정서에 맞는 성과급 제도로 가야지외국식으로 운영한다고 할 것 같으면 굉장히 어려운 문제가 나오지 않겠나, 그건 무슨 얘기냐 하면 너무 경쟁이 심하게 되면 그 경쟁에서 떨어지는 사람들은 결국 낙후되기 때문에 굉장히 불평하게 되고 사회가 분열됩니다.  그래서 사회가 분열되지 않는, 연구원이 분열되지 않는 그런 범위안에서 성과급 제도가 얼마냐, 그것을 저희들이 지금 연구하고 있습니다.  지금 다른 국가기관에서 성과급을 외국식으로 운영하고 있는데 그것이 오히려 일을 하는데 저해요인이 된다는 얘기입니다.  미국 같으면 되는데 우리나라는 어려운 것이 발견되어서 남이 잘못한 것을 그대로 따라가지 않겠다는 것이 저희 생각입니다. 
</p>
<p><b>○ 이주석 위원 </b> 알겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 김강선 </b> 이주석 위원님 수고하셨습니다.  다른 위원님 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  위원님들의 질의가 끝난 것 같습니다.
</p>
<p style="padding-left:1.2em">  제가 질의를 드리겠습니다.  제가 오전에 질의한 것이 두 가지가 빠졌어요.  첫째는 206억원에 대한 기금운영에 있어서 위탁이 편중되어 있다.  이자도 한 군데 있지 않고 차이가 있는 점, 그것에 대해서 간단히 우선 답변을 해주시길 부탁드립니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 한미은행 예금이 예치된 것이 차이가 있는데 그 말씀을 해주셨는데 기금의 75% 정도가 예치된 경우는 저희 연구원이 기금의 안전성 확보와 수익률 문제로 해서 기금의 만기가 도래되게 되면 재무 견실도가 높은 시중은행 6∼7개를 대상으로 연이율 조사를 실시합니다.  그래서 제일 높은 곳을 정해서 예치를 하다 보니까 그런 면들이 발생되었습니다. 
</p>
<p><b>○ 위원장 김강선 </b> 실리를 생각해서 편중되었다, 그렇게 보시는 것입니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 위원장 김강선 </b> 그 다음에는 분당개발에 대해서 제가 원장님의 고견을 부탁드린 바가 있습니다.  이것은 물론 성남시에 대한 문제만은 아니고 우리 도의원도 과연 어떤 개발이 바람직한지 900만 대표로서 도정에 소신을 정립하고 나아가서 우리가 집약된 의견을 갖고 중앙정부와 거기에 대한 대처를 해야 되지 않겠느냐.  용인개발이 일방적인 중앙개발로 해서 난개발이 되고 있어서 상당히 문제점이 많이 있습니다.  그래서 많은 연구를 하시고 경험이 풍부하신 원장님이 분당개발에 대해서 좋은 고견을 말씀해 주십사 하는 질의를 했는데…….
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그 부분은 제가 말씀을 안 드렸기 때문에 끝내시는 줄 알고 아까 말씀드렸는데, 정곡을 찔러 주셨는데 위원장님께서, 도시를 개발한다는 것이 근본적으로 저희들이 5개 신도시를 만들 때 건설부하고 굉장히 논란이 많았는데 저는 반대를 했던 사람의 하나입니다.  ''88년 분당도시를 만들기 위해서 정부에서 시작을 했는데 왜 도시를 그렇게 만들면 안 되는 이유를 설명했습니다.  그것은 대통령 앞에서 설명한 겁니다, 지금 말씀드리는 게.  경제수석 앞에서.  
</p>
<p style="padding-left:1.2em">  도시라는 건 하루 이틀에 이루어지는 게 아니다.  만약 20만 도시를 만들려면 다른 외국에 비하게 되면 보통 15년이 걸립니다.  왜 15년이 걸리냐, 도시는 조사를 해야 되고 지형이나 여러 가지 형편을 기본적으로 조사하는 시간이 많이 들어갑니다.  그리고 과학적인 조사 데이터로 인해서 인공적인 시설을 만들기 때문에, 인공적인 것은 사람이 움직이는 것이기 때문에, 생명체이기 때문에 다섯 가지 기능이 같이 한 세트로 들어가야 도시화 된다는 것이 교재 1페이지에 나오는 겁니다.  그렇기 때문에 도시는 그렇게 만드는 것이 아니니까 분당을 만들 때 5개 신도시 만드는 것을 정부가 내놓고, 그때 5대 신도시를 15조원을 출연해서 31조원의 효과와 166만인의 고용효과와, 그런 얘기를 하고 목표를 세워놓았었습니다.  그러나 그것이 전 안 된다고 얘기했습니다.  왜 안 되느냐, 주택만 만들어 가지고는 도시가 안 된다는 것이 저의 근본이기 때문에.  도시는 주택만 가지고는 안 됩니다.  다섯 개 기능이 한 세트로 가야 된다는 거.  다섯 개가 뭐냐, 직장, 주거지, 학교, 교통, 그리고 놀아야죠, 사람이 돈 버니까.  다섯 가지는 하나의 세트로 갑니다.  그래서 주거지역은 30%, 공업지역은 5%, 위락지역은 7%, 녹지지역은 60% 비율이 있습니다.  그리고 외국비율하고 우리나라 비율하고 다릅니다.  그 비율 때문에 이렇게 가지 않으면 실패한다.  실패했지 않습니까? 
</p>
<p style="padding-left:1.2em">  그래서 이번에 또 옛날식으로 신도시를 만들겠다고 하는데 그때 당시 도시계획법에서 도시를 만드는 것은 세계 어느 나라든지 법에 있어야 됩니다.  택지개발촉진법이라고 특별법을 만들었습니다.  그것이 예정지구를 건설부가 만들어서 지정합니다.  그 법에 의해서는 다른 게 따라오지 못합니다.  도시계획법도 맥을 못춰요.  그래서 도시개발계획에 의해서 법에 의해서 다 망가지는 겁니다.  왜 도시를 만드는 데 택지개발촉진법이, 옛날에는 필요했습니다.  저희들이 60년대라든지 그럴 때 국가가 힘이 있고 개인이 약했을 때.  지금은 개인이 공공보다 7대 4, 거꾸로 되지 않습니까?  이제는 민간에게 맡겨라 이거죠.  민간의 시장논리에 의해서 해야 된다는 것이 제 주장이고.  정부가 기틀을 잡아줘라, 기틀을 잡아주지 왜 정부가 나가서 땅 파고 하느냐 그게 잘못됐다는 거죠. 
</p>
<p style="padding-left:1.2em">  그래서 이번에 지정고시 하는 것도 저희들이 반대하고 설득시키고 그래서 주춤하고 있는 겁니다.  이제 남은 게 판교가 남아있는데 판교는 성남시가 얘기하고자 하는 것이 택지개발해서 땅 팔아 먹겠다는 얘기죠.  그래서 저희들이 안 된다는 거죠.  저희들이 다시 기획했습니다.  "안 된다 택지개발 12%로 줄여라.  60만밖에 안 된다" 원래는 30만 수용을 하겠다는 겁니다.  아파트 30층 올려가지고 경관 다 버리고 비행기 내리는데 그렇게 해서 하겠다는 겁니다, 성남에서.  그래서 지금 반대해서 브레이크 걸려서 저희들 안 대로 가는 걸로 생각하고 있는데.  질의하신 판교 벤처단지 그걸 말씀드리는 것이 아니고 경기도는,  도면이 되어 있을 겁니다.
</p>
<p style="padding-left:1.2em">  서울을 들락날락하는 인구가 64%입니다.  분당도 그렇고 일산도 그렇고.  서울의 직장수가 350만개밖에 안 됩니다.  서울시내에 있는 사람들이 차지하고 있는 것이 210만밖에 안 됩니다.  나머지는 경기도에서 다 갑니다.
</p>
<p style="padding-left:1.2em">  그럼 도시라는 것은 모 도시가 있어서 모 도시에 의존하기 때문에 이 도시들은 자꾸 분산을 해서 기능을 해야 됩니다.  그런데 그것이 전부 경기도 안에 있는 도시들이 그 기능을 해야 되는데 못 한다 이거예요.  분당도 저렇게 지어 놨습니다.  아까 말씀드린 대로 직장이 있으면 놀이시설도 있고, 학교도 있고, 이것이 다 있어야 살 수 있지 않습니까?  근데 서울서 다니면 첫째 직장이 없다는 거예요.  그럼 직장을 먼저 만들어야죠.  그래서 서울에 가는 걸 어떻게든지 끊어야 되겠다 그것이 저희가 경기 그랜디자인이라고 계획을 하고 있습니다.
</p>
<p style="padding-left:1.2em">  그랜디자인은 핵이 북쪽에 하나, 서쪽에 하나, 남쪽에 하나 이런 식으로 해서, 핵을 구성해서 그것이 한 290만 정도 인구가 되면 자생력이 생깁니다.  지금까지 자생력이 있는 도시는 하나도 못 만들었어요, 경기도가.  왜 그러냐?  수도권정비계획법에 의해서 안 되게 돼 있어요, 못 하게 되어 있어요.  택지개발촉진법에 의해서도 안 됩니다.  그래서 이번에 광역도시계획으로 깐 이유가, 사실 지사님하고 그것 때문에 최근에 옥신각신 했어요.  지사님이 "광역도시로 너무 깔면 손해 아니냐 쓰레기도 오고, 경기, 서울 게 다 오지 않느냐"  광역도시계획으로 다 깔아놓고 경기도의 기본계획을 만들어서 건설부에서 승인받아서 경기도의 31개 시·군이 골고루 살 수 있는 기능과 도로망을 형성해 줘야 된다.  그런 종합적인 계획을 만든 것이 경기 그랜디자인입니다.
</p>
<p style="padding-left:1.2em">  그래서 그 작업을 지금 하지 않으면 경기도는 난개발이 계속될 것이고 경기도의 기능이 서울에 의존할 수밖에 없게 만들었어요, 도로망이나 그런 것이.  서울시를 향한 도로망이 아니라 경기도에서 도로망을 만들어서 여기서 돌아가게.  그게 왜 가능한고 하니 지금 서해안개발을 하고 있습니다.  서해안개발이 강화, 인천 해서 평택 이렇게 해가지고 전라도까지 매갈로 폴리스를 만들려 그럽니다.  그것은 왜 가능하냐. 중국이 시장입니다.  미국이 시장이 아닙니다, 앞으로.  그래서 중국을 향한 시장을 만들자 한국에서.  그게 서해안이다.  평택 보세요.  인천은 안 됩니다, 다 꽉꽉 차서.  강화로 해서 우리가 서해안 당진으로 해서 목포까지 서해안을 쭉 이어지는 지금 도로망이 그렇게 되어 있습니다.  그 도로망을 따라서 이것을 만들어야 경기도가 정말 세계 중심이 되고 동북아의 중심이 물리적으로 가능하다고 보아왔기 때문에 국토종합개발계획 앞으로 2020년 지식산업 중심부라고, 그것 만드는데 얼마나 힘드는지 국토연구원하고 싸워서 만든 겁니다.  그게 왜 그러냐 상위계획이거든, 국토종합개발계획이 상위개발계획입니다.  그 상위계획의 근거가 있으니까 그 근거를 풀어주자 그겁니다, 근거에 따라서 해야 되니까.  근거가 지금까지 없었습니다.
</p>
<p style="padding-left:1.2em">  경기도는 지식기반 중심지라는 근거를 만들었기 때문에 경기도가 독립해서 살 수 있는 도시가 3개가 되는지, 4개가 되는지 그건 투자비에 따라서 다릅니다.  외국사람들이 투자하겠다고 와 있어요.  우리나라 돈은 안 써도 돼요.  왜, 그 도시는 이익이기 때문에, 이익이 생기지 않으면 도시가 안 됩니다.  장사가 돼야 되요.  서비스가 돼야 되요.  그러면 그것이 도시가 자생력이 생기는데 그게 인구규모가 290만 정도됩니다.
</p>
<p style="padding-left:1.2em">  그것을 저희가 경기 그랜디자인이라고 해서, 죄송합니다만 자시님께는 보고 안 하고 구두로만 얘기하는 건데 위원님들께서는 제가 그린 그림까지 보여드리는 겁니다.  그렇게 아시고 위원님들께서 여기서만 아시고 계시고 다른 데 가셔서, 지사님 좋아하시지 않을 테니까.  그건 양해해 주시고 오프로 해주세요.  그런 의미에서 기획위원님들이 저희 식구니까, 저희들이 안고 있는 문제부터 고민도 다 말씀드리고 그러는 거예요.  그 대신 여러분이 도와주셔야지, 다른 분과에서 도와 줍니까?  여러분이 식구니까 도와줘야죠.  다른 분과위원님들이 도와줍니까?  도시계획분과위에서 도와줍니까, 환경에서 도와줍니까?  위원님들이 저희들 식구니까 저희들을 도와주셔야죠.  저희가 생각은 가지고 있는데 이것을 펼치기 위해서는 여러 위원님들께서 많이 도와주셔야 되지 않겠느냐는 생각이 들어서 경기 그랜디자인이라는 것을 만들고 있다는 것을……. 
</p>
<p style="padding-left:1.2em">  이건 처음의 안입니다.  처음의 안인데 저희가 수정을 했습니다.  서울이 이겁니다.  수정한 건 여기가 핵이 되는 거죠.  핵이 돼 가지고 수원을 중심으로 도로를 다 넘기 때문에…….  그래서 이쪽이 하나의 핵이 되겠고 그 다음에 여기는 산이기 때문에 핵은 이룰 수가 없어요.  이쪽에는 주거공간이나 전원이 되겠고요.  여기가 핵이 됩니다.  그래서 이북하고 개성하고 전부 연결이 됩니다.  여기 핵 하나하고 여기 핵 하나하고, 동두천하고 이쪽 포천쪽에 핵이 2개 정도가 되지 않겠느냐 생각이 드는데.  그래서 그림을 저희가 그리고 있는데 이거는 시안으로 지난 번에 만들려고 했던 건데 이걸 가지고 수정을 합니다.
</p>
<p style="padding-left:1.2em">  그리고 제일 중요한 것이 여기입니다.  이렇게 해서 목포까지 나갑니다.  이게 서해안인데 서해안고속도로도 그래서 깔은 겁니다.  서해안고속도로를 7년전에 만들자 해서 만든건데 이 도로를 따라서 이쪽이 평택항하고 세계 중심의 물류중심이 되겠죠.  그러나 이쪽이 소외된 게 아니라 이쪽은 이쪽대로 가치가 있습니다.  산이 많고, 주택지로는 최고이기 때문에.  그래서 이쪽은 이쪽대로 활성화해야 되고 단, 3개가 되든, 4개가 되든 문제는, 저희 나라가 그렇습니다.  모든 문제를 한꺼번에 해결하려 그러는데 저는 한꺼번에 안 하려 그럽니다.  이것이 언젠가는 의회에 가고 여러 가지 설명과정이 필요하겠습니다마는 하나만 잡아서, 여기가 되든지 여기가 되든지 하나만 잡아 가지고 완전히 완성품을 만들어 놓자 그리고 난 후에 그 완성품을 가지고 다시 참고해서 이쪽으로 가든지 이쪽으로 가든지 그런 방향으로, 도로망도 여기서 다 이루어질 수 있는 경량전철을 놓으려고 그럽니다.  
</p>
<p style="padding-left:1.2em">  서울시 지하철 놓는 거 반대했습니다.  빚이 4조원이에요.  하루저녁 자고 나면 23억원이에요.  23억원씩 물고 있어요, 지금 서울에서.  그래서 경량전철은 굉장히 싸게 먹히고 건설비도 적게 들 뿐만 아니라 단기간에 할 수 있습니다.  지금 새마을버스 다니는 거 있죠?  새마을버스 다니는 스타일로 전부 연결하려고요.  그러면 굉장히 속도도 빠르고 다른 데 갈 필요없어요.  학교도 여기 다 짓고 한다고요.  정부에서 하라는 게 아닙니다.  민간 페이스로 해서 돈 벌 수 있게, 영업할 수 있게 만들어준다 그겁니다.  정부는 종이 짝만 줘라 이거예요.  왜 하지도 못 하면서 붙잡고 있냐 이거예요.  그래서 경기도가 어려운 문제가 생기는데.  그래서 이 시안은 처음 만들었던 게 이것이 아니고 수정하고 있다는 것을 말씀드립니다.  그래서 이 말씀을 드려야겠기에 지사님한테 보고도 안 드린 건데……. 
</p>
<p><b>○ 위원장 김강선 </b> 원장님의 좋은 말씀 많은 위원님들이 참고가 되리라 생각합니다.  끝으로 경기개발연구원은 정말 자타가 공인하는 두뇌의 집합입니다.  우리 기획위원회에도 선임위원회로서 이런 좋은 연구기관이 같이 한다는 것을 상당한 긍지로 생각하고 있습니다.  끝으로 원장님이 우리 기획위원회 여러 위원님들에게 꼭 하실 말씀이 있다면 한마디만 하셨으면 합니다.  없으시면 안 하셔도 됩니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 한마디 꼭 말씀드린다면 저희들이 연구하는 입장에서 저희들의 본분은 다하려고 노력하겠습니다.  그 본분을 다하려는데 여러분의 힘이 필요하기 때문에 여러분들이 저희들을 적극 지원해 주시고 저희들의 고민을 도와주시고 그렇게 해주십사 하는 부탁의 말씀밖에 없습니다.  대단히 감사합니다. 
</p>
<p><b>○ 위원장 김강선 </b> 네, 감사합니다.  경기개발연구원장님 수고하셨습니다.  더 이상 질의하실 위원이 안 계시므로 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치도록 하겠습니다.  
</p>
<p style="padding-left:1.2em">  위원 여러분께서 장시간 열의를 갖고 감사에 임해 주신 데 대해 감사의 말씀을 드립니다.  그리고 노춘희 연구원장님을 비롯한 연구원 관계자 여러분께서도 행정사무감사를 위한 자료준비와 위원님들의 질의에 성실히 답변해 주신 데 대해 감사드립니다.  오늘 여러 위원님들께서 감사시에 지적해 주신 사항은 도민의 뜻이니 만큼 이를 겸허하게 받아들여서 연구원 업무에 적극 반영될 수 있도록 최선의 노력을 다해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 연구원 임직원 여러분!  수고 많이 하셨습니다.  그러면 이상으로 경기개발연구원에 대한 2000년도 행정사무감사 종료를 선언합니다. 
</p>
<p class=''ar''>(15시42분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>김강선유영록김효정연동현윤동욱이진용양태흥노시범이주석</p>
<p><b>○ 행정사무감사 보조공무원
</b></p>
<p><p class=''em15''>전문위원 오태철지방행정주사 조한경지방행정주사보 박상선</p>
<p><p class=''em15''>지방기능8급 김경옥지방기능9급 김선애</p>
<p><b>○ 출석증인
</b></p>
<p><p class=''em15''>경기개발연구원장 노춘희행정실장 심무섭기획조정부장 양기용</p>
<p><p class=''em15''>도시경영연구부장 신원득도시지역계획부장 이상대교통정책연구부장 조응래</p>
<p><p class=''em15''>환경연구부장 성현찬지식산업연구부장 이기영사회개발연구부장 김흥식</p>
                <!--// 회의록내용 --> 

            <p class="skip">맨위로 이동</p>

            <div','경기도의회',false,'{"legacy_id": "audit-4643", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4643"}'::jsonb,'2000-11-23'::date,'2000-11-23'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4643');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1999.11.27. 토요일] 경기개발연구원 — 기획위원회 1999년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 1999년도 행정사무감사(1999. 11. 22. ~ 1999. 12. 01.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4701" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>1999년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제6호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 1999년 11월 27일(토)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시50분 감사개시)
</p>
<p><b>○ 위원장 고수복 </b> 좌석을 정돈해 주시기 바랍니다.  지금부터 지방자치법 제36조, 동법시행령 제16조 및 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구 원에 대한 1999년도 행정사무감사를 실시할 것을 선언합니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분, 그리고 연구원의 임직원 여러분!  안녕하십니까?  기획위원장 고수복 위원입니다.  오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무 감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고  2000년도 예산안 심사를 위한 자료로 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.  감사 위원 여러분께서도 연일 계속되는 감사 일정으로 노고가 많으십니다만 도민을 대표하여 도비출연기관인 경기개발연구원의 운영실태를 감사하는 것이니만큼 각 부분별로 세밀하게 검토하셔서 소기의 성과를 거둘 수 있게 되기를 당부드리면서 원활한 감사진행을 위하여 많은 협조있으시기 바라겠습니다.  끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 임직원 여러분께도 감사와 격려의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기개발연구원장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 합니다.  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1999년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 한 때에는 지방자치법 제36조제5항 및 경기도의회행정사무감사및조사에관한조례 제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부한 때에는 동법 동조항의 규정에 의하여 500만원이하의 과태료를 부과할 수 있음을 알려드립니다.  그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.  먼저 증인출석 여부를 확인하겠습니다.  경기개발연구원장 나오셨습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네. 
</p>
<p><b>○ 위원장 고수복 </b> 행정실장 나오셨습니까? 
</p>
<p><b>○ 행정실장 심무섭 </b> 네. 
</p>
<p><b>○ 위원장 고수복 </b> 기획조정연구부장 나오셨습니까? 
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 수도권정책연구센터장 나오셨습니까? 
</p>
<p><b>○ 수도권정책연구센터장 이해종 </b> 네.  
</p>
<p><b>○ 위원장 고수복 </b> 도시경영연구부장 나오셨습니까? 
</p>
<p><b>○ 도시경영연구부장 양기용 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 지식산업연구부장 나오셨습니까? 
</p>
<p><b>○ 지식산업연구부장 이기영 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 문화관광연구부장 나오셨습니까?
</p>
<p><b>○ 문화관광연구부장 김흥식 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 환경연구부장 나오셨습니까? 
</p>
<p><b>○ 환경연구부장 성현찬 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 다음은 선서요령을 설명드리겠습니다.  선서는 증인을 대표해서  경기개발연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 오른손만 들어주시면 되겠습니다.  그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 선서!  본인은 경기도의회가 지방자치법 제36조, 동법 시행령 제16조제1항, 경기도의회행정사무감사및조사에관한조례 제2조의 규정에 의하여 소관업무에 대한 1999년도 행정사무감사를 실시함에 있어서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서 지방자치법시행령 제17조4제5항과 경기도의회행정사무감사및조사에관한조례 제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''>1999년 11월 27일
</p>
<p class=''ar''>증인 경기개발연구원장 노춘희.
</p>
<p><b>○ 위원장 고수복 </b> 앉으시죠.  그러면 경기개발연구원장께서 나오셔서 간부소개와 업무보고를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 설중에 아침부터 저희 연구원을 위해서 오신 위원님 여러분 감사합니다.  저는 경기개발연구원장 노춘희입니다.  존경하옵는 고수복 위원장님과 위원님 여러분!  바쁘신 의정활동에도 불구하고 저희 연구원에 높은 관심과 애정을 가지시고 이렇게 보고일정을 허락하신데 대하여 먼저 연구원을 대표하여 감사의 말씀 올립니다.  지난 2월 연구원장에 부임한 이래 저희 경기개발연구원이 도민의 삶의 증진과 도정발전을 위한 중추적 연구기관으로 그 사명을 다할 수 있도록 저 자신 최선의 노력을 기울여 왔습니다.  특히 제가 부임하면서 경기도의 도약과 발전을 위해서 수도권 규제문제 해결이 시급하다고 판단하여 수도권정책연구센터를 연구원내에 처음 설치하였습니다.  수도권정책 문제를 집중적으로 연구케 하였으며 이와 같은 노력이 나름대로 높은 평가를 받아 지난 6월에는 청와대 직속 규제개혁위원회에 수도권규제해소 관련 전문연구기관으로 선정받은 바 있습니다.  도정의 발전을 위해 경기도민을 대표하여 불철주야 노력하시는 고수복 위원장님과 위원 여러분!  앞으로 여러분의 기대에 어긋나지 않도록 혼신의 노력을 경주하겠으며 많은 성원과 함께 지도편달해 주시기 바라면서 금년도 저희 연구개발원의 주요업무를 보고드리는 순서를 갖겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 저희 간부를 소개해 올리는 순서가 되겠습니다.  유 훈 고문님을 소개해 드립니다.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  심무섭 행정실장이십니다.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  그리고  조응래 기획조정연구부장 겸 도시교통연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  다음 이해종 수도권정책연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  그리고 양기용 도시경영연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  이기영 지식산업연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  김흥식 문화관광연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인    사) 
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 성현찬 환경연구부장이십니다. 
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  이것으로 소개말씀을 드리고 다음 보고순서는 일반현황과 재정운영, ''99년 연구사업 추진사항, 2000년 연구사업계획 그리고 ''98년 행정사무감사 지적사항, 조치결과 순으로 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 일반현황을 보고드리겠습니다.  1페이지가 되겠습니다.  경기개발연구원의 연혁과 기능은 잘 아시고 계시는 것과 같이 지난 1995년 처음 개원하였으며 지난 5년간 도정의 중ㆍ장기, 단기비전을 제시하고 정책개발을 지원하는 기능을 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  2페이지가 되겠습니다.  2페이지에서는 연구원의 기구를 말씀드리겠습니다.  이사장 밑에 원장, 부원장이 있고 기획조정실 산하에 기획조정연구부와 정보자료팀 외에 수도권정책연구센터와 5개 일반연구부서가 있으며 연구사업 지원 및 행정을 담당하는 행정실이 있습니다.  인력현황을 말씀드리면 정원이 58명에 현원이 46명, 12명이 결원 중에 있으며 특히 연구직의 결원이 9명으로 연구인력의 증원이 시급하다고 말씀드릴 수 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 3페이지가 되겠습니다.  시설로는 본 청사는 당초에는 지방행정연구원의 청사로 1998년 초에 완공되었으며 지난 10월하순 본 경기개발연구원이 입주하여 연구원중에서 처음 오랜 숙원이었던 독립청사를 마련하게 된 유일한 기관입니다.  기타 구체적인 시설물자 현황은 보고서로 갈음하여 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 재정운용 현황을 보고드리면 4페이지가 되겠습니다.  먼저 금년도 예산운용 사항부터 말씀드리겠습니다.  금년도 총 예산규모는 지난해 보다 12%가 증가된 297억 8,700만원입니다.  회계별로 보면 일반회계가 79억원, 특별회계가 219억원이 되겠습니다.  일반회계 세입내역은 기금이자 전입액이 17억원, 법인세 환급금액이 5억원, ''98년 이월금이 9억원, 도비보조위탁금이 34억원, 독립청사 확보에 따른 청사보증금환급액이  11억원, 수탁사업 등 사업수입이 1억 7,700만원입니다. 
</p>
<p style="padding-left:1.2em">  세출예산을 보시게 되면 기관운영비가 14억원, 연구부와 수질연구소 운영비가 59억원으로 전체예산의 76.6%를 차지하고 있습니다.  지자체적립금이 3억원, 예비비 및 기타 8억 700만원이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 5페이지가 되겠습니다.  기금관리특별회계 세입ㆍ세출내역에서 총 세입이 219억원으로 주요세입은 전년도 기금이월금이 200억원, 자체적립금이 3억원 그리고 기금운용에서 발생되는 이자수입이 16억원입니다.  세출은 기금 예치금 203억원과 수입된 기금이자를 일반회계에 전출하여 이자전출금이 16억 5,600만원이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 6페이지가 되겠습니다.  기금관리 현황을 보고드리겠습니다.  먼저 총 기금은 203억원이 현재 조성되고 있는 실정입니다.  설립연도 1995년에 100억원의 기금이 현재 203억원으로 2배 가량 확충되었습니다.  그러나 500억원을 당초목표로 하였습니다.  금년도부터 도의 재정지원 방법이 기존의 출연기금과 보조금 지원의 혼합체제에서 보조금지원체제로 전환함에 따라 외부로부터 추가적인 기금확충은 사실상 중단되고 있는 실정입니다.  따라서 ''99년도 기금증가분 3억원은 연구원 자체재원으로 적립한 것임을 아울러 말씀드리겠습니다.  조성된 기금은 한미은행을 비롯하여 8개 금융기관 중에 분산예치되어 있으며 금융기관별 예치액과 이자율은 보고서를 참조하여 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 7페이지 ''99년 연구사업 추진현황을 말씀드리겠습니다.  금년도 경기개발연구원의 주요 연구사업은 자체연구과제사업, 수탁연구과제사업, 정책연구과제사업 그리고 공청회 및 정책세미나, 지역연구간행물 발간 등의 기타 연구사업 등 크게 4개 사업으로 구분할 수 있겠습니다.  자세한 내용은 8페이지 이하 부문별 주요사업내용 및 계획에서 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  14페이지로 넘어가겠습니다.  먼저 연구과제 사업계획 중 자체연구과제 추진사업부터 말씀드리겠습니다.  본 연구원은 2000년도에 총 30개 자체연구과제를 계획하고 있습니다.  그 부분은 유인물을 참조해 주시고 27페이지가 되겠습니다.  수탁연구과제 추진계획에 대해서 말씀드리겠습니다.  본 연구원은 2000년에 1999년도 이월과제 5건을 포함해서 총 20개의 수탁과제를 수행할 계획인 바 이는 각 연구부서로 각각 3건 내외의 수탁연구과제 수행을 의미한다는 것을 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  28페이지가 되겠습니다.  본 연구원은 그밖에 외부 아웃소싱을 통해서 연구 외부의  노하우를 활용할 수 있는 위탁연구과제사업 9건을 수행할 계획입니다.  그리고 정책연구과제는 ''99년도보다 다소 증가한 총 20건을 수행할 예정입니다.  또한 경기도내 각 시ㆍ군으로부터 좋은 반응을 얻고 있는 지역연구는 분기별로 1건씩 총 4건을 수행하겠습니다.  그리고 나머지 내용은 유인물로 갈음하고자 합니다. 
</p>
<p style="padding-left:1.2em">  29페이지가 되겠습니다.  이상 2000년도 연구사업계획과 관련된 보고를 마치고 전 년도 ''98년도 행정사무감사 때 지적해 주신 조치결과를 말씀드리겠습니다.  ''98년도의 행정사무감사에서는 처리요구사항 2건, 건의사항 2건 총 4건의 지적이 있었는 바 4건 모두 조치를 취하였으며 위원님께서 말씀하신 구체적인 조치내용은 보고서를 참고해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음 순서로 저희 연구간부진은 소개드린 바 있습니다.  마지막 페이지에 경기개발연구원은 경기도민을 위한 연구기관입니다.  제가 경기개발연구원장으로 부임한 이래 이 점을 늘 명심하고 저희 연구 원이 경기도의 발전과 도약을 위해서는 명실상부한 필수적인 기관이 되도록 그 육성ㆍ발전에 최선의 노력을 기울이고 있습니다.  다만 저희 연구원이 경기도민을 위한 연구기관으로써 그 맡은 바 소임을 다하기 위해서는 기획위원회 여러 위원님들의 적극적인 지지와 성원이 절대적으로 필요하다는 점을 다시 한 번 느끼고 말씀드리고 싶습니다. 
</p>
<p style="padding-left:1.2em">  특히 경기도의 위상과 규모에 걸맞는 연구원이 되기 위해서는 연구인력의 규모성 있는 증원 등 저희 연구원이 앞으로도 지속적으로 확대ㆍ발전할 필요성을 강하게 느끼고 있습니다.  이 점 이해해 주시고 저희 연구원의 육성과 발전에 위원님들의 아낌없는 도움을 재삼 요청드리는 바입니다.  이상으로 ''99년도 주요업무보고를 마치고 금년도 저희 연구원에서 중점적으로 추진한 가장 중요한 수도권정책 추진실적을 우리 수도권정책연구센터장으로 계시는 이해종 박사님께서 슬라이드와 뷰포인트를 보내드리겠습니다.  대단히 감사합니다.
</p>
<p><br /></p>
<p>(업무보고는 끝에 실음) 
</p>
<p><br /></p>
<p class=''ar''>(11시11분 슬라이드상영시작) 
</p>
<p class=''ar''>(11시26분 슬라이드상영종료)
</p>
<p><b>○ 위원장 고수복 </b> 경기개발연구원장 수고하셨습니다.  그러면 감사질의를 하도록 하겠습니다.  질의는 원활한 진행을 위하여 일괄질의 후 일괄답변을 듣는 것을 원칙으로 하고 보충질의 시에는 일문일답으로 진행하도록 하겠습니다.  그러면 질의하실 위원께서는 질의하여 주시기 바랍니다.  연동현 위원 질의하여 주시기 바랍니다.
</p>
<p><b>○ 연동현 위원 </b> 안녕하십니까?  연천출신 연동현 위원입니다.  늦게나마 우리 경기개발연구원이 새로운 건물에 입주한 것을 축하드리고 영상물을 통해서 구체적인 설명 
</p>
<p>잘 들었습니다.  본 위원이 몇 가지 궁금한 점과 그에 대한 시책방향 등에 대해서 질의토록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 실버산업에 대한 과제발표를 한 사항이 있습니다만 본 위원이 생각할 때는 핵가족화 되어 가면서 앞으로 노인복지시설이 시급한 사항이라고 생각하고 있는데 이런 실버산업에 대한 과제가 여기서는 간단하게 중점사항에 대해서만 나왔기 때문에 그것을 구체적으로 설명해 주시고 그 다음에 실버산업을 운영하는 가운데 적정지가 어느 지역인지 이런 것까지 포함해서 말씀해 주시기 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 얼마전 임창열 도지사께서 도정시책 보고 시에 지식산업 기반확충에 대해서 앞으로 2000년 기정예산에 많은 예산을 확보하겠다고 말씀해 주셨습니다.  그런데 지금 날로 유통산업이 대형점포화 되면서 재래식 시장에 대한 문제점이 많이 야기되고 있습니다.  거기에 대한 구체적인 과제가 우리 연천지역을 굳이 말씀드리면 아직까지도 4, 5일 재래장이 서고 있는 지역이기도 합니다.  우리가 2년 전에 동두천에서 보았던 재래시장에 화재가 나서 대형참사를 우려하였던 부분도 없지 않아 있었습니다.  그런데 그쪽 동두천 같은 경우는 재래시장에서 주거를 하지 않은 관계로 참사를 면했습니다만 연천지역의 전곡같은 재래시장은 주거까지 같이 하고 있어요.  그래서 소방시설에 대한 문제점 이런 쪽도 연구과제에 포함시켰는지 이러한 것에 대해서도 구체적으로 말씀해 주시고 다음에는 법무담당관실에 접수되어 있는 부분이 경기북부출장소에 의뢰된 부분이겠습니다.  경기도 경제단체협의회에서 신청한 부분인데 군사지역에 공장설립 인ㆍ허가문제가 우리 경기개발연구원에 용역중이다 이렇게 얘기가 되고 있는데 그 부분의 추진경위와 현재 규제대책을 어떻게 풀어가고 있는지 아직까지 계획이 나와 있지 않은지, 나와 있으면 어떻게 되고 있는지 그 부분을 세세하게 설명해 주시기 바라고요.
</p>
<p style="padding-left:1.2em">  다음으로 본 위원이 생각할 때 물론 연구과제가 1년, 2년에 걸치는 중ㆍ장기계획도 중요하겠습니다만 단기정책 연구과제의 발표가 필요하겠다, 다시 얘기드리면 도는 도, 시는 시에서, 군은 군대로 따로 우리 경기개발연구원에서 연구발표가 접목되지 않았을 때는 어려움이 있지 않겠느냐, 물론 본 위원이 자료를 보았을 때에는 경기개발연구원에서 도정에 또는 중앙정부에 건의 내지는 반영된 부분이 상당수가 있습니다만 앞으로도 중ㆍ장기 연구과제 발표보다는 단기정책 연구발표가 부단히 필요하지 않겠느냐, 본 위원은 이렇게 생각하고 있습니다.  이 부분에 대해서 말씀해 주시기 바라고 특히 환경부분에 대해서 환경부분과 혐오시설에 대한 정책개발이 필요하지 않겠느냐, 주민들에 대한 비전제시를 할 수 있는, 예를 들어 환경부분이 우리 지역에 들어왔다, 또 혐오시설물이 우리 지역에 들어왔을 때 주민들로부터 수긍할 수 있는 다시 얘기드리면 세금을 감면해준다든가 그 지역에 복지시설이나 문화시설을 해주겠다는 이런 정책과제가 필요하지 않겠느냐, 그러면 원장님께서 그런 쪽에 어떤 견해를 갖고 계신지 그 과제부분에 대해 말씀해 주시기 바라고요.
</p>
<p style="padding-left:1.2em">  다음에는 폐기물이 방치돼서 부도된 부분에 대해서 대책을 과제발표한 부분이 있습니다, 경기개발연구원에서.  본 위원이 생각할 때는 부도사업장 방치폐기물 처리대책도 중요하지만 우선 환경법이 개정되어야 되지 않겠느냐, 예를 들어서 환경이 지금 굉장히 심각해 가고 있는데도 불구하고 현재 현행법으로는 적발과 시정, 그 다음에 고발조치하고 벌금 정도로 법이 되어 있단 말입니다.  그런데 이 부분을 경기개발연구원에서 정책을 중앙정부에 강하게 반영될 수 있는 발표가 필요하지 않겠느냐, 원상복구, 예를 들어서 폐기물을 해서 걸렸단 말입니다.  시ㆍ군의 지역 환경과에서.  그런데 지금 얘기 들으면 벌금형 정도로 끝나는 사례가 종종 있습니다.  그래서 이 사람들이 걸렸을 시에는 기존에 있는 폐기물까지 기존상태에서 원상복구할 수 있는 이런 쪽의 정책반영이 될 수 있도록 경기개발연구원에서 발표 좀 해주십사 하는 부탁을 드리면서 원장님의 견해는 어떻게 갖고 계시는지 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음에 경기개발연구원에서 하천 수해 위치도에 대한 파악은 하고 계시단 말입니다.  그런데 우리 경기도내 북부지역에 굉장한 수해를 당했음에도 불구하고 건설과, 방재과라든가 재해대책본부에서도 경기북부지역에 있는 교량 그 다음에 교량과 교량거리, 교각과 교각거리를 아직까지 갖고 있지 않은 것 같아요.  본 위원이 생각할 때는 현재 새로운 신기술로 교량을 놨을 때는 교각과 교각거리가 굉장히 멀어서 유수를 저해하는 지장은 없습니다만 상당히 오래된 교량들을 보았을 때는 철근이 안 들어간 무철근 교각이다 보니까 교각이 굉장히 거리가 좁고 커다랗습니다.  이것이 흐르는 물이 월류현상을 일으켰다 하는 것이 언론이나 여론을 통해서 많이 반영하고 있습니다.  그래서 이런 쪽에 경기도의 자료가 없다는 것이 아쉽다, 다시 얘기하면 항구복구나 응급복구가 중요한 것이 아니라 예방차원에서 이런 자료는 경기도에서 충분히 갖고 있어야 함에도 불구하고 아직까지 확보하지 않고 있다.  그래서 경기개발연구원에서는 이런 쪽의 연구과제도 한 부분이 아니겠느냐, 원장님께서 그 부분에 대해서 말씀해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 연동현 위원님 수고하셨습니다.  또 질의하실 위원님, 이남형 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이남형 위원 </b> 고양시출신 이남형 위원입니다.  먼저 경기개발연구원이 아까 원장님께서 업무보고하신 과정에서도 말씀하셨지만 설립된 지가 불과 5년이 아직 안 됐습니다.  그런데 본 위원의 생각으로는 이 짧은 시간 동안에 우리 경기개발연구원이 특히 경기도내의 싱크탱크로서 확고히 자리를 잡아가고 있고, 또 본 위원이 최근 언론지상이라든지 이런 것을 통해서 보면 연구 업적이 점진적으로 우리 경기도정에 반영되고 있지 않나 생각합니다. 
</p>
<p style="padding-left:1.2em">  더욱이 금년도에는 청사도 마련해서 이전을 하셨기 때문에 이렇게 짧은 기간내에 빠르게 성장으로 발전한 것은 아마도 본 위원 생각으로는 여기 계신 노춘희 원장님과 어려운 걸음을 해 주신 유 훈 상임고문님, 그리고 모든 연구원들이 합심 협력해서 노력한 결과가 아닌가 이렇게 생각합니다.  그 동안의 노고에 대해서 먼저 감사하다는 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그럼 질의를 시작하겠습니다.  먼저 경기개발연구원은 잘 아시는 바와 같이 지금 육성기금으로 약 203억원을 예치해 놓고 있습니다.  그래서 예치한 내용을 보면 한미은행에 100억원, 하나은행에 한 29억원 해서 여러 은행에 분산 예치를 하고 있습니다.  
</p>
<p style="padding-left:1.2em">  그런데 이 보고서에 보면 지난 해도 일부 논의가 있었습니다만 경기은행에 지금 10억원을 예치해 놓고 있는 걸로 돼 있는데 이미 다 아시는 바와 같이 경기은행은 퇴출된 지가 한참 됐고, 또 제가 자료를 한 번 훑어보니까 도 본청에서 행정사무감사를 한 결과에도 경기은행에 예치한 금액과 관련해서 원금 7,900만원, 그 다음에 추가 손실금 1억 600만원이 발생됐다고 지적이 돼 있는데 실제로 어떻게 처리가 되고 있는 것인지 그것 좀 한번 말씀을 해 주십시오. 
</p>
<p style="padding-left:1.2em">  아마 다들 아시지만 이제는 은행이나 보험회사도 과거처럼 일반 고객이 자금을 맡겼을 때 원금이 100% 보장되지 않는 시대가 왔기 때문에 앞으로는 원금을 어떻게 보장하면서 다만 얼마라도 이자에서 좀 더 유리하게 운용을 할 수 있을런지 한 번 체크를 철저히 해야 되는 시대가 된 것 같습니다.  그래서 내용을 보니까 기금관리운영위원회도 만드신다고 하는데 그 내용도 한번 말씀을 해 주십시오. 
</p>
<p style="padding-left:1.2em">  그 다음에 이와 덧붙여서 과거 수년간은 경기개발연구원에 보조하는 방식이 도에서 기금도 출연하고 또 일부는 보조금 이렇게 이원화체제가 돼 있었는데 지난 해에는 보조금 스타일로 바뀌었기 때문에 이것을 1년 정도 가까이 운영하시면서 어떠한 문제점은 없었는지 그것도 차제에 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 두 번째로는 2000년도 기본연구과제를 보니까 지방교육자치제도에 관한 연구 이것은 신원득 박사님이 하시는 걸로 돼 있고, 또한 지방세정 정상화시스템 구축은 이재현 박사님이 연구하신 걸로 돼 있고 이것을 포함해서 27건으로 확정돼 있습니다.  그런데 제가 정확히는 모르지만 연구과제 목록을 보니까 우리 경기도정에도 필요하고 상당히 시기상으로 보더라도 적절한 것으로 평가가 됩니다. 
</p>
<p style="padding-left:1.2em">  그런데 본 위원 생각으로는 다들 알고 계시지만 내년도 2000년도부터는 정부가 중앙경찰제도를 지방경찰제도로 전환하겠다는 것을 아마 여러분들도 다 언론지상을 통해서 알고 계실 것입니다.  이것이 정확히 모르지만 정부의 확고한 방침이 아닌가 봅니다.  그래서 이러한 지방경찰제도로 전환되는 것과 관련돼서 다각적인 차원에서 한번 검토와, 이건 중요한 일이니까 워낙 또 큰 일이고, 그래서 경기개발연구원에서 다각적인 차원에서 한 번 검토가 이루어졌으면 어떨까 하는 생각을 해 봅니다.  그래서 이게 내년도에 만약에 된다고 보면 시간적으로도 2000년대 과제에 올라갈 필요성이 있지 않나 이 자리를 빌어서 한번 말씀을 드려 봅니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 세 번째로는 ''99년 연구사업 추진실적을 보니까 기본연구과제 추진실적에 보면 경기도기업조사라는 항목이 있습니다.  이게 원래 연구대상기간이 ''99년 5월부터 12월로 돼 있는데 진행비율이 33%로 나와 있습니다.  또한 기업 및 노동 실태조사 이건 9월부터 11월까지로 돼 있는데 진행상황이 50% 정도 되는 걸로 돼 있습니다.  그 다음에 수탁 연구과제에 보면 지방자치단체간 협력 활성화 방안이 55% 정도 돼 있고요.  그 다음에 정책연구과제 중에서는 이재민구호품 전달체계 개선방안 연구가 10월 15일부터 12월 30까지로 돼 있는데 지금 진행비율은 10%입니다.  그 다음에 연구용역의 효율화 및 관리방법의 개선연구는 10월 4일부터 12월 4일까지 마감된 걸로 돼 있습니다만 연구가 전혀 안 돼 있는 상태로 보고서로 나와 있는데 과제물들이 워낙 많기 때문에 물론 개중에는 진행속도가 느려지는 부분이 분명히 있을 수 있다고 봅니다.  그런데 여기에 보면 전혀 하나도 진행이 안 된 부분들도 있고, 또 예정된 기간에 비해서 상당히 진행속도가 느린 부분도 있기 때문에 이 부분들은 구체적으로 담당하고 있는 연구원들이 너무 바빠서 못하신 건지, 아니면 과제의 중요성이 선정 당시에 비해서 떨어졌기 때문에 좀 속도를 조절하고 계신 건지, 어떤 사안이 있을 걸로 판단되는데 그 부분에 대해서 한번 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 네 번째로 여쭤보겠습니다.  수탁용역연구과제를 보니까 ''95년도에 2건, ''96년도에 10건, ''97년도에 12건, ''98년도에 11건, ''99년도에 15건 이렇게 매년 증가 추세를 보이고 있습니다.  이게 그만큼 우리 경기개발연구원이 안정적으로 성장 발전하고 있고 연구도 많이 하고 있다 이렇게 보여집니다.  그런데 연도별로 지금 5개년치가 되겠습니다만 용역비가 아마 있을 겁니다.  그래서 용역비는 각 연도별로 수탁용역과제하고 관련돼서 얼마씩 됐었는지 그걸 좀 한번 자료로 주시고요.
</p>
<p style="padding-left:1.2em">  그 다음에 용역내용이 ''99년도 같은 경우는 15건, ''98년도는 11건인데 이 건수 중에서 우리 경기도라든지 또 경기도내에 있는 31개 시ㆍ군에서 발주한 비율이 얼마인지 알려 주십시오. 
</p>
<p style="padding-left:1.2em">  그 다음에 ''99년도 예산집행 내역서를 제가 한번 봤습니다.  내역서를 보니까 세입 중에 수탁용역 수입예산이 약 1억 7,200만원이 지금 잡혀 있는데 현재까지 ''99년 10월 30일 기준으로 해서 전액 미수로 잡혀 있습니다.  그래서 본 위원 생각으로는 진행이 상당 부분 됐기 때문에 진행 속도와 맞춰서 어느 정도 용역수입도 들어오는 것이 합리적이 아닌가 보는데 이렇게 총액이 미수로 잡혀있는 사유가 뭔지 그것도 좀 말씀해 주시기 바라고요.
</p>
<p style="padding-left:1.2em">  그 다음에 다섯 번째로는 수질환경연구소 연구비 내역을 보니까 ''98년도에는 6억 4,700만원 정도가 집행이 됐습니다.  그런데 ''99년도에는 4억 9,600만원 정도로 집행이 돼서 무려 ''98년도 대비해 볼 때 1억 5,000만원이 크게 감소했습니다.  그래서 수질환경연구소 비용이 연구비가 대폭 감소된 사유가 뭔지, 지금 정확히는 모르겠습니다만 수질이 워낙 좋지가 않기 때문에 수질을 어떻게 하면 좀더 좋게 만드느냐 하는게 상당히 지금 중요한 현안으로 보여지는데 오히려 그런 차원에서 보면 이쪽 연구비는 좀더 많이 들어가야 되지 않느냐 이런 판단도 해 봅니다.  그런데 오히려 이게 엄청나게 줄었기 때문에 그 부분을 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 여섯 번째로는 본 위원이 알기로는 경기도 주변에는 서울시에도 서울시정개발연구원이 있는 걸로 알고 있고, 또 인천에도 인천시정개발연구원이 있는 걸로 알고 있는데 우리 주변에 있는 서울시나 인천시 연구원들하고 우리 경기개발연구원하고는 긴밀하게 교류를 하고 어떤 내용을 연구하고 있는지 상호 교류를 하는 것이 굉장히 중요할 걸로 봅니다.  왜냐하면 경기도의 문제가 경기도의 문제로만 끝나는 부분도 있지만 서울이라든지 인천하고 연계된 부분들이 상당히 많기 때문에 같이 교류를 하는 것이 상당히 필요하지 않나 생각되는데 실질적으로 보고서에 보더라도 교류를 추진하고 있다 이렇게 내용이 나옵니다.  그래서 지난 1년간 어떠하나 종류의 교류를 하고 계신지 그 부분 좀 말씀해 주시고, 또한 해외 연구기관과의 공동 연구추진도 하나의 업무로 지금 설정을 해 놓고 있습니다.  그런데 해외 연구기관과도 공동연구를 함께 하려고 하는 어떤 계획이 있으신지.
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 일 곱번째 여쭤보겠습니다.  지금 ''99년도 단기 정책연구과제에 보면 ''99년 1월 20일부터 ''99년 2월 27일까지 강화발전방안에 관한 연구가 있습니다.  이것은 본 위원 생각으로는 그 당시에 김포군 검단면하고 강화가 인천시로 편입이 돼 있지만 다시 경기도로 환원추진을 하고 있고 현재 환원추진위원회도 구성돼 있다는 것을 아실 겁니다.  그것과 관련돼서 단기 정책과제로 이것을 연구한 게 아닌가 판단되는데 연구한 과제의 주요한 내용이 어떤 내용들이 들어가 있는지 말씀해 주시고, 또 하나는 이것은 굉장히 민감할 겁니다.  그리고 발표도 아직 안 된 상태인데 본 위원 생각으로는 이게 물론 기간만 가지고 얘기할 수는 없지만 너무 짧은 기간 동안에 연구가 된 게 아닌가 판단도 해 봅니다.  그래서 이것은  우리 경기도하고 인천광역시하고 상당히 갈등의 소지도 있는 문제기 때문에 좀더 세밀하게 하셔서 만약에 환원추진위원회에서 이것을 활용할 수 있다 하더라도 전혀 문제가 안 될 수 있도록, 문제의 소지가 없도록, 또 우리가 이왕 연구한 것이고 또 필요한 것이니까 이것을 가지고 충분히 대외적으로 홍보할 수 있도록 만전을 기해 주시기 바랍니다.  이상으로 질의를 마치겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 이남형 위원님 수고하셨습니다.  또 질의하실 위원님.  정운천 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정운천 위원 </b> 안산의 정운천 위원입니다.  앞에 계신 두 분이 질의를 많이 해 주셨기 때문에 가급적이면 중복이 안 되는 범위 내에서 질의를 하겠습니다.  
</p>
<p style="padding-left:1.2em">  얼마 전 행정사무감사 있기 전에 노춘희 원장님이 취임하신 직후에 연구원 운영 자체평가를 하신 게 있는데요.  거기에서 결과를 보면 연구원의 활용도는 도정에 미치는 영향이 99.6%가 굉장히 긍정적이다 이렇게 나와 있고, 그 다음에 분야별 연구 수요로 보면 환경, 경제, 도시계획, 문화복지, 지방행정, 도시, 교통 이런 순으로 연구수요가 있을 것이다 이렇게 나와 있습니다.  물론 어느 조사결과나 마찬가지입니다만 간행물에 관해서는 도시분야, 지방행정, 그 다음에 경제, 교통, 환경 순으로 연구 분야별 기호도가 수요하고는 다르게 나와 있는 걸 볼 수가 있습니다.  이것을 보면 앞으로 분야별 연구수요로는 환경이 가장 앞선 걸로 나와 있는데 연구 분야별 기호도를 보면 환경이 제일 끝으로 나타나 있습니다.  그걸 보면 여태까지 경기개발연구원에서 물론 연구를 많이 하고 기여도 많이 했습니다만 실질적으로 연구 수요가 있는 부분에 연구를 집중하지 않은 게 아닌가라는 그런 추론이 가능한데 이 부분에 대해서 답변해 주시고요.
</p>
<p style="padding-left:1.2em">  그 다음에 간행물에 대한 기여도가 환경 부분이 굉장히 적게 나타나 있고, 그 다음에 연구 수요는 굉장히 많은 것으로 나타나 있기 때문에 앞으로 경기개발연구원에서 연구할 수 있는 분야를 환경쪽에 초점을 맞춰서, 그리고 삶의 질을 향상시키는 부분에 초점을 맞춰서 경기도정 진행방향을 좀 수정해 줄 의향은 없는지 그 부분 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  두 번째 질의 들어가겠습니다.  연구 자료를 보면 간행물의 활용도가 나와 있습니다.  연구결과가 전부 보고서로 나오기 때문에 간행물의 활용도를 검토해 보면 그 간행물이 어떻게 활용되고 있는지를 알 수가 있는 것 같습니다.  여기에 보면 업무참고용이 75%로 나와 있고, 정책자료용이 13%, 연구자료용이 7%로 나와 있습니다.  사실 업무 참고라는 것은 일견하고 본인들이 하는 업무에 일부 반영하겠다, 또는 반영하지 않더라도 참고하겠다 이런 정도의 수준인 것 같고요.  정책자료용은 아마 적극적으로 정책에 반영하는 수준인 것 같습니다.  그래서 작년도 행정사무감사시에도 정책에 반영될 수 있는 실질적인 연구를 저희들이 부탁한 게 있었습니다.  그런데 아직까지도 정책자료로 사용되는 부분이 13% 정도로 상당히 낮은 걸로 나와 있기 때문에 과연 우리가 수고스럽게 연구를 해서 그냥 보고서로써 빛만 보고 실질적으로 정책에 반영돼서 경기도의 전반적인 정책을 입안하고 실행하는데 활용되지 못하는 어떤 단절감을 느끼게 되는데 앞으로 정책에 적극적으로 활용할 수 있는 방안을 어떻게 생각하고 계신지에 대해서 답변해 주시기 바랍니다.  그리고 답변하실 때 구체적인 어떤 절차라든가 방법에 대해서 언급을 해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  세 번째 질의하겠습니다.  지금 ''98년도하고 ''99년도에 나온 연구보고서를 제가 한번 쭉 봤습니다.  물론 이 연구보고서의 목록은 여기 제출된 자료를 본 것이고요.  그 다음에 목록만 봤지 그 내용 자체는 간단하게 서술된 몇 가지만 봤기 때문에 구체적으로 어떤 연구가 진행됐는지는 모르겠습니다.  그런데 기획위원회에서 기획관리실의 정책기획관실과 예산담당관실, 정보통신담당관실의 업무보고를 받거나 아니면 행정사무감사를 할 때 저희들이 느낀 가장 큰 문제점은 정책이 입안되면 그것에 예산을 배정해서 현실로 나타나게 하는 과정이 필요하고, 예산이 집행되면 실질적으로 어떤 효과가 나왔는지 측정이 가능해야 되고, 그 측정된 결과를 가지고 앞으로 정책 입안을 하는데 피드백을 시켜야 되는 그런 가장 단순한 절차가 현재 경기도에서는 좀 없지 않겠는가, 또는 있다 하더라도 눈에 잘 안 띄는 현상을 저희들이 봤습니다.  앞으로 재정 운용이라든가 정책의 운영을 도민의 피부에 닿게 하고, 그 다음에 도민의 요구에 부응할 수 있는 방법을 찾기 위해서는 경기개발연구원에서 내놓는 모든 정책자료들이 정책에 가급적이면 반영이 되고, 반영된 정책이 예산으로 현실화되고, 그리고 측정할 수 있는 어떤 지표가 개발이 돼야 되지 않겠는가.  그리고 그 지표에 의해서 예산 배정의 합리성이라든가 효율성을 측정할 수 있고 그것이 결국 정책에 다시 피드백되는 절차를 기필코 마련해야 되는 시점에 와 있는 것 같습니다.
</p>
<p style="padding-left:1.2em">  그런 면에서 봤을 때 경기개발연구원에서 내놓은 지표도 많고 보고서도 많은데 그것이 정책에 반영이 안 되는 점에 대해서 가급적이면 적극적으로, 여기에 보면 굉장히 소극적으로 건의만 하고 끝나는 상황인데 적극적으로 반영할 수 있는 방안은 무엇인지 거기에 대해서 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 세부로 들어가서 보면 성과예산주의라든가 또는 행정수요 광역자치단체 평가시스템 개발에 관한 연구를 ''98년도에 3월부터 10월에 걸쳐서 양미영 박사님이 해 주셨습니다.  그런데 이 표가 제대로 만약에, 모르겠습니다, 이 내용이 제가 정확하게 숙지한 사항이 아니기 때문에 어떤 내용인지는 모르겠습니다만 여기에 기술된 내용을 보더라도 5개년계획 평가를 위한 평가지표를 개발해서 제시한 걸로 나타나 있습니다.  그런데 실질적으로 이것이 집행이 안 됐다는 말입니다.  그런데 이것이 상당 부분 만약에 정책에 반영됐다면 많은 예산을 절감할 수 있었을 것이라고 저는 판단됩니다.  그래서 그런 예를 보더라도 앞으로 연구하시는 것도 중요하지만 적극적으로 정책에 반영할 수 있는 방법을 한번 찾아보는 것도, 그 자체를 또 연구하는 것도 사실 중요하지 않겠나 이런 생각이 듭니다. 
</p>
<p style="padding-left:1.2em">  그리고 다음 네 번째 질의는 좀 구체적이기는 합니다만 제가 연구 과제명을 보다가 관심있는 부분 두 가지를 발견했습니다.  첫 번째는 지방 부도로의 기능의 제고 방안, 두 번째는 경기도 지리정보체계 구축방안 이렇게 해서 나온 보고서가 있는데 지방부도로의 기능 제고방안을 보면 경기도 전체에 관한 도로정비기본계획을 아마 수립한 걸로 보고서에는 나와 있는 것 같습니다.  그런데 감사관실을 감사하다 보면 14개 시가 도로정비기본계획을 세우고 있지 않은 상태입니다.  이것이 ''98년 3월에서 ''98년 10월까지 연구를 해서 보고된 그런 상황이라면 적어도 ''99년도에는 이것이 반영이 돼서 도로정비기본계획이 수립됐어야 되는데 이것이 안 돼 있고요.  그리고 작년도 행정사무감사 때에 저희들이 지적한 바에 의하면 특히 경기도 전체 예산의 거의 50%를 차지하고 있는 건설도시 관련 사업예산이 사실 구체적인 어떤 객관적인 지표없이 시행되는 부분이 사실 많습니다.  특히 도로부분이 그런데요.  도로부분이 사실 보면 어떤 일정 구간에 대한 도로건설 그 자체가 중요한 것이 아니라 그것이 가져오는 파급효과를 검토해서 객관적인 자료로 내놓아야 되는데 어디를 봐도 그런 객관적인 지표를 제시하고 예산을 집행하고 그리고 그 지표가 어떻게 달라졌는지에 대한 공시가 전혀 없기 때문에 투명행정에 있어서 가장 안 되는 부분 중의 하나 아니겠습니까?  그래서 아까 제가 두 번째 질의한 지표관리나 정책에 반영하는 문제에 관해서도 답변하시면서 특히 도로부분에 대해서 관련해서 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 경기도 지리정보체계 구축방안에 대해서 이외희 박사님께서 하셨는데 정보통신담당관실 감사하면서도 지리정보시스템의 개발에 있어서 다른 툴을 사용하면서 나중에 예상되는 데이터베이스의 공용화 부분이 상당히 우려가 되고요.  또 더군다나 데이터베이스뿐만 아니라 각기 다른 GIS 툴로 개발을 하기 때문에 결과적으로 생성된 시스템이, 소프트웨어 자체가 틀리고 모듈이 틀리고, 결과적으로 어플리케이션이 틀려지는 결과가 와서 나중에 다른 시스템, 말하자면 지오그래픽 포지셔닝 시스템이라든가 위성정보시스템이라든가, 아니면 시ㆍ군의 다른 어플리케이션하고 접목이 됐을 때에 과연 그것이 호환성이 있겠는가 하는 부분이 이 보고서에 있는지 모르겠습니다, 연구하신 게.  그래서 있다면 그것을 경기도의 정보통신담당관실하고 긴밀하게 협조를 해서 이것을 건설적인 방향으로 바꾸는 그러한 절차가 필요하지 않겠나 생각합니다.  그 부분에 대해서도 답변 좀 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 그 다음으로는 지금 연구개발의 시의성에 대해서 좀 질의를 하겠습니다.  ''99년도 단기정책 연구과제 중에 경기도 구조조정 방안에 관한 연구가 있었습니다.  ''99년 4월부터 ''99년 7월에 이 연구를 하셨는데 여기 내용에 보면 경기도 2차 구조조정에 대응하는 경기도 특수성이 반영된 구조조정안을 개발, 관리한 중앙부서와의 협의를 할 수 있게 한다 그 내용입니다, 협의하는 내용.  그 다음에 제2차 경기도 구조조정 방안 및 인력 조정방안을 제시한다 이렇게 돼 있는데요.  문제는 이 경기도 구조조정 방안에 대한 연구가 좀 일찍 됐으면 더 좋지 않았겠는가 그런 점에 대해서 질의를 드리고 싶습니다.  
</p>
<p style="padding-left:1.2em">  경기도 2차 구조조정 추진일정을 보면 ''99년 6월 12일 행자부로부터 지침이 시달됐고, 이로부터 시안을 작성해서 행자부에 보고한 것이 ''99년 7월 21일입니다.  그렇다면 연구보고서가 나오기 전에, 또는 나오는 시각에 행자부에 이미 보고가 되는 상황이기 때문에 이 보고서를 충분히 활용할 수 있는 기회를 놓쳤다는 거죠.  물론 연구 과정에서 도의 관련부서와 긴밀한 협조를 해서 할 수도 있겠습니다만 보고서가 일찍 완성돼서 2차 구조조정에 십분 반영될 수 있도록 시기를 좀 앞당길 수 있는 그러한 과정이 필요했다.  다시 말하면 경기도 구조조정 방안에 대한 연구는 좀 늦게 나옴으로써 역할을 제대로 못했지 않았나 하는 점에 대해서 답변 좀 해 주시고요.  
</p>
<p style="padding-left:1.2em">  그와 관련해서 연구 과제를 미리 앞당겨서 설정하는 절차도 필요하지 않겠는가.  물론 단기과제를 선정해서 정책에 반영하는 것도 좋습니다만 그래도 중요한 문제들, 말하자면 정책 중에 5개년개발계획을 세운다든가 아니면 권역별 개발계획을 세운다든가 아니면 지금과 같은 구조조정 문제라든가 이런 문제들은 좀 미리 앞당겨서 연구를 함으로써 과제물에 대한 성과물이 나왔을 때에 그것이 정책에 반영될 수 있는 시간을 확보할 수 있지 않겠나.  따라서 단기과제물도 중요합니다만 앞을 내다보는 과제 선정도 중요하다.  그 부분에 대해서 답변 좀 부탁드리겠습니다.
</p>
<p style="padding-left:1.2em">  그리고 간단한 질의 몇 가지만 하겠습니다.  지금 경기개발연구원의 기금을 보면 203억원이 조성된 걸로 알고 있고요.  사실 203억원이라는 것이 부족한 면이 있습니다.  왜냐하면 사실 연구기관이 외부의 압력이나 아니면 외부의 간섭을 배제할 수 있는 가장 중요한 방법은 자체적으로 독립되는 방법인데 그러기 위해서는 기금이 충분히 확보돼야 되는 방법밖에 없습니다.  그런데 203억원을 보면 여기서 나오는 이자가 올해 16억원 정도로 예상을 하고 있는 것 같습니다.  그런데 1년 예산을 보면 50억원 정도 되거든요.  물론 올해는 73억원이었습니다만 청사에 필요한 예산 20억원을 제외하면 53억원 정도 되고요.  앞으로도 대략 예측해 보면 50억원 정도 안 될까 이런 생각이 드는데, 이것을 8% 이자로 계산하면 625억원 정도의 기금이 필요합니다.  625억원의 기금을 과연 어떠한 방법으로 어떤 기간에 걸쳐서 조달할 수 있는지, 물론 개발연구원이시니까 얼만큼 계획이 세워진 걸로 짐작이 됩니다만 그런 계획에 대해서 답변해 주시고요.
</p>
<p style="padding-left:1.2em">  그리고 기금운영에 있어서는 아까 이남형 위원님께서 질의가 있었습니다만 경기은행 특정금전신탁에 있는 10억원에 대한 처리가 아직까지도 안 되고 있는지, 감사에서 지적된 바와 같이 7,900만원하고 1억 600만원에 대한 손실이 어떻게 처리가 되고 있는지에 대해서 답변 좀 해 주시고요.
</p>
<p style="padding-left:1.2em">  그리고 운영에 대해서 약간 질의가 있는데 말이죠.  예산 중에 연구부서하고, 그 다음에 기관운영 이렇게 크게 나눌 수 있습니다.  그런데 기관운영에서 가장 큰 것은 임차료로 나와 있습니다.  임차료를 보면 한 1억 800만원이 나간 걸로 나와 있는데 임차료가 여기 청사의 임차료인지 아니면 그 전에 있었던 임차료인지 제가 구분이 안 되네요.  청사를 구입한 것으로 알고 있는데 임차료가 나와서 질의드리니까 임차료가 여기 청사로 이전하기 전에 전 사무실의 임차료인지 아니면 청사의 구입대금을 분할해서 납부하기 때문에 일시적으로 이자보전을 위해서 지급하는 것인지 거기에 대해서 답변해 주시고요.  두 번째는 연구부 운영에 있어 가장 큰 것이 자산취득비로 나와 있습니다.  그런데 감사에서 지적된 바와 같이 자산취득할 때 많은 연구설비들의 구입방법에 대해서 지적된 것으로 나와 있습니다.  사실 연구원들은 생리가 저도 그렇습니다만 좀더 좋은 것을 갖고 싶어합니다.  연구설비는 가급적이면 좋은 것을 갖고 싶어하고 그렇기 때문에 외제를 구입하신 것 같은데 지금 일방적으로 다 지적은 되었습니다만 저는 여기서 우려되는 부분이 과연 그것을 대체할 순 국산이 한국에 있는지 그렇지 않으면 무조건 외제를 구입했다고 해서 문제될 것은 아니란 말입니다.  그래서 과연 설비의 대체가 가능한 건지 그리고 설비의 대체가 가능하지 않다면 현재 되어 있는 구입 관련된 규정을 바꾸든지 이런 적극적인 대처방안이 필요한데 거기에 대한 대응방안을 어떻게 갖고 계신지 답변해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 정운천 위원님 수고하셨습니다.  또 질의하실 위원님 유영록 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 유영록 위원 </b> 유영록 위원입니다.  동료위원들께서 자세하게 질의하셨기 때문에 저는 한 두가지 정도만 말씀드리겠습니다.  원장님이 올 2월에 취임하셨고 행정실장도 11월에 취임하셔 가지고 앞으로 21세기를 맞이해서 경기개발연구원이 새로운 체제로 들어섰는데 내년도를 시작으로 해서 21세기에 경기개발연구원이 어떤 방향으로 나갈 것인지에 대해서 전략적으로 말씀해 주시고요.
</p>
<p style="padding-left:1.2em">  그 다음에 다른 위원님이 지적하셨듯이 이 연구실적들이 실제로 정책반영이 되어 야 되는데 ''96년도부터 많은 연구업적을 남겼음에도 불구하고 저희 위원들이 평가하기에는 정책반영 실적들이 미미하지 않았나 평가합니다.  그래서 연구실적들이 정책반영에 평가되기까지 연구원에서 대안제시한 것들이 왜 안 되는지 어려운 점들이 있으면 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 경기개발연구원에서 많은 자료집들이 나오는데 저희가 작년까지는 연구성과물을 받아봤거든요.  그런데 올해 들어와서는 자료집들이 ''경기도 경제동향과 전망'' 매월 나오는 그것 하나밖에 위원들한테 전달이 안 되는 것 같거든요.  그래서 이런 연구원과 우리 위원회간에도 연구실적들이 보여지면 경기개발연구원이 이런 일들을 하고 도정이나 경기도 전체 일선 시ㆍ군에서 이루어지는 연구성과들을 볼 수 있는데 사실 그런 홍보면에서 부족하지 않았나 이런 것들을 말씀드리고 싶습니다.  그래서 앞으로 연구실적에 대한 홍보를 공격적으로 해야 되지 않나, 특히 각종 세미나나 공청회 자료집도 될 수 있으면 어렵더라도 저희 기획위원들한테 꼭 전달될 수 있도록 그런 어떤 채널을 마련해야 되지 않겠나 이렇게 말씀드리고 제 말씀 마치겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 유영록 위원님 수고하셨습니다.  그러면 답변준비와 중식을 위하여 감사를 잠시 중지하도록 하겠습니다.  원장님!  오후 두 시까지 두 시간 동안이면 답변준비가 되시겠습니까? 
</p>
<p><b>○ 경기개발연구원장  노춘희 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 답변준비와 중식을 위해서 14시 30분까지 감사를 중지토록 하겠습니다. 
</p>
