</p>
<p><b>○ 위원장 고수복 </b> 자리를 정돈하여 주시기 바랍니다.  감사를 계속 하겠습니다.  위원님들의 질의에 대한 답변을 듣도록 하겠습니다.  경기개발연구원장 나오셔서 답변해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 여러 위원님께서 질의하시고 의문나시는 부분에 답변 드리기 전에 전체 질의하신 내용이 연 위원님께서 7건을 해주셨고, 이남형 위원님께서 7건, 유영록 위원님께서 3건, 그리고 정운천 위원님께서 9건을 질의해 주셨습니다. 이에 대한 답변을 각각 드리겠습니다.  먼저 연 위원님께서 질의하신 사항을 보고드린다면 실버산업 활성화방안에 대한 연구종료 이후의 진행사항과 실버타운의 적지 등에 대한 견해를 물으셨는데 이에 대한 답변으로는 본 연구원에서는 ''98년 자체과제인 실버산업의 활성화 방안으로 인구구조가 고령화 사회로 진행됨에 따라 경기도와 경기도 자치단체의 실버산업 및 실버타운, 유료노인복지주택 등의 공급을 어떻게 촉진할 것인가에 비중을 둔 연구보고서였습니다.  보고서에는 경기도가 고령인구의 실버타운에 대한 여론조사를 바탕으로 수요를 파악하고 시장규모를 예측했으며 실버산업의 발전방향을 광역단체, 기초단체, 민간참여자로 구분하여 제시하였으며 연구종료 후 진행사항으로는 ''98년 11월 5일에 경기도 외자유치 해외자본에 대한 실버타운 설립문제에 대한 자문요청이 있어서 도내 유망부지, 실버타운 건립 시 관련법령, 실버타운 현황 등에 대해 조언을 제공한 바 있습니다.  ''98년 11월, ''99년 4월에는 미래내 실버타운 소생 프로젝트를 검토한 적이 있습니다.  미래내 실버타운 문제는 광주 도척성당 방상복 신부가 실버타운 건립 중 자금조달에 어려움을 격자 도에 기증의사를 표시하게 되어 도의회와 소생가능성을 가진 민간업자와 검토하였으며 유료시설의 도립화는 적절치 못하다고 생각하여 공유면적의 축소를 통한 분양가 인하를 제시한 적이 있습니다.  그리고 ''99년 2월, ''99년 4월 실버타운 후보지 선정작업을 내부 검토하였는 바 후보 도유지를 조사하기 위하여 28개 지역을 선정한 후 9개로 압축하여 실사한 바 있습니다.  그래서 국토이용계획법상 그린벨트, 군사보호지역으로 불가능하다는 결론을 내린 적이 있습니다.  또한 적정후보지에 대한 의견을 말씀드리면 일반적으로 실버타운의 후보지는 대도시 생활권과 아주 가까운 곳이거나 도시형으로 시내에 건립하는 것이 가장 적정하다고 생각됩니다.  교통이 좋아야 하고 외롭지 않게 많은 사람을 만날 수 있는 곳을 고령자들은 가장 선호하기 때문입니다.  그러나 실버타운이 복합단지로 여가시설, 쇼핑센터, 온천장, 의료시설 등과 같이 있으면서 인근의 간선도로와 지선으로 연결되는 경치 좋은 곳의 수도권이라면 어느 곳이나 가능하다고 생각됩니다.  따라서 연천군 등 대규모 복합단지로 자족기능을 갖추는 경우는 실버타운으로 가능하나 다만 소규모 단지로 조성할 경우에는 어렵다고 판단이 됩니다. 
</p>
<p style="padding-left:1.2em">  다음은 연천군에 소재하고 있는 재래시장의 얼마전 화재발생 문제입니다.  본 연구원에서 재래시장에 대한 연구추진을 한 바 있습니다.  여기에서 재래시장의 소방시설에 대한 구체적인 검토가 있었는지 물으셨습니다.  1998년에 본 연구원은 재래시장의 합리적인 재개발방안에 대하여 연구를 한 바 있습니다.  그러나 재래시장의 소방시설의 체계적인 구축 및 화재예방 등에 관해서는 상기과제의 연구범위를 벗어나기 때문에 구체적으로 검토하지는 못하였습니다.  앞으로 ''도시개발에 따른 소방수요예측과 운영개선방안''이라는 과제를 수행할 계획으로 있기 때문에 이 과제는 장차 재래시장 소방시설의 체계적인 구축 운영방안을 구체적으로 연구 검토하겠습니다.  참고사항으로 재래시장은 등록된 시장과 무등록된 시장으로 구분할 수 있는데 특히 무등록 시장은 주택가와 상업지역에 공용도로를 점유하여 발전해 왔기 때문에 소방시설 등 기반시설을 전혀 갖출 수 없었습니다.  일부 시ㆍ군에서는 부천시 같은 예를 보면 자율소방대를 조직하여 화재예방 및 구급활동에 대한 체계적인 훈련과 교육을 실시하고 있는 실정입니다. 
</p>
<p style="padding-left:1.2em">  다음은 향후 군사부분의 규제문제를 풀어가는 방안이 무엇인가를 질의하셨습니다.  경기도는 행정구역 면적의 24%가 군사시설보호구역입니다.  군사시설보호구역 문제는 국방부 및 예하부대의 입장이 중요하다고 생각합니다.  따라서 국방부에 조정건의를 한 바 121건을 민원중심으로 해제건의를 국방부에 한 바 있습니다.  그 결정에 따라 별도의 대응논리를 개발할 예정입니다.  12월 중에 집중적으로 연구를 하겠습니다.  군사시설보호구역 조정은 정부 및 군의 정확한 통계가 필요합니다.  특히 군사시설 보호구역내 인ㆍ허가 문제는 행정실무 및 정확한 통계를 작성하기 위해 시ㆍ군별 실무공무원 교육을 실시한 바 있으며 군과 협조를 위한 공문을 발송하여 연구 협조 및 민원해결에 필요한 사항을 조치하도록 하고 있습니다.  한편 군사전문가를 위촉하여 국방부 및 유관부대를 직접 방문하여 조사업무를 진행 중에 있습니다.  향후 군사시설 보호구역 규제개선연구를 위해서 국방연구원, 경기, 인천, 강원 공동연구를 수행할 예정입니다.  국방부 협조를 위해서 저희들은 별도로 국방연구원과 연찬회를 계속 하고 있다는 것을 참고로 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 중ㆍ장기 연구보다는 단기 정책과제 발표에 대한 연구원의 견해를 물으셨습니다.  연구원에서도 마찬가지의 문제인식을 같이 하고 있습니다.  연구원별 1개 과제 씩 수행하는 기본과제들은 기초연구의 성격을 띠는 경우가 많고 연구수행 기간 중 여건변화 등의 이유로 인하여 정책집행부서의 필요성을 즉각 충족시켜 주지 못하는 경우가 많습니다.  이런 문제 해결방안으로 연구원에서는 1998년부터 단기 정책과제를 발굴 수행하고 있는 실정입니다.  정책집행부서의 긴급한 현안문제에 대하여 연구원 의 예산으로 적합한 원내 인력을 동원하여 수시로 단기 정책과제를 수행하고 있습니다.  올해는 16건의 단기 정책과제를 수행하여 13건을 완료한 바 있습니다.  내년에는 경기도의회 및 각 집행부서에서 요구하는 사안에 대하여 적극적으로 대응하여 단기 정책과제를 수행코자 합니다.  단기 정책과제는 지금까지 공개발표하지 않는 것이 원칙이었기 때문에 향후에는 과제 성격상 대외비의 경우를 제외하고는 과제요청 부서의 동의를 얻어 후에 공개할 것을 다시 검토하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 혐오시설 입지에 따른 주민지원방안에 대한 정책개발 필요성을 물으셨습니다.  폐기물처리시설 설치 시 주변지역에 대한 지원방안은 폐기물처리시설설치촉진및주변지역지원등에관한법률시행령 제24조에 관련한 법령에 의하여 법적으로 지원토록되어 있습니다.  본 법에 따르면 소각시설 설치비용 중 2%를 주민편익시설에 사용하도록 규정하고 있습니다.  특히 가까운 일본의 경우 무사시노시에 있는 소각장의 경우 주변에 다양한 공민관, 시립도서관과 같은 사회복지시설, 체육 등의 주민편익시설을 함께 공존하게 함으로써 주민에 대한 지원에 최선을 다하고 있는 실태입니다.  따라서혐오시설의 입지에 따른 주민지원부분에 대한 정책과제 개발여부는 관련법들을 면밀히 검토하여 필요하다면 연구원의 정책과제 수행여부를 추후 철저히 검토하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 부도사업장 방치폐기물에 관련된 질의를 하셨습니다.  부도사업장의 방치폐기물의 처리와 관련되어 ''99년 2월 폐기물관리법을 개정ㆍ공포하면서 폐기물 배출자의 사업장 승계에 따른 폐기물 처리의무 자동승계, 폐기물 처리업에 대한 방치폐기물 처리이행 보증제도, 행정대집행에 대한 규정을 신설하여 방치폐기물에 대한 적절한 처리를 용이하게 하였습니다.  그러나 법 발효 전에 이미 발생된 방치폐기물에 대한 처리대책이 없어 남양주시의 1,500t 등 2개소에 2만 5,000t 정도의 경기도내 부도사업장 방치폐기물이 문제시되면서 방치폐기물의 처리를 위한 법안을 검토하였으나 현재 해당 시ㆍ군에서 대부분 방치폐기물을 처리하면서 추가입법의 필요성이 없어지게 된 것을 밝혀드립니다. 
</p>
<p style="padding-left:1.2em">  다음은 경기북부지역의 교량의 경우 교각간에 거리 등 시설현황에 대한 자료가 없는데 교량을 효율적으로 관리하기 위한 연구가 필요하지 않느냐라는 질의를 하였습니다.  현재 우리 연구원에서는 구조물, 시설물에 대한 연구를 수행할 인력이 없기 때문 에 향후 아웃소싱을 통해서 이와 같은 주제에 대해 연구하는 방안을 적극 검토하겠습니다.  이상 연동현 위원님께서 질의하신 데 대한 답변을 드렸습니다.  연 위원님!  빠진 것 있습니까? 
</p>
<p><b>○ 연동현 위원 </b> 됐습니다.  이따 보충질의할 경우가 되면 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 다음은 이남형 위원님께서 질의하신 사항을 보고드리겠습니다.  연구원기금 중 경기은행에 예치한 10억원 처리내역과 기금관리운영위원회의 역할을 물으셨고 기금관리에 대해서 정운천 위원님께서도 물으셨습니다.  같이 답변드리겠습니다.  경기은행 특정신탁에 예치한 기금 10억원이 아직까지 미처리된 사유는 경기은행퇴출 후 회수가능한 채권 8억 4,200만원의 확정시기가 ''99년 2월 17일이었습니다.  채권 중 중앙리스분은 가교리스사에서 ''99년 3월 15일부터 향후 5년간 3개월 단위로 원금과 이자 연리 5%로 상환토록 되어 있었습니다.  그간 3회에 걸쳐 2억 4,300만원이 회수되고 있습니다.  현재까지는 예치총액을 그대로 관리하고 있는 상태입니다만 2000년 1월 결산 시 고문회계사와 협의한 원금손실액 1억 5,800만원에 대한 처리대책을 강구, 기금운용상황을 정리하겠다는 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  다음 기금관리위원회라는 것이 운영되고 있는데 이 위원회가 어떤 것인지에 대하여  질의하셨습니다.  이전까지 본인은 기금관리에 있어서 행정실에서 안전성을 감안한 우량은행으로 정기예금위주 상품을 선정, 수익률을 감안 최고 금리상품예치 위주로 운영하였습니다.  그러나 급변하는 금융환경 변화에 따라 보다 능동적으로 대처하기 위하여 다수의 의견을 반영하며 원내 관련전문가들의 참여가 필요하다는 인식을 가지고 ''99년 4월 6일 규칙 제63호로 기금관리위원회운용규칙을 제정하였습니다.  그리고 ''99년 4월 8일 기금운용위원회를 구성, 현재까지 만기되는 기금에 대하여 예치방향 등 기금관련 중요사항에 대하여 심의운영하고 있습니다.  현재까지 개최실적은 5회에 달하고 있으며 위원은 기조부장과 경제 및 금융관련 박사님 세 분과 5명으로 구성되어 있습니다.  차후 기금관리 시는 항시 위원님들이 지적하신 안전성과 수익이라는 두 가지 개념을 마음에 담아 기금을 운용하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 보조금 지원체제로 전환되면서 나타난 문제에 대하여 물으셨습니다.  연구원설립기간이 비교적 짧고 IMF사태 이후 도의 재정상태가 어려워 불가피하게 기금출연에서 도비보조금으로 전환되었습니다만 연구사업하는 데는 큰 어려움은 없으나 모든 조직이 그러하듯이 재정적 독립이 되지 않을 때 독자적 연구가 어렵다는 점은 있지만 아직까지 그런 사례는 없습니다. 
</p>
<p style="padding-left:1.2em">  이남형 위원님께서 질의하신 지방경찰제도의 도입에 대하여 경기개발연구원이 다각적으로 검토할 필요가 있으며 이에 따라 2000년도의 연구사업계획에 포함시키는 것이 필요할 것으로 보신다고 질의하셨습니다.  지방경찰제도는 지방자치교육제와 함께 그 도입의 필요성이 강하게 제기되고 있으며 저희 연구원도 이와 같은 인식을 같이 합니다.  저희 연구원은 이에 따라 경기도청과 긴밀히 협의하여 정책과제 또는 연구원 자체과제 형태로 본 제도에 대한 연구를 수행할 예정이며 그 시기는 도청과 협의하여 필요하다면 내년 초순경으로 계획하고 있습니다.  아울러 이 위원님께서 말씀하신 경기개발연구원의 인근 타 시ㆍ도 연구원과의 교류실적은 어느 정도이며 해외연구기관의 공동연구를 위한 협력의향을 물으셨는데 우선 상호간에 교류와 협력을 위하여 광역도산하 총 14개 출연연구원에 참여하는 시ㆍ도연구협의회가 이미 구성되어 활발한 활동을 하고 있으며 저희 경기개발연구원은 본 협의회의 부회장 기관으로 중추적인 역할을 담당하고 있다는 것을 이 자리를 빌어 다시 한 번 말씀드립니다.  시ㆍ도연구원협의회는 말씀드린 대로 상호간의 교류와 협력을 통한 연구수행능력의 증대를 목적으로 있으며 공동세미나 개최, 논문집 발간, 공동관심사 토의, 이와 같은 광역적인 활동수행을 하고 있습니다.  저희 연구원은 본 협의회 활동 외에 한강수계지역 5개 시ㆍ도 연구원과 공동으로 한강수계 수질보전 및 관리를 위한 비용분담방안 연구를 하였으며 이미 법으로 제정되어서 완료되었습니다.  서울시정개발연구원, 인천발전연구원 등 2개 국책연구원과 수도권교통종합체계 조사연구를 수행하고 있습니다.  아울러 경기도 대기보전 실천계획 수립을 위하여 서울, 인천 등과 공조체제를 활발히 유지하고 있습니다.  해외 연구기관과의 공동연구는 미국에 있는 대도시행정협의회 ICMA와 직접 교류를 현재 하고 있으며 RPA라고 뉴욕에 있는 지역계획협회하고 뉴저지, 수도권과 같은 성격을 가지고 있는 리져널 플래닝 어소시에이션이라는 기관과 공동협정을 지난 달에 제가 직접 가서 맺은 바 있습니다.  그리고 앞으로 영국, 블란서, 일본 등의 우수 연구기관과 교류협력방안을 강구 중에 있음을 다시 한 번 말씀드립니다.
</p>
<p style="padding-left:1.2em">  또 위원님께서 물으신 기업경기조사 비지니스 서베이 인덱스의 진행 정도가 33%, 기업 및 노동실태조사가 55% 진행이 된 경위에 대해서 말씀하셨습니다.  기업경기조사는 지난 4월 간이조사를 실시하였으며 발표는 ''경기도 경제동향과 전망'' 4월호에 하였고 7월초에 정식으로 1차 조사를 실시한 것입니다.  그 결과는 7월에 별도의 책자로 발표되었습니다.  현재는 두 번째 조사가 진행중이며 12월에 발표될 예정입니다.  이조사는 일천하기 때문에 그와 같은 %가 나오고 있는 것입니다.  기업 실업실태조사는 연 2회 실시하기로 되어 있으며 현재 조사가 진행중이고 11월 30일 완료예정입니다.  그 발표는 12월 초순에 이루어질 것으로 계획되고 있습니다.
</p>
<p style="padding-left:1.2em">  참고로 두 조사의 중요내용은 다음과 같습니다.  경기기업경기조사는 기업의 가동률, 자금사정, 수익률, 수출전망, 고용전망 등을 굉장히 전문적으로 지역별 조사가 이루어지고 있다는 것을 말씀드리며 실업실태조사는 실업률, 실업이후 향후 고용전망 등을 업종별로, 지역별로 파악하는 조사라는 것을 말씀드립니다. 
</p>
<p style="padding-left:1.2em">  다음은 계속해서 지방자치단체간 교류활성화에 대한 연구와 이재민구호품 전달체계 에 관한 연구 용역의 효율화 및 관리방안의 연구 등 진척사항이 늦은 이유를 물으셨습니다.  지방자치단체간 교류활성화에 관한 연구는 80%이상 진행되고 있으며 중간보고서가 제출되고 있습니다.  중간보고서 내용에 대한 발주처의 검토의견을 반영하여 12월말에 마무리할 예정이라는 것을 말씀드립니다.  이재민구호품 전달체계에 대한 연구와 용역에 관한 효율화, 관리방안에 대한 연구는 실제 연구를 요청한 시기가 연구원이 가장 바쁜 10월중순이어서 실제적으로 많은 작업이 이루어지지 못한 것이 사실입니다.  그러나 이재민구호품 전달체계에 대한 연구는 외국의 사례검토가 마무리되는 대로 연구인력을 집중투입, 12월초 실제 수해가 발생한 파주, 연천지역 출장을 통하여 지역의 의견을 적극 반영하여 보고서를 12월말까지 마무리할 것을 확답드립니다.  연구용역의 효율화, 관리방안에 대한 연구는 현재 추진 중이며 특히 여타 과제가 끝나는 12월 중으로 마무리될 예정이며 끝나는 대로 제일 먼저 위원님들께 보고서를 갖다 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 질의하신 ''95년부터 ''99년까지 경기도 및 시ㆍ군이 수주한 수탁용역사업에 대하여 답변드리면 연구원 설립초기인 ''95년에는 경기도로부터 수탁받은 것은 1건으로 계약금액이 9,500만원이었으며 시ㆍ군에서 수주한 용역은 광주군 장기발전계획 1건 계약금액은 3,800만원 등 2건에 1억 3,300만원이었습니다.  ''96년도에 경기도로부터 수탁한 용역은 21세기 일등경기를 대비한 사회복지종합계획 등 9건에 3억 6,070만원이며 시ㆍ군에서 수주한 용역은 연천군 장기발전계획 등을 포함 2건으로 1억 8,000만원을 수행한 결과가 있습니다.  ''97년에 경기도로부터 수탁한 용역은 7건으로 계약금은 17억 300만원이었으며 시ㆍ군에서 수주한 용역은 수원시 어메니티 플랜 등 9건으로 전년보다 수주건수는 늘었으나 계약금은 4억 9,040만원이었습니다.  ''98년에 경기도로부터 수탁용역은 대기보전실천계획 등 3건으로 계약금은 5억 7,646만원이었으며 시ㆍ군에서 수주한 용역은 9건으로 5억 3,090만원이었습니다.  ''99년에는 경기도로부터 수탁용역 건수가 늘어 경기북부접경지역 발전용역 11건으로 계약금은 8억 2,015만 2,000원이었으며 시ㆍ군에서 수주한 용역은 5건으로 계약금은 3억 2,299만 3,000원이었습니다.  지난 ''95년부터 금년까지 총 수주금액은 43건에 43억 3,800원이었다는 것을 덧붙여 말씀을 드립니다.  따라서 ''99년도 수입예산 중 수탁용역사업 수입이 ''99년 9월까지 잡히지 않은 사유를 보고드리겠습니다.  수탁용역사업은 연도 중 수시로 계약이 이루어지고 있으며 계약시 30%∼50%의 선수금을 받아 사업경비로 지원하고 있으나 수탁사업의 성격상 성과품을 제출하여야 준공금을 받을 수 있으므로 일부 사업은 연도 중 사업비가 부족한 실정에 있어 원활한 사업비 지원을 위하여 수탁사업의 수익금을 매년 12월 이사회시 예산을 확정 후 12월 중에 일반회계로 전입하기 때문에 수입 의결되어 현재까지 미수금으로 나타나고 있는 것이 사실이라는 것을 밝혀 드립니다.
</p>
<p style="padding-left:1.2em">  다음으로 질의하신 수질환경연구소의 ''98년 대비 ''99년 예산집행이 감소한 내역에 대해서 보고드리겠습니다.  수질환경연구소는 ''98년 6월 1일자로 개소하여 사무실 확보, 기본장비 구입 등 연구소 개소 준비에 따른 많은 예산이 집행되었습니다.  ''99년도는 인건비, 과제연구비 등만 집행되었고 ''99년 12월말 대비 집행액이 감소되었습니다. 
</p>
<p style="padding-left:1.2em">  ''99년의 단기정책과제로 수행된 강화발전 마스터플랜 연구의 주요 연구내용에 대한 설명과 과업기간이 짧아 심도깊은 연구가 이루어지지 못한 것에 대해서는 강화추진위원회에 활용될 수 있도록 심도깊은 연구가 필요하다고 지적하셨습니다.  본 계획은 강화 환원과 관련하여 강화군의 현안문제를 파악하고 강화군의 발전 전략을 마련하는데 목적이 있습니다.  연구결과에 의하면 강화군이 경기도에 환원될 경우 10대 전략사업 추진에 향후 5개년 동안이 소요될 것으로 전망되는 예산이 나와 있습니다.  단기정책과제의 특성상 많은 예산과 인력이 투입되지는 못하였기 때문에 강화추진위원회에서 활용할 수 있는 자료가 마련되기 위해서는 보다 심도깊은 연구가 필요하다고 말씀드릴 수 있습니다.  참고적으로 강화군에서 국토연구원에서 의뢰한 강화발전용역비가 5억원 수준에 이르고 있다는 것을 덧붙여서 말씀을 드리겠습니다.  
</p>
<p style="padding-left:1.2em">  이상 이남형 위원님이 질의하신 것에 답변을 드렸습니다.  이 위원님, 빠진 것이 있습니까? 
</p>
<p><b>○ 이남형 위원 </b> 나중에 일괄적으로 질의하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그럼 순서에 의해서 정운천 위원님께서 질의하신 내용을 말씀드리겠습니다.  연구원의 자체평가에서 나온 연구수요 분야에서 실제 기여도가 높은 분야가 다른데 연구가 미흡한 것이 무엇인가, 그리고 향후 연구방향을 환경 및 삶의 질로 전환할 의향이 없느냐는 것을 질의하셨습니다.  환경 분야의 경우 연구수요와 실제 연구 기여도가 다른 이유는 실제 기여도의 조사항목이 연구발행물을 대상으로 했으며 자체연구를 제외한 기타 간행물에서 환경분야가 많이 다루어지지 않았기 때문에 향후 환경분야에 대한 연구가 보다 많이 이루어지도록 하겠다는 말씀을 드립니다.  
</p>
<p style="padding-left:1.2em">  아울러 저희 연구원은 환경 및 삶의 질 향상 분야가 그 어느 분야보다도 중요하다고 생각합니다.  그래서 수질환경연구소를 운영하는데 많은 노력을 기울여 왔습니다.  앞으로 더욱 위원님께서 지적하신 대로 환경 및 삶의 질 분야에 배전의 노력을 기울이겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음 정책 입안과 예산 반영 그리고 집행결과에 대한 평가와 평가결과를 환류하는 순환적 정책과정이 경기도정에서 잘 이루어지지 않고 있는 바 경기개발연구원의 정책대안 제시나 집행, 평가에 관한 보다 더 적극적인 노력이 필요하다고 말씀하셨습니다.  실제 그렇습니다.  연구원에서 마련된 연구결과물이 곧바로 정책 집행을 위한 방안으로 전환되는 것이 가장 바람직합니다.  실제적으로 이러한 직접적인 교류에는 한계가 있는 것이 사실입니다.  하지만 가능한 구체적인 정책대안 형식의 연구가 이루어지도록 정책대안 부분을 강조하겠습니다. 
</p>
<p style="padding-left:1.2em">   또한 정책결과에 대한 평가를 위한 연구작업이 진행되어 제시되었으며, 경기도 차원에서 평가작업을 수행하는데 활용하고 있는 것이 사실입니다.  예컨대 경기도 도정평가지표 개발에 관한 연구는 시ㆍ도에 10개의 시책을 평가하는데 활용한 바 있습니다.  광역자치단체 평가시스템에 관한 연구는 올 상반기 각 실ㆍ국ㆍ과에서 경기발전 1차 5개년계획의 집행실적을 평가하는데 활용되었습니다.  이러한 평가과정에 본 연구원이 직접 참여하고 있는 것을 다시 한 번 이 자리를 빌어 밝혀 드립니다.  다만 그 평가결과를 다시 새로운 정책으로 환류하는 작업에는 연구원에서 할 수 있는 범위가 제한되어 있다는 것을 덧붙여 말씀드립니다.  추후에는 이러한 연구를 진행하는 개별연구 위원에게 노력을 통하여 연구결과가 경기도정과 산하기관의 예산과 평가를 실시하고 평가결과를 환류하는 과정을 추적하도록 모니터시스템을 저희들이 구축해 놓고 있다는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그리고 경기도 구조조정 방안에 관한 정책제안제도의 연구결과 실제 경기도 2차 구조조정 방안에 반영하여 늦은 감이 있다는 말씀을 하셨는데 경기도 구조조정 방안에 관한 연구는 실제적으로 경기도 기획관리실 구조조정팀과 공동작업으로 이루어진다는 것을 말씀을 드립니다.  저희가 독립해서 연구하는 것이 아니고 집행부와 공동작업으로 이루어집니다.  지난 3월부터 공동작업을 통하여 경기도 특수성을 반영한 구조조정안을 마련하기 위한 작업을 진행하였으며, 경기도 2차 구조조정안으로 심의 확정한 구조조정안 역시 본 연구원에서 운영하는 경기도 제2차 구조조정안을 최종적으로 확정한 바 있습니다.  따라서 경기도가 행정자치부에 건의한 내용이 바로 본 정책과제의 결과물이며, 최종 경기도 구조조정안 역시 본 연구과제의 최종 결과물을 반영 마련하는데 일치한 내용임을 밝혀 둡니다.  
</p>
<p style="padding-left:1.2em">  결과적으로 본 연구는 경기도 구조조정 과정에서 경기도 구조조정팀과 같은 시기에 공동작업으로 진행되어 그 연구 결과의 대부분이 경기도 제2차 구조조정안에 반영되었다는 것을 밝혀 드립니다.
</p>
<p style="padding-left:1.2em">  다음은 정책입안과 예산 반영, 그리고 집행결과에 대한 평가와 평가결과를 환류하는 순환적 정책과정이 도정에 잘 이루어지지 않고 있는 바 연구원의 정책대안 제시나 집행, 평가에 대한 보다 더 적극적인 노력이 필요하지 않은가 하는 것을 말씀하셨습니다.  실제적으로 연구원에서 마련되는 연구 결과물이 곧바로 정책 집행을 위한 방안으로 전환하는 것이 가장 바람직하다는 것입니다.  실제적으로 이런 것은 직접적으로 적용하는데 한계가 있기 때문에 사실은 가능한한 구체적인 정책대안을 ABC안으로 연구하는 것이지 저희들이 1개 안만 정책대안으로 제시하는 것이 아닙니다.  그것은 연구기관의 성격상 대안만 마련해 주는 것이지 저희가 A안을 집행하라 그런 것은 아니기 때문에 그 실정을 말씀드립니다.  
</p>
<p style="padding-left:1.2em">  정책 결과에 대한 평가를 위한 연구작업이 진행되어 제시되고 있습니다만 경기도 차원에서 평가작업을 시행하는데 활용하고 있을 뿐이지, 예컨대 경기도 도정평가지표개발에 관한 연구에서도 그 예가 나타나고 있습니다.  쉽게 시책을 평가하는데 활용된 바는 있습니다.  광역자치단체 평가시스템에 관한 연구도 올 상반기에 각 실ㆍ국ㆍ과와 경기발전 1차 5개년계획을 집행 활용하는 일을 저희들이 노력하고 있습니다.  다만 여기서 평가결과 다시 새로운 정책으로 환류하는 작업에는 연구원에서 관여할 수 있는 범위가 아까 말씀대로 한계가 있다는 것을 덧붙여 말씀드립니다.  그렇기 때문에 추후에 연구를 진행한 개별연구원들의 노력을 통하여 연구결과가 경기도 정책과 예산에 반영되어 평가를 할 수 있는 평가제도가 반드시 제도적으로 수립해야 된다는 것을 느낍니다.  
</p>
<p style="padding-left:1.2em">  다음 1998년에 수행된 지방부도 기능 제고문제와 연구와 관련해서 말씀드리면 시ㆍ군의 도로기본계획이 없는 문제와 도로건설 예산이 커다란 부분을 차지하고 있는 것이 사실입니다.  객관적으로 이를 평가할 수 있는 지표가 없습니다.  그렇기 때문에 저희들은 ''98년에 수행된 지방도로기능 제고방안 연구에서 이미 건설된 도로를 잘 활용하는 방안에 대해 연구를 하였습니다.  도로정비기본계획 수립을 경기도에 정책 건의하여 올 연말부터 사업추진이 될 예정입니다.  또한 각 시급 도시에 있어서 교통정비기본계획 수립시 1998년에 수립된 경기도교통종합기본계획에 광역도로망계획이 반영되고 있다는 것을 말씀드립니다.  또한 올해는 도로사업의 투자우선순위의 결정방안이라는 자체연구를 수행하여 이 연구에는 한정된 재원 속에서 도로사업의 투자 효율을 극대화하기 위한 평가기준을 설정, 투자우선순위 선정을 목적으로 작업을 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  또 정 위원님이 말씀하신 데이터베이스 구축이 다를 경우 위성정보와 시ㆍ군 데이터 발생하는 문제, 중복되는 문제 등 경기도지리정보체계 구축방안에 대해서 언급하였습니다.  이와 같은 DB 호환은 한 종류를 사용하는 것이 가장 쉽습니다. DB 구축에 소프트웨어가 다를 경우 공통적으로 이용하는 파일형식 DXF를 통해 이용이 가능하므로 큰 문제는 없을 것 같습니다.  최근에 GIS소프트웨어 상호간에 변환없이 이용할 수 있는 체계를 지향하고 있지만 아직 완전 변환이 없이 사용할 수 있는 장비가 아니라는 것을 말씀드리고, 경기도의 지리정보체계 구축방안에서는 경기도내에 데이터베이스 구축이 될 수 있는 한 같은 소프트웨어를 이용하도록 권장하고 있습니다.  그래서 GIS에 관한 문제가 크기 때문에 연구원 자체에서 내년에 GIS에 관한 팀을 별도로 구성할 계획이라는 것을 위원님들께 보고드립니다.
</p>
<p style="padding-left:1.2em">  정운천 위원님께서 질의하신 ''99년도 예산 중 기관운영비 중 임차료는 청사가 확보됐는데 무슨 임차료인지 물으셨습니다.  답변을 드리면 기관운영비에 잡혀있는 임차료는 신청사 이전에 사용하던 인계동 사무실의 임대관리비라는 것을 말씀드립니다.  
</p>
<p style="padding-left:1.2em">  지금까지 정운천 위원님 질의에 대한 답변을 드렸고, 마지막으로 유영록 위원님께서 질의하신 것을 보고드리겠습니다.  21세기 경기개발연구원의 운영전략은 무엇인가라고 말씀하셨습니다.  저희 연구원은 향후 경기도가 지식기반 사회 중심으로 자리잡을 것이라는 인식하에 향후 연구원의 운영방침으로 지식기반 산업의 육성을 위한 비전과 실천전략이 제시돼야 된다고 봅니다.  그리고 도정수행에 능동적으로 대응할 수 있는 실천성 높은 정책대안의 개발이 미흡한 것이 사실입니다.  이와 같은 것을 보완하기 위해서 저희들은 노력을 할 것입니다.  도민의 삶의 질 향상을 위한 환경복지 정책의 개발을 앞으로 하겠습니다.  연구인력의 효과적인 활용으로 심층적이고 창의적인 연구 성과의 산출 등 네 가지 측면에 저희 연구원의 목표를 두고 있습니다.  
</p>
<p style="padding-left:1.2em">  이와 아울러 연구원 재정의 안정적인 운영을 위해 연구원 기능을 확충하기 위하여 민간기업 등으로부터 기금을 출연받을 수 있는 제도를 만들고 있다는 것을 이 자리를 빌어 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  그리고 연구성과 자료집이 전년까지는 배부가 잘 되었으나 금년에는 ''경기도 경제동향과 전망''에 대해서 배부가 되지 않았다는 것을 물으셨습니다.  공청회나 세미나 등의 자료집은 홍보 차원에서 기획위원회 위원님에게라도 배부할 의향이 없는지에 대한 질의를 하셨습니다.  먼저 ''99년도 보고서에서 배부가 안 된 이유는 본 원의 연구과제물이 거의 연도말에 완료되어 아직 발간이 되지 않았기 때문에 배부되지 않았으며 향후 발간되는 간행물은 당연히 도 위원님들께 갖다 전달해 드리겠습니다.  또한 공청회나 세미나 자료집은 지금까지 현장 참석자 위주로 배부하였으나 향후로는 위원님의 말씀대로 연구원의 홍보 차원에서라도 반드시 기획위원님께 제일 먼저 자료를 준비해서 갖다 드리겠습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 유 위원님께서 말씀하신 것에 답변을 드렸고, 제가 그 중에 빠진 것이 있는 걸 보완해서.  정운천 위원님께서 연구장비의 국산 대체화에 대한 방안을 질의해 주셨는데 답변이 미진했기 때문에 그걸 마저 보완을 해 드리겠습니다.  연구원에서 지금까지 구입한 장비는 총 54개종이며 이 중 외국산이 5개 종류입니다.  조달청을 통해 구입 의뢰하는 초기단계의 국산 대체방안을 이미 검토하고 있습니다.  연구기관에서 국산 대신 외국 장비를 도입하는 이유는 기기의 성능, 특히 정밀성, 내구성 때문이라는 걸 말씀드립니다.  국산장비가 개발되어 있는 GC나 혹은 IC의 경우 대개 수질분석용 고가장비와 같이 고장이 자주 나고 그래서 갖고 있는 분석의 신뢰도가 떨어지기 때문에 아직까지는 국내장비가 보편화돼 있지 못한 실정이라는 것을 밝혀 드립니다.  
</p>
<p style="padding-left:1.2em">  외산의 경우 분석기기는 본 연구원뿐만 아니라 다른 보건환경연구원, 국립환경연구원 등에서 주로 구입되고 있는 실정으로 국내 분석기기 시장의 경쟁력이 향상되지 않는 한 앞으로도 이와 같은 대체는 어려운 것이 문제라고 생각됩니다.  특히 국산장비의 경우 최신의 효율적이고 자동화된 동시에 정밀도가 뛰어난 외산에 비하여 한 세대가 뒤떨어진 경우가 대부분이므로 기기상에서도 국산을 추천하지 못하고 있는 실정입니다.  그러나 AAS라든지 TOC라든지 관측정기기에 대해서는 개발된 국산장비가 전혀 없는 것이 현재 우리나라의 실정이라는 것을 밝혀 드립니다.
</p>
<p style="padding-left:1.2em">  이상 네 분 위원님께서 질의하신 것에 답변드렸습니다.  대단히 감사합니다. 
</p>
<p style="padding-left:2.4em">    (고수복 위원장, 유영록 간사와 사회교대)
</p>
<p><b>○ 위원장대리 유영록 </b> 경기개발연구원장님 수고하셨습니다.  다음은 보충질의에 들어가도록 하겠습니다.  보충질의는 일문일답으로 진행하겠습니다.  보충질의하실 위원님 계시면 신청해 주시기 바랍니다.  연동현 위원님 보충질의해 주시기 바랍니다. 
</p>
<p><b>○ 연동현 위원 </b> 원장님의 세세한 설명을 잘 들었습니다.  그런데 두 가지 중에 하나는 오전 중에 질의한 부분에서 궁금한 점이 있어서 여쭙고요.  또 하나는 교부세에 대해서 여쭤보려고 하거든요.  첫 번째는 환경분야에 대해서 지금 날로 심각해져 가는 환경에, 고발이나 시정, 벌금 이 정도의 환경법이 돼 있는 걸로 본 위원은 생각하고 있는데 경기개발연구원에서 정책과제로 중앙정부에 어느 정도 반영할 수 있는 건의 사항에 대한 걸 여쭤봤었거든요.  그러니까 본 위원이 가만 보기에 원상복귀, 기존에 우리가 불법 쓰레기를 갖다버렸을 때 적발해서 벌금만 내면 현재 현행법 정도로 해서 조치가 됐었다는 말입니다.  이 부분에 대해서 여쭤봤는데 그 부분이 빠진 것 같아요.  그 부분 좀 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 환경문제는 환경부라는 곳이 있어서 지방자치단체에서 할 수 있는 게 한계가 있습니다.  그래서 환경을 복원한다는 것이 시ㆍ군에서는 하고 있지만 그 법의 한계 때문에 못하는 것으로 현장에 대한 문제해결에 관한 법을 개정하는 운동을 지방자치단체에서는 벌이고 있는 걸로 알고 있고, 저도 경기도 전체의 문제를 놓고 봤을 때 환경법이 너무나 경직돼 있기 때문에 처음 생겨 가지고 지방자치를 해 보지 않아서 현장에 대한 반영을 안 하고 있기 때문에 법 개정을 하지 않으면 보전에 관한 문제가 어려운 것이 아닌가 그런 생각을 해서 법에 관한 개정 작업을 저희들이 하고 있습니다.  
</p>
<p><b>○ 연동현 위원 </b> 지금 원장님께서도 말씀을 해 주고 계시지만 저도 노파심에, 또 경기민의 한 사람으로서 팔당상수원 문제도 지금 굉장히 심각성을 낳고 있듯이 향후 임진강과 한탄강이, 앞으로 2010년도인가 그때 가서는 우리나라도 물부족 국가라는 정도까지 나오는데 지금부터 이 법이 개정되지 않고서는 맑은 물을 보급받을 수 없다.  그래서 정책적으로 경기개발연구원에서 중점적으로 연구 발표를 하시면서 중앙 보건복지부나 환경부 차원에서 반영이 될 수 있도록 부탁 좀 드리겠습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 교부세 부분에 대해서 한번 여쭙고 싶거든요.  저희 연천군 실례로만 봐도, 더더욱이 북부지역의 접경지역에 있는 김포나 파주, 더더욱이 우리 연천지역은 100%가 군사보호시설구역으로 묶여 있습니다.  그리고 3개 군단에 4개 사단이 자리를 잡고 있기 때문에 현재 우리 연천주민이 군인들하고 기대 산다고 해도 과언이 아니거든요.  그런데 제가 알고 있기로는 도에서 교부세율을 현 사병들의 교부세율의 적용을 어느 정도는 받고 있다고 하는데 실질적으로 지방자치가 운영되고 있으면서 사실 상ㆍ하수도나 생활환경 쓰레기 이 정도도 다 지방자치 경제에서 경비로다 조달하고 있다는 말입니다.  그러면 군인들이 100이라고 칠 때 100명분에 대한 교부세 비율에 적용을 해야 한다고 생각하는데 이 부분에 대해서 어떻게 생각하시는지.  이것은 좀 연구도 해 봐야 되고 또 지방자치법 개정이라든가 상위법에도 적용이 됐으면 하는 바람입니다.  원장님 한번 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것은 제가 경험을 하고 있습니다.  만약 부대에 3,000명이 있다고 했을 때 국방부에서도 환경오염 문제를 굉장히 다루고 있습니다.  오히려 민간부분보다 국방부에서는 환경, 수질에 관한 것을 늪을 조사해서 연구를 해 가지고 정화시설을 하는 것이 아니라 자연정화를 하는 것이 군에서도 발달한 데가 많습니다.  그런 현장이 몇 군데 있습니다.  
</p>
<p style="padding-left:1.2em">  그래서 군에서도 환경오염 문제가 여러 가지로 자기네들이 독단적으로 연구를 하고 있습니다.  그래서 지금까지 군의 시설이 만약 거기에 100명이 있다면 100명이 상ㆍ하수도 쓰는 것이 문제가 되지 않느냐.  옛날에는 그와 같이 됐는데 국방부 자체에서 환경부의 환경법을 지키는 것을 솔선수범하고 있기 때문에 아마 그런 문제는 크게 문제가 되지 않는다고 보는데 제도상도 그렇게 안 돼 있습니다, 부처와 부처간에 협조해서 자체적으로 하고 있지.  그 법을 사실은 만들어줘야 되지 않느냐 그런 생각을 하기 때문에 저희가 접경지역을 연구하다 보니까 이런 게 발견을 했기 때문에 그것도 제도적으로 보완하려고 노력하고 있습니다. 
</p>
<p><b>○ 연동현 위원 </b> 그리고 제 생각은 사실 연천군을 가지고 국한해서 말씀드리는 것은 죄송스러운 부분이 있지만 연천지역의 주민들은 사실 중앙정부로부터 돈을 받아야 된다고 개인적인 소견은 그렇습니다.  전 지역이 100% 군사지역으로 묶여 있음에도 불구하고, 그 다음에 군 징발지로 있기 때문에 자기 소유로 있어도 재산권 행사를 전혀 못하고 있어요.  그래서 이런 것은 개인적인 소견으로 볼 때 국방부나 중앙정부에서 연천군 주민들만큼은 오히려 돈을 줘야 되는 것 아니겠느냐.  이 부분을 박사님께서는 어떻게 생각하고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그래서 그것을 저희가 연구하는 것이 실사를 하는 것이 있습니다.  실사를 왜 하는고 하니 그런 기초 데이터를 구축하기 위해서 합니다.  연천이 100%인데 사실 방법은 세금감면 혜택에서부터 실행을 할 수가 있습니다.  그런데 그건 조사가 안 됐기 때문에 그 데이터가 없어서 그 기준을 저희들이 마련을 아직 못하고 있습니다만 이와 같은 문제는 이것을 전공하는 박사님들이 답변을 드려야지 되는데 지금 시간이 없으시기 때문에 제가 대강 말씀을 드립니다만 구체적인 답변을 수치까지 아시고 싶으면 저희 해당 연구원 박사님의 답변을 들으실 수 있습니다.  
</p>
<p><b>○ 연동현 위원 </b> 그러면 개별적으로 제가 나중에 한번 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 담당 연구원하고 구체적인 걸 아셔 가지고 지역에 가서 말씀을 해 주시면 충분히 될 걸로 생각합니다. 
</p>
<p><b>○ 연동현 위원 </b> 이상입니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 연동현 위원님 수고하셨습니다.  다음 보충질의하실 위원님. 이남형 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이남형 위원 </b> 질의에 대한 답변 잘 들었습니다.  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 감사합니다. 
</p>
<p><b>○ 이남형 위원 </b> 그런데 기금에 대해서 아까 제가 질의를 드렸는데요.  지금 답변하시는 과정에서 보면 3개월 단위로 현금에 대해서 일부씩 회수하시는 걸로 해서 2억 4,300만원을 회수하셨다고 말씀하시면서 2000년 1월 결산시에는 1억 5,800만원을 정리하시겠다고 말씀하셨는데 이 부분이 구체적으로 손실처리하시겠다는 것인지, 어떠신지.  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것은 담당이 행정실장입니다.  수치를 다루시는 분한테…….
</p>
<p><b>○ 행정실장 심무섭 </b> 제가 답변을 드리겠습니다.  저희가 현재 결손은 특정금전신탁으로 경기은행이 퇴출되면서 손실금이 1억 5,800만원입니다, 이자까지 해서.  그래서 그걸 현재 한미은행측하고 협의 중에 있는데 그 손실을 보장하는 출연금으로 현재 협의 중에 있습니다.  잘 될 걸로…….
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 협의가 끝났습니다. 
</p>
<p><b>○ 이남형 위원 </b> 그러면 실질적으로 손실되는 것은 없다는 말씀이시네요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 이남형 위원 </b> 그 부분은 알겠습니다.  그 다음에 지방경찰제도에 대해서는 2000년 초에 상황을 보셔서 한번 검토를 하시겠다 말씀하셨는데요.  그건 여기서 결정하실 문제시지만 가급적이면 그렇게 해 보셨으면 어떨까 다시 한 번 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그리고 아까 답변주시는 과정에서 수질환경 금액이 지난 해에 비해서 금년도에 줄어들었고 비용이 오히려 줄었다고 말씀을 드렸는데 그 부분 다시 좀 정확하게, 제가 이해를 잘 못하겠거든요.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그 문제는 구체적으로 연구하신 성 박사님께서 답변을 드리겠습니다.
</p>
<p><b>○ 환경연구부장 성현찬 </b> 환경연구부장 성현찬입니다.  제가 잠시 답변을 드리겠습니다.  ''98년도 6월 1일자로 저희 수질연구소가 발족을 해 가지고 초기에 아까 말씀드린 대로 기자재라든가 이런 부분에서 돈이 많이 소요가 됐습니다.  1억 2,000만원 정도가 들었는데 올해 ''99년 6월 5일자로 수질환경연구소가 없어졌습니다.  기존에 연구원내에서 생활환경이라든가 대기, 폐기물, 자연환경을 담당했었고요.  한강수계법도 만드는 당시에 상당히 수질이 중요했기 때문에, 그런데 그 일이 끝나고 나서 올해 구조조정이 되면서 기존에 생활환경과 수질환경연구소가 통합이 돼 가지고 환경연구부로 통합이 됐습니다.  환경연구부에서 수질, 대기, 폐기물 전체를 다루게 돼 있습니다.  그러다 보니까 올 6월까지만 예산을 세우고 그 이후에는 전체 인원이 들어갔기 때문에 예산이 일부 줄어든 그런 부분입니다.  
</p>
<p><b>○ 이남형 위원 </b> 잘 알겠습니다.  충분히 이해가 됐습니다.  그 다음에 마지막으로 강화와 관련된 문제를 아까 제가 질의를 드렸는데요.  원장님 답변하시는 과정에서 보면 국토개발연구원에 5억원으로 지금 발주가 돼 있다, 또 연구가 진행중이다 말씀하셨는데요.  발주처가 어디입니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 발주하는 데가 인천시에서 5억원을 최기선 시장이 주고 연구 좀 해 달라고 그래서 공청회하는 데도 제가 갔었습니다.  거의 지금 끝났습니다. 
</p>
<p><b>○ 이남형 위원 </b> 그럼 발주처가 인천광역시가 되겠네요?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 이남형 위원 </b> 언제쯤 완전히 발표를 할까요?  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 지금 다 나왔습니다.
</p>
<p><b>○ 이남형 위원 </b> 제가 왜 이걸 여쭤 보느냐 하면 다 아시는 거지만 경기도하고 인천광역시하고, 경기도에도 도환원추진위원회가 구성돼 있고 그런데 인천쪽에서는 이 부분에 대해서 반감을 일으킬 테니까 5억원씩 들여서 돈만 들어갔다고 더 좋은 결과가 나오는 건 아니겠지만, 어쨌거나 개발하게 되면 저희 쪽에서 만든 걸 보니까 개발연구비가 우선 적고 개발하는데 이 부분이 이와 같이 대응을 하는 것이 맞는지 안 맞는지 모르겠지만 준비를 철저하게 할 필요가 있지 않겠나 이런 생각에서 말씀드리는 겁니다.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그 문제는 제가 관여하고 있기 때문에 말씀드립니다만 
</p>
<p>어떻게 하든지 이것을 좀 디펜스를 하기 위해서 5억원을 국토연구원에 줬는데 원유철의원님이 가지고 있다 해서 보니 보고서 내용이 옛날에 저희가 기본계획 세운 것 이상이 안 나옵니다.  제가 여기 오기 전에 강화기본계획을 세웠는데 그 이상이 안 나오고 지금 문제는 경기도에서 할 것은 연구보고서가 중요한 것이 아니고 어떻게 집행하고 어떻게 실천하겠다는 액션프로그램이 나와야 됩니다.  그래서 해야 될 것은 경기도에서 그런 액션프로그램을 해주어야 5억원짜리가 아니라 100억원짜리이상의 가치가 있을 것이 아니냐 저는 그렇게 생각하기 때문에 그 보고서는 별 것 아니라는 것을 제가 알고 있기 때문에 말씀드립니다. 
</p>
<p><b>○ 이남형 위원 </b> 알겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 이남형 위원님 수고하셨습니다.  다음 보충질의하실 위원님, 정운천 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 정운천 위원 </b> 안산출신 정운천 위원입니다.  원장님 답변 잘 들었고 개중에는 충분한 답변이 된 것도 있고 물론 제가 질의를 정확하게 하지 않아서 그런지 의사가 잘 전달되지 않은 부분도 있는 것 같습니다. 
</p>
<p style="padding-left:1.2em">  첫 번째 연구원 자체평가에서 간행물이용 분야별 순위하고 연구수요분야하고 이것이 거꾸로 된 부분이 환경부분에 있어서 많다고 말씀드렸고 그래서 제가 문제로 삼은 것은 조사방법에 있어서 그런 것이 아니라 환경부분이 중요해 지는데, 실질적으로 환경부분에 대한 수요는 많은데 연구보고서나 이런 것을 통해서 활용할 수 있는 분야는 적다.  그 부분에 대한 답변도 일부 있었습니다만 제가 보충적으로 질의드릴것은 환경부분은 실질적으로 기업이나 주민 그리고 정부 또는 지방자치단체 3자가 상당히 이해가 대립되는 부분이기 때문에 이런 부분에 대한 연구조사나 이런 것은 사실 실질적으로 현장을 뛰면서 많은 이해 관계자들의 얘기를 듣고 그리고 객관적인 판단을 할 수 있는 자료를 내놓는 것이 필요하다라고 판단하고 있습니다.  그런데 환경분야 연구를 보면 대개 이론적인 연구가 상당히 많습니다.  예를 들어서 수질부분이 COD나 BOD가 얼마다.  그리고 과거에 비해서 얼마가 악화되었다 하는 정도로 끝나는 부분이 대부분입니다.  그래서 앞으로 연구를 하실 때에 환경분야, 다른 분야도 다 마찬가지겠습니다만 환경분야는 이해가 상당히 대립되는 부분이기 때문에 3자의 의견을 충분히 듣고 이해타당한 부분에 대해서는 적극적으로 수용하고 그리고 문제를 해결할 수 있는 어떤 자료를 제출하기 위해서 그런 부분에 집중적으로 연구를 해서 자료를 내놓는 것이 어떤가, 그런 보고서가 나와야만 사실 환경문제를 해결하는데 상당히 도움이 되지 않겠는가 하는 점에서 여쭤봤습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 답변을 구체적으로 드리겠습니다.  지금 도시개발이나 도시행정 때 수요공급의 원리이어야 됩니다.  서울시의 경우도 인구가 준다는 것은 수요공급원리의 균형이 깨졌기 때문입니다.  경기도도 이와 같은 수요공급원리에 의해서 업무가 정책개발이 되어야 되는데 그것이 빗나가고 있다는 것이 저희 느낌입니다.  똑같은 생각을 하고 있기 때문에 그것을 저희들이 분석을 늘 합니다.  정책이 있으면 모니터가 돼서 평가를 해야 되는데 우리나라 행정이라는 것이 계획만 하고 집행만 해 버립니다.  지금은 시대가 바뀌기 때문에 사회구조가, 사회시스템이 바뀌어 가지고 시민이 금방 압니다, 행정이라는 것을.  그것을 누가 조사를 안 합니다.  그래서 앞으로는 평가하는 작업이, 그래서 저희들은 평가작업의 기준을 마련하고 있는 것이 바로 그것입니다.  제가 오고 나서 2월 21일부터 11월 7일까지 경기도가 하고 있는 정책을 다 통계를 내봤습니다.  수요공급의 원리를 따라 주려고.  그런데 아까 말씀드린대로 건수로 보게 되면 제일 많은 것이 경제투자관리실에 174건입니다.  이것이 제가 와서 2월 20일부터 11월 7일까지 조사한 것입니다.  그 다음에 146건이 자치행정국, 그 다음에 세 번째가 기획관리실 142건 그리고 환경국이 136건, 지금 이것 어디에도 내놓은 것이 아닙니다.  저희가 자체적으로 우리 살림을 하기 위해서 빼본 것입니다.  자성하기 위해서 저희가 빼본 거예요.  도대체 경기도가 뭘 하고 있는가.  여기에 정책개발을 맞춰줘야 되니까.  그래서 지금 말씀하신 대로 똑같은 생각을 가지고 자료통계가 나와야 거기에 대한 기준이 나오니까, 그래서 저희들도 이런 것을 계속 연구하다 보니까 안 되겠구나 해서 이것을 뽑은 겁니다.  그래서 쭉 나와 있는데 제일 적은 것이 11건 공보관실입니다.  그 다음에 기타가 되겠습니다만 이와 같이 해서 북부출장소가 93건 건수가 많이 있습니다.  저희 연구원이 앞으로 해야 될 것이 이 수요공급원칙을 따라서 정책개발을 해주어야 되지 않느냐 하는 것이 제 생각입니다. 
</p>
<p><b>○ 정운천 위원 </b> 알겠습니다.  그리고 이 문제는 아까 추가적인 질의하고 맥을 같이 합니다만 연구결과가 정책입안에 직접적으로 활용이 안 되는 부분이 있다.  그 다음에 된다 하더라도 예산편성과정을 거쳐서 집행이 되고 성과측정을 한 결과가 다시 정책에 피드백되는, 정책에 환류되는 부분이 아직까지 마련이 안 되셨다고 답변하셨습니다.  그런데 아이러니컬하게도 아까 구조조정안에 대한 연구가 늦었다라고 질의드렸는데 그 부분에 대한 답변 중에 경기도 기획관리실과 공동연구를 통해서 모든 것을 반영했고 그리고 행자부의 건의사항도 모든 것이 반영되었다 이렇게 말씀하셨단 말입니다.  제가 느끼는 것은 정책의 연구결과가 직접적으로 반영되고 그것이 예산에 편성되어서 집행될 수 있는 가장 유일한 방법은 경기도에서 직접 업무를 담당하시는 분과 연구를 공동으로 하는 것이 아닌가 이런 생각을 해 봤습니다.  성과예산주의를 저번에 아주 시끄럽게 하면서까지 정책에 반영하고 집행했던 기억이 납니다.  작년 이맘때쯤.  그런데 지금 와가지고 행자부에서도 그렇고 경기도에서도 그렇고 성과예산에 대한 실질적인 집행이 그리고 이행이 안 되고 있는 그런 상황이거든요.  그 이유 중의 하나가 과연 성과측정을 어떻게 할 것이냐에 대해서는 아직 구체적인 지침이 안 내려온 그런 상황입니다.  그렇다면 저번에 이재원 박사님도 성과예산에 관한 방안에 대한 연구도 하셨습니다만 거기에 모든 답이 들어 있어요.  그런데 이것이 실질적으로 정책에 반영이 안 되고, 실질적으로 정책을 실행하는 데도 반영이 안 되는 것은 연구를 하실 때 좋은 안만 내놓고 현재 현상에 대한 검토작업이 아무래도 직접 일을 담당하시지 않으시니까 파악하기 어렵지 않겠는가 하는 생각이 듭니다.  그렇다면 앞으로 연구하실 때는 보조적으로라도 그런 분들을 참여시켜 가지고 같이 하시면 어떨까 생각하는데 거기에 대해서는 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 좋은 지적이신데 케미컬화하자는 것이 제 부르짖음이고 유기화하자는 것이 제가 늘 말씀드린 것입니다.  그래서 어느 부하고 저희하고 또 부와 부와의 관계가 있습니다.  어느 부에서는 그것이 잘 되는 수가 있고 그렇지 않을 때도 있습니다.  그것은 왜 그런가 이유를 봤더니 우선 예산에 관한 것도 문제되기 전에 체계적인 제도적으로 습관화되지 않아 가지고, 저희 연구원은 그래도 수십년간 학위를 하고 그 분야의 전문가들입니다.  그런데 계장과 과장이 있고 국장이 있고 그렇습니다.  계장이나 과장이나 이런 사람들 하고 일을 하기 위해서 유기체가 되어야 됩니다.  그런데 그렇게 유기체가 된 부서는 일이 잘 되고 유기체가 똑 같이 되지 않는 데, 차등이 있겠죠.  개인감정이나 뭐 여러 가지.  그래서 그것을 유기화하자는 것이 제 생각이기 때문에 점차적으로 유기화하는 방법을 제가 마련하고 있는 중입니다.  그래서 지금까지 눈에 띄지는 않지만 눈에 띄는 성과가 내년 정도면 가시화되지 않겠는가, 시간이 필요한 것 같습니다.  어느 정도 시간이 투입되어야지 하루아침에, 사람과 사람사이에 서로 만나고 이렇게 해서 유기화되는 것이지 처음부터 전화로, 공문으로 해 가지고는 안 되지 않겠느냐, 단 애로는 있습니다.  그 고충은 제가 말씀드리지만 사실 집행부에서 해야 될 일도 저희들한테 던져주는 일이 많습니다.  알고 보면 아무 것도 아닌데.  저희는 굉장히 고가의 자원을 가지고 있는데 그것을 낭비하는 결과가 되거든요.  그런 것은 제도적으로 저희들이 앞으로 고쳐야 되지 않겠느냐, 적어도 고급인력은 고급인력답게 활용해야지 그래야 발전하죠.  이런 것이 다 의회에 계신 여러분들께서 그런 구조를 리엔지리어링을 해주어야 된다고 생각합니다. 
</p>
<p><b>○ 정운천 위원 </b> 알겠습니다.  그것은 같이 해결해 나가야 되지 않을까 생각합니다.  많이 협조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음 질의하겠습니다.  경기 부도로 기능 제고방안 중에서 미처 제가 파악을 못했습니다만 경기도 도로망이 전체가 전산화가 되어 있나요?  그래서 거기 관련된 자료가 데이터베이스로 구축이 되어 있습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 조 박사님이 답변하겠습니다. 
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 기획조정연구부장 조응래입니다.  지금 저희 경기도 도로망 같은 경우에 1만㎞ 정도 있는데 지난 번에 경기도 교통종합기본계획이라는 것을  하면서 6,870㎞에 대해서 전산화 작업을 했습니다.
</p>
<p><b>○ 정운천 위원 </b> 거기에 대한 질의를 하겠습니다.  제가 여기 의회에 들어와 가지고 제일 궁금하게 여겼던 부분 중의 하나가 도로건설할 때 임의적으로 도로를 건설하는 것처럼 보인단 말입니다.  실제가 아닌지 그런지 모르겠습니다만.  왜 그런 생각을 하게 됐냐면 많은 도로 중에 특별한 구간을 선정해서 확ㆍ포장공사를 한다든가, 도로를 신설한다든가 했을 때 과연 그 도로를 건설하는데 들어가는 비용이 얼마인데 실질적으로 기대효과는 어떤 수치로 나온다.  예를 들어서 한 개 지표를 얘기하는 것이 아니라 여러 개 지표가 나올 수 있지 않겠습니까?  그러면 그 도로를 다른 건설예정인 도로에 비해서 우선적으로 선정한 이유가 뭐냐 했을 때는 아무도 답할 수 없는 그런 상황인데 만약에 데이터베이스가 되어 있으면 어떤 구간을 선정해서 그 도로를 확ㆍ포장했을 때의 효과하고 그 다음에 관련된 지선들의 교통량의 변화라든가 이런 것이 다 나타날 수 있습니까? 
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 경기도 교통종합기본계획이라는 계획을 수립하게 된 게 도로를 분석하기 위한 기초데이터라고 할 수 있는 도로망에 대한 현황자료하고 그리고 사람간에 통행이 어떻게 이루어지고 있는지 통행실태조사가 전혀 없었습니다.  그래서 저희가 그 조사를 끝냈고 그 데이터를 활용해 가지고 올해 자체과제로 도로사업에 투자우선순위 결정방안이라는 것을 하고 있습니다.  사실 그것을 하는데 있어서 문제는 저희가 경제성 분석을 하면 좋은데 각 시ㆍ군에서 시의원님이라든지 또 도의원님들의 압력 그리고 북부지역의 균형개발차원의 문제 이런 것들이 투자우선순위를 왜곡시키는 문제이기 때문에 그런 것들이 종합적으로 반영된 투자우선순위 결정방안에 대해서 현재 연구하고 있고 이것은 올해로 끝나는 것이 아니라 올 연말부터 도로정비 기본계획이라는 게 들어갑니다.  그것은 저희가 안을 만들어 놓으면 도의원님들하고 시ㆍ군의 의원님들하고 협의를 통해서 결정지을 예정입니다.
</p>
<p><b>○ 정운천 위원 </b> 그러면 현재로써는 선정된 예산투입대상 도로건설이 있지 않습니까? 그것을 했을 때의 효과같은 것은 지표로 금방 튀어 나오겠네요?
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 현재로써는 총 차량 주행거리라든지 주행시간이라든지절감효과가 어떻게 되는지 그런 것을 갖고 하고 있습니다. 
</p>
<p><b>○ 정운천 위원 </b> 그러면 복합효과도 나옵니까?  예를 들어서 도로를 딱 하나만 지정했을 때 효과하고 그 도로를 하면서 연관된 다른 도로를 확ㆍ포장하는 것과 또 전혀 별개인 다른 시ㆍ군의 도로를 건설하는 데 효과가 같은 연계되는 도로를 확ㆍ포장하게 되면 더 시너지효과가 나지 않겠어요?
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 지금 분석하는 시스템 자체는 전혀 개선을 안 했을 때, 모두 다 개선했을 때, 개개의 노선을 개선했을 때 그런 형태로 해서 개별노선의 효과분석을 하고 있습니다. 
</p>
<p><b>○ 정운천 위원 </b> 활용할 수 있는 것은 내년부터 가능한가요?
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 그런데 제가 아까도 말씀드렸습니다만 일단 연구결과로써는 결과가 도출될 수 있지만 그것을 결정하는데 있어서는 각 집행부라든지 의회라든지 그런 조율을 거쳐 가지고 결정을.
</p>
<p><b>○ 정운천 위원 </b> 내부적인 요인말고 경제적인 요인이라든가 그런 것만.
</p>
<p><b>○ 기획조정연구부장 조응래 </b> 현재 저희 평가기준으로써는 결과는 나옵니다. 
</p>
<p><b>○ 정운천 위원 </b> 알겠습니다.  그 다음 질의하겠습니다.  GIS 하시면서 제가 생각하는 것과 동일한 생각인 것 같습니다.  그리고 연구내용도 저희들이 기대하는 내용하고 거의 비슷하지 않은가 생각되는데 정보통신담당관실에서는 6개 GIS 소프트웨어를 툴을 사용해 가지고 GIS를 구축하고 있습니다.  그리고 시범사업하는 것도 여섯 군데이고  앞으로 내년에는 더 늘어날 것으로 생각되는데 사실 관련된 예산이 상당히 많습니다.  그리고 GIS를 구축해 놓으면 별도의 다른 시스템과 연계되어 가지고 상당히 앞으로 생산성 제고를 위해서 활용할 수 있는 시스템이라고 판단하는데 경기도에서 생각하고 있는 것은 6개 소프트웨어를 시범사업에 활용해 가지고 그 6개를 동시에 31개 시ㆍ군에 확대할 생각을 갖고 있습니다.  거기에 대한 지적은 행감에서 했습니다만 경기개발연구원에서도 적극적으로 집행부서하고 협조해서 그쪽에서 아직 모르는 게 선진국에서 하는 GIS 실질적인 검증내용이 없거든요.  서로 다른 소프트웨어를 가지고 생성된 DB가 서로 호환이 되는지 검증을 해봐라 했는데 된다고 하면서 검증은 안 해 봤습니다.  그런 부분도 같이 연구하고 한번 검증과정을 같이 했으면 싶거든요.  그 부분 가능하시겠죠?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 기술적인 문제가 됩니다만 서울시에서도 그것을, 행자부에서 지금 실수한 게 그것입니다.  행자부에서 주민등록 실수한 것, 똑같은 현상인데 저도 사진을 찍으라고 해서 찍었는데 사진이 어떻게 나온 줄 모르죠.  그렇기 때문에 사진을 갖고 가서 이것을 찍어라.  그렇게 찍은 것은 괜찮죠.  사진갖다 주고 이것 찍어라.  그게 왜그러냐면 기종을 선택할 때 행정적으로 기종을 선택하면 안 됩니다.   GIS 관계는 기종이 굉장히 중요합니다.  기종이 하루가 다르게 변합니다.  선 마이크로라는 회사가 있습니다, 미국에.  선 마이크로가 있고 여러 가지 회사들이 많은데 그 회사에서도 가장 광범위하게 쓸 수 있고 다른 시스템과 같이 갈 수 있게 할 수 있는 방법을 그 사람들이 다 개발했습니다.  그런데 우리나라에서는 그 것을 갖다 쓰는 것이 아니고 전부 조달청 납품이고 과거의 구식모델, 싼 것 가지고 하게 되니까 그런 문제들이 생긴다고 저는 보고 GIS라는 것은 과학적인 기술이기 때문에, 그것이 검증이 되어야 된다고 보기 때문에 그것이 경기도에서 네트워크화 하는 것도 저로서도 의문스럽고 기술검토를 먼저 해야 된다.  그래서 저희는 GIS팀을 만들려고 그러기 때문에, 아직 안 만들었기 때문에 다행스럽게 생각합니다.  그리고 전부 호환이 될 수 있게 시스템을 구축하려고 합니다.  기계도 그렇고.
</p>
<p><b>○ 정운천 위원 </b> 팀 구성하셔 가지고 정보통신담당관실하고도 같이 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 정운천 위원 </b> 마지막 질의드리겠습니다.  사실 일반기업 같은 경우는 예산을 투입하게 되면 실질적인 효과가 금방 나타나거든요.  예를 들어서 제품의 품질이 올라가는 것하고 여러 가지 효과가 있겠습니다만 단적으로 얘기해서 주당 순익이 올라간다, 1주당 수익이 300원에서 500원 올라갔다 그러면 67%의 효과가 있었다고 보는데 일반행정분야에 있어서는 예를 들어 예산을 3조 6,000억원을 썼는데 과연 어떤 효과가 있었느냐 이러면 단적으로 얘기하기가 상당히 어렵습니다.  무엇을 몇 개 지었고 무엇을 몇 m를 늘렸고 하는 정도만 나오지 실질적으로, 종합적으로 얼마만큼 효과가 있었다는 게 안 나오는데 그래서 얼마전에 경기개발연구원에 제가 행감자료 중의 하나로 삶의 질을 측정할 수 있는 지표개발이 과연 가능한가, 저는 가능할 것 같다는 생각이 들어서 질의를 드렸더니 어느 분이신지는 모르겠습니다만 저의 생각하고 비슷하더라고요.  그리고 측정이 가능한 것으로 답변이 왔습니다.  그래서 정책기획관실에서도 그 문제가 논의되어 가지고 만약에 그 지표개발이 가능하다면 실질적으로 활용할 수 있도록 정책기획관실과 상호 긴밀하게 협조하셔서 같이 개발해 주시기 바라고 그것이 설사 처음에야 첫술에 배부르지 않을테니까 지표가 나와도 활용하는데 많은 문제점들이 있을 겁니다.  그것을 개선해 나가면 언젠가는 중요한 지표 중의 하나로 활용할 수 있지 않을까 생각됩니다. 
</p>
<p style="padding-left:1.2em">  그리고 그 질의는 그 정도 하고 아까 기금 중에서 제가 질의한 것 중에 한 가지 빠진것이 있는데 1년에 50억원 정도를 쓸 때 수탁용역시 또 아무런 수입이 없을 경우에 독립할 수 있는 기금이 625억원 정도 된다.  203억원 정도밖에 없기 때문에 그 갭을 과연 어떤 방법으로 메울 것인지, 도에서도 도움이 있겠습니다만 도도 어려운 형편이기 때문에 단시일내에 갭을 극복할 수 없을 것 같고 자체적으로 어떤 계획이 있으신지.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그 계획은 대개 지금 있는 저희 전문인력이, 경기도의  1,000만 인구가 산다.  그 다음에 예산이 시ㆍ군 합해서 12조원이다.  인구가 있고 예산이 있습니다.  그리고 면적이 있습니다.  그래서 언제든지 계획하는 사람은 기본이 인구입니다.  인구부터 출발하기 때문에 지금 12조원의 예산을 가지고 있고 전체 GRP나 이런 것 봐서 전문연구원이 50명 규모가 최소단위입니다.  50명 규모의 단위는 되어야 됩니다.  그리고 한 600억원 정도의 기금이 있다 해도 8% 가지고 계산을 해 보셨죠.  600억원 정도 기금의 수입이자 가지고 운영한다는 것은 얘기가 안 됩니다.  왜냐하면 연구원이라는 것이 자체독립을 해야 됩니다.  저는 그것을 주장합니다.  경영화해야 된다,  경영화한다는 것은 여기서 제품을 생산해서 팔아 가지고 그 수익성 가지고 운영합니다.  어느 나라든지 연구원이 그렇게 되어야 된다고 봅니다.  앞으로 지사님께도 말씀드렸어요.  독립해야 된다, 경영화 해야 된다.  지사님 무슨 말인지 못 알아 듣고 ''얼마든지 돈 줄게 성과물만 제대로 만들면 되지 않냐'' 이렇게 하시는데 아닙니다.  그래서 이 연구원이 제대로 세계적인 수준의 연구원이 되려면 개인들이 참여를 해야 됩니다, 기업가가.  기업가가 1억원을 준다든지 2억원을 준다든지 해서 기부를 받아가지고, 기부금낸 것은 세제혜택이 되어야 됩니다.  그렇지 않으면 누가 기부를 합니까?  세제 공제가 안 되는데.  같은 기부를 해도 세제혜택을 받는 데는 그것이 명예도 되고 자기네들 실질소득이 되기 때문에 내줍니다.  그런데 우리나라 세법이 그게 안 되어 있습니다.  그래서 이번에 시정연구원의 육성법을 제정하겠다는 근본 취지가 그것입니다.  독립하기 위해서.  법에 근거가 안 되어 있기 때문에.  삼성도 1억원을 주고 싶은데 주어봤자 소용없는 것입니다.  자기네들 세제혜택도 못 받고 명예도 없고 아무 것도 안 돼요.  왜, 이 기관이 조례에 의해서 되는 거니까.  그래서 법에 의해서 세제혜택을 받을 수 없고 또 연구하는 분들 신분보장이 안 되어 있어요, 조례에 의하니까.  대학을 간다해도 서로 교류해야 되는데 이것이 전부 지식산업 아닙니까?  대학하고 연구하고 다 교류해야 되는데 여기서 연구하는 것은 대학에서 50% 밖에 안 봐준다.  그러면 어떻게 여기서 연구하는 것이 대학하고 산ㆍ학연구가 이루어집니까?  그런 근본적인 근거법이 없기 때문에 ''아 이거 안 되겠다'', 부랴부랴 근거법을 만들고 있는데 그런 것이 된 후에는 어떻게 되느냐면 저희가 기부도 우선, 경기도의 자원이 많지 않습니까?  기업들이 돈 주고 싶다는 사람이 있어요.  지금 저희가 3억원을 계약했는데 주택공사, 토지공사 저희들에게 연구해 달라고 3억원 갔다 줬어요.  제가 안 한다고 그랬어요.  사인 안 하고 북북 그어버린 적이 있는데 ''너희 30억원 내놓아라'' 그랬어요.  ''너희 그 동안 돈 많이 벌었으니까 연구비용을 좀 내라, 사회에 환원해야 될 것 아니냐'' 안 한다고 그어 버렸어요, 처음에.  그랬더니 해 달라고 그래서 나중에 제가 심하지 않느냐 초창기에 시작하는 건데.  ''좋다 우리는 거기서 반만 쓰겠으니 반은 면제해 주마'' 3억원 돈 가지고 와서 연구해 주고 있습니다.  왜 그런고 하니 돈을 줘서 연구해도 자기네들 혜택이 없어요.  제도적으로 잘못된 것이 아니냐, 외국기관에는 자기가 돈주면 그것이 세제혜택도 받고 명예도 되고 그래서 좋은데 그 제도를 바꾸고, 그 다음에 안 된 경우에 또 독립하는 방법이 뭐냐, 경기도예산을 쭉 보면 8,000억원 정도가 외주로 나갑니다.  그러면 외주나가는 것 경기개발연구원에 한 번 거쳐 나가게만 해주어도 거기서 이자만 받아도 얼마입니까, 이게 8,000억원인데.  그래서 그것까지 생각하고 있으니까 독립해야 된다는 것이고 보조금받은 것 달갑지 않습니다.  그래서 어떤 방법으로든지 저희가 독립해야 되니까 50명의 연구원이 있어야 되고 600억원, 700억원 얼마가 될지 연구분량에 따라 달라질 것으로 생각이 됩니다.  기본방침은 그렇게 가지고 있습니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 정 위원님!  다 되셨습니까?
</p>
<p><b>○ 정운천 위원 </b> 제가 궁금해서 그렇습니다.  수도권정책관련 추진실적 아까 슬라이드를 봤는데 그 과정에서 보면 이해가 안 가는 부분이 하나 있었습니다.  규제개선으로 수도권 비중을 약화시키고 영호남 및 지역개발을 촉진시킨다는 부분인데 규제를 개선하게 되면 아무래도 규제가 많이 없어지니까 수도권이 오히려 비대화되지 않겠느냐 하는 게 일반적인 생각이고 지금 수도권 정비계획법 개정하는 과정에서도 타 시ㆍ도에서 상당히 반대하는 이유 중의 하나가 그것이라고 생각되는데 슬라이드 내용에 보면 규제개선으로 수도권 비중을 약화시키고 영호남 지역의 개발을 촉진시킨다는 부분이 이해가 안 가기 때문에 그 부분에 대한 답변을 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 수도권 문제는 참 그렇습니다.  제가 수도권 문제를 다루는 게 20년이 더 됐죠.  문제를 해결하는 방법이 없는 것이 아닙니다.  방법은 30년동안 떠들었으면 됐죠.  방법이 없는 게 아니예요.  뭐가 문제냐, 이제 결심을 해주어야 됩니다.  지금 결심이 안 되고 있지 않습니까?  하향평준화, 평준화의 대표적인 예가 학교가 그렇게 되어 있잖아요.  학교라는 것이 그 사례는 똑같은데 이게 개발한다, 발전한다는 것이 뭡니까?  쉽게 말씀드리면 미국같은 나라에 가면 수종이 한 가지입니다.  비쭉 멋대가리 없이 커져 있죠.  왜, 토양이 비옥하니까.  수종이 다양할 수가 없어요.  한 가지 나무만 비쭉 올라갔어요, 한 가지만.  한국에는 어떠냐, 토질이 산성화되어 있어서 고생대 국가기 때문에 가장 생명력이 강한 나무만 지금 남아 있습니다.  그래서 숲이 우거져 큰 나무 작은 나무 섞여서 아주 균형이 잘 잡혀 있죠.  외국의 산하고 우리나라 산하고 다른 것이 그것입니다.  큰 놈은 크게 놔두고 작은 놈은 작게 놔두어서 발전하는 것이지, 큰 놈을 잡아서 왜 너 크냐, 그냥 잡아 내려가지고 똑같이 키를 만들겠다는 얘기인데.  학교가 그렇잖아요.  영재는 영재교육하라 그거예요.  미국도 사립학교 가서 잘 되고 영국도 마찬가지 사립학교에 능력있는 사람은 가라 그거예요.  그래야 경쟁이 되어서 발전하지.  시장경제원리, 자유경제원리가 뭡니까?  자유경제 기틀을 무너뜨리겠다고 지금 정치논리에 의해서 되고 있는 것이 국가죠.  경쟁력이 25위에서 38위로 떨어졌잖아요.  왜 떨어졌어요?  수도권 자꾸 죽이려고 그러니까, 있는 데 것은 잘 하게 북돋아 주어서 잘 하고, 단, 문제는 이것이 확산되는 기간이 있어요.  여적효과란 말이죠.  그게 무슨 얘기냐 하면 만약 연못이 있는데 돌을 던지면 파도가 끝까지 가지 않습니까?  똑같아요, 경제 논리는.  이 논리는 왜 모르느냐 그거예요.  여기가 커져야 그것이 퍼져서  파급 효과가 가는 거지.  지난 번에 대통령 오셨을 때 제가 그 말씀이에요.  397조원을 투자해서 30년간 1만불이 되었습니다.  지금 세계적으로 38위 제일 꼴찌예요.  왜 이렇게 됐느냐 이거예요.  그래서 이것을 어떻게든지 끌어올리려면 잘 되는 데를 자꾸 북돋워서 잘 되게 만드는 것이 빠르지.  그래서 수도권에는 21조원 투자해서 국세가 얼마 걷혔느냐 하면 28조원이 걷혔어요.  그럼 벌써 7조원 벌었다는 것 아닙니까?  국가 경영이 이것이지.  비수도권은 얼마냐.  36조원 투자했다 그거예요.  세금 얼마 걷혔느냐.  16조원 걷혔어요.  대통령이 아직도 기억하고 계시더라고요.  그 논리는 맞거든요.  그런데 왜 이걸 탈피 못하느냐 이거예요.  수도권이 발전해야 여적효과가 생겨서 자꾸 발전을 하지, 그럼 전라도에 갖다가 전부 만들어서 어느 하세월에 국제경쟁력에 이길 거예요.  제주도에다 언제 갖다가 투자해서 언제 할 거예요.  이건 조금 부처이기주의라도, 그럼 국가 경영하는 사람이 이것을 잡아줘야지 국가경영의 논리가 맞지 않는다 이거예요.  그래서 그걸 인식하고 있는데 이게 표 때문에 그런 겁니다, 표.  여기서 말씀드릴 것은 아니지만 이래서는 안 되겠다는 얘기예요, 이래서는.  
</p>
<p><b>○ 정운천 위원 </b> 알겠습니다.  그럼 아까 그 얘기는 장기적으로 그렇다는 말씀이시죠?  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 아니죠.  과거 30년 동안 해 온 걸 분석한 결과예요.  그러니까 앞으로도 마찬가지죠.  그 논리는 죽일 수 없어요.  세계 어느 나라라도 다 마찬가지입니다. 
</p>
<p><b>○ 정운천 위원 </b> 알겠습니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 되셨습니까, 정운천 위원님?  이진용 위원님 오전에 의회운영위원회에서 의회사무처 감사가 있었기 때문에 질의를 못하셨거든요.  그래서 보충질의 있으시면 해 주시기 바랍니다. 
</p>
<p><b>○ 이진용 위원 </b> 위원장님께서 제게 질의 기회를 주셔서 고맙습니다.  시간도 오래 됐고, 또 여러 위원님들께서 질의를 차근차근 많이 해 주셨기 때문에 중복되는 질의를 피해가면서 몇 가지 질의를 드리겠습니다.
</p>
<p style="padding-left:1.2em">  연구원의 설립목적이라고 하면 아마 경기도에서 주민이 행복하게 살 수 있는 그런 장기적인 비전을 만들어내는 것이라고 생각됩니다.  그런 것들은 가깝게는 규제도 해소해야 되고 효율적인 개발 전략도 제시를 해야 될 것입니다.  그런데 이러한 것들이 바로 우리 경기개발연구원의 연구결과가 지적인 기반이 되어야 가능하지 않나 이런 생각이 듭니다.  그래서 근간에 규제 해소나 효율적인 개발 전략의 연구 결과가 상당히 고무적이라고 생각이 돼서 치하를 드리면서 몇 가지 질의를 드리겠습니다.
</p>
<p style="padding-left:1.2em">  여기서 자체적으로 기금관리위원회를 운영하고 계시죠?  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 네.
</p>
<p><b>○ 이진용 위원 </b> 위원장은 어느 분이 맡고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그건 원장이 맡고 있습니다.
</p>
<p><b>○ 이진용 위원 </b> 위원장은 원장님이 맡고 계시고요.  그 다음에 위원 구성은 몇 분이나 됩니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 다섯 사람입니다. 
</p>
<p><b>○ 이진용 위원 </b> 관련된 분야를 전공하시는 분이 구성돼 있습니까?
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그리고 금융 관계……. 
</p>
<p><b>○ 이진용 위원 </b> 조금 전에도 말씀드렸지만 상당히 열심히 연구하고 계시는데 돈까지 관리를 하시느라고 어려움이 많으실 것 같아서 돈에 대한 관리는 별도로 전문가들을 책임있는 그런 분들을 직원 가운데서 선정을 하셔 가지고 맡기시는 게 어떤가 생각이 됩니다. 
</p>
<p style="padding-left:1.2em">  지난 7, 8월에 작년에 예산 결산에 대해서 검사를 하면서 도교육청에 대한 결산검사 기간 중에 도교육청이 상당히 효율적이고 합리적으로 돈을 운용하는 걸 봤습니다. 그게 여러 사람이 관여해서 하는 것이 아니고 한 사람이 기금관리를 잘 해 가지고, 예산 관리를 잘 해 가지고 상당히 모범적인 사례로, 전국 교육청 가운데서도 우수한 사례로 지금 남아 있습니다.  그래서 돈 관리를 연구와 같이 병행한다는 게 어떻게 보면 형식에 치우칠 수도 있다 이런 생각이 들어 가지고 고려가 돼야 되지 않겠나 이런 생각이 드는데 생각해 보신 바가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 마침 잘 하셨습니다.  제가 와보니까 사무처라고 있었어요.  사무처에 사무과라고 기구를 개편했습니다.  이름 자체도 행정지원실, 지금 실장님이 여기 뒤에 계시지만.  그리고 나서 보니까 총무과 하나밖에 없습니다.  그래서 행정실이 행정과도 되는데 재정을 같이 취급하고 있더라고요.  그런데 재정은 독립해야 된다.  그래서 이번에 재정과를 별도로 만들었습니다.  팀을 재정만 별도로다루게, 지적을 잘 해 주셨는데 기구를 보니까 그렇게 잘못돼 가지고 재정과를 별도로 독립해서 전문가가 일을 할 수 있도록 전담하게 만들었습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그렇게 해서 기금관리에 대해서는 별도로 운용하는 것이 좋지 않겠나 해서 말씀드렸습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 연구 과제와 관련해서 몇 가지 질의드리겠습니다.  친환경적 도시개발 및 정비정책 추진방향에 대해서 연구도 여러 차례 있었고 워크숍도 있었던 걸로 자료에 나와 있는데 그 가운데 친환경적인 산지 개발을 통해서 지방자치단체의 재정력을 제고할 수 있는 방안에 대한 유사한 연구 사례가 있었는지.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 캐나다에서 온 목조건물이 코리아CC에 가보시면 있는데 거기에 제가 아이디어를 줘서 하고 있습니다.  그래서 수익사업으로 될 수 있게 산지 개발을 해서 앞으로 산지가 65%기 때문에 수익성이 있는 사업으로 자연친화적인 태양열을 이용하고 자연수를 이용해서 그런 걸 하려고 지금 계획을 시범적으로 하고 있습니다. 
</p>
<p><b>○ 이진용 위원 </b> 우리 경기도가 전체적으로 65% 정도가 산으로 돼 있고 특히 재정력이 약한 그런 시ㆍ군일수록 대부분 산지가 많은 지역입니다.  그래서 지금 이를테면 개발이 제한돼 있던 지역이 가능한 지역으로 풀리게 되면 상당히 무분별한 개발이 일어납니다.  그래서 산지 개발에 대한 합리적인 모형을 도출할 필요가 있지 않겠나 싶고요.  그런 걸 통해서 이왕이면 적극적으로 그런 지역의 재정력을 증대시킬 수 있는 방안까지 함께 고려돼야 되지 않겠나 생각이 됩니다.  그래서 그런 데에는 용역을 주고 싶어도 인력이 정말 아쉬워서 인력을 못주니까 경기개발연구원에서 자체적으로 과제를 발굴해서 연구를 해서 지원해 줄 필요가 있지 않겠나 하는 생각이 듭니다.  어떻게 적극적으로 고려 좀 해 주시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그건 벌써 이미 몇 군데를 했고, 지금 진행 중에 있습니다.  어디인고 하니 양평 가다 보면 양수리 있지 않습니까?  양수리에 환경친화적인 마을을 저희가 조성하고 있고, 지금 이진용 위원님께서 조금 지각을 하셨는데요.  아까 샘플을 여기 화면으로 저희가 보여 드렸는데 그걸 못보셨거든요.  그걸 언제 보시고 싶으면 저희가 보여드릴 테니까, 그래서 환경친화적인 구체적 사례까지 저희 경기도에서 이렇게 가야 된다 그래서 샘플을 화면으로 보여드렸습니다. 
</p>
<p><b>○ 이진용 위원 </b> 환경친화적인 개발 뿐만 아니라 특히 제가 말씀드리는 요지는 그런 개발 속에서 재정력이 약한 시ㆍ군의 재정력 증대에 보탬이 될 수 있는 방향으로 연구가 돼야 되지 않겠나 생각됩니다.  
</p>
<p style="padding-left:1.2em">  저희 위원님들께서 그 자료를 보셨으니까 저한테 도움이 될 만한 자료들이 있었습니까?  그럼 우리 위원님들한테 돌아가서 듣기로 하고 다음 질의드리겠습니다.  중앙정부의 정책에 따라서 그린벨트가 많이 해제될 텐데 그린벨트 해제에 따른 대책에 대해서 연구한 결과가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것도 아까 화면에서 아주 소상하게 대외비가 있었는데 기자들까지 쫓아내고 보여드렸습니다.  이 위원님께서 조금 일찍 오셔서 중요한 걸 보셨어야 되는데.
</p>
<p><b>○ 이진용 위원 </b> 죄송합니다.  다음 질의드리겠습니다.  지금 관광자원이 제3의 산업이라고 해서 여러 지역에서 저희들이 언뜻 보기에는 과연 그 지역에 관광산업을 저렇게 집중적으로 육성할 필요가 있나, 도비가 지원될 필요가 있나 이런 지역까지도 관광개발에 열을 올리고 있습니다.  좀 지역실정에 맞는, 또 특화된 이런 관광개발이 돼야 될 것이라고 생각되는데 지역특성에 맞는 특화된 관광개발에 대한 연구 결과가 있었습니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 현재 저희들이 49개 지역을 연구하고 있습니다.  그래서 지역특성과 자원을 조사하고 있습니다.  지역의 자원이 도대체 뭐냐.  절이 있다면 절, 약수터가 있다면 약수터, 또 옛날에 고인돌이 있다면 고인돌, 역사적인 문화자원을 기초로 해서 개발의 기준을 만들어야 되기 때문에 도에 있는 전체 시ㆍ군의 관광지도를 지금 만들고 있습니다.  그리고 나서 그 기준이 나갈 겁니다. 내년에는 아마 이 위원님께서 보실 텐데.
</p>
<p><b>○ 이진용 위원 </b> 기대가 됩니다.  그 다음에 원장님께서 꾸준히 주장해 오셨던 식수원 전용댐에 대해서 잠깐 질의를 드리겠습니다.  현재 상당히 오랫 동안 주장을 해 오셨는데 정책적으로 받아들여지지 않고 있는 원인이 뭐라고 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것도 역시 아까 말씀드린 대로 표 때문입니다, 표.  그래서 지금 대통령께서 다시 물러서셨어요.  왜 물러선고 하니 전문가의 얘기를 들어보니까 아니거든요.  환경단체의 얘기만 들으신 겁니다.  그래서 식수전용댐을 처음에는 저희들이 주장했는데 환경부에서 저희들하고 안 하는데 너희가 왜 하느냐 그런 감정 때문에 안 한 것이지, 환경부도 지금 환경평가원이라고 그래서 저희들이 가지고 있는 연구원에다가 돈을 주고 그것 다시 좀 연구해 봐라 그래서 다시 돌아왔습니다.
</p>
<p style="padding-left:1.2em">  그것은 왜 그런고 하니 물리적으로 팔당댐의 오니층이 4m, 지금 23m까지 올라갔습니다.  고기 썩은 것, 조개 썩은 것, 퇴적물 그게 썩어서 더 물이 담아질 수가 없어요.  그리고 또 오염이 되기 때문에.  그래서 18조원을 투자를 했는데 18조원을 투자해서 ppm을 하나로 올린다고 그러는데 거기다가 100조원을 쏟아 보세요.  저는 안 된다고 봅니다.  이제 그것이 판단이 됐기 때문에 다시 식수전용댐이 아니라 소규모댐으로 바뀌었습니다.  저는 식수전용댐이라고 그랬는데 소규모댐으로 바뀌어서 도에서는 도대로 연구를 할 겁니다. 
</p>
<p><b>○ 이진용 위원 </b> 그런데 조금 전에 전체적인 답변을 하시면서 합리적이지 못한 그런 결정들에 대해서 시장원리에 의해서 결정이 되는 쪽으로 돌아가야 된다 이런 의지를 말씀하셨는데 시장원리라는 것은 합리적인 결정만 시장원리가 아니고 다소 불합리하더라도 수요자들의 입장에서 원하는 방향이 바로 시장원리가 아닌가 이런 생각이 듭니다.  그래서 물론 물을 수요로 하는 사람들은 상수원 지역 주민들만은 아니지만 식수전용댐 ,이를 테면 예정지역이라고 제가 표현하겠습니다.  그런 지역에서 이런 말만 나오면 그걸로 인한 새로운 규제가 우려되기 때문에 아직 적극적으로 반대를 하고 있습니다.  그건 원장님께서도 이미 들으셨을 겁니다.  그래서 지난 번에도 제가 그런 말씀을 드렸지만 중앙정부에서도 이런 정책을 받아들인다면, 이걸 받아들여서 무리하게 시행을 하려고 하지 말고 이렇게 기피하는 시설을 받아들이는 지역에는 그것 이상으로 가는 혜택이 주어진다면 그 사람들이 오히려 유치하려고 들 겁니다.  식수전용댐유치위원회가 가평에서 만들어졌다, 얼마나 정책적으로 고무적인 일입니까?  
</p>
<p style="padding-left:1.2em">  그래서 지금 원장님께서 그 동안 식수전용댐의 필요성에 대해서는 충분히 연구를 하셨기 때문에 그 다음에는 실천 가능한 계획이 뭔가.  지역주민들의 의사가 반영된 실천계획의 수립이 또 그 다음에 중요하다고 생각됩니다.  그래서 그 동안 원장님께서 실천계획이 뭔가 또 고민을 해 오셨을 것 같습니다.  말씀 듣고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그래서 아까 서두서부터 제가 유기체라는 말씀을 드렸는데 바로 그게 실천 가능한 계획입니다.  그래서 계획이 종이로 된 계획으로 해서는 100% 해도 소용이 없고, 그것이 주민의 피부에 닿는 시행을 했을 때 현실성있는 계획을 해야 되는데 현장의 감이 없어 가지고 탁상에서 계획했기 때문에 그런 문제가 나왔던 겁니다. 
</p>
<p style="padding-left:1.2em">  그래서 지난 번에 6개 지역의 식수전용댐 관계는 엔지니어회사를 동원해서 현장조사를 다 했었습니다.  그런데 현장만 조사한 것인지 입문조사, 거기에 살고 있는 분들의 의견이나 이런 것을 조사 안 했어요.  거기까지 가려면 시간이 걸리거든요.  그 단계가 아니기 때문에 하나의 구상안이였었거든요.  구상안으로 끝났었기 때문에 그안이 간다는 얘기를 하지 않았어요, 계획이니까.  그것이 어느 정도 구상이 확정됐을 때 입문조사를 또 해야 돼요.  그 지역의 주민은 어떻고 B/C분석을 해 봐서 손비가 어떻게 되는지, 편익과 비용이 어떻게 되는지, 그 지역을 개발하는 것이기 때문에.  그래서 그와 같은 조사가 안 끝났기 때문에 지금 어느 지역에 몇 개를 한다는 건 구상이요, 전문가가 조사한 결과지 그 지역이라고 지금 확정된 것도 아니기 때문에 거기까지 가려면 아직 시간이 남아있다고 봅니다. 
</p>
<p><b>○ 이진용 위원 </b> 제가 우려해 온 바가 사실 해소가 안 됐습니다.  원장님 말씀은 그 전에 그 동안 몇 차례 그런 말씀을 할 기회가 있었지만 과거나 지금이나 그 점에 대해서 진전이 없습니다. 
</p>
<p style="padding-left:1.2em">  제가 드리는 말씀은 그런 정부나 도의 정책이 어느 특정지역의 주민들에게 그 동안 불신을 많이 쌓아 왔습니다.  이제는 정책이 발표되면서 그런 불신에 대한 우려까지도 같이 해소시키면서 추진이 돼야지 이게 가능하죠.  그렇지 않으면 그것 때문에 합리적이고 꼭 필요한 정책이 좌절되고 포기되는 일이 발생되고 있습니다, 현재도.  그래서 지금 말씀이 아직은 실천 가능한 세부적인 계획에 대해서는 생각해 보시지 않으셨다고 하니까 바로 입문분야에 대해서도 충분한 고려가 돼서 다음에 식수전용댐이든 소규모댐이든 정책이 발표될 때 주민들에게는 ''아!  저 정책이 발표되니까 우리 지역에는 이렇게 좋아지는구나'' 이런 생각이 들어야 된다고 생각을 합니다, 다른 정책들도 마찬가지고.  우리 경기개발연구원에서 앞으로 정책을 개발하는데 합리적인 의사 결정과 함께 지역주민의 민원이 반영된 정책대안이 제시가 돼야 되지 않겠나 이런 생각이 듭니다.  
</p>
<p style="padding-left:1.2em">  아울러 본 위원도 합리적인 부분으로만 정책들이 결정된다면 좋겠습니다.  그러나 현실적으로 그렇지 않습니다.  이게 우리들이 살아가는 모습들 아닙니까?  그래서 그런 부분을 연구하시는 분들이 현실을 고려한 연구가 됐으면 좋겠다 이런 당부를 드리면서 질의를 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 고맙습니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 이진용 위원 수고하셨습니다.  시간이 많이 지났는데 잠깐 한 가지만 질의라기보다는 의뢰를 부탁드립니다.
</p>
<p style="padding-left:1.2em">  정책연구과제에 보면 강화발전 마스터플랜 연구가 올 1월 20일부터 2월 27일까지 결정이 됐거든요.  강화하고 검단 환원 관련해서 아마 연구과제가 결정된 것 같은데, 강화 연구에 대한 과제는 있는데 검단에 대한 연구과제는 거의 없는 걸로 알고 있습니다. 
</p>
<p style="padding-left:1.2em">  사실 김포시가 ''95년도 인천광역시로 편입될 때 상당히 김포시가 기형적으로 돼 있거든요, 지정학적으로.  그래서 내년부터 수자원공사하고 현대건설 몇 개 민간기업체가 컨소시엄을 결정해서 경인운하 공사를 시작하는데 그것과 관련돼서 환원추진위원회에서 만약에 단기적으로 아마 강화뿐만 아니라 같이 공동으로 묶어서 어떤 할 수 있는 마스터플랜계획을 의뢰하면 하실 계획이 있으신지에 대해서 답변을 부탁드립니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 강화ㆍ김포검단추진위원회에 제가 운영위원으로 들어가 있습니다.  구체적인 연구 방향은 아직 안 나왔고 사실 이게 늦었습니다.  운영위원회 때 지적을 했습니다만 운영위원회에서 할 일이 지금 종이위에 그림 그리는 것이 중요한 것이 아니다 그 말씀을 드렸어요.  무슨 얘기인지 위원님들이 놀라셨는데, 그때 계셨죠?
</p>
<p><b>○ 위원장대리 유영록 </b> 네, 있었습니다.  
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 지방자치법을 고쳐야 됩니다.  왜 지방자치법을 고쳐야 되는고 하니 주민투표제도가 안 돼 있어요.  지방자치법에 주민투표를 해서 행정구역을 바꾸는데 제도적으로 장치가 돼야지 지금 종이짝만 그려 놓고 좋은 플랜을 만들어 놔도 현실적으로 법에 근거가 없기 때문에 어렵다고 그래서 이걸 먼저 해야 된다고 우선순위를 주장한 것이 바로 그겁니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 저희도 위원회에서 잘 들었는데요.  사실 지역주민들은 도에서 계획 자체가 없지 않으니까 어차피 제도적으로 주민투표법이 국회를 통과해서 하게 될 경우와 또 주민들이 그런 것에 대비해서 적어도 경기도로 다시 재환원되면 어떤 계획이 있는지를 굉장히 지역주민들은 알고 싶어하더라고요.  그래서 아울러 지금 원장님께서 지적하신 국회에서 지방자치법의 개정, 또 주민투표법의 제정 이런 것도 시급하고 또 홍보 전략의 일환으로써 그것도 아마 추진위원회에서 의뢰되지 않으면 안 되겠다는 생각이 개인적으로 듭니다.  그래서 동시에 아마 돼야 되지 않을까 그런 생각이 드는데 종이짝으로 그린다기보다는 미래에 대한 어떤 청사진이라고 그럴지 비전들을 갖고 있어야만 그 지역주민들이 주민투표법이 제정되면 아마 다시 환원될 수 있는 어떤 홍보가 되지 않나 해서 말씀드렸습니다. 
</p>
<p><b>○ 경기개발연구원장 노춘희 </b> 그것은 계획하는 사람의 입장에서 이미 됐어야 되는데 그게 안 나왔고, 그러다보니까 최기선 시장은 5억원을 국토연구원에 갖다 줬는데 나온 것 봐봤자 별 것 아닌데 경기도에서 김포 검단하고 강화의 계획안을 저희들이 만들어 놓은 게 지금 없지만 그것은 투자비가 1,750억원인가 뽑아보니까 대개 그래요.  투자비가 따르고 그런 계산이 나오더라고요.  그러나 주민들에게 홍보용으로 할 수 있다는 것은 지금 늦었지만 빨리 해야 되지 않느냐 그런 생각은 듭니다.  그래서 운영위원회에서 한번 논의가 되고 그에 관한 얘기가 없었기 때문에 이 다음에 운영위원회를 빨리 소집해 가지고 지금 할 수 있는 것은 빨리 해야 된다고 봅니다.  저도 동감입니다. 
</p>
<p><b>○ 위원장대리 유영록 </b> 알겠습니다.  더 이상 질의하실 위원이 안 계시므로 이상으로 경기개발연구원에 대한 질의와 답변을 모두 마치도록 하겠습니다.  토요일 오후 늦게까지 위원 여러분께서 장시간 열의를 갖고 감사에 임해 주신 데 대해 감사의 말씀을 드립니다.  그리고 노춘희 연구원장님을 비롯해서 연구원 관계자 여러분께서도 행정사무감사를 위해 자료 준비와 위원님들의 질의에 성실히 답변해 주신 데 대해서 감사를 드립니다.  오늘 여러 위원님들께서 감사시 지적해 주신 사항은 도민의 뜻이니만큼 이를 겸허하게 받아들여서 연구원 업무수행에 적극 반영하도록 최선의 노력을 다해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그러면 이상으로 경기개발연구원에 대한 1999년도 행정사무감사 종료를 선언합니다. 
</p>
<p class=''ar''>(16시27분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원
</b></p>
<p class=''aMan''>고수복연동현이남형이진용정운천유영록홍영기</p>
<p><b>○ 행정사무감사보조공무원
</b></p>
<p><p class=''em15''>전문위원 오태철지방행정주사 이용인지방행정주사보 박상선</p>
<p><p class=''em15''>지방기능7급 임숙영지방기능8급 이춘영지방기능9급 김정원</p>
<p><b>○ 출석증인
</b></p>
<p><p class=''em05''>ㆍ경기개발연구원</p>
<p><p class=''em15''>원장 노춘희행정실장 심무섭</p>
