            <p class="skip">맨위로 이동</p>

            <div','경기도의회',false,'{"legacy_id": "audit-4701", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4701"}'::jsonb,'1999-11-27'::date,'1999-11-27'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-4701');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[1998.11.26. 목요일] 경기개발연구원, 경기지방공사 — 기획위원회 1998년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제5대 경기도의회 기획위원회</b> · 1998년도 행정사무감사(1998. 11. 21. ~ 1998. 11. 30.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=4757" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>1998년도 행정사무감사
</p>
<h4>기획위원회 회의록 
</h4>제5호
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원, 경기지방공사
</p>
<p><hr /></p>
<p>일  시 : 1998년 11월 26일(목)
</p>
<p>장  소 : 경기개발연구원회의실, 경기지방공사회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시35분 감사개시) 
</p>
<p><b>○ 위원장 고수복 </b> 좌석을 정돈해 주시기 바랍니다.  지금부터 지방자치법제36조, 동법시행령제16조와 경기도의회행정사무감사및조사에관한조례에 의하여 경기개발연구원에 대한 1998년도 행정사무감사 실시를 선언합니다.
</p>
<p style="padding-left:1.2em">  안녕하십니까?  기획위원장 고수복 위원입니다.  오늘은 기획위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행부의 행정사무 전반에 관한 실태를 파악하여 지방의회 의정활동과 ''99년도 예산안 심사시 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 연구원 원장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.  감사위원 여러분께서도 연일 계속되는 감사일정으로 노고가 많으십니다만 도민을 대표하여 도비 출연기관인 경기개발연구원의 운영실태를 감사하는 것이니 만큼 각 부분별로 세밀하게 검토하시어 소기의 성과를 거둘 수 있기를 당부드리면서 원활한 감사진행을 위하여 많은 협조 있으시기를 바랍니다.  끝으로 행정사무감사 준비를 위하여 애쓰신 연구원 관계직원 여러분께 감사드리며 간단히 인사에 갈음합니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기개발연구원장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 되므로 먼저 선서를 하셔야 하며 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1998년도행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 할 때에는 지방자치법제36조제5항과 경기도의회행정사무감사및조사에관한조례제30조의 규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 동법동조항규정에 의하여 500만원 이하의 과태료를 부과할 수 있음을 알려드립니다.  그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (기  립)
</p>
<p style="padding-left:1.2em">  먼저 증인출석 여부를 확인하겠습니다.  경기개발연구원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 사무처장 나왔습니까? 
</p>
<p><b>○ 사무처장 표찬섭 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 총괄기획연구부장 나왔습니까? 
</p>
<p><b>○ 총괄기획연구부장 신원득 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 생활환경연구부장 나왔습니까? 
</p>
<p><b>○ 생활환경연구부장 이정임 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 산업경제연구부장 나오셨습니까? 
</p>
<p><b>○ 산업경제연구부장 이상훈 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 도시 지역계획연구부장 나오셨습니까? 
</p>
<p><b>○ 도시 지역계획연구부장 </b>이외희  네.
</p>
<p><b>○ 위원장 고수복 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 조응래 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 국제경제연구부장 나왔습니까? 
</p>
<p><b>○ 국제경제연구부장 이기영 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 수질환경연구소장 나왔습니까? 
</p>
<p><b>○ 수질환경연구소장 성현찬 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 다음은 선서요령을 설명드리겠습니다.  선서는 증인을 대표해서 연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인께서는 오른손만 들어 주시면 되겠습니다.  그러면 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 선서!  본인은 경기도의회가 지방자치법제36조, 동법시행령제16조제1항, 경기도의회행정사무감사및조사에관한조례제2조의 규정에 의하여 소관업무에 대한 1998년도행정사무감사를 실시함에 있어서 기관장으로서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법시행령제17조의4제5항과 경기도의회행정사무감사및조사에관한조례제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.
</p>
<p class=''ar''>1998년 11월 26일.
</p>
<p class=''ar''>증인 경기개발연구원장 유훈, 사무처장 표찬섭, 총괄기획연구부장 신원득, 생활환경연구부장 이정임
</p>
<p class=''ar''>산업경제연구부장 이상훈, 도시 지역계획연구부장 이외희, 교통정책연구부장 조응래
</p>
<p class=''ar''>국제경제연구부장 이기영, 수질환경연구소장 성현찬
</p>
<p><b>○ 위원장 고수복 </b> 자리에 앉아 주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (착   석)
</p>
<p style="padding-left:1.2em">  다음은 경기개발연구원장께서 나오셔서 인사와 함께 간부를 소개해 주시고 업무보고를 해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 연일 사무감사를 위해서 수고하시는 위원님들께 먼저 감사의 말씀을 드립니다.  산하기관 중에서 저희 경기개발연구원을 제일 먼저 찾아 주신 데 대해서 사의를 표합니다.  저희는 이 기회에 금년에 얼마나 열심히 연구했는가를 말씀드리고 내년에는 어떠한 계획을 가지고 연구하겠다는 것을 설명드리는 기회로 삼겠습니다.  아무쪼록 부족한 점이 있더라도 너그러이 이끌어 주실 것을 앙망하면서 간단히 인사를 마치겠습니다.  그러면 다음에 저희 간부들을 소개를 드리겠습니다.  먼저 사무처장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  다음에 총괄기획연구부장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  생활환경연구부장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  산업경제연구부장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  도시 지역계획연구부장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  교통정책연구부장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  국제경제연구부장.
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  그리고 수질환경연구소장입니다. 
</p>
<p style="padding-left:2.4em">    (인    사)
</p>
<p style="padding-left:1.2em">  다음에는 업무보고를 드리겠습니다.  말씀드릴 순서는 제가 먼저 연구사업에 관한 업무보고를 드리고 이어서 사무처장이 일반현황과 재정운영에 관해서 말씀을 드리도록 하겠습니다.  먼저 8페이지부터 시작하겠습니다.  ''98년도 연구사업 추진상황을 간단히 말씀드리겠습니다.  금년도 연구사업의 중점방향은 대체로 네 가지로 잡았습니다.  첫째는 수도권 관련규제 완화를 위한 경기도 논리의 개발과 둘째는 경제위기 극복을 위한 경기도 역할의 성공적 수행의 뒷받침, 셋째는 수질문제 등 환경보전과 삶의 질 향상을 위한 방안의 제시, 그리고 넷째는 교통환경 개선을 위한 구체적 방안의 제시 등입니다.  이것을 위해서 자체연구사업으로서는 경기도와 경기도의회로부터 추천을 받은 과제를 중심으로 광역자치단체 정책평가시스템 개발 등 25건의 자체과제를 선정해서 10건은 이미 완료해서 보고서가 나왔습니다.  그리고 15건은 현재 연구가 진행중에 있습니다.  그 다음에 도 및 시 군으로부터 의뢰받은 수탁과제 18건 중 경기도 교통종합기본계획 수립 등 6건은 완료하였고 12건은 현재 진행중에 있습니다.  그 밖에 IMF 극복을 위한 경기도의 대응과제를 비롯한 정책세미나를 여러 번 개최했고 이천시를 비롯한 지역연구 2건과 6회의 학술연구지 발간을 해서 배포를 했습니다.  그리고 민선2기 출범에 부응하는 도정의 혁신적 정책개발 지원과 새로운 행정수요에 능동적으로 대처하는 연구원으로서의 위상을 정립해 가고 있습니다. 
</p>
<p style="padding-left:1.2em">  9페이지 이하는 자체 연구과제를 간단히 소개한 것입니다.  지난 번 업무보고 때 이미 말씀을 드렸기 때문에 구체적인 것은 생략하겠습니다.  다음에 12페이지로 넘어가겠습니다.  기타 연구사업에 대해서 말씀을 드리겠습니다.  저희가 단기정책지원과제를 많이 수행하고 있습니다.  거기에는 현재 6개 과제로 나와 있습니다만 최근에 업무보고 인쇄가 끝난 다음에 1건이 추가돼서 현재 7개 과제를 이미 완료하였거나 추진중에 있습니다.  첫째는 ''99년도 경기도정계획 수립입니다.  이것은 저희가 과거에 완료한 제1차경기발전5개년계획에 입각해서 내년도 경기도의 도정계획을 수립했습니다.  이것은 정책포럼으로 인쇄를 해서 아마 위원님들에게 현재 배포해 드린 책자 속에 들어 있을 것으로 압니다.  두 번째는 팔당상수원 1급수를 위한 대책방안입니다.  7월 1일부터 7월 30일까지 연구를 수행했습니다만 그 후에도 수차에 걸쳐서 수정했습니다.  이번에 정부가 팔당상수원 수질개선방안을 발표했습니다마는 경기도 안은 저희가 주로 연구를 했습니다.  그 다음에 세 번째는 국민공원묘지 조성방안 검토입니다.  이것은 저희가 연구를 해서 국민공원묘지 조성은 바람직하지 않다는 결론을 내려서 도에 제출했습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 네 번째는 도립대학 설치안 검토입니다.  이것은 위원님도 잘 아시는 바와 같이 경원대학을 도립대학으로 전환하는 것이 바람직하냐 하는 연구였습니다.  저희는 긍정적으로 평가해서 경원대학을 도립대학으로 하는 것이 바람직하다고 결론을 내려서 도에 제출했습니다만 경원대학이 도중에 철회를 했기 때문에 도립대학의 설립은 현재는 실현을 보지 못하고 있습니다.  그 다음에 다섯째는 지방세제 개편 및 지방교부세 확충방안입니다.  이것은 지금 경기도를 비롯한 각 시 도가 중앙정부와 협의해서 지방세제를 지방자치단체에 유리한 방향으로 개편하고 지방교부세의 교부율도 인상하고자 하는 교섭을 위해서 안을 마련한 것입니다.  그 다음에 여섯째는 경기도 북부지역 및 접경지역 실태조사 연구입니다.  내년도에 가서 저희가 본격적으로 북부지역과 접경지역에 관한 연구를 하겠습니다만 우선 금년도에 사전 예비연구를 하는 것입니다.  다음에 유인물에는 없습니다만 일곱째가 경기도 실업기금 조성 및 운영방안입니다.  이것은 12월 1일부터 12월 31일까지 연구를 완료하는 것으로 되어 있습니다.  이 단기정책 지원과제는 갑자기 도에서 저희들에게 요청해 오는 경우가 많습니다.  경우에 따라서는 일주일 내에 보고서를 내라 그런 요청도 있고 해서 저희가 단기정책지원과제 연구를 위해서 많은 노력과 시간을 바치고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음에는 세미나 및 강연회가 되겠습니다.  거기에는 여섯 번으로 돼 있습니다마는 최근에 또 하나가 추가돼서 일곱 번이 되겠습니다.  제1회는 3월 19일에 IMF 위기극복을 위한 경기도의 대응과제라는 세미나를 개최했고 제2회는 7월 15일에 제2기 민선도정의 과제와 역할이라는 주제로 세미나를 가졌습니다.  그리고 제3회는 9월 24일에 21세기 수도권정책의 대전환이라는 주제로 세미나를 가졌고 제4회는 ''99년도경기도예산편성방향이라는 정책토론회를 가진 바 있습니다.  그리고 제5회는 11월 19일에 애드윈 밀스라고 하는 세계적인 도시경제학의 권위자를 초청해서 강연회를 가진 바 있습니다.  그리고 거기에는 나와 있지 않습니다마는 11일 27일 개발제한구역 제도개선 공청회를 여성회관에서 개최할 예정으로 있습니다.  이것도 갑자기 저희 연구원에 지시가 떨어져서 이것을 주관하게 되었습니다.  다음에 일곱 번째는 12월 4일에 21세기를 향한 수도권 성장관리 정책이라는 주제로 정책세미나를 서울시정개발연구원, 인천발전연구원, 그리고 저희 연구원의 3개 연구원 공동으로 서울에서 개최할 예정으로 있습니다. 
</p>
<p style="padding-left:1.2em">  다음에 13페이지가 되겠습니다.  저희가 두 달에 한 번씩 경기21세기라고 하는 학술지를 발간하고 있습니다.  최근에 ''98년 11월/12월호를 경기도 외국인 투자유치 전략이라는 특집주제로 발간했습니다.  그 다음에 지역연구입니다.  이것은 1년에 두 번씩 발간하고 있습니다.  ''97년에 파주시하고 포천군을 연구했고 ''98년에 이천시와 김포시를 연구했습니다.  이 김포시에 관한 지역연구는 최근에 발간이 돼서 위원님들에게 배포해 드렸습니다.  지난 번에 저희 업무보고 때 말씀이 계셔서 금년에는 김포시에 관한 지역연구를 그냥 발간에만 그치지 않고 12월 10일에 김포현장에 가서 세미나 겸 출판기념회를 가질 예정으로 있습니다.  그래서 저희 지역연구의 발간을 축하도 하고 홍보하려고 생각하고 있습니다.  다음에는 경기연구입니다.  이건 1년에 한 번씩 발간하는 학술지가 되겠습니다. 
</p>
<p style="padding-left:1.2em">   14페이지가 되겠습니다.  앞에서 금년도에 저희가 연구한 것, 업적을 간단히 말씀드렸고 14페이지 이하는 내년도에 어떠한 계획을 가지고 연구사업을 추진하겠다고 하는 것을 말씀드리겠습니다.  먼저 기본방향은 연구결과의 실효성이 예상되는 정책과제를 선정하고 연구원 1인당 1과제 연구로 책임성 있는 연구를 수행하고 경기도 및 시 군에 필요한 수시정책과제 및 지역연구과제를 수행하고 과제수행과 병행한 세미나 개최 및 각종 전문연구지를 발간할 예정으로 있습니다.  거기 ''99년도 연구사업계획을 총괄하는 표가 나와 있습니다.  자체연구과제를 수행하고 그 다음에 수탁연구과제는 19가지 정도를 생각하고 있습니다.  그리고 지역연구는 금년까지는 1년에 두 번 발간했습니다마는 내년부터는 그전에 말씀드린 바와 같이 세 번, 3개 시 군을 선정해서 발간할 예정으로 있습니다.  이것은 각 시 군으로부터 요청이 많아서 이것을 소화하기 위해서 1년에 적어도 세 번은 해야 된다고 생각하고 있습니다.  그 다음에 수시과제 이것은 아까 말씀드린 도에서 갑자기 요청하는 정책지원과제가 되겠습니다.  저희는 10개 과제 정도를 생각하고 있는데 금년도의 추세로 미뤄봐서 10개 과제가 더 될는지 모르겠습니다.  정책세미나는 매번 개최할 계획으로 있습니다마는 아까 말씀드린 바와 같이 금년도에도 본래는 네 번 개최할 예정이었습니다마는 일곱 번이 됐습니다.  경기연구는 1년에 한 번 발간하고 그 다음에 과제연구보고서, 번역시리즈 이런 것은 매년 해 오던 것입니다.
</p>
<p style="padding-left:1.2em">  다음에 15페이지가 되겠습니다.  자체연구사업 추진계획을 간단히 말씀드리겠습니다.  먼저 경기도 각 실 국 및 경기도의회 의원님들에게 과제를 추천해 주십사하고 의뢰를 드렸습니다.  그래서 총 58개 과제를 추천받았습니다.  이 중에서 25개 과제를 우선 연구과제로 채택했습니다.  이 추천과제 58개 대비 25개를 반영해서 43%의 반영률을 나타내고 있습니다.  그리고 연구책임자 24명 전원 추천과제를 채택해서 100% 반영했습니다.  이게 무슨 말씀이냐면 금년도까지만 하더라도 저희가 자체개발하는 연구과제도 있었습니다마는 내년도에는 전적으로 도와 의회에서 추천하는 과제만을 채택하기로 했습니다.  그러더라도 저희가 추천받은 58개 과제를 다 소화하지 못하는 실정입니다.  거기 경기도와 경기도의회에서 추천한 과제에 대한 개략이 나와 있고 또 그것을 어떻게 소화하겠다는 것이 간단히 나와 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 16페이지 이하에는 대체로 내년도에 어떠한 과제를 수행하겠다고 하는 것이 나와 있습니다.  우선 총괄기획연구부는 경기도의회의 지역발전 공헌도에 관한 조사 연구, 이것은 도의회 의장님께서 추천해 주신 과제입니다마는 이것을 포함해서 5개 과제를 내년도에 수행할 계획으로 있습니다.  그 다음에 생활환경연구부는 폐기물 소각방식의 비교 분석 및 경기도 적용에 관한 연구를 포함해서 3개 과제, 그리고 산업경제연구부가 21세기 경기도 산업정책 방향을 포함한 4개 과제, 그리고 도시 지역계획연구부가 수도권 인구이동 특성에 관한 연구를 포함해서 4개 과제를 수행할 예정입니다.  교통정책연구부는 도로사업의 투자우선순위 결정방안을 포함한 3개 과제, 그리고 국제경제연구부는 외국인 직접투자에 대한 경기도 차원의 인센티브 연구를 수행할 예정입니다.  그리고 수질환경연구소는 경기도 민간환경단체의 역할에 관한 연구를 포함해서 4개 과제를 수행할 예정으로 있습니다. 
</p>
<p style="padding-left:1.2em">  17페이지에는 경기도와 도의회에서 추천한 과제들이 소개됐습니다.  아까도 말씀드린 바와 같이 경기도에서는 47개 과제, 도의회에서는 11개 과제가 추천이 됐습니다.  다음 18페이지 이하는 내년도에 수행할 연구과제에 관한 세부계획이 나와 있습니다.  그것은 생략하겠습니다.  26페이지로 넘어가겠습니다.  기타 연구사업 계획에 대해서 말씀을 드리겠습니다.  수탁과제 추진계획을 말씀드리면 저희가 경기도와 각 시 군의 관련기관으로부터 수탁과제를 받아가지고 진행할 계획으로 있습니다.  현재 진행중인 수탁과제 6건과 각 부에서 대체로 2개 과제 정도 수행할 계획으로 있습니다.  그래서 내년도에는 19건 정도의 수탁과제를 수행할 계획으로 있습니다.  26페이지에 나와 있는 표는 ''98년도에서 ''99년도로 이월되는 수탁과제가 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음에 27페이지로 넘어갑니다.  기타 연구사업 계획이 되겠습니다.  아까도 잠시 말씀드린 바와 같이 먼저 지역연구는 내년도에 3개 시 군을 대상으로 할 계획으로 있습니다.  그래서 저희가 지역적인 안배를 고려해서 경기북부지역에서 1시 군, 경기남부에서 1지역, 그리고 경기동부에서 1지역 해서 3개 시 군에 관한 지역연구를 내년에 수행할 예정입니다.  그리고 수시연구는 아까 말씀드린 바와 같이 도에서 시급을 요하는 정책과제가 저희한테 떨어지면 그것을 수행할 계획으로 있습니다.  다음에 세미나 및 간행물 발간이 되겠습니다.  아까도 말씀드린 바와 같이 일단 세미나는 내년에 한 분기에 한 번씩 네 번 하는 것으로 계획을 세웠습니다.  그리고 간행물 발간은 경기21세기를 여섯 번, 경기연구를 한 번, 그리고 세미나자료집은 수시로 발간하고 번역서를 두 번으로 계획을 세웠습니다.  이상 연구사업에 대한 말씀을 마치겠습니다.  이어서 저희 사무처장께서 보고를 드리도록 하겠습니다. 
</p>
<p><b>○ 사무처장 표찬섭 </b> 사무처장 표찬섭입니다.  제가 보고드릴 사항은 연구원의 일반현황과 재정운영사항, 그리고 작년도 행정사무감사시 지적사항에 대한 조치사항에 대해서 보고를 드리겠습니다.  배부해 드린 유인물 1페이지를 참고해 주시기 바랍니다.  먼저 일반현황을 보고드리겠습니다.  연구원의 연혁은 ''94년 8월 23일 경기개발연구원 설립 기본계획을 수립하였고 ''95년 1월 18일자로 경기개발연구원설치및육성조례를 제정 공포한 후에 내무부장관의 연구원 설립허가와 법인설립등기를 필한 후 ''95년 3월 20일자로 개원을 하였습니다.  다음 연구원의 기능은 도정의 중장기 비전 제시와 정책을 개발하여 지원하는 역할을 하고 있습니다.  각 부서별 기능은 유인물로 갈음하겠습니다.
</p>
<p style="padding-left:1.2em">  다음 2페이지가 되겠습니다.  기구 및 인력에 대해서 보고를 드리겠습니다.  연구원에는 18명의 이사님과 두 분의 감사가 있습니다.  그리고 이사장은 경기도지사가 당연직이고 도의회 기획위원회 위원장님께서도 당연직 이사가 되시겠습니다.  그리고 연구과제에 대한 자문을 구하기 위해서 대학 교수급으로 구성된 20명의 연구자문위원회를 구성 운영하고 있습니다.  연구원의 기구는 원장 밑에 연구실장, 수질환경연구소장, 사무처장, 그리고 자료전산실장이 있고 연구실에는 표에 있는 바와 같이 6개 부장이 있습니다.  연구원의 정 현원은 정원 49명 중 현원 44명으로 현재 5명이 결원중에 있습니다.  그리고 현원 44명 중에는 연구직 즉, 박사급이 26명, 그리고 관리직 18명이 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 3페이지가 되겠습니다.  시설현황을 보고드리겠습니다.  저희 연구원은 아직 독립 청사를 확보하지 못하였기 때문에 한미은행 경수영업본부 건물 13층과 14층의 357평을 임대하여 본원으로 활용하고 있고, 수질환경연구소는 본원에서 한 500m 지점에 위치한 한미빌딩 2층의 108평을 임대 활용하고 있습니다.  저희 연구원에 비치하고 있는 장서는 국내외 도서, 학위논문 등 1만 349권을 보유 활용하고 있습니다.  또 전산장비는 PC, 프린터 등 120대를 확보 활용하고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 페이지가 되겠습니다.  재정운영사항에 대해서 보고드리겠습니다.  먼저 기금관리사항이 되겠습니다.  기금조성액은 총 200억원이고 출연기관별로는 경기도가 전체기금의 68.5%인 137억원, 시 군이 19.8%인 39억 6,100만원, 전 경기은행과 제일은행이 각각 10억원씩 그리고 연구원 자체적립이 3억 3,900만원이 되겠습니다.  기금예치사항은 외환은행 32억원, 제일은행 34억원, 상업은행 20억원, 한미은행 87억원, 한국투자신탁 17억원 그리고 전 경기은행에 10억원이 각각 분산 예치돼 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 페이지가 되겠습니다.  다음은 ''98년도 예산개요를 보고드리겠습니다.  예산 총규모는 작년보다 39.3%가 증가한 264억 8,400만원입니다마는 순계 예산에서 기금 200억원과 자체적립금 2억원을 제외하면 실제 연구원 운영비는 39억 6,300만원이 되겠습니다.  회계별 규모는 일반회계가 41억 6,300만원, 기금관리 특별회계가 223억 2,100만원이 되겠습니다.  다음은 일반회계 세입 세출내역을 보고드리겠습니다.  먼저 세입예산 내역은 기금관리 특별회계의 기금이자에 대한 전입금이 23억 2,100만원, 일반회계 운영자금에 대한 이자수입이 6,000만원, ''97년도 선급 법인세환급금이 3억 9,400만원, 순세계잉여금이 5억 6,700만원, 도비보조금이 5억원 그리고 수탁용역사업 등에 따른 사업수입이 3억 2,100만원이 되겠습니다.  세출예산내역은 인건비 14억 2,000만원, 물건비 12억 7,700만원, 이전경비 3억 7,300만원, 자본적 지출금 7억 7,900만원, 자체적립금 2억원, 예비비 1억 1,400만원이 되겠습니다.  
</p>
<p style="padding-left:1.2em">  다음 6페이지가 되겠습니다.  기금관리 특별회계의 세입 세출내역을 보고드리겠습니다.  세입예산 규모는 223억 2,100만원으로 ''97년도에서 이월된 기금이 148억원, ''98년도 도에서 새로 출연한 교부금이 50억원, 연구원 자체적립금이 2억원, 기금 200억원에서 발생한 이자수입이 23억 2,100만원이 되겠습니다.  세출내역은 기금예탁금이 200억원, 이자수입을 일반회계로 전출하는 금액이 23억 2,100만원이 되겠습니다.  
</p>
<p style="padding-left:1.2em">  다음은 ''99년도 예산안에 대한 개요를 보고드리겠습니다.  참고로 저희 연구원의 예산승인절차는 이사회의 의결을 거쳐 11월말까지 도지사의 승인을 받아 집행하도록 돼 있습니다.  그래서 내일 이사회를 개최할 계획이기 때문에 이것은 하나의 안이 되겠습니다.  내년도 예산규모는 285억 3,500만원으로 ''98년도보다 7.7%인 20억 5,100만원이 증가되었습니다.  회계별 규모는 일반회계가 65억 7,900만원, 기금관리 특별회계가 219억 5,600만원입니다.  내년도부터는 도 방침에 따라 연구원의 운영방법을 출연기금의 이자수입에 의존하여 운영하던 체제에서 도비보조금 지원체제로 바뀌었음을 보고드립니다. 
</p>
<p style="padding-left:1.2em">  다음 7페이지가 되겠습니다.  일반회계 세입 세출내역을 보고드리겠습니다.  먼저 67억 5,900만원 규모의 세입예산내역은 기금관리 특별회계에서 이자전입금이 16억 5,500만원, 일반회계 운영자금에서 발생된 이자수입이 6,000만원, ''98년도 선급 법인세환급금이 5억 6,300만원, 순세계잉여금이 3억 3,000만원, 도비보조금이 31억원, 임차보증금 반환금이 6억 9,400만원, 수탁용역 등 사업수입 1억 7,700만원을 계상했습니다.  참고로 ''98년도 도에서는 출연한 50억원과 운영비 5억원을 합하면 모두 55억원을 지원받았습니다마는 금년부터는 보조금체제로 전환돼 있기 때문에 도비보조 31억원을 지원받아 운영할 계획으로 있습니다.  다음 세출내역은 기관운영비가 10억 3,400만원, 연구부 운영비가 43억 7,300만원, 수질환경연구소 운영비가 7억 8,800만원, 자체적립금이 3억원, 예비비 8,400만원을 계상했습니다. 
</p>
<p style="padding-left:1.2em">  다음은 기금관리 특별회계 세입 세출내역을 보고드리겠습니다.  세입예산 219억 5,600만원의 내역은 ''98년도에서 이월된 기금이 200억원, 연구원 자체적립금이 3억원, 기금이자수입 16억 5,600만원을 계상했습니다.  세출내역은 기금예탁금이 203억원, 이자수입을 일반회계로 전출하는 것이 16억 5,600만원이 되겠습니다.  
</p>
<p style="padding-left:1.2em">  다음 28페이지를 참고해 주시기 바랍니다.  ''97년도 행정사무감사시 지적사항에 대한 조치결과를 보고드리겠습니다.  작년도 행정사무감사는 11월 29일 10시부터 17시 30분까지 바로 이 장소에서 감사를 실시했습니다.  감사반은 당시 박영하 위원장님 등 열네 분이 감사를 실시했습니다.  감사결과 지적사항은 시정요구 2건, 건의요구 4건 해서 모두 6건이 지적돼서 모두 처리를 완료하였습니다.  29페이지부터는 시정 및 건의요구사항에 대한 조치결과를 수록한 것입니다.  이것은 서면으로 갈음하겠습니다.  이상 보고를 마치겠습니다.
</p>
<p>(경기개발연구원 소관 업무보고서는 끝에 실음)
</p>
<p><b>○ 위원장 고수복 </b> 경기개발연구원장 수고하셨습니다.  그러면 감사질의를 하도록 하겠습니다.  질의는 원활한 진행을 위하여 일괄질의 후 일괄답변을 듣는 방법으로 하는 것을 원칙으로 하고 보충질의시에는 일문일답식으로 진행하도록 하겠습니다.  그러면 질의하실 위원께서는 질의하여 주시기 바랍니다.  이남형 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이남형 위원 </b> 고양시출신 이남형 위원입니다.  질의에 앞서 본 경기개발연구원이 설립된지 불과 3년반 정도밖에 되지 않았습니다.  제가 알고 있기로는 ''95년초에 설립된 걸로 알고 있습니다.  사람으로 치면 아직 유아단계를 벗어나지 못하고 있다고 생각합니다.  이렇게 짧은 기간동안에 우수연구원 확보 등 상당히 많은 어려움이 있었을 걸로 생각합니다.  그럼에도 불구하고 오늘날 많은 과제물을 산출해 내는 등 수준높은 경기개발연구원의 기틀을 잡는 데 많은 노력을 기울여 주신 유훈 원장님의 그동안의 노고에 대해서 이 자리를 빌어 감사의 말씀을 드립니다.  본 위원은 두 가지 방법으로 질의를 하겠습니다.  일반행정 업무분야에 관한 질의를 먼저 하고 이어서 조사연구사업에 관한 질의를 하겠습니다.  
</p>
<p style="padding-left:1.2em">  먼저 일반행정업무에 관해서 말씀을 드리겠습니다.  본 위원이 알고 있기로는 현재 경기개발연구원에는 기금규모가 약 200억원인 것으로 알고 있습니다.  ''98년도에도 경기도에서 기금출연금 50억원이 있었고 도비보조금 5억원 정도가 있었습니다.  아까 사무처장님도 업무보고에서 말씀을 하셨지만 ''99년도에도 조금 방향은 바뀌었지만 도비보조금 항목으로 31억원이 보조되는 걸로 있습니다.  본 위원의 생각으로는 경기개발연구원이 이제 4년차에 들어가기 때문에 중장기적으로 볼 때는 충분한 자체자금을 확보해서 경기개발연구원을 운영해 나가는 데 필요한 모든 자금을 자체 충당하는 것이 마땅하다 이렇게 판단합니다.  그래서 만약 향후에 경기개발연구원을 자체재정을 가지고 운영한다면 어느 정도 규모의 기금이 설정돼야만 가능한지, 아마 그런 추계를 한 번쯤 해보시지 않았을까 이렇게 판단합니다.  그래서 그 추계를 하신 내용이 있다면 내역을 한번 설명해 주시고 그 다음에 어떻게 기금을 조성할 것인지, 그리고 기간은 어느 정도 할 것인지 이 부분을 질의드립니다. 
</p>
<p style="padding-left:1.2em">  두 번째로는 경기도에서 ''96년, ''97년, ''98년도 지속적으로 출연금이나 도비보조금을 지원해 온 걸로 알고 있는데 실제 경기개발연구원의 계좌로 도비보조금이나 출연금이 어느 시기에 입금됐는지 여쭤보고 싶습니다.  왜냐하면 경기도의 예산상으로는 잡혀있다 하더라도 만약에 경기개발연구원으로 그 예산이 연도 중에 넘어올 수 있기 때문에 연초에 넘어오느냐, 연말에 넘어오느냐에 따라서 상당히 많은 경기개발연구원의 경영이라든지 이런 부분과 연관되어 있기 때문에 그 부분을 한번 실제로 어떻게 돼 있는지 제가 알아보고 싶은 생각이 있어서 말씀드리는 것입니다.
</p>
<p style="padding-left:1.2em">  세 번째로 경기개발연구원에는 지금 많은 연구원들이 근무하고 있는 걸로 알고 있습니다.  지난해 ''97년과 ''98년 현재까지의 사이에 연구원으로 종사를 하다가 자진해서 퇴임을 하신 분이나 아니면 기타 다른 사유로 퇴임하신 연구원들이 얼마나 되는지 한번 여쭤보고 싶습니다.  왜냐하면 경기개발연구원 내에 근무하시는 분들은 만족스러운 분위기 속에서 최상의 과제물을 산출해 냄으로써 그 과제물을 통해서 경기도의 발전방향에 커다란 기여를 해야 되는 임무가 있다고 봅니다.  그래서 연구원 중에서 혹여라도 분위기가 만족스럽지 않다든지 해서 퇴임하신 분이 있다면 향후 어떤 대응방안을 가져야 되겠다, 본 위원은 이렇게 생각합니다.  그래서 질의를 드리는 것입니다.  
</p>
<p style="padding-left:1.2em">  그 다음에 네 번째로는 수탁용역사업 수입이라 해서 2억 8,800만원이 계상돼 있는 것이 있습니다.  그것은 지난 ''98년 9월 2일 작성된 업무보고서에서 제가 발췌한 내용입니다.  이 금액이 구체적으로 어떤한 내용인지, 아마 제가 알고 있기로는 연구원 등이 외부에서 과제물을 수탁해서 연구하는 과정에 자금의 일부를 경기개발연구원의 자금으로 내놓은 것이 아닌가 판단하는데 이것이 구체적으로 어떻게 수탁용역사업 수입으로 잡히게 되는 것인지 자세하게 설명해 주시기를 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  다섯 번째로는 장서의 구입과 관련해서 말씀올리겠습니다.  장서구입을 보면 국내의 장서 뿐만 아니라 주로 미국이라든지 일본에서 발간되는 책자들도 많이 있는 걸로 돼 있습니다.  그래서 어떠한 장서를 어떠한 방법으로 구입하는지, 구입하는 장서목록을 결정하는 내부적 시스템하고 미국이라든지 일본에서 장서를 구입할 경우에는 경기개발연구원까지 도착하기 까지는 어떠한 과정을 거쳐서 도착하게 되는지 여쭤보겠습니다.  
</p>
<p style="padding-left:1.2em">  다음에 여섯 번째로 일반행정업무와 관련된 부분으로 마지막 질의가 되겠습니다.  경기은행이 얼마 전에 부도 처리됐습니다.  그래서 경기은행이 부도처리된 내용과 관련해서 몇 가지 말씀드리겠습니다.  제가 제출해 주신 자료 65페이지를 보니까 경기개발연구원 육성기금 운영현황이 있습니다.  이 내용을 살펴보면 ''98년도 초에 한미은행 경기 수원지점에 정기예탁금으로 40억원에 16.7%라고 돼 있습니다.  이게 ''98년 2월 20일이 예치한 날짜입니다.  또 제일은행 매탄지점에도 ''98년 2월 19일 예치하고, 외환은행 동수원지점에도 ''98년 1월 3일, 외환은행 동수원지점에 "yes 큰기쁨"으로 1월 16일, 상업은행 정기예금 ''98년 1월 16일 이게 연이율로 따지면 16.7% 짜리입니다.  물론 그 당시에 제가 보기에는 금리수준이 상당히 높았었습니다.  지금은 여러분들도 잘 아시는 바와 같이 금리수준이 대폭 하향조정되어서 10% 미만으로 내려가 있습니다.  제가 보기에는 상당히 운영을 잘 했다 이런 평가를 내립니다. 
</p>
<p style="padding-left:1.2em">  그런데 한 가지 궁금한 것은 예치는 ''98년초에 했지만 몇 년기간으로 정기예금을 하거나 예치한 것인지를 제가 하나하나 불러드린 부분에 대해서는 말씀을 해주시고 그 다음에 경기은행에 맨밑을 보면 특정금전신탁 10억원 12.5% 해서 ''97년 1월 14일 예치한 게 있습니다.  제가 알고 싶은 것은 경기은행이 지난 번에 이미 부도처리가 됐기 때문에 일반정기예금이라든지 이런 것은 다 보장됩니다.  그런데 특정금전신탁은 보호대상 상품에서 아마 제외되고 있는 걸로 알고 있는데 이 10억원이 ''97년 1월 14일 예치된 것이기 때문에 아마 지금까지도 있지 않나 판단이 되는데 만약에 이 부분이 지금까지 있다면 경기은행은 이미 부도처리가 됐기 때문에 이것이 과연 지금은 어떻게 운영되고 있는지 여기에 좀 문제가 있지 않나, 채권이 아니고 은행예금에 대한 확보방안이 여러 가지 어려운 형편일 걸로 생각됩니다.  그런데 이 부분이 구체적으로 어떻게 걸려있는지 자세하게 설명해 주시기를 부탁드립니다.  
</p>
<p style="padding-left:1.2em">  다음은 조사연구사업과 관련해서 몇 가지만 간단하게 질의를 드리겠습니다.  본 위원이 알고 있기로는 경기개발연구원의 주요연구사업으로는 자체연구라든지 수탁연구, 지역연구, 정책세미나 이런 게 많이 있습니다.  그런데 ''98년도의 경우를 보면 자체연구사업으로 24건, 수탁연구사업으로 16건이 돼 있습니다마는 본 위원이 알고 싶은 것은 자체연구과제나 수탁연구과제를 선정하는 경우를 보면 경기도나 경기도의회 의원들에게 어떠한 과제물을 선정하는 것이 좋은가 조사를 하셔서 하는 부분이 많은 걸로 생각됩니다.  그 부분을 구체적으로 좀 자세하게 설명해 주시고, 본 위원이 생각하기로는 이 부분을 좀 확대할 필요가 있지 않겠는가.  예를 들어서 경기도 내에도 아주대학이라든지 수원대학이라든지 이런 대학들도 있고 연구기관도 조금 더 있을 것입니다, 금융 기관들도 있고.  그래서 경기도나 도의회 뿐만 아니라 관련기관을 확대해서 좀더 다양한 의견을 수렴해 가지고 연구과제를 선정하면 더 많은 의견이 수렴되지 않을까 그래서 그 부분에 건의사항을 드리면서 수탁연구과제물 선정방법을 자세히 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  이 과제물과 관련해서 제가 한 가지를 특히 더 말씀드리고 싶은 것은 도내에는 중소기업이 굉장히 많이 있습니다.  그런데 제가 나름대로 확인해 보니까 물론 IMF도 오고 했지만 지금 중소기업이 아주 많이 부도가 났습니다.  그리고 굉장히 어려운 상황에 있기 때문에 이와 관련해서 중소기업에 대해서 정부나 도에서 지원하는 방식이 대개 자금지원을 해준다든지 정보를 제공해 주는 수준에 머물고 있는데 본 위원의 생각으로는 각종 생산품이 많이 나오기 때문에 이 부분에 대한 유통구조, 판매망을 어떻게 설치한다든지 이런 부분에 관한 연구도 해주셨으면 고맙겠다 이렇게 말씀드리면서 또 하나는 아마 중소기업을 경영하고 계신 분들을 만나서 뵈면 다들 그런 말씀을 많이 들었을 것입니다.  우리나라는 어음제도가 없어야 된다 이런 얘기를 저도 많이 듣습니다.  실제로 어음은 제가 알고 있기로 물품을 납품한다든지 사업을 하는 과정에서 물품이 납품된 이후에 한 1개월 내지 2개월이 지나야 어음을 받습니다.  그리고 그 어음결재일은 그로부터 5, 6개월이 갑니다.  그래서 이 부분이 중소기업을 경영하시는 분들한테는 상당히 커다란 문제점으로 등장하고 있는데 중소기업 육성차원에서 어음제도의 개선방안도 한 번쯤 검토해 주셨으면 하는 말씀을 드립니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 두 번째로는 연구과제가 결정되면 연구자가 지정되고 연구완료기간이 설정되는 걸로 알고 있습니다.  그런데 본 위원이 생각하기로는 연구과제물은 그 난이도라든지 중요도에 따라서 연구기간이 다양할 걸로 생각합니다.  제가 제출해 주신 자료를 개략적으로 점검해 보니까 최하 6개월에서 근 1년에 이른 부분도 있는데 연구기간을 6개월로 설정한다든지 1년으로 설정한다든지 이런 기간을 어떤 과정을 거쳐서 설정하시는지 말씀해 주시고, 최근에 보니까 ''98년 10월말쯤에 경기지방공사의 중장기개발 경영계획이 완료된 걸로 자료에 나와있습니다.  그래서 이 부분은 신원득 연구원께서 연구를 하셨으니까 이따 간략하게 어떻게 경영계획을 하는 것이 좋은가 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  세 번째로는 본 위원이 ''98년의 경우 자체연구사업과 수탁연구사업 40건을 연구원별로 확인해 봤습니다.  그랬더니 대개 1연구원당 1과제가 편성됐습니다.  그런데 직접 연구원명을 좀 거론하겠습니다.  양기용 연구원과 이외희 연구원, 이상훈 연구원, 전미경 연구원, 김군수 연구원, 신원득 연구원, 이정임 연구원, 이양주 연구원 등 8명 연구원의 경우는 과제물이 두 가지였습니다.  그 다음에 성현찬 연구원, 황순진 연구원, 김흥식 연구원, 조응래 연구원 등 4명은 세 가지 과제물을 산출해 냈습니다.  그래서 본 위원이 생각하기로는 24명 중 12명은 2건 내지 3건을 하셨고 또 절반에 해당하는 12명은 1건만 했습니다.  그래서 2건을 하신 것까지는 이해가 되는데 1건을 연구과제물로 생산해 내는 분이 있는가 하면 3건을 과제물로 생산해내는 분은 업무배분상에 조금 문제가 있지 않나 그런 생각을 했습니다.  그래서 물론 과제물의 성격상 과거에 대학이라든지 박사학위 과정에서 연구한 내용이 교통이면 교통, 수질이면 수질 이렇게 특화돼 있기 때문에 어쩔 수없이 이렇게 된 것인지 한번 여쭤보겠습니다.  
</p>
<p style="padding-left:1.2em">  네 번째로는 지역연구사업에 대해서 말씀드리겠습니다.  조금 전에 유훈 원장님께서 지역연구사업과 관련해서 ''98년도 하반기 12월 10일에는 김포시 연구사업이 완료됐기 때문에 10일에 김포시 관내에서 세미나를 개최하시겠다고 말씀해 주셨습니다.  이 부분은 본 위원이 지난 9월 2일 경기개발연구원 업무보고시에 유훈 원장님께 제안했던 내용입니다.  그래서 사실은 제가 이 부분이 어떻게 됐는가 질의를 드리려고 생각하고 왔는데 유훈 원장님께서 말씀해 주셨기 때문에 대단히 감사하게 생각을 합니다. 
</p>
<p style="padding-left:1.2em">  다섯 번째로는 1시 1군 담당연구원제도를 하고 있는데 어느 연구원이 어느 시 군을 담당하는지 서면으로 명단을 제출해 주시고 1시 1군 담당연구원제도와 관련해서 연구원이 구체적으로 당해 시 군과 어떠한 교류를 하고 있는지 말씀해 주시기 바랍니다.  자료에 보면 현지방문을 위주로 운영한다 이렇게 돼 있습니다.  그런데 방문빈도라든지 한 번 방문했을 때 거기서 어느 정도 시간을 머물고 있는지, 또 어떠한 분들을 만나시는지 그 다음에 방문결과는 어떻게 되어 있는지 말씀해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 여섯 번째 자료전산실 운영과 관련해서 말씀드리겠습니다.  지금까지 자체연구과제나 수탁연구과제, 지역연구사업 여러 가지 과제물들이 많이 나왔습니다.  이러한 과제물들이 지금 자료전산실에 모두 전산화되어서 수록되어 있는지 한번 여쭤보겠습니다.  이상으로 본 위원은 질의를 모두 마치겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 원활한 회의진행을 위해서 10분간 휴식하고자 하는데 이의 없으십니까?  
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 11시 40분까지 감사중지를 선포합니다. 
</p>
<p class=''ar''>(11시35분 감사중지)
</p>
<p class=''ar''>(11시35분 감사계속)
</p>
<p><b>○ 위원장 고수복 </b> 좌석을 정돈하여 주시기 바랍니다.  속개하겠습니다.  질의에 앞서서 지금 윤동욱 위원님께서 댁내에 애사가 있어서 일찍 자리를 떠나셨습니다.  그래서 윤동욱 위원님께서 질의하실 내용을 제가 낭독해 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  남양주출신 윤동욱 위원입니다.  경기개발연구원에서 연구한 과제에 대하여 질의하겠습니다.  경기개발연구원의 감사자료 73페이지 ''97 사업계획서의 과제연구를 보면 자체연구 9건, 지역연구 2건, 수탁연구 21건으로 총 32건의 과제를 연구하였으며, 감사자료 82페이지 ''98 사업계획서를 보면 자체연구 25건, 수탁연구 18건 등 지역연구 총43건을 연구하여 ''97년도 및 ''98년도에 총 75건을 연구하였다고 보고하셨습니다.  그러면 질의하겠습니다.  경기개발연구원에서 연구한 총 75건의 과제가 지금 지방자치단체에서 실제로 추진되고 있는 과제는 몇 건이나 되는지와 미추진되고 있는 과제연구를 분류하여 말씀해 주시고, 미추진된 연구과제가 있다면 많은 예산을 들여 연구한 과제가 사장화되어 그만큼 예산이 낭비되었다고 생각하는데 미추진되고 있는 사유는 무엇인지 밝혀 주시고 미추진 과제는 향후 어떻게 관리할 계획인지 답변해 주시기 바랍니다.  이상 윤동욱 위원님께서 질의해 주신 질의자료였습니다.  윤동욱 위원님께서 자리에 안 계시지만 답변도 역시 관계공무원께서는 해주시고 속기해 주시기 바랍니다.  계속해서 질의를 하도록 하겠습니다.  질의하실 위원님, 장현수 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 장현수 위원 </b> 질의에 앞서서 경기도 관계관이 임석하셨습니까?
</p>
<p style="padding-left:2.4em">    (「정책기획관실 직원이 참석했습니다」하는 관계공무원 있음)
</p>
<p style="padding-left:1.2em">  네, 알았습니다.  신문보도나 또 제가 여론을 듣기로는 구조조정에 따라서 경기개발연구원이 경기지방공사와 통합한다라는 여론과 그런 신문보도를 본 적이 있는데 원장께서는 지사님과 또는 관계공무원으로부터 그런 언질을 받은 사실이 있는지, 또 통합을 한다면 어떤 방법으로 경기개발연구원과 경기지방공사와 연계해서 할 수 있는지 그것에 대한 답변을 해 주시기 바랍니다.  두 번째 경기개발연구원이 발족한 지 4, 5년이 됐습니다마는 지금 465평을 임대해서 운영을 하고 있고 수질환경연구원은 여기서 떨어진 데서 한 50평을 임대해서 분산돼서 운영하고 있는데 원장께서는 앞으로 경기개발연구원이 독자적으로 건물을 신축을 해서 정말로 경기도 850만의 웅도에 보다 발전적이고 21세기를 향한 새로운 모델을 연구해야 된다고 생각합니다.  그러한 경기개발연구원을 새로 신축할 계획과 그런 예산이 얼마나 드는지, 또는 추진을 어떻게 하고 있는지 계획이 있는지 없는지 소상히 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 이것은 개인적인 얘기입니다.  원장님께서 보고하신 북부, 동부, 남부 시 군에 ''99년도에는 연구를 개발하겠다 이렇게 말씀하셨는데 남부의 최남단인 안성시를 내년도에 연구하실 계획은 있으신지, 또 그러한 계획이 있다면 안성시를 해주는 게 좋겠다는 의견을 말씀드리고 시 군에 연구개발할 때 시의원이나 또는 도의원들도 함께 세미나나 이런 것을 같이 연구하면서 접촉하셨는지, 기이 한 데는 어떻게 했는지 말씀해 주시기 바랍니다.  이상입니다.
</p>
<p style="padding-left:1.2em">  그리고 위원장님과 관계 수감기관에 죄송한 말씀을 드리겠는데 저희 한나라당이 오늘 중앙위원회를 갖습니다.  도의원은 당연직이기 때문에 저희 유 위원님과 저는 질의를 하고 자리를 뜨겠습니다. 
</p>
<p>답변은 정확히 해 주셔서 나중에 의회 회의록에서 볼 수 있게끔 해 주시기 바랍니다.이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 위원님들에게 죄송한 부탁의 말씀을 드리겠습니다.  일정이 바빠서 위원님들께서 자료를 충분히 검토하시고 질의사항이 많겠으나 요지만 간단간단하게 질의해 주시기 바랍니다.  또 질의하실 위원님, 유영록 위원 질의해 주시기 바랍니다.
</p>
<p><b>○ 유영록 위원 </b> 김포출신 유영록 위원입니다.  몇 가지 질의하겠습니다.  저는 자료요청을 일단 요구합니다.  첫 번째로 현재 이사회 명단하고 현직위, 그 다음에 이사로 선임된 일자, 이사, 감사에서 한 부 제출해 주시고요.  그 다음에 경기개발연구원의 정원이 49명, 현원이 44명인데 사무처직원은 사무처장만 하시고 연구원들은 만약 석사, 박사 취득하셨으면 전공분야가 무엇인지, Ph.D.받은 연도하고 박사학위논문이라 할지 석사학위논문 그것을 해서 연구원들 자료로 제출해 주시면 고맙겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 원장님께서 12월 19일에 김포지역 연구보고서 내면서 김포시에서 세미나를 개최했다고 하는데 형식이 어떤 건지, 그 다음에 지난 번 저희가 보고서 나오기 전에 1차로 경기개발연구원 연구원들이 김포시에 와서 1차 세미나를 하고 저도 회의가 있어서 잠깐 참여를 했는데 세미나를 보면 주로 시의 관계공무원들이 참석한 가운데 세미나가 있었습니다.  조금 전에 장현수 위원님께서 말씀하셨듯이 차후에라도 지역연구에 대한 조사가 있을 때 적어도 관계공무원 말고 시 도의원들, 기타 지역에 관심있는 인사들도 지역연구를 위한 사전작업으로 세미나에 동참할 수 있었으면 좋겠다하는 것을 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그 다음에 사무처장님한테 몇 가지 질의를 하겠습니다.   경기개발연구원 일반회계 예산이 지금 계속 ''97년에 26억 7,000만원, ''98년에 41억 6,000만원, ''99년에 무려 65억원 이렇게 계상하고 있는데 지금 저희가 IMF한파 위기에도 불구하고 경기개발연구원의 일반회계 예산을 계속 증액한다는 것은 사실 그만큼 관심이 많다는 것입니다.  도에서도 그렇고 기획위원회에서도 그렇고 그래서 그런 면에 중점을 두시고 재정관리를 원활하게 하시는데 기금문제에 있어서 한 가지만 여쭤보면 저희가 연이율이 계속 10%를 넘는데 한미은행에 ''98년 10월 26일 40억원을 더모아확정예금으로 1년 6개월 예치시켰는데 이것만 연이율이 9.7%거든요.  특별히 이 당시에 연이율이 하락해서 이렇게 된 건지 다른 것은 최고 높은 것은 16.7%까지 있는데 그것에 대해서 답변해 주시고요.  이상입니다.  나머지 구체적인 세입 세출예산개요 같은 것은 차후에 개인적으로 다시 한 번 여쭙겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 유영록 위원님 수고하셨습니다.  다음 질의하실 위원님, 이진용 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 이진용 위원 </b> 가평출신의 이진용입니다.  먼저 1995년 개원 이후에 도정의 중장기비전제시와 정책개발지원이라는 기능에 충실하여 왔음을 그동안의 연구결과물을 보고 알 수 있습니다.  여러분의 그러한 노력에 격려의 말씀을 드리면서 기획위원으로서 본 위원이 여러분을 지원할 수 있는 일이 있다면 성심껏 지원하겠다는 말씀을 드리면서 행정사무감사에 대한 질의에 들어가겠습니다.  본 위원의 질의는 먼저 연구방향의 전환 필요성에 대해서 말씀드리고자 합니다.  그간의 연구가 도정의 중장기비전을 제시하는데 중점을 두어왔다면 최근 IMF 이후에 여러분의 연구는 단기 또 실사구시적인 실천적 연구중심으로 변화가 있어야 되지 않겠는가 하는 생각을 합니다. 
</p>
<p style="padding-left:1.2em">  올해 네 번의 세미나가 있었는데 그중에 한 가지만 예를 든다면 IMF 위기극복을 위한 경기도 대응과제에서 볼 수 있듯이 연구내용이 개념적이고 추상적이어서 과연 도 집행부에서 목적하는 바를 바로 이룰 수 있는 근거를 제시하였는가하는 이런 생각을 갖게 됩니다.  그래서 이 점에 대해서 여러분의 의견을 듣고 싶고, 두 번째로 수환경연구를 위해서 설립된 수질환경연구원의 연구에 대해서 묻고자 합니다.  ''99년도 과제 경기도 민간환경단체 역할에 관한 연구 외 3건으로 되어 있는데 수환경연구에 대한 요구에 비추어서 볼 때 내년도 연구과제가 너무 느슨하게 편성된 것이 아닌가하는 생각이 듭니다.  그 점에 대해서도 의견을 묻고 싶습니다.
</p>
<p style="padding-left:1.2em">  다음으로 지역연구의 연구대상지역 선정에 대해서 먼저 장현수 위원님께서도 언급을 하셨지만 본 위원의 생각은 지금 도내 몇몇 지방자치단체가 연구용역비를 책정하기가 어려울 정도로 재정상태가 상당히 좋지 않습니다.  이번에 도정방침에서도 나타났듯 지역간 균형발전을 이루고자 하는 측면에서도 재정자립도가 열악한 그런 시 군의 발전계획을 갖다가 제시할 수 있는 이런 전환이 필요하지 않겠는가하는 이런 생각이 듭니다.  그 점에 대해서도 제가 여러분이 연구대상지역을 선정하는데 여러 가지로 고민거리가 많을 것 같은데 제가 이런 기준을 한 가지 제시함으로써 그런 어려움을 덜어 드리는 것이 아닌가하는 생각이 듭니다.
</p>
<p style="padding-left:1.2em">  다음으로 시 군발주 연구과제 용역비가 얼마나 되는지 연구과제별로 밝혀 주시고요.  그 다음에 가평군 장기종합발전계획 연구현황에 대해서 서면으로 제출해 주시기 바랍니다.  특별히 이 점과 관련해서는 통합모형의 필요성을 제가 말씀드렸는데 오늘 김군수 연구원님께서 자리에 참석하지 않으신 것 같네요.  그 점에 대해서 말씀을 듣고 싶습니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 정운천 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 정운천 위원 </b> 안녕하십니까?  안성출신 정운천 위원입니다.  먼저 질의에 앞서서 경기개발연구원은 경기도에 있어서 군함으로 치면 자이로와 같은 것이 아니냐 이렇게 생각합니다.  군함에서 함장은 물론 경기도지사지만 거기에 대한 어떤 방향을 읽어줄 수 있는 자이로와 같은 아주 중요한 기구가 경기개발연구원이 아니냐 이렇게 생각합니다.  그런 점에 비추어서 몇 가지 질의를 드리겠습니다.  ''95년부터 ''97년까지의 연구내용을 검토한 결과 연구내용을 보면 기초조사가 ''95년의 경우에 2건, 기법 및 지표개발이 2건, 전략적인 정책대안이 9건 해서 13건을 연구하셨고 ''96년도에는 선진사례 등 기초조사가 1건, 기법 및 지표개발이 2건, 전략정책대안이 16건 해서 19건을 연구과제로 연구하셨습니다.  ''97년도에는 기초조사 2건, 나머지 7건이 정책대안으로 9건을 연구하셨습니다.  문제는 이렇게 연구한 과제가 도정에 어떻게 반영되었는지 거기에 대해서 제 나름대로 주어진 자료를 검토해 본 결과 참고자료로만 쓴 것이 ''95년 2건, 기본자료로만 쓴 것이 7건, 계획에 일부 반영한 것이 2건, 적극적으로 정책에 반영한 것이 2건, 이것은 어차피 경기개발연구원에서 제출해 준 자료로만 한 것임을 밝혀둡니다.  ''96년도에는 참고자료 1건, 기본자료 4건, 계획에 반영한 게 3건, 적극적으로 정책에 반영한 게 11건, 19건이 연구됐고요.  ''97년도에는 기본자료 2건, 계획에 반영 2건, 적극적인 정책반영이 5건 그래서 9건이 이렇게 도정에 반영된 것으로 봤습니다.  ''95년도에 보면 대부분의 연구자료가 참고자료나 기초자료로 활용되었을 뿐이고 적극적으로 정책에 반영된 것은 제출된 자료로만 가지고도 2건밖에 지나지 않기 때문에 실질적으로 연구한 과제가 정책에 반영된 것이 상당히 미흡했다 이렇게 볼 수 있고요.  다행스러운 것은 ''97년도, ''98년도로 가면서 적극적으로 정책에 반영된 부분이 많이 늘어나고 있습니다만 반영된 내용을 보면 일부 어떤 방향제시에 대해서 연구한 내용을 그대로 쓰기보다는 일부 어떤 취지나 방향으로 가는 것까지도 적극적인 정책반영으로 되었기 때문에 실제적으로 반영되는 부분은 상당히 적은 부분에 지나지 않지 않겠느냐 이렇게 판단이 될 수밖에 없습니다.  그래서 제가 연구내용을 몇 가지 봤습니다마는 특히 오늘 제시해 주신 경기도통행유발원단위 산정방안에 대해서 조금 전에 제가 검토했고 또 이 부분에 대해서는 제가 결산검사하면서 도로건설부분에 예산 규모의 50% 이상을 차지하는 자본지출에서도 많은 부분을 차지하는 도로건설부분에 대해서 결산검사를 하면서 교통영향평가를 받은 부분이 상당히 적음을 알고 놀랐습니다.  그리고 교통영향평가도 제출해 주신 경기도통행유발원단위 산정방안에 보면 상당히 오차가 많다, 그리고 거기에 사용된 변수 자체도 상당히 실질적인 것이 아니다라고 지적해 주신 점에 대해서도는 이 연구가 상당히 심도있게 되어 있지 않느냐 이런 부분은 긍정적으로 평가할 수 있습니다.  그런데 제가 말씀드리고자 하는 것은 원단위 산정방안이 과연 경기도에서 즉흥적으로 사용할 수 있는 정도까지 실증적인 것이냐 하는 부분에 대해서는 약간 회의적이지 않느냐 이런 생각이 듭니다.  그 원인은 여기 제시된 모델 자체가 경기도와 충분히 상의돼 가지고 활용할 수 있는 현 단계까지 와 있는지, 아니면 이론적인 연구에 의해서 실제적으로 반영하지 못할 부분까지 변수로 잡아서 만들어 놓은 이런 위주의 모델인지를 제가 모르기 때문에 그 부분에 대해서 여쭙고요.  그래서 여기 산정된 모델방안이 과연 경기도에서 당장, 아니면 가까운 시일내에 활용할 수 있는 것인가 하는 부분에 대해서 답변해 주시기 바랍니다.    그리고 이 모델이 어느 정도 중요하느냐 하면 결산검사 하면서 놀란 것이 과연 이 도로가 다른 도로에 비해서 왜 우선순위를 가지고 개발이 되고 개설이 되고 확장 포장하느냐 하는 질문에 대해서는 어느 공무원도 답변을 못합니다.  단지 필요하기 때문에 한다, 하지만 우리가 알듯이 모든 도로는 다 필요합니다.  그렇지만 우리가 한정된 재원을 가지고 투자를 할 때 보다 합리적이고 보다 투자승수가 높은 그런 도로를 개설해야 되는데 거기에 대한 계량적인 그리고 계량적이 아니더라도 어떤 충분한 사유가 없다는 것이죠.  그래서 다른 도로와 비교분석한 데이터가 전혀 없는 상태에서 결정된다, 그래서 많은 예산이 낭비될 소지가 많다 이런 걱정을 했습니다.  그런데 다행히 이번 10월에 통행유발원단위 산정방안이 나왔기 때문에 아까같이 모델이 과연 실증적인 것이냐라는 질의를 드리고 만약에 실증적이라면 과감하게 도입할 수 있는 방안을 찾아야 되지 않겠느냐 하는 점에서 질의드렸습니다.
</p>
<p style="padding-left:1.2em">  그리고 두 번째로 질의드릴 것은 조금 아까도 거론했습니다만 정책에 직접적으로 반영되는 연구과제가 적다라고 지적했는데 그 원인을 한 번 검토해 보면 경기개발연구원 자체 목소리가 굉장히 작은 것 같습니다.  아까 말씀드린 대로 자이로와 같은 기능을 한다는 얘기는 객관적으로 나름대로 현재 도정이 흘러가는 방향을 분명히 좌표로 찍어서 앞으로 환경이 어떻게 변하니까 이런 방향으로 가야 된다라는 어떤 방향제시를 해야 되는데 현재까지 진행된 상황을 보면 경기도지사가 위탁하는 과제 그리고 각 실 국장이 위탁하는 과제 이것만 연구하다 보니까 실질적으로 당장 필요하지만 연구라는 것은 사실 충분한 기간이 필요합니다.  많은 자료를 검토해야 되고 실증적으로 검증도 해봐야 되고 많은 시행착오를 거쳐서 정책대안이 나오는데 충분한 시간도 주지 않고 며칠만에 연구과제를 내놔라 그러면 요구되는 결과치를 보여주는 수밖에 없기 때문에 어차피 거기서 예산을 받아 쓰는 처지에 그러지 않을 수가 없는 상황이니까 이런 현상이 자꾸 벌어지다 보면 실질적으로 대안제시가 안되고 도에서 제시하는 어떤 정책에 대해서 구색만 맞춰주는 결과가 되지 않겠느냐, 그래서 제 생각에는 위탁과제를 많이 줄이고 경기개발연구원이 탄생한지 벌써 4년째가 되어 가는데 이 정도 되면 자체적으로 내년도에 경기도의 거시지표는 어떠니까 현재 집행되는 정책 중에 어떤 것은 잘못됐고 앞으로의 정책은 어느 방향으로 나아가야 된다라는 자기목소리를 내주셨으면 기능을 제대로 하는 것이 아니겠느냐, 그렇게 돼야지만 경기개발연구원이 존재하는 목적을 달성할 수 있지 않겠나 이런 점에서 앞으로 자기 목소리를 내줄 수 있는 방향과 그런 계획을 원장님께서는 제시해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 세 번째는 연구환경에 대해서 질의드리겠습니다.  지금 전산실 운영이 69개의 PC로 돼 있는데 제가 의문을 갖는 것은 물론 전산 현황이 전혀 안나타나 있기 때문에 거기에 대해서 구체적으로 말씀은 못 드리겠습니다만 과연 아까 예를 든 경기도통행유발원단위 산정방안에 대해서는 분명히 모델을 여러 번 돌려야 되는, 컴퓨터에 넣고 여러번 돌려야 되고 자료도 입력해야 되고 그리고 이것 외에도 다른 연구를 하다보면 시뮬레이션도 해야 되고 그리고 각종 모델을 돌려야 되는데 거기에 걸맞을 정도의 용량을 갖고 있느냐, 아니면 간단하게 쓸 수 있는 PC정도만 돼 있어서 연구할 때 다른 데 위탁해서 거기에 별도의 비용을 지출하는가, 이것은 비용문제가 아니고 연구의 효율성을 위해서는 그 정도의 전산시설은 가지고 가야 하지 않느냐 그런 점에서는 다른 예산을 줄이더라도 그런 연구에 필요한 부속설비는 충분히 지원해야 되겠다는 점에서 그 부분에 대해서 사무처장께서는 답변해 주시고 그리고 원장님께서는 그 시설이 충분한지 안한지에 대해서도 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 업무보고하신 7쪽을 보면 대개 보면 연구부분을 아까도 유영록 위원님께서 지적했습니다마는 계속 늘어나는 과정에 있습니다.  그런데 연구부 운영이 늘어난 것은 물론 타당하고 적극적으로 권장할 만한 부분이지만 작년에 비해서 배로 증가한 부분은 내용을 알아야 되겠습니다.  그래서 그 부분이 왜 배 정도 늘었는지 그리고 그 타당성은 어떤 이유에서 거증될 수 있는지 그 부분에 대해서 사무처장께서는 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 경기개발연구원은 자체과제와 수탁과제 이렇게 나눠져 있는데 연구인력이 자체과제에 많이 투입돼야 되겠다 이런 관점에서 개인당 기준으로 수탁과제와 위탁과제의 비중이 ''95년부터 ''98년까지 어떻게 돼 있는지 중요한 부분은 답변해 주시고 자세한 부분은 자료로 제출해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 정운천 위원님 수고하셨습니다.  다음 연동현 간사님 질의해 주십시오. 
</p>
<p><b>○ 연동현 위원 </b> 연동현 위원입니다.  저는 중장기발전계획 및 경기1차 5개년계획에 대한 내용과 몇 가지 간단한 내용으로 해서 질의를 드리도록 하겠습니다.  정책실에서도 나와 계시니까 도지사의 공약사항에 중장기발전계획에 경기북도발전계획을 굉장히 중점적으로 사업 내지는 과제를 많이 제시한 부분이 있었습니다.  그리고 아까 정운천 위원님 말씀 중에서도 경기개발연구원에서의 지침과 제시하는 사항은 경기도 일환의 모든 총괄적인 사업 수뇌부가 아닌가라는 생각을 하면서 말씀드리도록 하겠습니다.  본 위원의 지역출신지가 연천이다 보니까 지역에 대한 말씀을 아니드릴 수가 없게 됐고요.  또 중장기계획에서 제시되고 도외시된 부분이 있는 것 같아서 말씀드리는 겁니다.  이번 계획에서도 연천군이 포함되어 있지 않고 앞으로 21세기 통일의 문턱에 다가서는 상황에 연천군이 계획에 아예 포함이 안돼 있다는 얘기는 통일을 준비하지 않겠다는 내용과도 같지 않겠느냐, 그러면 성문화와 말로만 해서 과제와 목표를 달성하겠다는 내용이 아니겠느냐 하는 얘기를 강하게 말씀드리고 싶은 마음입니다.  통일이 되면 최북단에 있는 연천지역을 지나지 아니하고는 지금 금강산개발과 금강산 관광이 이루어지고 있는 상황에 앞으로 경원선 열차가 복선화됨으로써 연천지역은 우리나라의 중앙에 위치하고 있는 지역이고, 본 위원이 생각할 때는 전문지식은 없습니다마는 앞으로의 종합적인 물류유통센터도 연천군에 위치가 돼야 되지 않겠느냐 저는 이렇게 생각하는 마음에, 저희 연천지역은 더욱이 재정자립도가 열악한 가운데 수탁계약을 하지 못하는 사항의 지역이기도 합니다.  그래서 유훈 원장님께 질의드린 사항은 연천군사업은 자체사업으로서 중장기계획으로 연구할 의사가 없으신지 그 부분까지 같이 말씀해 주시고요.  다음에 연구 자문위원과 비상임연구위원으로 해서 많은 연구과제를 책자를 통해서 세미나 등 해서 내주셨습니다마는 연구 자문위원이 지금 업무책자로 봐서는 20명, 비상임연구위원은 52명으로 되어 있는데 이 인원이 항시 부동적인지 유동적인지 그 부분하고 비상임연구위원이 연구하는 동안 경기개발연구원에서 경비지출을 어떠한 식으로 하고 있는지 그 사항도 내역을 통해서 말씀해 주시고요.  그 다음에 연구원들의 용역비 중 연구원에 납부한 금액에 대한 업무보고가 있습니다마는 ''97년도 계약금액이 22억 5,126만 6,000원, 일반회계 전출금이 3억 196만 1,000원 이렇게 돼 있습니다.  그런데 ''98년도에는 계약금액이 12억 2,063만 5,000원, 일반회계 전출금이 1억 6,857만 7,000원 이렇게 돼 있습니다. 
</p>
<p>그러면 전년 대비 차이나는 원인이, 물론 경제적으로나 또 수탁사업에서도 있는 것인지 모르겠습니다만 그러한 원인이 무엇인지 말씀해 주시고요.  다음에 ''95년도에 경기도 31개 시 군별 성장잠재력 종합평가와 지역경제 육성방법에 대해서는 서면으로 제출하여 주시기를 부탁드리겠습니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 연동현 간사님 수고하셨습니다.  다음은 위원님들의 질의에 대한 답변을 듣도록 하겠습니다.  조금 전에 말씀드렸다시피 다음 감사일정이 바쁩니다.  그렇기 때문에 유훈 원장님을 비롯한 각 연구부장께서는 요지만 간단히 답변해 주시고 서면답변으로 요구하지 않는 사항이라도 이 정도는 꼭 위원님들에게 보고드리고 싶다하는 사항이 있으시면 서면답변으로 해 주시기 바랍니다.  경기개발연구원장 나오셔서 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 답변을 드리겠습니다.  위원님들이 질의하신 순서에 따라서 말씀을 드리겠습니다.  먼저 이남형 위원님께서 질의하신 내용에 대해서 답변을 드리겠습니다.  저희가 현재 기금이 200억원 있습니다.  그런데 이 위원님께서는 중 장기적으로 자체기금을 얼마나 확보할 계획인가, 또 과거의 그러한 계획이 있다면 그 내용을 밝히면 좋겠다는 말씀이 계셨습니다.  저희가 과거에 연구원의 기금이 350억원 정도는 돼야 되겠다는 계획을 세운 바 있습니다.  2001년에 350억원 정도는 기금이 조성돼야지 그 기금의 이자를 가지고 연구원을 운영할 수 있겠다고 생각했습니다.  그런데 그 후에 예기치 않았던 수질환경연구소가 설립되고 그 다음에 교통문제연구센터 같은 것을 설립하면 좋겠다는 도의 요청이 있었습니다.  그리고 아시는 바와 같이 현재 이율이 자꾸 떨어지고 있습니다.  그래서 연 10%도 안 되는 수준입니다.  앞으로 연리 8.5% 정도로 떨어질 것이 아니냐 이렇게 예측하고 있습니다.  그래서 만일에 저희 연구원을 기금으로 운영한다면 500억원은 가져야 하지 않겠느냐 이렇게 생각하고 있습니다.  그런데 500억원 정도의 기금을 조성하기 위해서는 민간기업에서 출연을 받는다고 하더라도 아무래도 도에서 많은 출연이 있어야 되겠다 이렇게 생각하고 있습니다.  그래서 도가 연간 50억원 정도의 출연은 해줘야 500억원이 달성되겠다 이렇게 저희들이 생각했습니다.  그런데 도에서 매년 경기개발연구원을 위해서 어려운 형편에 50억원씩 출연하기는 어렵다고 판단하신 것 같습니다.  그래서 내년도부터는 기금출연에서 도비보조로 전환하는 정책을 도가 채택해서 31억원의 도비보조를 예산안에 반영했습니다. 
</p>
<p style="padding-left:1.2em">  다음에 도비보조금이나 출연금은 언제 저희 연구원의 계좌에 입금시켜 주느냐는 말씀이 계셨는데 도가 비교적 이 문제에 대해서는 저희 요구에 잘 응해 주고 있습니다.  대체로 출연금의 경우는 연초 1월중에 저희 계좌에 입금시키고 도비보조금도 결정되면 과거에는 일시에 계좌에 입금시켜 줬습니다마는 금년에는 조금 어려워 가지고 두 번에 나눠서 입금시켜 줬습니다마는 그것도 비교적 저희가 원하는 시기에 저희 계좌에 입금시켜 줬다고 하는 것을 말씀을 드리겠습니다.  
</p>
<p style="padding-left:1.2em">  그 다음에 저희 연구원의 이직률에 대한 질의가 계셨습니다.  저희 연구원에 그간에 이직한 사람이 다 합해서 5명입니다.  그런데 현재 25명인데 이직률이 그렇게 높은 편이 아니라고 생각합니다.  그 중에 한 사람은 다른 연구원의 원장으로, 한 사람은 집이 부산인데 부산연구원으로 가면 좋겠다고 해서 갔고 세 사람은 금년 초에 대학으로 갔습니다.  그래서 다 합해서 5명인데 이 정도면 이직률이 높은 편이 아니라고 생각하고 비교적 저희 연구원들이 현재 연구분위기에 자족을 하고 있다고 생각하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음에 수탁용역사업 수익이 어떻게 계상이 되느냐는 질의가 계셨는데 저희가 수탁과제의 20%를 일반회계 전입금으로 책정하도록 하고 있습니다.  그런데 외부에 우리가 다시 하청을 주는 경우에는 하청준 금액을 뺀 나머지 금액의 20%를 일반회계 전입금으로 계상하도록 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 아까 장서 구입방법에 대해서 질의가 계셨는데 우선 자료실에서 장서구입을 위해서 목록을 배부합니다.  각 연구원들에게 목록을 배부하고 각 연구원으로부터 신청을 접수하고 그 다음에 신청된 도서목록을 가지고 신청목록을 작성해서 자료관리위원회의 심의에 부칩니다.  선임연구원 한 사람, 책임연구원, 사무과장, 자료전산실장 이렇게 5명으로 구성된 자료관리위원회가 있습니다마는 여기서 심의를 거쳐 가지고 원장의 승인을 얻어서 최종적으로 결정하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 저희 기금의 운용사항이라든지 특히 특정금전신탁에 대해서는 나중에 사무처장께서 일괄해서 말씀을 드리겠습니다.  그 다음에 자체연구, 수탁연구사업이 어떻게 결정이 되느냐는 질의가 계셨습니다.  자체연구는 과거에는 저희가 자체개발도 했습니다마는 그간에 도의회 사무감사 때마다 있었던 말씀이 얼마나 정책에 반영이 됐느냐, 정책에 반영되지 않은 추상적인 연구만 하는 것이 아니냐는 질책이 많이 계셨습니다.  그래서 저희가 정책에 반영될 수 있는 연구를 해야 되겠다 해서 금년에는 추천과제를 대부분 하고 자체개발을 조금 했습니다마는 내년에는 전적으로 도와 도의회에서 추천한 과제만을 저희가 선정했습니다.  이렇게 하는 것이 정책에 잘 반영되는 길이라고 생각했습니다.  그래서 추천과제가 들어오면 저희가 각 부에 리스트를 줘 가지고 각 부에서 대체로 어떠한 과제를 선정하면 좋겠다고 하는 것을 검토해 가지고 원장한테 제출하면 원장이 이것을 주로 부장들로 구성된 위원회에 부의합니다.  그래서 그 위원회의 심의를 거쳐 가지고 20명 정도로 구성되는 연구자문위원회의 심의를 거쳐서 자체연구를 확정하도록 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 수탁연구는 주로 도나 시 군에서 저희에게 용역을 주는 겁니다.  그러니까 이것은 저희가 하느냐 안 하느냐는 결정을 내리는 외에는 별로 선택의 여지가 없다고 하겠습니다.  좀더 자체연구나 수탁연구를 결정함에 있어서 광범위한 의견을 들으면 좋겠다는 말씀이 계셨는데 저희가 현재는 도나 도의회에서 추천된 과제도 다 소화를 하지 못하기 때문에 좀더 광범위한 추천을 받기는 어려운 실정입니다마는 다만 아까 말씀드린 바와 같이 연구자문위원회, 주로 대학교수들입니다.  이런 사람으로 구성된 연구자문위원회에서 그분들의 의견을 저희들이 충분히 반영해서 연구과제를 결정하고 있다는 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음에 중소기업의 유통구조라든지 어음제도에 대해서 좀더 연구를 하는 게 좋겠다는 말씀이 계셨는데 앞으로 적극 반영하겠습니다.  그 다음에 연구과제에 있어서 연구자는 어떻게 결정하고 연구기관은 어떻게 결정하느냐는 질의가 계셨는데 연구자는 아까 말씀드린 바와 같이 도나 도의회에서 추천된 과제를 가지고 각 부에서 연구자를 대체로 선정합니다.  이것은 각자의 희망에 따라서 연구자를 결정합니다.  그리고 기간은 아까 말씀드린 바와 같이 내부의 위원회, 그리고 연구자문위원회 이러한 과정을 거치기는 합니다마는 아주 짧은 경우에는 6개월동안에 연구를 완성하고 아주 긴 경우에는 12개월로 합니다마는 대체로 연구자가 연구기간을 결정해서 그것이 아까 말씀드린 내부의 위원회 또는 연구자문위원회를 거치는 과정에서 타당하다고 인정되면 그대로 연구기간이 결정됩니다.  그리고 지방공사의 중장기계획에 대한 질의가 계셨는데 이것은 나중에 신원득 박사가 말씀을 드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 1연구원 1시 군담당제도에 대해서는 여러 위원님들께 서면으로 배포를 했습니다.  그 다음에 지역연구는 이남형 위원님의 말씀을 적극적으로 반영해서 저희가 김포연구부터는 끝난 다음에 현지에 가서 세미나 겸 출판기념회를 갖도록 결정했습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 1연구원 1시 군담당제에 있어서 대개 어떠한 교류를 하느냐, 또 방문빈도는 어느 정도이고 어떠한 사람들과 접촉을 하느냐는 그런 질의가 계셨는데 저희가 각 시 군에 담당자를 결정하도록 공문을 보내서 각 시 군에서 대체로 기획계장을 저희 카운터 파트로 정해 주셨습니다.  그래서 저희 연구원들이 시 군에 가면 주로 자기 카운터 파트와 접촉하는데 주로 기획계장이 저희 카운터 파트로 지정돼 있습니다.  방문빈도는 저희가 한 분기에 한 번으로 생각했습니다.  그래서 그렇게 하려고 노력했습니다마는 금년에는 조금 늦게 시작했고 저희가 원체 업무량이 많아서 바쁜 관계로 5월 22일 하루종일 시 군의 관계자들과 면담을 하고 돌아와서 출장보고서를 제출하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음에는 윤동욱 위원님께서 질의한 정책에 반영된 과제가 얼마나 되고, 반영되지 않은 과제가 얼마나 되느냐 이것은 서면으로 좀더 구체적인 것을 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  그 다음에 장현수 위원님께서 질의하신 내용이 되겠습니다.  지방공사와 경기개발연구원을 통합한다는 신문보도가 있었는데 사실이냐는 질의였습니다.  이것은 사실무근입니다.  제가 도의 관계자들과도 확인해 봤습니다만 전혀 그러한 논의가 없었다고 합니다.  그리고 저희 경기개발연구원을 서울시정개발연구원 수준으로 질적으로 향상을 시키기 위해서 도가 굉장히 많은 노력을 하고 있고 도지사께서도 그런 말씀을 여러 번 하셨습니다.  그리고 그 방안으로서 내년도에 31억원의 보조금을 예산안에 반영했다는 말씀은 아까도 드렸습니다.  지방공사와 저희 경기개발연구원은 역시 그 기능이 다르기 때문에 통합할 수가 없을 것으로 압니다.  어떻게 해서 그런 얘기가 나왔는지 저희도 많이 궁금하게 생각합니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 독립청사 확보방안이 있느냐는 말씀을 하셨습니다.  저희가 사실은 우만동에 대지를 확보해서 거기다가 독립청사를 짓는 방안을 구상하고 있었습니다.  그런데 지금 IMF체제 하에서 청사를 짓겠다고 말씀을 드리기도 어렵고 해서 독립청사 건설방안은 저희가 많이 주저하고 있었습니다마는 최근에 공무원교육원과 같은 곳에 있는 지방행정연구원이 서울로 이사를 갔으면 좋겠다 그런 제안이 저희한테 왔습니다.  그러면서 경기개발연구원이 살 수가 없겠느냐, 자기들 청사를 사주면 자기들이 그 돈에 보태 가지고 서울 가서 독립청사를 구입하겠다는 것이었습니다.  그래서 제가 지금 인천부시장으로 간 남기명 실장하고 협의했습니다.  이러한 제안이 있는데 어떻게 하면 좋겠느냐 그랬더니 42억원 정도가 들었답니다.  1년에 42억원을 줄 수 없으니까 3년 할부상환으로 교섭을 해 보라고 그래서 제가 교섭을 했습니다.  마침 지방행정연구원 원장이 제 제자였기 때문에 협의했더니 3년 연분상환이 좋다고 해서 저희가 현재 지방행정연구원 청사를 구입하는 방안을 구상하고 있습니다.  지사님께도 말씀을 드려서 지사님의 내락을 받았습니다.  그런데 지사님은 3년이 아니라 5년상환으로 하라는 말씀이 계셨는데 어쨌든 지사님도 지방행정연구원 청사가 바람직한 청사 확보방안이 되겠다고 하는 데 동의를 하셨습니다.  그래서 나중에 저희가 상세한 내년도 예산안을 드리겠습니다마는 저희가 그래서 내년도 1차년도 분으로 15억원을 예산에 반영했습니다.  그런데 그 15억원은 현재 두 군데 임차하고 있는데 그 임차보증금 7억원이 있습니다.  그래서 임차보증금 7억원에다가 도비보조 8억원을 보태서 15억원으로 우선 1차년도 분을 저희가 지급하고 그리고 이사하는 것으로 현재 계획을 세우고 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 장 위원께서 지역연구에 관한 말씀을 하셨고 내년도에는 안성시를 지역연구의 대상으로 삼으면 좋겠다는 말씀이 계셨습니다.  저희가 시의원, 도의원님들과 그렇게 많이는 면담하지 않습니다마는 필요한 분들과는 저희가 면담도 갖고 있습니다.  그런데 여러 위원님들이 그런 말씀이 계셨는데 앞으로는 좀더 많은 시의원, 도의원님들과 면담을 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  유영록 위원님께서....... 
</p>
<p><b>○ 위원장 고수복 </b> 자리에 안 계신 위원님들 질의사항은 서면으로 답변해 주세요.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> IMF 이후에 저희 연구원의 연구과제를 좀더 실천중심의 단기과제로 전환해야 하지 않느냐, 여전히 추상적인 연구과제만을 연구하는 것이 아니냐 그런 질의가 계셨습니다.  저희가 실천적인 과제를 연구하려고 노력하고 있습니다.  그래서 아까도 말씀드린 바와 같이 자체연구과제를 선정하는 과정에서도 도나 도의회에서 추천하는 과제를 선정하도록 노력하고 있고 또 아까도 말씀드린 바와 같이 단기정책과제는 그야말로 실천적인 과제입니다.  너무 시간이 촉박해서 저희가 충분히 시간과 노력을 들이기는 어렵습니다마는 어쨌든 실천과제라고 하는 면에서는 단기정책과제는 정책에 반영될 수 있는 과제라고 말씀을 드릴 수가 있겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 수질환경연구소의 내년도 연구과제를 보면 조금 느슨한 감이 있다, 특히 민간환경단체의 역할이라고 하는 연구과제도 들어있다는 말씀이 계셨는데 이것도 도 의원님께서 추천한 과제이고 누군가 해야 되는데 결국은 수질환경연구소 소장으로 있는 성 박사가 이것을 연구하기로 했습니다.  그 밖의 과제들은 다 수질과 직접적으로 관계가 있는 과제라는 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 재정자립도가 열악한 시 군에 대한 연구를 많이 하면 좋겠다는 말씀이 계셨습니다마는 저희가 금년도의 정책과제로도 하고 있습니다마는 내년도에 경기북부지역의 발전방안에 대해서 저희가 내년 1/4분기 내에 연구를 완료하도록 하고 있습니다.  지금 도지사님 말씀에 의하면 북부지역개발에 관한 연구가 완성되면 그것을 가지고 중앙정부하고 담판해서 중앙정부의 지원을 얻어내겠다는 말씀이 계셨습니다.  그래서 북부지역의 재정자립도가 열악한 시 군에 대한 연구가 이루어질 수 있을 것으로 압니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 시 군에서 수탁한 용역비가 얼마인가 그러한 질의가 계셨는데 ''98년도 총 수주금액은 12억 2,000만원인데 이 중에서 시 군에서 수탁한 과제는 5억 3,000만원이 되겠습니다.  그 다음에 가평군의 연구에 대해서는 여기 김군수 박사가 대기하고 있습니다.  나중에 가평군 연구를 책임지고 있는 김군수 박사가 가평군의 장기발전계획에 대해서는 조금 더 구체적으로 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음에 정운천 위원님 질의에 대한 답변을 드리겠습니다.  연구한 과제가 도정에 얼마나 반영됐느냐는 말씀이 계셨는데 어쨌든 저희가 도정에 반영될 수 있는 과제를 연구하기 위해서 최선의 노력을 다하고 있고 그 방안의 하나로서 아까도 누누이 말씀드린 바와 같이 도나 도의원님들이 추천한 과제를 일차적으로 연구과제로 선정하고 있다는 말씀을 다시 한 번 드립니다.  그리고 금년에 연구한 과제에 대해서 아주 깊은 질의가 계셨는데 지금 지우석 박사가 대기하고 있습니다.  그래서 나중에 지우석 박사가 조금 더 구체적으로 말씀을 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  자기 목소리를 내면 좋겠다는 말씀이 계셨는데 이게 자기 목소리하고 정책에 반영된다고 하는 것하고 어떻게 보면 이율배반적인 관계에 있다고 말씀드릴 수가 있습니다.  그래서 사실은 자기 목소리를 내려면 자체개발 연구과제를 많이 해야 되는데 그러려면 그게 도정에 반영이 됐느냐는 질의가 많이 나옵니다.  그래서 저희는 자기 목소리를 낸다고 하는 목표하고 도정에 반영될 수 있는 과제를 연구한다는 목표 이러한 이율배반적인 목표를 어떻게 조화시키느냐에 대해서 상당히 고민하고 있습니다.  그래서 어느 쪽에 우선권을 부여할 것이냐 하는 것이 저희의 어려운 난제라고 말씀드릴 수 있겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 앞으로 조금 더 연구원들이 보강이 되면 우리 정 위원님이 말씀하시는 자기 목소리를 내는 문제, 그 다음에 다음년도의 경기전망 이런 등등의 문제에 대해서 깊이있는 연구가 가능하리라 생각합니다.
</p>
<p style="padding-left:1.2em">  그리고 저희 연구환경에 대한 질의가 계셨습니다.  특히 자료실의 전산장비현황은 어떠냐는 말씀이 계셨습니다.  지금은 주로 B, C급입니다.  그런데 내년도 예산에는 전산장비 구입을 위해서 2억원 정도의 예산을 책정해서 내년도까지 대형 컴퓨터도 구입하는 것으로 계획하고 있습니다.  그 다음에 그것이 불가능했던 이유는 저희가 세들어 있기 때문에 언제 나가야될 지 모르기 때문에, 랜을 깔면 이사할 때 문제가 되기 때문에 저희가 독립청사가 확보되면 내년에 랜도 깔고 대형 컴퓨터도 구입하는 것으로 생각하고 있습니다. 
</p>
<p><b>○ 정운천 위원 </b> 죄송합니다만 지금 연구는 어디서.......
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 주로 PC를 가지고 하고 꼭 필요한 경우에는 외부에 가서 하는 것으로 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 자체과제와 수탁과제 맨먼스 배정문제에 대한 질의가 계셨습니다.  그런데 대체로 저희 한 사람이 자체과제는 한 과제, 그리고 수탁과제는 한 사람이 대체로 2개 내지 4개 과제를 담당합니다.  아까 위원님의 질의에 그런 얘기가 있었는데 현재 보고서에는 수탁과제에는 연구책임자만 나와 있습니다.  자체과제는 연구책임자가 연구자입니다.  그런데 수탁과제의 경우에는 저희 보고서에는 연구책임자만 나와 있습니다마는 그 연구과제를 위해서 굉장히 많은 사람들이 연구에 종사하고 있습니다.  예를 들면 저희가 시흥시 장기발전계획을 연구하는데 시흥시 장기발전계획의 경우에는 15명이 연구에 종사합니다.  그러다 보니까 한 사람이 자체과제 외에도 수탁과제를 2건 내지 4건 그렇게 담당하고 있습니다.  평균 한 사람이 3건 정도의 수탁과제를 담당하고 있습니다.  그러니까 사실 어떻게 보면 굉장히 업무량이 많다고 말씀드릴 수 있는데 저희가 밤일을 해서라도 이러한 업무량을 소화는 하고 있습니다마는 역시 연구의 질에 영향을 준다고 생각합니다.  그래서 저희가 내년도에는 조금 더 연구원을 증원하는 것으로 생각하고 있습니다.  그리고 대개 자체과제와 수탁과제 맨먼스 배정에 관한 질의가 계셨는데 이것은 저희가 계산을 해 가지고 서면으로 답변을 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음에는 연동현 위원님의 질의가 되겠습니다.  연천지역에 대한 연구를 한 일이 있느냐 그런 질의가 계셨는데 저희가 ''97년도에 연천군 장기발전계획을 수탁과제로 수행을 했습니다.  연천군이 없는 돈에서 저희 연구원에 용역을 주셔서 연천군의 장기발전계획을 수탁과제로 수행을 했습니다.  장기발전계획을 수행하는 과정에서 여러 가지 안을 내기는 했습니다마는 연천군의 재정사항이 원체 열악해서 그러한 장기발전계획을 수행하는 데에는 상당히 어려움이 있는 것으로 생각을 했습니다.  
</p>
<p style="padding-left:1.2em">  그리고 또 한 가지 말씀드릴 것은 아까도 잠시 말씀드렸습니다마는 내년도에는 접경지역을 포함한 북부지역발전계획을 도에서 저희 연구원에 용역을 줄 계획으로 있습니다.  그래서 저희가 1억 5,000만원 정도의 예산을 들여가지고 내년 1/4분기에 완료해서 도에 제출하면 도에서 이것을 중앙정부와 지원방안을 협의할 예정으로 있다고 듣고 있습니다.  
</p>
<p style="padding-left:1.2em">  그 다음에 자문위원에 관한 말씀이 있겠습니다.  자문위원에는 아까도 잠시 말씀을 드렸습니다마는 임기가 2년인 대학교수들입니다.  이 사람들이 한 번 출석을 하면 수당 10만원을 지급하고 있습니다.  현재 1년에 두 번 정도로 자문위원회를 개최하고 있습니다마는 자문위원들은 좀더 빈번히 회의를 가지면 좋겠다는 요청이 있습니다.  그래서 현재는 대체로 20명 전원이 모이는 전체회의만 가집니다마는 앞으로 가능하면 분과별로 나누어서 자문위원회를 개최하려고 생각하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 비상임연구원에 관한 질의가 계셨습니다.  비상임연구원은 상당히 필요하다고 생각을 하는데 지난 번 감사원 감사에서 지적이 있었습니다.  연구원에 박사도 25명이나 되는데 무엇 때문에 비상임연구원을 활용하느냐는 질의가 있어서 내년도에는 비상임연구원을 많이 줄이려고 생각합니다.  아주 특별히 필요한 경우 외에는 비상임연구원을 활용하지 않는 방향으로 계획을 하고 있습니다.  비상임연구원은 대체로 월간 60만원 내지 100만원 정도로 그 사람의 경력에 따라서 다릅니다마는 예를 들면 전임강사급 정도는 60만원, 정교수는 100만원 이런 수준으로 수당을 지급하는데 아주 긴 경우에는 4, 5개월 비상임연구원을 활용하는 경우도 있고 단기간에 걸친 경우에는 2개월이나 3개월 또는 1개월짜리 비상임연구원도 간혹 있습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 대체로 제가 답변드릴 것은 그 정도입니다마는 먼저 제가 미처 답변을 드리지 못한 특히 재정이라든지 행정에 관한 사항은 처장께서 보고말씀을 드리고 또 구체적인 연구사업에 관한 보고는 신원득 박사, 김군수 박사, 지우석 박사가 이어서 보고를 드리도록 하겠습니다.  그러면 먼저 처장님 나오시죠.  
</p>
<p><b>○ 위원장 고수복 </b> 잠깐만요, 그냥 진행할까요?
</p>
<p><b>○ 이남형 위원 </b> 답변을 마저 다 듣고 하죠.
</p>
<p><b>○ 위원장 고수복 </b> 네, 답변해 주시기 바랍니다. 
</p>
<p><b>○ 사무처장 표찬섭 </b> 기금관리사항에 대해서 이남형 위원님과 유영록 위원님께서 질의하신 사항을 답변해 드리겠습니다.  업무보고 4페이지에 수록된 내용 중에서 유영록 위원님께서 다른 것은 10% 이상의 이율이 되는데 왜 금년 10월 26일 예금한 한미은행의 40억원에 대해서는 9.7%를 했느냐 라고 말씀해 주셨습니다.  이것은 저희가 자금이 만기되면 시중금리를 일제히 조사를 합니다.  그래서 당시에 저희가 7개 은행을 조사한 결과 예를 들면 국민은행은 8.5%, 주택은행은 9.9%, 신한은행은 9.1%, 하나은행이 9.1%, 외환은행이 9.1%, 상업은행이 9.9% 그리고 한미은행이 9.7%였습니다.  그래서 당시에 제일 이율이 높은 데로 예탁을 했습니다.  
</p>
<p style="padding-left:1.2em">  그리고 이남형 위원님께서 여기에 대한 만기가 언제냐고 말씀하셨고 또 퇴출된 경기은행에 10억원의 특정금전신탁이 어떻게 된 것이냐고 질의를 하셨습니다.  여기에 대한 것은 4페이지 예탁현황에 나온 것을 보면 예탁일자하고 예탁기간이 쭉 나와있습니다.  그리고 예탁기간 내에는 1년부터 3년까지 있습니다마는 이것은 확정금리로 돼 있는 사항입니다.  그리고 특정금전신탁에서 거기에 대한 경유를 자세히 보고드리겠습니다.  제가 이것은 별도 유인물을 배부해 드리면서 그 유인물에 의해서 간략히 보고를 드리겠습니다.  먼저 예치현황을 보고드리면 예치금융기관은 전 경기은행에 10억원을 ''97년 1월 14일부터 2000년 1월 14일까지 3년 만기 연리 12.5%로 예치를 했습니다.  당시에 타 상품금리는 10% 내외였습니다.  다음 신탁자금 운영사항에 대해서 보고를 드리겠습니다.  전 경기은행에서 본원에서 신탁한 10억원을 갚고 중앙리스에 9억 5,500만원, 금호할부금융에 2,300만원, 새인천중기에 1,300만원을 각각 신탁하고 그리고 나머지 900만원은 현금으로 관리를 했었습니다.  문제발생의 경우는 위원님들께서 잘 아시겠습니다마는 지난 9월 29일자로 금융구조조정 개편에 따라서 5개 은행이 퇴출되고 또 퇴출됨으로써 5개 은행에 대한 금융업무정지와 동시에 인수은행이 계약이전결정명령서에 특정금전신탁 상품이 제외됨으로써 그후에 여신업무가 중단됐던 것입니다.  
</p>
<p style="padding-left:1.2em">  다음장을 참고해 주시기 바랍니다.  그러면 금방 중도해지 등의 조치를 취하지 못한 사유로서는 당시 경기은행의 퇴출여부에 대한 여러 가지 설이 있었고 또 퇴출이 되어도 예치금에 대한 원리금 보장에는 이상이 없다는 논란이 대두되었습니다.  그리고 퇴출당시 중도해약을 할 경우에는 7,900여만원의 원금손실이 됨으로써 중도해지결정에 상당히 어려움이 있었습니다.  또한 참고로 말씀드리면 9월까지의 약정금리에 대해서는 일자를 어기지 않고 계속 수입이 잡혔었습니다.  그리고 그간 저희들이 조치한 사항으로는 손실보전을 위해서 경기은행의 재산인 경기은행 수원지점의 이 건물이 되겠습니다.  이 건물 등 부동산 3건 하고 신경기상호신용금고에 예치한 410억원에 대한 가압류를 했고 또 9월 19일자에는 경기은행 안양지점 등 3개 지점에 대한 전세권을 가압류 조치한 바 있으나 10월 26일자로 경기은행의 파산선고로 인해서 모든 효력이 상실된 상태에 있습니다.  한편 도 산하기관 중 특정금전신탁에 예치한 기관과 연대를 해서 채권확보를 위한 전문가의 법률상담이라든가 소송수행도 준비 중에 있습니다.   
</p>
<p style="padding-left:1.2em">  다음 페이지를 참고해 주시기 바랍니다.  그러면 앞으로의 전망에 대해서 보고를 드리겠습니다.  금감위하고 예금보험공사에서 지정한 회계법인에서 신탁한 업체에 대한 자산을 실사한 결과 신탁총액 10억원 중에서 회수가능한 금액이 8억 1,500만원 정도 예상됩니다.  펀드사별로는 금호할부금융은 정상은행으로 2,300만원 전액이 회수 가능하고 중앙리스는 신탁금 9억 5,500만원 중에서 82%인 7억 8,300만원이 회수 가능하고 현금보관 중인 900만원은 전액 회수가 가능하도록 돼 있습니다.  그리고 회수불가능 금액인 1억 8,500만원은 펀드사별로 보면 새인천중기가 1,300만원인데 이 회사는 지난 7월 13일자로 부도가 났습니다.  그리고 앞에서 말씀드린 중앙리스는 1억 7,200만원이 되겠습니다.  신탁금액의 95%를 차지한 중앙리스채는 가교리스사인 한국리스주식회사와 협의를 한 결과 신탁금액의 82%인 7억 8,300만원의 수준에서 회수가 가능하고 지급방법은 가교리스사에서 매월 회수된 채권액을 3개월 단위로 10% 수준의 이자를 지급하고 나머지 금액을 갖고 신탁금액 비율에 따라 원금을 상환하도록 협의가 돼서 리스채 원금회수 소요기간은 약 3년에서 5년 이내로 예상되겠습니다. 
</p>
<p style="padding-left:1.2em">  한편 11월 30일까지 저희가 경기은행 파산관제법인에 신탁재산 채권신고를 한 후에 진행상황에 따라 대처방안을 강구하고 인수은행인 한미은행과 고객입지 차원에서 원금보전에 대한 방안을 협의 중에 있습니다.  그런데 한미은행 측에서 상당히 긍정적으로 협의가 되기 때문에 원금보전에 대하여는 무리없이 협의될 전망으로 있습니다.  또한 법률전문가와 계속 실익여부를 협의해 가지고 소송수행방법도 검토 중에 있음을 보고드리면서 이상 보고를 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  다음에는 정운천 위원님께서 ''97년도 하고 ''98년도를 비교해 볼 때 연구비가 상당히 증가된 이유가 뭐냐고 말씀하셨습니다.  저희 연구원에서는 서울시 시정연구원 수준으로 연구원을 대폭 인력보강할 계획을 갖고 있습니다.  그래서 내년도에는 연구원을 26명에서 38명으로 12명을 확충할 계획으로 3억 8,900만원이 증가됐고 또 연구사업도 금년도에는 25개 과제였습니다마는 앞으로 증원할 박사급에 1과제씩 연구과제를 주기 위해서 34과제로 예산을 편성해서 증가된 것이 1억 2,900만원이 되겠습니다.  또한 관내 대학과의 합동연구비를 3억원 정도 계상했고 아까 원장님께서도 말씀하신 독립청사 확보비로 15억원을 계상했습니다.  또한 수질환경연구소 운영비에 연구기자재 확보라든가 기타 해서 1억 3,800만원을 추가로 확보했습니다. 
</p>
<p style="padding-left:1.2em">  다음에는 연동현 위원님께서 질의하신 ''97년도와 ''98년도 전출금에 차이가 났는데 그 사유는 뭐냐라고 말씀하셨습니다.  아까 이것은 원장님께서도 말씀드렸습니다마는 저희가 수탁사업 용역을 하면 다시 재위탁하는 비용을 제외한 금액의 20% 범위 내에서 일반회계 자원으로 전입금을 잡아서 그것을 우리가 자체적립이라든가 일반 연구사업비에 충당을 하고 있습니다.  그래서 ''97년도에는 18건의 계약금이 21억 5,100만원이고, ''98년도에는 10건의 계약금으로 12억 2,000만원을 입금해서 그 차이가 생겼던 것입니다.  이상 답변을 마치겠습니다. 
</p>
<p><b>○ 총괄기획연구부장 신원득 </b> 이번에 경기지방공사 중장기경영계획 연구책임을 맡고 있는 신원득입니다.  이번 중장기경영계획은 여러 위원님께서 아시다시피 지방공사가 탄생한지 1년 남짓한 상태에서 앞으로 경기지방공사의 미래상을 어떻게 정립할 것인가 이런 것이 절실히 요청돼 가지고 저희 연구원에 대해서 미래의 비전을 제시하는 용역을 의뢰한 것이 되겠습니다.  이 결과물은 얼마 전에 나왔어야 되나 현재 지방공사에서 여러 가지 외부 여건변화로 인해서 좀더 요청한 사항이 있어서 지금 원고 재교 중에 있습니다.  그래서 아마 가제본한 상태로 나와있습니다.  그것은 이번달 말까지는 완성품이 나오는데 다만 추가적인 내용을 삽입하는 관계로 며칠 늦어지고 있습니다.  
</p>
<p style="padding-left:1.2em">  경기지방공사의 중장기계획 내용을 간단히 요약해서 말씀드리겠습니다.  경기지방공사 중장기경영계획은 크게 다섯 부분으로 나누겠습니다.  첫째는 경영의 기조가 되겠습니다.  지금 환경적으로 보면 지방공기업에 대한 민영화라든지 아니면 여러 가지의 많은 한계점이 나타나고 있고 경기지방공사가 대표적인 지방공기업으로서 앞으로 어떻게 헤쳐 나가야 될 것인지에 대해서 이론적 근거라든지 실효성 그리고 경기도에서의 위치한 위상 이런 것을 정립해 줌으로 인해서 경기지방공사가 어떻게 경기도에 기여하고 이런 것을 하나의 경영기조로 삼았습니다.  
</p>
<p style="padding-left:1.2em">  특히 이 경영기조에서는 크게 연구를 세 부분으로 나눴는데 한 부분은 이게 막연한 중장기경영계획이 아니고 실효성을 높이기 위해서 단기경영계획, 말하자면 ''98년부터 4개년계획을 연차별로 세웠고, 이것은 연차별 계획이 되겠습니다.  그리고 중기계획은 6년간, 장기계획은 10년간 이렇게 해서 단기, 중기, 장기로 3단계로 구분해서 계획을 만들었습니다.  특히 저희들이 계획을 만들면서 중점을 두고 있는 사항은 과거에 지방공기업이라고 하면 주로 공공성 측면에서 많이 부각했지만 현재 지방자치단체에서 지방경영이라는 모토를 가지고 운영하는 실정에서 볼 때 경기지방공사도 과거처럼 공공성에만 한정돼서 할 것이 아니고 수익성이라는 차원도 상당히 중점을 둬야 된다는 차원에서 경영계획의 방향을 설정했습니다.  말하자면 공공성과 수익성을 동시에 확보할 수 있는 차원에서 경영계획을 수립했다 이렇게 말씀드릴 수 있겠습니다.  또 한편으로는 경기도 지역경제에 지방공사가 어떻게 기여할 것인지 하나의 틀을 정립해 가지고 경기도에서 경기지방공사가 얼마만큼 기여할 수 있고 또 경기도민을 위해서 바람직한 기업이 되겠는가 이런 것에 착안해서 했습니다.  
</p>
<p style="padding-left:1.2em">  두 번째로는 사업영역을 설정했습니다.  현재 지방공사 같으면 경기도에만 있는 것이 아니고 각 광역자치단체에 많이 있습니다.  그러나 그 명칭을 보면 주로 도시개발공사라고 돼 있습니다.  예컨대 서울시 도시개발공사, 광주 도시개발공사, 부산 도시개발공사 이런 개발공사로 돼 있기 때문에 그 주력사업이 주로 주택건설이라든지 택지개발 이런 것에 한정돼 있습니다.  그러나 지금 단계적으로 볼 때는 IMF라는 한파가 닥쳐있고 중장기적으로는 볼 때는 과연 토지에 대해서 효율적 개발이 이런 사업으로서 한정될 것인지 상당히 의문이 있습니다.  그래서 중장기경영계획에서는 사업영역을 도시개발 차원, 소위 말해서 택지개발이라든지 이런 토지자원비용 차원에서 한정할 것이 아니고 앞으로는 연계화된 시설문제, 예컨대 어떤 건물을 지었다 그러면 그것을 관리하고 어떻게 이용할 것인지, 말하자면 관광지 개발 같으면 관광지를 개발한 다음에 그것을 어떻게 관리하고 경영할 것인지를 일련의 흐름에 따라서 지방공사가 사업을 해야 된다 또 하나는 해외사업부문에 지방공사가 적극 나서야 된다는 것입니다.  
</p>
<p style="padding-left:1.2em">  그러니까 해외무역관계도 지금 경기도에 있는 경기무역관이라든지 KOTRA 지사라든지 많은 기관이 있지만 실질적으로 경기도의 중소기업 아니면 경기도 무역을 대신해 주는 기관은 없습니다.  그래서 경기지방공사에서 차제에 공공개발이나 이런 시설사업 뿐만 아니라 해외사업 쪽으로 눈을 돌려가지고 그런 사업을 다각화함으로 해서 지방공사가 앞으로 살아남고 위상을 확립해야 된다는 차원에서 사업영역을 설정하는 데 저희들이 이론적인 근거를 제시하고 그런 모형을 제시함으로 인해서 지방공사의 중장기경영계획 아래서 사업영역 구성을 이렇게 타당성있게 정립했다는 것이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  세 번째로는 사업부문의 실천계획을 정립했습니다.  금방 말씀드린 첫 번째나 두 번째는 상당히 구상적으로 돼 있지만 이런 중장기경영계획은 구상의 차원에서 그칠 것이 아니고 실질적으로 과연 앞으로 투자비는 얼마나 될 것이고, 그러면 그 투자비에 따라서 사업을 한 결과 추정되는 이익은 과연 어느 정도 발생할 것인지 이런 것을 사업별로 다 추정했습니다.  예컨대 공공개발 측면에서는 산업단지라든지 유통단지, 택지개발, 임대주택, 관광지개발의 여러 가지 사업을 하나하나 저희들이 다 따져서 실천계획을 세웠고 두 번째로 시설사업 같은 경우는 경기도에서 많이 발생하고 있는 환경처리기초사업에 대한 전망 그리고 앞으로는 현재와 달리 문화복지 수요가 많이 나오고 있는데 이런 문화복지에 대한 사업, 해외사업 무역거래라든지 이런 것을 하나하나 따져서 사업부문별 실천계획을 단계별로 설정했습니다.  
</p>
<p style="padding-left:1.2em">  그리고 네 번째는 경영관리수단을 정비했는데 필수적으로 조직 및 인력관리방안, 마케팅전략 이런 것을 경영관리수단으로 정비했습니다.  그래서 금방 말씀드린 네 가지 단계를 종합해서 경기지방공사의 미래상을 정립했는데 간단히 말씀드리면 실천계획을 통해서 투자비 같은 경우는 단기계획에 약 8,000억원이 들어갔는데 중기계획은 약 1.5배, 장기계획은 약 2.5배 이렇게 설정했고 추정된 기대이익 자체도 단기계획에 비해서 중기계획은 2.2배, 장기계획은 3.8배 이런 구체적인 수치까지도 저희들이 제안을 했습니다.  
</p>
<p style="padding-left:1.2em">  말하자면 경기지방공사의 중장기계획은 저희들이 말한 구상자체가 아니고 실천계획까지 담당함으로 인해서 지방공사가 앞으로 어떻게 나가야 되고, 중장기경영계획이 끝나는 2018년에는 어떤 모습을 정립해야 될 것인지 단계별로 설정한 것을 말씀드리겠습니다.  아마 여기에 관해서는 경기지방공사의 행정사무감사시 좀더 보완적인 설명이 있을 걸로 생각됩니다마는 위원님께 제가 부탁드리고 싶은 것은 지방공사가 사실 여러 가지 국내외적으로 굉장히 어려운 실정에 있습니다.  그럼에도 불구하고 이런 중장기경영계획을 비롯해서 많은 적극적인 사업의지를 가지고 있다는 것을 밝혀두고 지방공사의 행정사무감사시 많은 아량이 있기를 부탁드립니다.  감사합니다. 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 다음에 김군수 박사, 가평군 장기발전계획. 
</p>
<p><b>○ 이진용 위원 </b> 발전계획을 말씀하시기 전에 여러 위원님들의 이의가 없다면 서면으로 받는 걸로 하겠습니다, 가평군에 국한된 것이기 때문에.  그렇게 하고 제가…….  
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 아까 원단위에 관한 질의를 하셨습니다.  원단위에 관한 말씀을 드릴까요? 
</p>
<p><b>○ 정운천 위원 </b> 오래 걸리면 간단히 요점만 말씀해 주시고 나머지는 서면으로 해주시면 고맙겠습니다. 
</p>
<p><b>○ 지우석 박사 </b> 경기도 통행유발 원단위 설정방안에 대해서 연구한 지우석입니다.  제 연구보고서에 대한 질의의 요지를 요약하면 첫째, 보고서에서 제시된 모형이 이론적인가 아니면 실제 적용이 가능한 것인가 하고 둘째는 적용 가능하다면 언제부터 쓸 수 있는가 이렇게 요약할 수 있겠습니다.  결론만 간단히 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  보고서에서 제시된 산정모형은 실제 적용을 위한 모형이며 모형결과인 원단위를 사용할 수 있는 시점은 모형의 결과가 통계적 유의성을 가질 수 있을 만큼 충분한 데이터가 확보된 시점입니다.  그렇기 때문에 신뢰성있는 데이터를 확보하기 위해서 데이터인프라라는 이름으로 데이터를 수집 관리하는 체계를 제시한 바 있습니다.  현재 경기도에서는 일회성으로 조사되고 또 바로 사장되고 있는 데이터를 모아서 그것을 분석할 수 있는 기관까지 제가 제시를 하였습니다.  이상입니다. 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 네, 보고를 마쳤습니다.  
</p>
<p><b>○ 위원장 고수복 </b> 다음은 보충질의를 하는 순서가 되겠습니다마는 위원장으로서 사전에 위원님들에게 양해를 구하고자 하는데 어떠십니까?  보충질의는 서면으로 하고 서면답변으로 받았으면 하는데 어떠시겠습니까?  
</p>
<p><b>○ 정운천 위원 </b> 죄송합니다마는 보충질의는 간단간단하게 일문일답식으로 해서 여기서 끝내는 것이 더 나을 것 같은 생각이 듭니다. 
</p>
<p><b>○ 위원장 고수복 </b> 그러면 그렇게 하도록 하겠습니다.  보충질의를 하도록 하겠습니다.  보충질의를 하실 위원께서는 거수로 신청하여 주시기 바랍니다.  정운천 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정운천 위원 </b> 안산의 정운천입니다.  답변 잘 들었습니다.  그리고 많은 부분이 수긍이 가기 때문에 몇 가지만 보충질의를 드리겠습니다.  아까 원장님께서 말씀하신 도정에 반영될 수 있는 과제선정과 자기목소리를 내는 부분에 대해서는 이율배반적인 것도 있지만 제가 보는 관점에서는 자기목소리를 가지고 도정에 반영될 수 있는 필요한 과제를 미리미리 선정해서 연구에 임한다면 연구기간이 상당기간 확보될 수 있기 때문에 보다 충분한 연구가 돼서 자세하고 실현가능한 연구결과가 나올 수도 있는 반면에 지금과 같은 방법을 계속 유지하게 되면 도에서 요구하는 자료를 주어진 시간 내에 하기 때문에 연구내용이 불충분할 수도 있고, 그리고 연구과제를 선정하다 보면 당장 필요한 것만을 선정하기 때문에 방향성을 잃어버릴 수도 있고 또 시기적절하게 연구결과가 도정에 반영할 수 있는 시기를 놓칠 수도 있기 때문에 그런 면에서 오히려 이율배반적인 면보다는 같이 갈 수 있는 두 마리의 토끼가 아닌가 이렇게 생각도 됩니다.  그점에 대해서 한 가지 질의를 드립니다. 
</p>
<p style="padding-left:1.2em">  또 하나는 아까 모델에 대해서, 적용시기에 대해서 지 박사님께서 말씀하시면서 교통데이터 인프라를 빨리 구축해야 되겠다고 말씀하셨는데 물론 저도 봤습니다.  그것을 도에다 정식적으로 제의해서 이게 제가 보기에는 굉장히 중요한 내용이기 때문에 당장 실천가능할 수 있도록 실천방안과 데이터 수집계획까지도 제시를 해주셨으면 하는 아쉬움이 있었습니다.  그래서 그 부분을 추가적으로 답변해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 제가 다 말씀드리겠습니다.  우선 자기목소리를 내는 것하고 정책에 반영되는 연구하고 조화시킬 수 있는 방안이 있다는 말씀을 하셨습니다.  저도 거기에 전적으로 동감합니다.  그래서 내년도에는 저희가 주로 도하고 도의회에서 추천한 과제만 자체연구과제로 선택했습니다마는 앞으로 가능하면 자체개발과제도 저희가 선정해서 연구하되 정책에 반영될 수 있는 그런 실천적인 연구를 하도록 노력을 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 원단위에 관한 연구와 관련해서 질의가 계셨는데 저희가 매년 연구가 끝나면 도에다 정책건의라고 하는 것을 공문으로 냅니다.  물론 저희 연구보고서 말미에도 정책건의가 있습니다만 그것을 다시 공문으로 해서 보고서와 함께 도에다 냅니다.  정책건의에 이제 정 위원님이 말씀하신 것을 충분히 반영해서 도에서 될 수 있는 대로 빨리 인프라를 구축하도록 그렇게 촉구를 하겠습니다.
</p>
<p><b>○ 위원장 고수복 </b> 이진용 위원님 보충질의 해 주시기 바랍니다.
</p>
<p><b>○ 이진용 위원 </b> 한두 가지만 질의드리겠습니다.  재정자립도가 낮은 지역을 우선 지역연구의 대상지역으로 선정했으면 좋겠다는 말씀에 대한 답변이 다소 불충분해서 구체적으로 현재의 기준은 어떻게 돼 있는지 그것을 알고 싶고요.  그 다음에 본 위원이 직접 질의드린 그런 기준을 채택할 수 있는 가능성에 대해서 간단하게 말씀해 주십시오.  그 다음에 시 군발주 연구과제 용역비가 5억 3,000만원이 수주가 됐는데 그것을 과제별로 나눠서 서면으로 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 그러면 한 가지는 서면으로 답변드리고 처음에 질의하신 재정자립도가 낮은 지역을 지역연구의 대상으로 삼을 수 없느냐 그런 질의의 말씀인데 현재 지역연구의 대상지역을 선정하는 기준은 대개 지역안배를 합니다.  그래서 내년도에는 북부, 남부, 동부 이렇게 지역안배를 합니다.  그런데 이런 지역안배를 하는 경우에도 될 수 있으면 재정자립가 낮은 지역을 선정할 수 있다고 생각합니다.  그래서 위원님의 말씀을 명심해서 내년도에는 가능하면 저희가 선정한 지역내에서도 재정자립도가 낮은 지역을 선정하도록 노력하겠습니다.  아까 위원님마다 자기 출신구를 선정해 달라는 그런 요청이 많이 있어서, 그리고 아까 나가시면서 장 위원님이 안성시를 꼭 내년도에 지역연구의 대상으로 삼아달라고 그러셨는데 위원님 말씀을 저희가 유념해서 될 수 있으면 재정자립도가 낮은 지역을 대상으로 삼도록 노력하겠습니다.
</p>
<p><b>○ 위원장 고수복 </b> 이남형 위원님 보충질의해 주시기 바랍니다.
</p>
<p><b>○ 이남형 위원 </b> 시간도 많이 흘렀고 유훈 원장님께서 제가 충분히 이해할 수 있게 답변해 주셨기 때문에 간략하게 두서너 가지만 여쭤보겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 연구원 수탁용역사업과 관련해서 마련된 2억 8,800만원에 대해서 과제별, 일시별, 연구원별 적립내역을 서면으로 제출해 주시기 바랍니다.  두 번째로는 1연구 1인 1시 군 담당책임자 제도와 관련해서 당해 시 군에 방문한 이후에 출장보고서를 작성하는 것으로 답변을 주셨는데 제가 고양시출신이다 보니까 고양시 방문결과에 대해서 나중에 서면으로 제출해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그 다음에 유훈 원장님께서 지역연구사업과 관련해서 이번에 최초로 김포시에서 출판기념회겸 세미나를 개최하신 것에 대해서는 대단히 감사하게 생각합니다.  또한 한 가지 더 말씀을 올리면 중소기업 육성에 관해서 많은 관심을 기울여 주시고, 아까도 제가 말씀드렸습니다만 판매망 구축이라든지 어음제도 개선방안에 대해서 유 원장님께서는 적극 반영하시겠다고 답변을 주셨는데 이 문제는 굉장히 중요한 문제라고 본 위원은 생각하기 때문에 앞으로도 많이 연구해 주시기 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그리고 일반행정문제와 관련해서는 여기보면 한미은행이라든지 ''98년도 연초에 각종 예금에 가입한 부분들은 지금 수익률이 연이율이 16.7%로 돼 있는데 이게 3년간의 기간이라고 답변하셨습니다.  그래서 이 시기에는 IMF 직후에 금리가 다들 아시는 것이지만 무척 많이 치솟았습니다.  그래서 사실 한때는 회사채 3년만기 같은 금리는 34, 35%까지 육박한적이 있었는데 어떻게 보면 결과적으로 잘 됐다 이런 판단을 합니다.  아주 운영을 잘하셨다고 보여지고 다만 경기은행 특정금전신탁에 관해서 자료로 주셨는데 이부분에 대해서 한 가지만 여쭤보고 마무리하겠습니다.  자료를 보니까 경기은행에다가 특정금전신탁자금 10억원을 경기개발연구원에서 맡겼고 경기은행은 중앙리스에다가 상당부분의 금액 즉 9억 5,500만원 정도를 맡겼던 것으로 알고 있습니다.  내용이 그렇게 나와 있는데요.  그런데 중앙리스도 문제가 생겨서 한국리스에서 가교리스사가 새로 선정이 된 것으로 돼 있습니다.  그리고 한국리스(주)하고 협의해 보니까 약 7억 8,300만원이 회수가 가능하다 이렇게 돼서 천만다행이라고 생각합니다.  그런데 3개월 단위로 연 이자율 10% 수준으로 해서 지급이 되고 리스채 원금에 대해서는 3년 내지 5년이 예상된다, 이렇게 나와 있는데 이것은 실질적으로 회수가 가능한 건지 그부분을 정확히 답변해 주시면 좋겠습니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 두 가지는 서면답변을 드리도록 하고 그 다음에 제가 구체적으로 말씀 못드렸는데 김포시 지역연구에 대한 행사는 그냥 단순한 출판기념회수준이 아니고 연구원 세 사람이 가서 그 지역연구의 결과를 간단히 보고를 드리고 그 다음에 김포지역에서 토론자가 몇 분이 나오도록 그렇게 되어 있습니다.  그래서 그분들의 토론을 듣고 그리고 흔히 하는 출판기념회식의 간단한 리셉션을 가져서 그렇게 하고 있습니다.  앞으로도 이런 지역연구가 나올 때마다 저희가 현지에 가서 지금 김포시에서 계획하고 있는 것과 같은 그런 출판기념회를 가지도록 노력을 하겠습니다.  그리고 중소기업 판매망이나 어음제도개선 이런 데 대해서는 저희가 앞으로 적극적으로 연구하도록 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  그리고 기금에 대해서는 처장이 상세히 말씀드리겠습니다만 저희는 현재 한미은행측에서 원금은 보전해 주겠다 그런 약속을 저희한테 하고 있습니다.  그래서 그 표에 보시면 저희가 ''98년 10월 26일에 40억원을 한미은행 수원지점에 예탁한 것으로 그렇게 되어 있습니다.  연리 9.7% 1년 6개월 예치기간인데 이것을 저희가 한 이유는 이것이 상호신용금고에 맡겼던 건데 상호신용금고와 조금 문제가 있어서 늦게 받기는 했습니다만 원금하고 이자를 충분히 다 받았습니다.  그리고 40억원을 어디에다가 예탁을 할 것이냐를 많이 고민했습니다만 한미은행측에서 자기들에게 기금을 많이 맡기면 특정금전신탁 원금 보전을 적극적으로 하겠다 그런 약속이 있어서 저희가 40억원을 한미은행에다가 예탁을 하고 한미은행측에서 특정금전신탁에 적어도 원금보전에는 적극적으로 협력해 줄 것으로 기대하고 있습니다. 약속을 이행하리라고 생각하고 있습니다.  아까도 처장께서 말씀드렸습니다만 한미은행이 지금 저희 연구원뿐만 아니라 중소기업재단도 있고 또 문화재단도 있고 경기도의 기금을 많이 유치하기 위해서 특정금전신탁에 돈이 몰린 기관에 대해서 원금보전을 해주겠다는 그런 약속을 하고 있습니다.  그래서 그 사람들도 역시 저희한테 기대는 게 있기 때문에 약속이행을 할 것으로 저희는 지금 생각하고 있습니다.
</p>
<p><b>○ 이남형 위원 </b> 한미은행에서 약속을 하고 있으니까 저도 회수되기를 바라고 있습니다.  뒷부분을 보시면 중앙리스를 인수한 한국리스(주)가 지금 정상적인 절차에 따라서 만약에 회수한다면 여기 나와 있는 내용을 보면 3년 내지 5년 이내로 회수가 예상된다, 이렇게 돼 있는데 한미은행에서 물론 당연히 지금 원장님 말씀처럼 원금상환에협조적으로 해 주시기를 저도 바라고 있고 사실 그렇게 될 것으로 판단은 되지만 만에 하나라도 그렇게 안될 경우에는 지금 이 내용만 보면 한국리스로부터 7억 8,300만원에 해당하는 원금회수가 가능한 것으로 돼 있거든요.  그래서 제가 한 가지 더 여쭤보고 싶은 것은 이 부분이 정말 현 시점에서 한미은행과 사적인 약속이 아니고 공적인 방법으로 7억 8,300만원을 회수할 수 있는 것인지 그 부분만 정확하게 말씀해 주시면 좋겠습니다. 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 그것은 한미은행측하고 교섭한 것이 아니고 가교리스회사하고 저희가 얘기를 하고 있습니다.  그것은 가교리스회사 쪽의 얘기기 때문에 저희는 그것이 적어도 7억 8,300만원 정도는 원금이 회수가 될이 확실한 것으로 생각하고 있습니다.  그런데 저희가 여러 가지 지금 방안을 생각하고 있습니다.  그중의 하나는 소송을 제기하는 것입니다.  저희뿐만 아니라 경기은행에 특정금전신탁을 맡긴 기관들이 공동으로 소송을 제기하는 방법도 최후의 경우에는 저희가 구상하고 있습니다.  저희가 소송을 제기할 금고도 저희 나름대로 있다고 생각해서 여러 가지 지금 방안을 저희가 강구중에 있습니다.  그래서 이러한 원금회수가 잘 안될 경우에 대처방안도 생각하고 있습니다. 
</p>
<p><b>○ 이남형 위원 </b> 이 부분은 제가 판단할 때도 경기은행이 어느 누구도 생각하지 못할 정도로 갑자기 퇴출당하고 이렇게 되다 보니까 불가피한 사유라고 봅니다.  물론 특정금전신탁이 금리가 약간 높았기 때문에, 금리 이자관계 때문에 여기다가 예탁하신 것으로 알고 있는데 충분히 그렇게 된 사유에 대해서는 그렇게 이해를 하겠고 지금 원장님 말씀하신 것처럼 가급적이면 빠른 시일내에 어떤 방법을 통하든 회수하실 수 있도록 각별히 신경써 주시기를 부탁드립니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 한 가지만 더 첨가해서 말씀드리면 확정적인 것은 금년 12월에 결정이 난다고 합니다.  그러니까 그것을 기다려 보고 그 다음에 저희가 후속조치를 강구하겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b>  다음 질의하실 위원님, 연동현 간사님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 연동현 위원 </b> 원장님께 질의가 아니고 1997년도에 수탁업무로서 연천군 장기발전계획의 책자자료 좀 구할 수 있겠습니까? 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 보고서 드리겠습니다. 
</p>
<p><b>○ 연동현 위원 </b> ''95년도에 경기도 31개 시 군별 성장잠재력 종합평가와 지역경제 육성방안이라는 이 보고서도 구할 수 있겠습니까? 
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 그것도 드리겠습니다. 
</p>
<p><b>○ 연동현 위원 </b> 이것을 꼭 좀 부탁드리겠습니다.  네, 이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 정운천 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 정운천 위원 </b> 다른 위원들께서 질의하실 것 같아서 제가 아까는 빠뜨렸습니다만 아까 경기지방공사 중장기경영계획에 대해서 신 박사님께서 충분히 설명해 주셨습니다마는 한 가지 부분에 대해서 궁금한 점이 있습니다.  아까 세 번째 사업부문별 실천계획에 있어서 추정이익을 추정해서 제시하셨다는데 물론 실질적으로 하셨지만 빠뜨리신 것 같아서 다시 여쭤봅니다.  그것이 캐쉬플로우(cashflow) 수준으로 해서 현재가치로 할인된 금액에서 추정이익을 산출하신 건지 아니면 총계개념으로 미래가치로 해서 가격을 서로 비교해서 투자비하고 회수금액과 비교해서 추정이익을 하시는지.  왜 그러느냐 하면 경기지방공사에서 제출된 자료를 보니까 추정이익이라는 것을 현재가치로 하지 않고 그냥 어느 시점에서의 현금 아웃플로우(outflow)하고 인플로우(inflow)를 비교해서 추정이익을 한 것 같아서 그 부분에 대한 설명을 해 주시고, 또 하나는 모델을 만드실 때 여기경기지방공사는 가장 중요한 것이 자금 확보같은데 중장기경영계획을 하시면서 자금조달계획이 어떤 대안으로 제시된 게 있는지 그것에 대해서 설명해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 유훈 </b> 제가 간단히 말씀드리겠습니다.  현재가치로 환산하지 는 못했습니다.  현재가치로 환산한 것은 아니고 그쪽에서 자꾸 추정이익을 내라고 해서 저희가 조금 주먹구구식인 그런 추정이익이라는 것을 말씀드리고요.  그 다음에 자금 확보방안은 사실은 지방공사가 저희한테 용역을 주고 마지막에 저희한테 무엇을 요청했느냐 하면 이것을 가지고 경기도에 가서 우리가 브리핑을 하고 그리고 경기도에서 이것을 뒷받침해 주겠다는 약속을 받아 줬으면 좋겠다, 그러한 상당히 무리한 요구를 했습니다.  신현득 박사가 상당히 많이 고민하고 그랬는데 먼저 남기명 실장하고 그 문제에 대해서 협의도 했습니다마는 용역받은 데서 그런 의무까지 질 것 뭐 있느냐, 경기도는 그러한 브리핑을 받을 수도 없고 자금확보에 대해서 경기도가 약속하기가 어렵다 그런 말씀이 있었습니다. 
</p>
<p><b>○ 정운천 위원 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 더 질의하실 위원님 안 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 제가 위원장으로서 유훈 원장님과 답변에 임해 주신 관계자 여러분에게 부탁의 말씀을 드리겠습니다.  지금 서면으로 답변하실 문제가 있는데 이 점에 대해서 말씀드리겠습니다.  지금 바쁘셔서 또 개인사정으로 답변을 다 듣지 못하고 보충질의를 하지 못하시고 가신 위원님들이 계십니다.  보충질의는 정말 아주 심도있게 검토하셔서 질의하신 위원님들로 하여금 명쾌한 답변이 되도록 준비해 주시면 감사하겠습니다.  저를 비롯한 여러 위원님들은 유훈 원장님을 비롯한 답변에 임해 주신 관계자 여러분의 인격을 믿고 또 이 나라 학자이시고 석학이시라는 것을 굳게 믿고 있습니다.  이상입니다.  이상으로 경기개발연구원에 대한 질의 답변을 마치도록 하겠습니다.  위원 여러분들께서 그동안 열의를 갖고 감사에 임해 주신 데 대해 감사의 말씀을 드립니다.  그리고 유훈 원장을 비롯한 연구원 관계자 여러분께서도 행정사무감사를 위해 자료준비와 위원님들의 질의에 성실히 답변해 주신 데 대해 감사드립니다.  오늘 여러 위원님들께서 감사시에 지적해 주신 사항은 도민의 뜻이니 만큼 이를 겸허하게 받아 들여서 연구원 업무수행에 적극 반영하도록 최선의 노력을 다해 주시기를 부탁드립니다.  여러분 수고하셨습니다.  그러면 이것으로 경기개발연구원에 대한 ''98년도행정사무감사를 종료할 것을 선언합니다. 
</p>
<p class=''ar''>                                                            (13시35분 감사중지)
</p>
<p class=''ar''>                                                            (15시28분 감사계속)
</p>
<p><b>○ 위원장 고수복 </b> 좌석을 정돈하여 주시기 바랍니다.  지금부터 지방자치법제36조, 동법시행령제16조 및 경기도의회행정사무감사및조사에관한조례에 의하여 경기지방공사에 대한 1998년도행정사무감사 실시를 선언합니다.
</p>
<p style="padding-left:1.2em">  안녕하십니까?  기획위원장 고수복 위원입니다.  오늘은 기획위원회 감사일정에 따라서 경기지방공사에 대한 행정사무감사를 실시하게 되었습니다.  여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 집행부의 행정사무전반에 관한 실태를 파악하여 지방의회 의정활동과 ''99년도 예산안심사시 활용하며 아울러 이를 도정시책에 반영하고자 함이 그 목적인 만큼 감사에 임하는 지방공사사장님과 임직원 여러분께서는 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.  연일 계속되는 감사일정으로 노고가 많으신 감사위원 여러분께서도 도민을 대표하여 경기지방공사의 운영실태를 감사하는 것이니 만큼 각 부분별로 세밀하게 검토하시어 소기의 성과를 거둘 수 있기를 당부드리면서 원활한 감사진행을 위하여 많은 협조가 있으시기를 바랍니다.  끝으로 행정사무감사를 위하여 애쓰신 지방공사 관계 직원 여러분께 감사드리며 간단히 인사에 갈음합니다.  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다.  감사를 받는 경기지방공사사장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하게 됨으로써 먼저 선서를 하셔야 하며 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 1998년도행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다.  만약 증인이 허위증언을 할 때에는 지방자치법제36조제5항과 경기도의회행정사무감사및조사에관한조례제30조규정에 의하여 고발될 수 있으며 증언 또는 진술을 거부할 때에는 동법 동조항 규정에 의하여 500만원 이하의 과태료를 부과할 수 있음을 알려드립니다.  그러면 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (기  립)
</p>
<p style="padding-left:1.2em">  먼저 증인출석 여부를 확인하겠습니다.  경기지방공사사장 나왔습니까?
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 경기지방공사부사장 나왔습니까?
</p>
<p><b>○ 경기지방공사부사장 김현구 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 총무이사 나왔습니까?
</p>
<p><b>○ 경기지방공사총무이사 이춘욱 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 총무부장 나왔습니까?
</p>
<p><b>○ 경기지방공사총무부장 박정규 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 개발부장 나왔습니까?
</p>
<p><b>○ 경기지방공사개발부장 윤오근 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 사업부장 나왔습니까?
</p>
<p><b>○ 경기지방공사사업부장 신삼철 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 무역부장 나왔습니까?
</p>
<p><b>○ 경기지방공사무역부장 한규영 </b>네.
</p>
<p><b>○ 위원장 고수복 </b> 외자유치부장 나왔습니까?
</p>
<p><b>○ 경기지방공사외자유치부장 이동주 </b> 네.
</p>
<p><b>○ 위원장 고수복 </b> 다음은 선서의 요령을 설명드리겠습니다.  선서는 증인을 대표해서 지방공사사장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 오른손만 들어 주시면 되겠습니다.  그러면 선서해 주시기 바랍니다.
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 선서!  본인은 경기도의회가 지방자치법제36조, 동법시행령제16조제1항경기도의회행정사무감사및조사에관한조례제2조의 규정에 의하여 소관업무에 대한 1998년도행정사무감사를 실시함에 있어 기관장으로서 성실하게 감사를 받을 것이며 또한 증인으로서 증언함에 있어서는 지방자치법시행령제17조의4제5항과경기도의회행정사무감사및조사에관한조례제18조의 규정에 의하여 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다.  1998년 11월 26일 증인 경기지방공사사장 민병균, 부사장 김현구, 총무이사 이춘욱, 총무부장 박정규, 개발부장 윤오근, 사업부장 신삼철, 무역부장 한규영, 외자유치부장 이동주.
</p>
<p><b>○ 위원장 고수복 </b> 자리에 앉아 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  (착  석)
</p>
<p style="padding-left:1.2em">  다음은 경기지방공사사장께서 나오셔서 인사와 함께 간부소개를 해 주시고 업무보고를 해 주시기 바랍니다.
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 안녕하십니까?  경기지방공사사장 민병균입니다.  오늘 존경하는 기획위원회 고수복 위원장님과 여러 위원님들을 모신 가운데 저희 경기지방공사 행정사무감사를 수감하여 지도편달을 받게 된 것을 매우 뜻깊게 생각합니다.  그동안 의정활동을 통하여 도민 복지증진과 도정발전에 많은 노력을 기울이고 계신 가운데서도 경기지방공사에 대한 여러 위원님들의 각별한 관심과 끊임없는 성원에 진심으로 감사의 말씀을 드립니다.  지난해 12월 1일 경기도공영개발사업단 업무를 인수하여 출범한 경기지방공사는 IMF 경제위기와 부동산 경기침체 상황에서도 이 극복을 위하여 최선의 노력을 경주하고 있습니다.  외국인투자자 유치와 민간개발자들과의 합동개발 방식 등 다각적인 지역 확보 방안을 강구하고 있습니다.  한편 도차원에서도 역점사업으로 추진하고 있는 외국인 투자자 유치를 위하여 지방공사에서는 지난 8월 17일자로 행정자치부의 정관개정인가를 받아 업무를 전담할 외자유치부를 신설하였으며 금번 구조조정에 즈음하여 업무의 보다 능동적인 수행을 위하여 외자유치 1팀과 2팀으로 구분하여 운영하고 있습니다.  지방공사 전 임직원들은 어려운 경제 여건 속에서 도민과 항상 함께하는 봉사정신으로 도민의 기대에 부응하는 공기업으로 발전하여 도민 복지증진과 지역 균형개발 촉진을 위한 공사의 역할을 충실히 해 나갈 것입니다.아무쪼록 경기지방공사가 건실한 공기업으로 발전 도약할 수 있도록 위원님들의 각별한 관심과 지속적인 지도편달을 부탁드리겠습니다.  업무보고를 드리기에 앞서 먼저 지방공사 임원과 간부를 소개해 올리겠습니다.  먼저 김현구 부사장님.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 이춘욱 총무이사입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  다음 박정규 총무부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  신삼철 사업부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  윤오근 개발부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  한규영 무역부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이동주 외자유치부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이번에 외자유치전문직으로 두 명을 채용했습니다.  김문덕 전문위원입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  부동산개발을 담당하고 있습니다.  또 한 명인 박병문씨는 지금 일본에서 하고 있는 부동산투자유치로드쇼에 참석해서 이 자리에 배석을 못했습니다. 
</p>
<p style="padding-left:1.2em">  다음은 배부해 드린 유인물에 의해서 경기지방공사의 주요업무사항을 보고드리도록 하겠습니다.  보고드리기에 앞서 지난 제124회, 제128회 임시회시에 질의하신 사항에 대한 지방공사의 처리결과를 보고드리도록 하겠습니다.  별도 유인물로 돼 있습니다.  지난 제128회임시회의 때 서영석 위원께서 경기도공영개발사업단 인수당시 재무현황과 미분양택지 용지현황 및 추진대책에 대해서 질의하신 바가 있어 지난 9월 16일 동 자료를 보고드렸습니다.  이진용 위원께서는 5개년간 추정손익계산서에 대한 질의가 있어서 9월 16일 자료를 제출해 드렸습니다.  그리고 지난 제124회임시회의시에 황교선 위원께서 ''98년도 추정손익계산서와 중장기계획에 대한 보고를 해 달라고 해서 3월 7일 보고를 모두 마쳤습니다.  그 중 중장기계획에 대해서는 본 업무보고를 끝낸 뒤에 영상물을 통해서 별도 보고드릴 준비가 돼 있습니다.  양해해 주신다면 지난 9월 3일 제128회임시회 업무보고 내용 중 일부 변경된 내용을 중심으로 해서 보고를 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  보고드릴 내용은 일반현황, ''98년도 업무총괄, 주요 추진업무 현황순으로 보고를 드리도록 하겠습니다.  먼저 업무보고입니다.  3페이지를 봐 주십시오.  설립목적, 자본금, 임무 기능은 보고를 생략드리고 주요 연혁 중 지금 근무하고 있는 건물이 지난 10월 1일 사옥 건축 준공을 하여 10월 29일 사옥을 이전하였습니다.  총 사업비는 128억원, 건평은 3,392평입니다. 
</p>
<p style="padding-left:1.2em">  다음에 조직 변경사항에 대해서 보고를 드리도록 하겠습니다.  지난 8월 17일 종전 조직의 상임감사가 있었습니다마는 비상임감사로 조직을 바꾸고 감사업무는 경기도의 감사관이 그 업무를 대행하도록 조직이 변경되었으며 이 때 외자유치 전문직 3명을 채용했습니다.  그리고 경기도의 조직개편과 관련해서 당초에 8명의 비상임이사가 5명으로 조정되어서 현재 운영하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 4페이지가 되겠습니다.  사장 아래에 해외담당 부사장을 두고 그 해외담당 부사장 밑에 무역부와 외자유치부를 관장토록 했으며 사장 밑에 업무이사는 업무부, 사업부, 개발부를 관장하도록 조직을 운영하고 있습니다.  이 조직개편과 아울러서 당초에 정원이 60명이었습니다마는 정부의 정책에 의해서 정원조정이 57명으로 감원이 됐습니다.  그 중 2명은 감사와 사업이사 자리를 없애면서 같이 정원조정을 했고 나머지 1명은 ''99년도에 감원을 하라는 정부의 지침이 내려와서 내년에 1명을 감원할 계획으로 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 ''98년도 총괄부분을 보고드리겠습니다.  먼저 ''98년도 예산규모가 되겠습니다.  총 규모 1,393억원으로 세입 세출을 맞추고 있습니다.  세입예산은 용지매출이 622억원, 무역매출이 56억원, 지역개발기금 등 218억원, 전기미수금 183억원, 전기이월금 240억원, 기타 74억원으로 구성돼 있으며, 지출예산은 용지조성사업비 422억원, 분양주택건설비 194억원, 무역매출원가 54억원, 지역개발기금 등 135억원, 차기이월금 506억원, 기타 82억원으로 조성돼 있습니다.  개발사업은 금년도에 607억원의 사업비를 예상하고 있으며 택지부분에 2개 사업지구 365억원, 산업단지 1개 지구에 39억원, 주택건설 2개 사업지구에 121억원, 관광단지 2개 사업지구에 9억원, 기타 업무근린시설에 73억원의 사업비가 들어갈 계획으로 진행하고 있습니다.  해외지원사업은 금년도에 수출입 400만달러를 계획하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 경영효율성 제고에 관한 부분을 보고드리겠습니다.  주요성과는 조직운영의 효율화를 위해서 외차유치촉진 전담기구를 설치했습니다.  또한 경영혁신을 위해서 유사기능 수행부서의 통합운영과 위인설관이 아닌 업무중심 조직운영을 하고 동태적 업무수행을 위한 테스크포스팀제를 적극 활용하여 추진하고 있습니다.  인력운영은 경영혁신을 위한 인력감축 3명으로서 현재 정원 57명으로 운영하고 있습니다.  그리고 ''99년도부터는 능력위주의 연봉제 도입을 검토하고 있습니다.  또한 공사 중장기비전 설정을 위한 중장기 경영계획을 수립했습니다.  이것은 본 보고가 끝난 후에 별도 영상물로 보고를 드리도록 하겠습니다.  사업영역 다각화를 위해서 남한강정비사업에 대한 위 수탁을 추진하고 있으며 임대사업을 계속 추진하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 8페이지 주요 추진업무에 대해서 보고드리겠습니다.  적극적인 외자유치를 위해서 투자유치의 기본방향을 설정하고 투자유치 추진방안을 설정해서 공사 자체의 프로젝트를 추진하고 있으며 도내 타 기관과 일반기업의 추진 프로젝트를 지원하는 업무를 하고 있습니다.  투자유치 대상사업은 기존 프로젝트인 축령산리조트와 어연 한산산업단지에 대한 프로젝트를 계속 투자유치사업으로 추진하고 있으며 신규예상 프로젝트로서는 복합시설과 리조트사업, SOC사업과 동 시설유치, 기업체 연계를 통한 M＆A 등 제 활동을 전개할 계획으로 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 10페이지 외자유치 추진전략에 대해서 보고를 드리겠습니다.  외자유치는 3단계로 구분하여 첫 단계에서 외자유치 기반구축을 하고 2단계에서 해외유치선을 다변화시키며 3단계에서는 개발부분의 국제화를 꾀하는 방향으로 업무를 추진코자 합니다.  먼저 1단계는 내부업무 추계정비와 정보시스템을 구축하고 단기프로젝트를 적극 발굴하며 적극적인 해외세일즈를 하는 것으로 설정해서 추진하고 있으며, 2단계에는 외국인투자자 관심사업을 개발하고 선진 유력기업과의 전략적 제휴를 하는 방법으로 외자유치를 추진코자 하고 있습니다.  향후에 외자유치 프로세스에 대해서는 지난 번 축령산 현지활동시에 제가 개략적인 보고를 드렸기 때문에 생략하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 14페이지 남한강정비사업 위 수탁 추진에 대해서 설명드리겠습니다.  남한강정비사업은 한강 본류, 경기도와 강원도 경계로 해서 하류부분으로 53.2㎞구간에 대한 하천정비사업이 되겠습니다.  사업기간은 ''99년부터 2008년까지 10년간으로 계획하고 있으며 예상사업비는 1,300억원으로 추정되고 있습니다.  이 사업비는 한강의 모래와 자갈, 골재를 매각해서 사업하는 내용이 되겠습니다.  주로 사업은 한강본류의 제방 하천개수사업과 지류에 대한 하천개수사업이 포함되겠습니다.  저희가 이 사업을 수탁하면서 수탁수수료는 약 80억원으로 경기도와 협의가 돼 있습니다.  주요 추진사업으로는 하천정비와 하상정리, 하천둔치 조성과 취 양수장 보강, 배수펌프장 설치 등이 되겠습니다.  본 사업의 추진은 홍수피해 예방사업을 우선적으로 추진하고 사업비는 취득골재 매각 수입금으로 확보하며 환경관리 보전과 개선을 기본적으로 하는 사업이 되겠습니다.  앞으로 본 사업의 추진은 건설교통부의 서울국토지방관리청과 행정절차를 이행하면서 환경영향평가 용역과 실시설계용역을 추진해서 내년도 하반기부터는 골재채취에 들어가도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 15페이지 현안사항에 대해서 보고드리겠습니다.  먼저 기흥 구갈3지구 합동개발방식 도입입니다.  본 사업은 용인시 기흥읍 구갈리에 위치해 있으며 면적은 29만 2,000평으로 예상사업비는 2,321억원, 보상비가 1,133억원, 개발비가 1,187억원 정도로 추정하고 있습니다.  현안사항을 보고드리면 지속적인 지가하락으로 사업성이 저하되고 있고 주택 건설업체들이 선수분양을 기피하고 있으며 보상비 재원부족으로 인한 사업시기가 순연되고 있습니다.  본 사업을 적극적으로 추진하기 위해서 민간개발자와 합동개발하는 방식을 도입코자 업체들과 협의를 하고 있습니다.  이 합동개발방식은 저희 공사가 보상, 인 허가, 택지분양, 공사 감독업무를 수행하고 민간개발자들은 공동주택지를 확보하며 단지조성공사를 시행하는 방법이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 16페이지 어연 한산지방산업단지 조성 활성화가 되겠습니다.  위치는 평택시 청북면 일원에 면적 20만 9,000평, 그 중 외국인 전용지구를 8만평으로 지정 추진하고 있으며 도에서 매입할 계획으로 있습니다.  사업비는 총 664억원, 그 중 용지비가 209억원, 개발비 139억원, 간선시설비 316억원으로 조성되겠으며 유치업종은 조립기계와 기타 제조업으로 되어 있습니다.  외국인 전용지구에는 고도의 첨단업종을 유치할 계획으로 있습니다.  현안사항은 조성원가가 당초에 48만원으로 조성되어 인근 공단인 포승공단보다 훨씬 고가인 사항을 나타내고 있습니다.  다음은 외국인 전용지구 지정에 따른 외국인업체 대상 임대지원을 경기도에서 추진하고 있다는 것을 보고드리며 앞으로 조성원가를 인하하기 위해서 폐기물처리장을 유상공급하고 폐수처리장 건설비용으로 국고지원 53억원을 받는 것으로 추진하고 있습니다.  유상공급과 국고지원을 하게 되면 당초 48만원대의 조성원가가 35만 5,000원대로 내려갈 수 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 분양촉진을 위해서 주한대사관과 외국 상공관련단체들을 방문하면서 홍보를 계속 하고 있습니다.  본 사업시에 사업단지의 활성화를 위해서 경기도에서 국도로부터 본 단지까지 약 5㎞의 진입로 확장공사를 도에서 추진하고 있습니다.  이 사업도 경기도에서 저희 공사에 위탁을 하려고 추진하고 있습니다.  총 사업비는 약 270억원 정도 예상하고 있습니다.  다음 자금 수지전망을 보고드리겠습니다.  단기적으로 ''98년부터 ''99년도까지 전망해 본다면 출자자산인 토지와 건물의 분양이 저조하여 유동성 확보에 어려움이 있고 고유토지의 적극적인 판매와 신규사업지구의 합동개발방식을 통한 선수분양으로 재원확보에 진력하고 자금부담을 줄이기 위해 외국투자자 유치활동의 전개가 필요하며, 초기투자자가 투자비가 적고 회임기간이 짧은 주택사업 등을 추진하고 ''99년도에는 보상비 등의 투자로 지역개발기금의 차입과 자본금 증자가 불가피할 것으로 보입니다.  2000년 이후의 중 장기 전망을 보면 ''99년 하반기부터 부동산 경기가 회복될 것으로 예측되어 경영효율성 제고를 위한 신규사업을 추진하고 토지개발의 특성상 초기투자비가 크고 회임기간이 긴 점을 고려하여 자체자금으로 사업 수행능력을 갖출 수 있도록 적정자산규모를 확대할 필요가 있다고 보겠습니다. 
</p>
<p style="padding-left:1.2em">  이상 간략하게 보고드리고 사업지구별 현황에 대해서는 유인물로 대신할까 합니다.  그러면 저희가 준비한 중 장기계획 용역성과물을 영상물을 통해서 보고를 드리도록 하겠습니다. 
</p>
<p class=''ar''>(16시00분 영상물 상영개시)
</p>
<p class=''ar''>(16시18분 영상물 상영종료)
</p>
<p style="padding-left:1.2em">  이상으로 업무보고를 마치겠습니다.
</p>
<p>(경기지방공사 소관 업무보고서는 끝에 실음)
</p>
<p><b>○ 위원장 고수복 </b> 지방공사 사장 수고하셨습니다.  그러면 감사질의를 하도록 하겠습니다.  질의는 원활한 진행을 위하여 일괄질의 후 일괄답변을 듣는 방법으로 하는 것을 원칙으로 하고 보충질의시에는 일문일답식으로 진행하도록 하겠습니다.  그러면 질의하실 위원께서는 질의하여 주시기 바랍니다.  정운천 위원 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 정운천 위원 </b> 안산의 정운천 위원입니다.  업무보고를 잘 들었습니다.  그런데 업무보고를 들으면서 꿈에 부풀어야 될 그런 입장인데 들으면서 점점 더 안개속으로 들어간듯한 기분은 어쩔 수가 없는 것 같습니다.  제 생각으로는 현재 경기지방공사가 주어져있는 여건하에서 경쟁력을 갖추고 활로를 찾는 것이 무엇보다도 중요하다고 생각하는데 방금전에 들은 업무보고를 보면 상당히 꿈에 젖어있는 게 아닌가 이런 판단이 됩니다.  우리가 어떤 사업을 시행할 때 자금이 넉넉할 때는 자금을 무한정 쓰더라도 투자효과가 있는 것은 무엇이든지 다 할 수가 있습니다.  그러나 자금이 없을 경우 또 조달할 가능성이 희박할 경우 그리고 조달하는 데 들어가는 노력이 많이 소요될 경우에는 주어진 여건하에서 조달될 자금의 범위 내에서 가장 우선순위의 투자를 선택해서 집중적으로 투자를 함으로써 수익성을 올리고 또 경쟁력도 향상될 것이라고 생각합니다.  그런 점에서 몇 가지에 대해 질의를 하겠습니다.  세 가지에 대해서는 과거년도의 데이터에 대해서 궁금한 점을 질의하고 나머지 네 가지는 앞으로의 계획에 대해서 몇 가지의 경우로 나누어서 질의드리겠습니다. 
</p>
<p style="padding-left:1.2em">  첫 번째 제가 1997년도 말 현재 공영개발사업단의 감사보고서와 경기지방공사의 감사보고서를 대사해본 결과 몇 가지면에서 차이점이 있기 때문에 그 부분에 대해서는 일문일답으로 했으면 좋겠습니다.  위원장님께서는 양해해 주시기 바랍니다. 
</p>
<p><b>○ 위원장 고수복 </b> 그러면 일괄질의가 아니고 일문일답입니까? 
</p>
<p><b>○ 정운천 위원 </b> 이 문제에 대해서는 그렇게 넘어가야 제가 이해될 것 같습니다. 
</p>
<p style="padding-left:1.2em">  작년도 감사보고서 13페이지를 보시면 완성용지에 구청부지라는 게 있습니다.  그 구청부지가 도대체 어떤 사업에 있어서 남은 재고자산입니까? 
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 지금 제가 자료준비가 안 됐는데요. 
</p>
<p><b>○ 정운천 위원 </b> 그러면 ''97년도 감사보고서…….  그러면 일문일답으로 하지 말고 그냥 일괄질의로 하겠습니다.  
</p>
<p><b>○ 위원장 고수복 </b> 네, 그러세요.
</p>
<p><b>○ 정운천 위원 </b> 작년도 감사보고서를 보면 경기지방공사 감사보고서 주석사항 중에 재고자산에 대한 내용이 있습니다.  그중에 완성용지의 구청부지로 52억 9,400만원이 있습니다.  도대체 구청부지가 어떤 사업에서 남은 재고재산인지에 대해서 설명해 주시고요.  미성용지사업비가 북부거점도시에 1,900만원이 있는데 그것이 도대체 어느 사업에 따른 재고재산으로 남은 부분인지 지금 제출해 주시는 사업내용에 없기 때문에 감사보고서를 이해하는 데 상당히 어려움이 있습니다.  그래서 그 부분에 대해서 설명해 주시면 참고하겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 같은 보고서 16페이지에 보면 경기도청으로부터 수탁예수금 208억 8,400만원을 받은 게 있습니다.  수탁예수금이라는 것이 도대체 뭐고 이 208억 8,400만원을 언제, 어느 때, 어떻게 경기도청에 반환을 하는 것인지 거기에 대한 조건과 반환계획을 설명해 주시기 바랍니다.  분명히 예수금이라는 것은 언젠가는 지출해야 되는 금액이기 때문에 이것을 알아야만 앞으로 사업계획을 짤 때 자금계획을 짤 수 있을 것 같습니다.  거기에 대한 설명을 좀 해주시고요.  
</p>
<p style="padding-left:1.2em">  그리고 작년도 감사보고서에 보면 보조부와 총계정원장을 정기적으로 대설하지 않고 있기 때문에 보조부와 총계정원장이 차이가 있다 이렇게 감사보고서에 지적된 것 같습니다.  그 이유가 무엇이고 지금 그것이 시정됐는지 설명해 주시기 바랍니다.  그리고 공영개발사업단 감사보고서의 현물출자금액하고 경기지방공사의 경기도에서 현물출자한 금액을 각기 주석에 달았는데 그것을 상호 대조해본 결과 순액으로는 14억 1,800만원이 차이가 나있습니다.  경기지방공사에는 총자산이 1,447억 9,100만원으로, 공영개발사업단에서의 현물출자했다고 나와있는 자산총계가 1,433억 7,290만원 이렇게 나와 있습니다.  그러니까 14억 1,821만 4,130원의 그 차이가 도대체 무엇인지 두 개의 감사보고서를 서로 비교해 봐도 이해를 할 수 없고요, 그 세부내역으로 들어가면 다른 부분은 일치하는데 기타 미수금, 완성용지, 미성용지사업비 이 세 개가 금액이 서로 틀립니다.  아마 개정분류상의 차이인지 아니면 다른 차이인지 모르겠습니다마는 공영개발사업단에서 넘길 때에 완성용지는 373억 1,800만원이었는데 경기지방공사에서 받을 때의 완성용지는 99억 3,400만원으로 돼 있고요.  공영개발사업단에서 기타 미수금으로 기록한 것은 13억 9,900만원인데 경기지방공사에서 기타 미수금으로 받은 돈은 632억 8,000만원으로 돼 있어요.  공영개발사업단에서 미성용지사업비로 계상된 것이 629억 7,700만원인데 경기지방공사에서 받은 것은 299억 1,300만원으로 돼 있습니다.  그리고 물론 차량운반구도 조금씩 틀리고 비품도 조금씩 틀립니다마는 금액이 그렇게 크지 않기 때문에.  단지 총금액이 틀리고 그 다음에 내부에서도 큰 금액들이 틀린 이유가 그당시에 어떤 이유로 이렇게 차이가 나는지, 개정분류상의 어떤 차이가 있는지, 그리고 현물출자를 받으면서 어떻게 경기도로부터 수탁예수금이라는 것을 받았는데 그 이유가 무엇인지 이것은 경기지방공사를 이해할 때 상당히 도움이 될 것 같아서 조금 이따가 설명을 해주시기 바랍니다.  그리고 내용이 복잡한 경우에는 자료로 제출해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  두 번째 자료 중에 추정손익계산서를 제출했습니다.  제가 자료를 요청할 때 추정재무제표를 요청했습니다.  추정재무제표라는 것은 다 아시는 바와 같이 추정손익계산서와 추정대차대조표, 추정이익잉여금 처분계산서가 합해져서 추정재무제표가 됩니다.  물론 거기에다 제조원가, 공사원가를 추가하면 더 좋겠습니다마는 그래도 재무제표라면 손익계산서와 대차대조표가 제출돼야 되는데 손익계산서만 5개년치가 제출됐습니다.  그리고 어떠한 방법과 가정하에 이런 추정손익계산서가 제출됐는지 전혀 안 나타나 있기 때문에 그것은 추정손익계산서로의 가치가 상당히 없다고 말씀드릴 수가 있습니다.  그래서 분명히 추정손익계산서가 작성된 것을 보면 어떠한 가정과 방법에 의해서 손익계산서가 수정된 것으로 추정되는데 그 부분에 대해서는 다시 제출해 주시면 고맙겠습니다.  
</p>
<p style="padding-left:1.2em">  그 다음에 세 번째 감사자료를 쭉 봤을 때 거기에 제출된 사업내용을 하나씩 봤습니다.  그런데 두 가지점에서 좀 이상한 게 있어서 먼저 간단한 질의를 하겠습니다.  7쪽을 보시면 수원 권선3지구 택지개발사업이라는 게 있습니다.  거기에 보면 1998년 9월부터 분양을 실시한다고 돼 있는데 지금 투자 및 회수계획을 보면 ''97년도까지 716억원이 들어왔다 이렇게 돼 있습니다.  그런데 분양이 실시되기 전에 들어왔는가, 물론 이것이 분양선수금인지 어떤지 모르겠습니다마는 거기에 대한 내용을 설명해 주시고요.  
</p>
<p style="padding-left:1.2em">  다음에 기흥 구갈3지구 택지개발사업에서도 조성공사 착공이 ''99년 4월로 돼 있습니다.  그러니까 아직 공사착공이 안된 것인데 ''98년도 계획에 대금회수 209억원으로 돼 있습니다.  이것도 어떻게 공사가 착공하기 전에 대금이 회수되는지, 계획이 잡혔는지 거기에 대해서 설명해 주시고요, ''98년 계획이니까 대금이 들어온 게 있을 것 같은데 그것이 어떻게 들어왔는지 설명을 해주시기 바랍니다.  
</p>
<p>그리고 쭉 제출된 자료를 저 나름대로 분석을 해봤습니다.  그래서 과연 도대체 이것을 지출할 수 있는 자금이 충분히 있는가, 지금 물론 경기지방공사는 참 불운하게도 경기도로부터 현물출자를 받을 때에 가용재원이 없는 상태에서 받았습니다.  현금이 266억원 정도밖에 안되는 상황에서 엄청난 고정재산을 받았기 때문에 이것은 자금회전이 안되기 때문에 새로운 사업을 할 때  상당히 제약요건으로 작용을 하고 있습니다.  
</p>
<p style="padding-left:1.2em">  그래서 가장 급선무는 현재의 재고자산을 어떻게 빨리 처분해서 자금화하느냐 하는 부분하고, 신규사업을 할 때 거기에 투자될 재원을 어떠한 방법으로 조달하느냐 이게 가장 급선무같은데 아까 업무보고가 끝나고 프리젠테이션한 것을 보면 어떻게 하겠다 이것만 나와있습니다.  그러니까 어떻게 하겠다라는 것은 사실 재원이 있을 때 가능한 것인데 재원이 없기 때문에 제가 상당히 답답함을 느꼈습니다.  그래서 제가 별도로 자금을 추적해 봤습니다.  제출해 주신 자료에 따라서 주요사업별로 현금흐름을 봤습니다.  쭉 검토해 보니까 제출된 자료가 두 가지인데 서로 틀립니다.  그러니까 앞부분의 사업별 자금투자와 회수계획하고 뒤에 쭉 액셀로 뽑으셨는지 사업별 총계로 억단위로 돼 있는 자금계획하고 숫자가 잘 안 맞아요.  그래서 두 가지로 뽑아봤는데 주요사업별 현금흐름을 보면 수원 권선3지구 택지개발 이것이 1998년도까지 199억원 정도 들어가고 회수되는 게 291억원 그래서 순수하게 91억원이 들어온다 이렇게 돼 있어요.  그런데 실질적으로 들어왔는지 모르겠습니다마는 계획이 그렇게 돼 있습니다.  이런 식으로 뽑았을 때에 수원 권선3지구 택지개발은 장내 공사가 완성될 때까지 투자수익이 13.2%, 그 다음에 기흥 구갈3지구는 16.3%, 어연 한산은 2.9%, 부천 상동 주택단지는 19.9%, 권선3지구 주택사업은 5.7%, 축령산리조트는 13.8%, 대부 임해관광단지는 13.8% 이런 식으로 추정을 했습니다.  그런데 물론 여기에는 허수가 있습니다.  지금 경기지방공사가 주로 하는 투자수익이라는 것이 일반적으로 투자분석을 하는 사람들이 즐겨쓰는 현재가치할인법으로 확인한 것이 아니고 사업기간 중에 총 들어간 투자비와 그리고 그것이 완공됐을 때에 예상되는 채권의 회수가 완결됐을 때까지의 모든 자금회수부분하고 그 차이를 비교한 것이 투자수익이다 이렇게 보고 있습니다.  여기에는 뭐가 간과됐느냐면 기간수익, 즉 이자율이 간과된 것입니다.  
</p>
<p style="padding-left:1.2em">  그러면 지금 말씀하신 13.2%는 적어도 5년동안에 걸쳐서 총 들어온 현금에서 총 나간 현금을 뺀 그 차이가 총 들어간 금액의 13.2%다 이런 얘기입니다.  그렇다면 만약에 평균 5년이 걸렸다 치면 5년보다 더 걸리는 사업도 있습니다마는 이것은 1년에 2.4% 정도밖에 안됩니다.  가장 많다는 부천 상동 주택사업도 19.9%로 1년에 4% 정도밖에 안됩니다.  이것은 이자율보다도 안되는 것 아니냐.  그렇다면 아까도 말씀드린 바와 같이 지금 하겠다는 수익성과 공익성, 물론 공익성은 있는 걸로 판단됩니다마는 수익성 부분에서는 상당히 열악하지 않느냐.  그러면 과연 이런 수익성가지고 외자유치를 제대로 할 수 있을까, 그리고 앞으로 우리가 계획하는 민자유치를 과연 계속 할 수 있을까 이런 부분이 자꾸 걸리기 때문에 외국인이나 우리나라 국내 투자가들도 분명히 어느 정도의 사고는 가지고 있는 사람들인데 자기들이 가지고 있는 자원을 과연 이렇게 수익성이 없는 데다가 선뜻 투자할 것이냐.  그렇다면 지금 할 수 있는 방법은 오로지 경기도에만 의지하는 방법밖에 없습니다.  
</p>
<p style="padding-left:1.2em">  그래서 제가 볼 때는 전반적으로 사업을 재검토하셔가지고 수익성있는 사업을 발굴해서 그것을 적극적으로 홍보해서 아니면 현재 추진 중인 사업들 중에 수익성을 올릴 수 있는 방법을 강구해서 그것을 적극 홍보해서 투자자들을 유인하고 그들로부터 자금을 끌어들이는 방법이 있어서 그것이 선행이 돼야 경기지방공사가 앞으로 생각하시는 원대한 꿈을 실천할 수 있는 바탕이 될 수 있다고 생각하는데 그런 부분은 전혀 없는 것 같아서 아주 답답했습니다.  
</p>
<p style="padding-left:1.2em">  그래서 다음 질의로 어떻게 경기지방공사에서는 저런 꿈을 꿀 수 있을까?  그렇다면 분명히 자금조달계획은 있을 것이다.  그러면 자금조달계획을 한 번 듣고 싶습니다.  제가 여태까지 마치 저렇게 큰 사업을 시행하는데 전혀 어떤 자금조달계획이 없이 했을까 하는 우려가 돼서 여태까지 질의를 했는데 제가 잘못 생각했을 수도 있으니까 그렇다면 자금조달계획을 제시해 주시기를 바랍니다.  그리고 중장기계획에서도 설명을 하셨는데 경제성 및 투자효율을 극대화 하겠다 그리고 투자소요액 및 추정손익을 계산한 바에 의하면 몇 천억원의 이자수익이 나는 것으로 돼 있습니다.  그래서 다시 한 번 질의를 드리는데 그것이 과연 현재가치할인방법에 의해서 계산된 투자수입이냐, 투자수익률이냐 그리고 투자수입금액인지 설명을 좀 해주시고요.  
</p>
<p style="padding-left:1.2em">  그 다음에 아까도 설명하면서 제가 언뜻 봐서 메모를 한 것입니다마는 외자유치 과정에서 컨설팅비로 ''99년도에 1,000만달러를 벌어들이겠다고 했는데 1,000만달러를 벌어들이겠다는 것인지 그냥 지출하겠다는 것인지 잘 모르겠습니다.  그것이 지출계획인지 수입계획인지 설명해 주시고 만약에 지출하는 것이라면 어느 업체에 어떻게 컨설팅을 의뢰할 것인가 그 다음에 벌어들이는 것으로 했다면 어느 방법으로 컨설팅을 해서 1,000만달러를 벌어들일 계획인지 설명을 해주시기 바랍니다.  
</p>
<p style="padding-left:1.2em">  제가 이렇게 우려를 하면서 이런 질의를 드리는 것은 경기지방공사는 아까 설명하신 분의 말대로 할 일이 굉장히 많습니다.  그리고 경기도가 경쟁력을 향상시키고 그런 것을 갖기 위해서는 그일을 경기지방공사가 해주지 않으면 안됩니다.  경기도가 일일이 나서서 산업단지를 구성하고 또는 아까 사업목적으로 제시하신 모든 것을 다 할 수가 없습니다.  그래서 가능하면 경기지방공사가 경쟁력을 갖고 그 일을 모두 해주셔야만 경기도가 경쟁력을 갖출 수 있고 아까도 프리젠테이션 하시면서 설명하신 바와 같이 중소기업들이 경쟁력을 갖고 나갈 수 있도록 지원해 줄 수 있는 유일한 방법이기 때문에 제 생각에는 무엇보다도 먼저 자금조달하는 방법을 세워야 되지 않겠는가.  그래서 그것을 최대한 확보할 수 있는 방안을 강구하고 나서 그 범위 내에서 사업계획을 해야 되지 않느냐.  물론 그 자금을 유치하기 위해서는 수익성이 있는 사업을 발굴하고 제시하는 게 중요합니다.  그렇지만 듣는 사람으로 하여금 이것은 너무하다라는 생각이 들게 하면 안된다.  그래서 그 부분에 대해서 좀더 구체적인 사업계획이 필요하지 않겠나 하는 생각이 듭니다.  답변해 주시기 바랍니다.  감사합니다. 
</p>
<p><b>○ 위원장 고수복 </b> 또 질의하실 위원님 안 계십니까?  연동현 간사님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 연동현 위원 </b> 방금 정운천 위원님께서 전체적인 회계 내지는 모든 것을 포괄적으로 질의를 하셨기 때문에 본 위원은 두 가지 정도만 질의라기보다 궁금한 사항에 대해서 여쭤보는 식으로 말씀드리도록 하겠습니다.  우리가 ''97년부터 ''98년 동안의 사업시행 중에 설계변경사업이라는 게 두 가지가 있어요.  업무근린시설신축공사라 해서 수원시 권선구 권선동 이것하고 도급자가 일신, 우림건설 다음에 수원 권선3지구 택지개발사업 해서 네 차례 설계변경한 것인데요.  물론 맨처음에 사업발주 수주를 하기 위한 설계도하고 지금 물론 물가변동이 간단명료하게 돼 있기 때문에 맨처음 금액하고 전체적으로 3차 설계변경 하면서 9억원 이상이 차이가 나고 있지 않습니까?  간단하게 나와 있으니까 물가변동, 수량증가 이런 식으로 돼 있단 말입니다.   그래서 이 부분을 세부적으로 말씀해 주시든지 이게 긴 사항이면 서면으로 해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그 다음에 수원 3지구 역시 마찬가지입니다.  성지건설외 2개사 해서 36억원 이상 차이가 나는데 이 부분도 간단명료하게 물가변동 내지는 수량증가 이렇게 나와 있어요.  그러니까 이 부분을 제가 봐서는 무슨 내용인지 모르겠어요.  그냥 설계변경하기 위한 목적에서 이렇게 했던 건지 그 부분을 나쁜 시각으로 보고 말씀드리는 게 아니니까 그 부분을 세부적으로 말씀해 주시고요.  오전에 경기개발연구원에서 얘기를 들었는데 지방공사에서 1억 6,320만원을 수탁의뢰를 하지 않았습니까?  그런데 지방공사에서 수탁의뢰 받은 결과 거기에 대한 것을 지방공사에서 반영시키고 있는 겁니까?  이따 전체적으로 한꺼번에 말씀해 주시기로 하고요.  그 부분을 구체적으로 사업에 반영한다든지 지방공사정책에 반영했다든지 이런 게 있으면 말씀해 주시기 바랍니다.  저는 이 정도로 해서 궁금한 사항을 여쭤보는 사항이니까 이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 연동현 간사님 수고 많으셨습니다.  다음 질의하실 위원님, 이남형 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이남형 위원 </b> 질의에 앞서서 설립된 지 불과 1년 정도밖에 안됐기 때문에 매우 경영 환경이 열악한 것으로 알고 있습니다.  이러한 상황에서도 의욕적으로 업무를 확대해서 열심히 해보겠다, 이렇게 일하고 계신 민병균 사장님을 비롯한 관련 임직원에 대해서 먼저 감사의 말씀을 드리면서 본 위원도 지방공사가 의욕적으로 임하고 있는 모든 사업이 정말 뜻한 대로 잘 되도록 그렇게 같이 기원하고 있다는 말씀을 먼저 드립니다.  본 위원이 파악하기로는 경기지방공사는 택지개발사업이라든지 산업단지조성사업이나 주택개발사업, 관광지개발사업 그리고 무역업무 이런 많은 일을 하고 있는 것으로 알고 있습니다.  또 계획하고 있는 것으로 알고 있습니다.  이러한 많은 일들은 제가 보기에는 그 기간도 상당히 오랜 시간이 걸리고 또 조금 전에 정운천 위원님께서 지적하신 바와 같이 아주 많은 자금이 장기간에 걸쳐서 투입된다, 이렇게 저는 봅니다.  그래서 이러한 일들을 잘 완수하기 위해서는 무엇보다도 커다란 문제가 대규모의 자금을 어떻게 확보하느냐, 그 다음에 제도를 어떻게 정비하느냐, 이 제도정비는 경기지방공사의 힘만으로 되는 게 아닙니다.  그래서 많은 주변의 관련기관이나 인사들을 어떻게 설득하고 법이나 관계법령을 개정하느냐 이런 문제까지 달려 있다고 봅니다.  또한 이러한 일들을 추진하기 위해서는 훈련되고 숙련된 인적 자원이 많아야 된다 저는 이렇게 봅니다.  과연 이 세 가지를 다 충족시킬 수 있을까 걱정이 앞섭니다.  먼저 자금에 대해서 말씀드리면 본 위원이 제출된 자료를 보니까 ''98년도만 해도 용지조성자금이라든지 이러한 부분으로 약 607억원이 투입된 것으로 돼 있습니다.  또한 향후에는 9,138억원이 투입될 예정으로 돼 있습니다.  그런데 현재 경기지방공사에서 보유하고 있는 현금은 약 270, 280억원 정도밖에 되지 않습니다.  물론 ''98년도 예를 보면 622억원이 용지매출수입으로 잡혀 있습니다.  그런데 제가 한 가지 궁금한 것은 622억원이 주택용지라든지 이런 것을 매출해서 현금이 전액 들어온 것인지 이 부분이 정확치 않습니다.  그것은 그렇다 치고, 그래서 과연 이렇게 많이 필요한 자금을 어떻게 어떤 식으로 조달할 것이냐, 제가 알고 있기로는 ''99년도에는 경기도 예산상으로 180억원을 경기지방공사에 지원하는 형태로 되어 있는 것으로 알지만 기타 특별한 대안이 없지 않느냐, 자금을 확보하는데.  이 문제가 상당히 큰 문제다 이렇게 본 위원은 생각합니다. 
</p>
<p style="padding-left:1.2em">  두 번째로는 제도정비에 관해서 말씀드리겠습니다.  제도정비를 하기 위해서는 먼저 무엇보다도 관련된 기초자료를 충실히 모아서 그것을 잘 조합해 가지고 자료로 만들어 내야 됩니다.  먼저 예를 들면 외국인 투자유치를 많이 하고 있고 또 그쪽에 힘을 많이 쓰시는데 좋은 방안입니다.  그래서 예를 들면 축령산이라든지 이런 데에 외자유치를 하겠다고 하는데 제가 보기에는 상당히 구체적으로 들어가야 되지 않겠느냐, 외자유치를 위해서는 구체적인 대안을 가져야 되지 않겠느냐고 봅니다.  왜냐 하면 외국인 투자자 입장에서 생각해 보면 외국인 투자자는 투자할 데가 한국만 있는 게 아닙니다.  경기도에만 있는 것도 아닙니다.  외국인 입장에서는 한국뿐만 아니라 중국이든 인도네시아든 필리핀이든 멕시코든 전 세계를 상대로 해서 투자할 수 있습니다.  그래서 그 사람들이 투자할 때는 우선 안전성도 고려할 것이고 수익률도 고려할 것이고, 그 다음에 원금을 언제 회수할 수 있느냐 이런 기간도 검토할 것입니다.  그래서 우리 입장에서만 외국인 투자유치를 하겠다 이렇게 하는 것보다는 외국인 입장에서 과연 그 사람들이 투자를 결정할 때 어떤 메리트가 있느냐, 수익률이 높냐, 안전성이 확보되느냐, 단기간내에 회수할 수 있느냐, 이런 것을 많이 고려하기 때문에 이런 메리트를 우리가 그 사람들한테 충족시켜 줘야 될 필요가 있다고 봅니다.  그런데 과연 이러한 부분들이 충분히 돼 있느냐 상당히 의문이라고 봅니다.
</p>
<p style="padding-left:1.2em">  또 하나 예를 들면 어연 한산단지 외국인전용공단을 설립한다고 계획을 잡고 있는데 물론 당연히 저도 잘 돼야 한다고 봅니다.  제출해 주신 자료를 보니까 외국인전용임대공단을 설치하기 위해서 투자유치상 메리트를 주기 위해서 법인세를 5년간 100% 감면하겠다.  또한 소득세에 대해서는 3년간 50%를 면세하겠다 이런 좋은 안을 갖고 있습니다.  그런데 이러한 안이 제가 세법에 대해서 정확한 지식이 없기 때문에 정확히는 모르지만 과연 아이디어만 가지고 되는 것인가, 현행 세법상으로도 가능한 것인지 이러한 것이 구체적으로 조사가 돼 있는지.  또한 외국인 투자유치와 관련해서 자본재에 대한 관세와 특별소비세 등을 전액 면제하겠다 이런 내용도 들어가 있습니다.  물론 방향은 좋은데 이러한 내용들이 지금 세제와 관련된 법개정 사항인지, 아니면 시행령만 개정해도 되는 사항인지 이런 것이 구체적으로 어떻게 돼 있는지 이런 부분들을 내부인프라가 구축이 잘 돼 있는지, 만약에 지금 안돼 있다면 아무 것도 안돼 있는 상태에서 외국인한테 여기와서 투자하시오 이렇게 해서는 저는 어렵다고 생각합니다.  그래서 그런 내부인프라 구축에 어느 정도 돼 있는지 모르지만 많은 힘을 기울여야 되겠다 이렇게 봅니다.  그 다음에는 제가 지난 번 어느 신문에서 본 내용인데 주변 위원님들한테 들은 말씀인데 유명한 어린이 놀이 회사가 있지 않습니까?  레고랜드라고.  그런데 거기에서 원래 우리나라에 2억불 정도를 투자를 추진하려고 했다는 얘기를 들었습니다.  그런데 여러 가지 행정상의 규제 이런 문제 때문에 일본 동경인가 어디로 이전했다는 얘기를 들었습니다.  바로 외국인들한테 메리트가 전혀 없다 이런 것을 반증하는 겁니다.
</p>
<p style="padding-left:1.2em">  그런데 경기지방공사라고 해서 법이라든지 시행령이 고쳐지지 않은 상태에서 할 수 있느냐, 어렵다고 봅니다.  그래서 그런 부분들을 우선 내부적으로 정비하고, 그 다음에 외부적으로는 관련 기관들과 계속적으로 긴밀하게 연결관계를 맺어야 되겠다 이렇게 봅니다.
</p>
<p style="padding-left:1.2em">  그 다음에 무역부문하고 관련해서 말씀드리겠습니다.  무역부문도 마찬가지입니다. 먼저 경기도 관내에는 지금 중소기업이 굉장히 많은 것으로 알고 있습니다.  그래서 자료에도 보니까 500개 중소기업에 대해서 생산품목이라든지 이런 것을 검토한다 이렇게 말씀이 나와 있는데 제가 보기에는 중소기업이 워낙 많으니까 그 중에서 어떤 생산을 하고 있는지, 또 어떠한 정도의 규모를 가지고 있는지, 또 생산에 들어가는 원가는 얼마 정도 되는지, 그래서 그게 국제시장에 나갔을 때 외국인들 입장에서 충분히 경쟁력을 갖추고 있는지 이런 것들을 사실 종합적으로 검토해야 됩니다.  그래서 종합적으로 검토한다면 거기에는 상당한 인력과 시간이 투입돼야 한다고 생각되는데 과연 지금 이런 것들이 잘 돼 있는지, 또한 이것은 국내의 문제이고 무역을 한다면 우리가 국내생산품이라든지 이런 것을 외국에 팔기도 하고 외국생산품을 국내에 수입하는 문제이기 때문에 외국에 관련된 바이어들을 잘 알아야 됩니다.  그래서 바이어들의 리스트업이 잘 되어 있는지, 또 이러한 바이어들은 어떤 것을 좋아하는지, 어떤 물품에 대해서, 생산품에 대해서 그 사람들이 나라가 다 다르니까 동일한 생산품이라 하더라도.  예를 들어서 홍콩에서 메리트가 있는 것이 멕시코에서는 메리트가 없을 수도 있으니까 지역별로 메리트가 있는 상품이 무엇인지, 경기도 관내에서 생산되는 품목들 중에.  이런 것이 충분히 내부인프라가 구축되고 외국과 관련된 외부인프라도 구축되고 동시에 이게 병행돼야 되는데 이런 부분들이 과연 잘 돼 있는지 아까도 말씀하셨습니다만 주택개발사업이라든지 산업단지조성이라든지 또 택지개발사업이라든지 많은 일을 하려고 계획을 잡고 있는데 제가 말씀드린 이런 내부적인 문제, 또 우리가 내부적으로 검토해야 될 문제들이 아직 정리가 안돼 있는 상태로 알고 있습니다.  물론 설립된지 얼마 안됐고 또한 열악한 환경이기 때문에 그렇다는 것은 제가 압니다.  그러나 이렇게 일을 진전시킨다면 우선 내부부터 정비를 해야 되겠다는 말씀을 하나 드리고 싶습니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 네 번째로는 주신 자료를 보니까 ''98년도에 용지매출금액이 622억원이 잡혀 있고 무역수출은 56억원이 잡혀 있습니다.  그런데 용지매출 622억원은 실제로 용지를 매출해서 현금 유입된 금액이 622억원이라는 이야기인지 아니면 용지매출하게 되면 한꺼번에 돈이 들어올 수도 있지만 계약금만 들어오고 중도금이 들어오고 이러니까 이 622억원이라는 수치가 계약금 상태의 수치인지 아니면 총 금액인지, 유입된 금액인지 그것을 확인해 주시기 바라고, 다음은 이 622억원과 56억원의 내용이 구체적으로 어떤지, 그래서 용지매출이 622억원이 되려면 사업별로 여러 군데가 있지 않습니까?  사업별로 어디에 얼마가 어떻게 팔렸는지 이런 내용을 자세하게 확인해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그 다음에 다섯 번째로는 남한강개발사업이 저희가 아직까지 모르고 있던 그런 내용이 여기에 있습니다.  그래서 이 부분하고 관련돼서 말씀드리겠습니다.  아까 민병균 사장님께서 보고하시는 과정에서 경기도에 수탁수수료로 80억원을 내겠다……. 
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 이것은 저희가 받는 것입니다. 
</p>
<p><b>○ 이남형 위원 </b> 그렇습니까? 
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 네.
</p>
<p><b>○ 이남형 위원 </b> 제가 볼 때 10년간에 걸쳐서 하기로 계획이 돼 있는데 이것은 구체적으로 생산추정 매장량, 그러니까 골재가 매장돼 있을 테니까 그 매장량이 어느 정도 되는 건지, 어느 정도 예측을 해서 1,300억원이라는 이런 수치가 나온 건지, 그 다음에 생산하는 것과 판매하는 것을 직접 경기지방공사에서 모두 할 생각인지 아니면 생산이나 판매 중에 일부분은 위탁을 한다든지 방법이 여러 가지가 있을 것입니다.  이 부분은 어떻게 계산하고 계신지, 그리고 정확히는 모르지만 골재라는 것이 제가 알기로는 건축경기라든지 경기가 활성화 되느냐 안되느냐에 따라서 상당히 영향을 받습니다.  그래서 지금과 같이 IMF경제 상태에서 건축경기라든지 상당히 위축돼 있는데 물론 앞으로 가면 상당히 활성화될 가능성이 많이 있겠습니다만 현 시점에서 볼 때 10년이라 하더라도 어떤 방식으로 10년간 해야 될 건지 그런 부분도 구체적으로 검토가 돼야 하지 않겠는가 이렇게 말씀드리면서 마지막으로 제출해 주신 추정손익계산서가 ''99년도부터 2002년까지 돼 있는데 조금 전에 정운천 위원님께서도 말씀을 주셨습니다만 여기보면 ''99년도에는 당기순이익이 40억원이 나있는 것으로 돼 있고 2001년도에는 59억원이 나는 것으로 돼 있고 2002년도에는 43억원이 나는 것으로 돼 있는데 저도 아까 말씀드렸지만 상당히 걱정이 앞선다고 느끼고 있고 지금 마음이 그런데 이것을 보면 굉장히 큰 수익은 아니지만 그래도 마음이 편안해지는 느낌을 받습니다.  그런데 제가 여쭤보고 싶은 것은 추정손익계산서가 어떠한 과정과 근거를 가지고 추정된 것인지 그 부분을 말씀해 주시기 바랍니다.  그래서 본 위원이 질의드리는 이런 문제들은 단순히 질의를 위한 질의가 아니고 경기지방공사의 역할이 경기도 앞날에 상당한 영향을 미치고 또 중차대하기 때문에 경기지방공사가 계획하고 계신 그런 모든 사업들이 계획대로 잘 진행돼야 되겠다, 아까 서두에 제가 말씀드렸습니만 그렇게 저도 생각하고 있습니다.  그래서 잘 돼야 되겠는데 그러기 위해서는 구체적으로 계획도 실행하고 정말 검토에 재검토를 해야 되고 이렇게 해야만 된다고 보기 때문에 제가 짧은 기간이지만 검토해 본 결과 느끼는 내용들을 질의드린 것입니다.  이상 여러 가지로 어려운 환경속에서 임해 주시느라고 힘드실텐데 함께 힘을 합쳐서 열심히 해 보시기 바랍니다. 
</p>
<p><b>○ 위원장 고수복 </b> 이남형 위원님 수고하셨습니다.  네, 이진용 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이진용 위원 </b> 가평출신 이진용 위원입니다.  앞서서 여러 위원님들께서 구체적으로 여러 가지를 물으셨기 때문에 저는 중복되지 않는 범위내에서 몇 가지 질의드리겠습니다.  본 위원은 먼저 다음 공사가 공공성과 수익성을 동시에 추구해야 하는 그러한 어려운 입장에 있다는 사실을 알고, 또 그러한 공사의 설립배경이 지역 균형개발과 도민 복리증진에 기여한다는 목표하에 설립되었기 때문에 여러 가지로 수익성만 문제 삼을 것이 아니다, 이런 생각을 하면서 본 위원의 생각에 의욕이 있는 부분이 있어서, 또 일견 염려가 되는 부분이 있어서 그런 부분에 중점을 두고 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 본 위원은 당 공사가 대부분의 사업이 대형이어서 지금 주요사업 8가지가 저희들한테 제시가 됐는데 1조 1,145억원에 293만 7,000평이라는 이런 대규모의 사업이 진행되고 있습니다.  이렇게 사업들이 대형이다 보니까 자금회수 등의 측면에서 상당히 위험부담이 높습니다.  물론 추정손익계산서를 보면 앞으로 향후 손익의 규모는 적지만 현재 부동산 등으로 갖고 있는 고정자산이 현금화되는 유리한 측면을 볼 수 있고 이것은 곧 자금조달의 측면과 관련돼서 긍정적인 부분을 볼 수가 있습니다.  그런데 당 공사는 그러한 대규모사업을 추진하다 보니까 자본집약적인 사업이 추진되고 있는데 직원 채용시에 보증인도 세우지 않는 관리상의 문제가 노출됐습니다.  그래서 그런 문제가 이렇게 대규모 자본을 관리하는 직원들이라면 당연히 신경을 썼어야 되지 않나 하는 생각이 들었는데 그 부분에 대해서 공사 사장님을 견해를 묻고 싶습니다.  그리고 그러한 대규모 사업은 극소수에 그쳐야 하는데 IMF의 어려운 상황임에도 불구하고 어쩔 수 없이 하는 사업들이 많기 때문에 염려가 되는 측면이 많습니다.  앞으로 초대형사업은 극소수에 그쳐야 하고 자금회전이 빠른 중소규모사업에 집중돼야 하지 않겠나 이런 생각이 됩니다.  만약에 이런 대형사업 하나가 실패된다면 그로 인한 도 집행부의 부담이 엄청나게 커질 테고 또 이것은 도민들의 어려움으로 이어질 것이기 때문입니다.  그런 점에 대해서 공사 사장님의 견해를 듣고 싶고 다음으로 사업 다각화와 관련해서 한두 가지 묻겠습니다.  지금 현재 저희들에게 제시된 보고서에 의하면 약 56억원이 무역매출로 인한 수익으로 잡혀 있는데 구체적인 내용을 말씀해 주시고, 그 다음에 음식물 쓰레기를 활용한 환경관련사업이 제시됐습니다.  좀더 구체적인 계획을 말씀해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  또 사업 다각화와 관련해서 폐수처리장이나 하수종말처리장 등 장래성이 있는 환경관련사업으로의 진출계획은 없는지 그런 점들에 대해서 말씀해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 이진용 위원님 수고하셨습니다.  또 질의하실 위원님 안 계십니까?  정운천 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 정운천 위원 </b> 제가 앞부분에 질의하면서 하나 빠뜨린 게 있는데 다른 게 아니고 대부도 관광단지를 개발하면서 안산시하고 관련된 광역상수도 자금부담하기로 계획한 게 있습니까?  그거 관계하시는 분 안 계십니까?  그 부분에 관계돼 가지고 자금지출될 금액이 확정이 돼 있나요, 아니면 유동적입니까?  
</p>
<p><b>○ 사업계획팀장 정동선 </b> 자금지원은 도에서 재정지원을 하는 걸로 돼 있습니다. 
</p>
<p><b>○ 정운천 위원 </b> 도에서 재정지원하고 우리한테 주면 우리가 다시 안산시에 주는 식입니까 아니면 경기도에서 대신 지급해 주는 겁니까? 
</p>
<p><b>○ 사업계획팀장 정동선 </b> 경기도 방침이 확정되지는 않았는데 지방공사에 줘 가지고 지방공사에서 안산시 상수도사업에, 현재 ''98년도 예산이 모자라 가지고....... 
</p>
<p><b>○ 정운천 위원 </b> 출연금 형식으로 내고 우리가 다시 지급하는 형식입니까?  네, 알겠습니다.  그 부분도 자세히 설명해 주시고 그 부분이 과연 우리 자금계획에도 포함돼 있는지 그것도 아울러서 확인해 주시기 바랍니다.  이상입니다. 
</p>
<p><b>○ 위원장 고수복 </b> 정운천 위원님 수고하셨습니다.  또 질의하실 위원님 안 계십니까?  그러면 사장님, 한 시간이면 답변이 준비되겠습니까?
</p>
<p style="padding-left:1.2em">  그러면 답변준비와 휴식을 위하여 18시까지 감사를 중지하도록 하겠습니다. 
</p>
<p class=''ar''>(17시07분 감사중지)
</p>
<p class=''ar''>(18시04분 감사계속) 
</p>
<p><b>○ 위원장 고수복 </b> 자리를 정돈해 주시기 바랍니다.  감사를 계속하겠습니다.  위원님들의 질의에 대한 답변을 듣도록 하겠습니다.  경기지방공사 사장 나오셔서 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 먼저 정운천 위원님께서 질의하신 사항에 대한 답변을 드리겠습니다.  위원님께서는 구청부지 매각에 대해서 첫 번째 질의해 주셨고 그 다음 수탁예수금 208억원과 공영개발사업단 감사보고서와 지방공사의 감사보고서가 일치하지 않는 사항, 그리고 경기지방공사의 투자재원 확보방안, 그리고 권선3지구 분양이 ''98년 9월 실시되었는데 이에 대한 ''97년도 회수사유, 구갈3지구에 대한 채권계획과 관련한 대금회수 사유, 그리고 지방공사의 5개년 손익계산서가 어떤 과정과 방법으로 지출되었는가, 그리고 중 장기계획상의 재원조달방안이 어떻게 되었는가, 그리고 경기지방공사에서 수행하고 있는 각종 사업이 수익성이 떨어지는 데에 대한 질의와 마지막으로 대부임해관광지의 광역상수도 분담금에 대한 질의를 해 주셨습니다. 
</p>
<p style="padding-left:1.2em">  먼저 질의해 주신 구청부지 52억 9,455만원에 대해서는 도의 공영개발사업단에서 기 분양을 하고 계약금 10%와 중도금 18%의 합계인 20억원이 현재 입금되었으며 나머지 52억원은 ''98년부터 2001년까지 매년 18%씩 입금예정으로 있고 금년도에는 중도금 18%와 연 8%의 이자합계인 5억원이 입금되었습니다.  그리고 수탁예수금 208억 8,469만원에 대한 내역은 ''97년도 12월중에 선수분양된 권선3지구 공동택지 분양대금이며 택지개발의 사업시행자가 경기도지사이므로 선수분양대금 전액을 수탁예수금으로 계상한 사항이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 ''97년도 공영개발사업단의 감사보고서와 경기지방공사의 감사보고서가 일치하지 않는 사항과 ''97년도 감사보고서의 보조부와 총계정원장의 추세에 대한 차이에 대해서 물으셨습니다.  본 사항은 경기도공영개발사업단의 공사 전환을 위한 자산 부채평가를 현재 우리 공사 고문회계사로 계신 임성빈 회계사께서 주관하셨는데 그 당시 현물상의 재산가액과 감정가액의 차이로 발생되었습니다.  위원님께서 지적하신 사항은 양해해 주신다면 차이 발생 비교표를 작성해서 서면으로 답변을 올릴까 생각하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 계획사업을 효율적으로 추진하기 위해서 경기지방공사의 투자재원 확보방안에 대해서는 정운천 위원님과 이남형 위원님께서 같은 내용으로 질의해 주셨습니다.  함께 답변 올리도록 하겠습니다.  먼저 경기지방공사에 대하여 깊은 애정과 관심을 갖고 계신 데 대하여 위원님께 감사를 드립니다.  ''98년 중 공사에 필요한 사업비는 권선3지구 택지조성비 154억원, 어연 한산산업단지 조성비 38억원, 부천 상동 용지비 57억원, 업무근린시설 공사비 73억원, 지역개발기금 상환기금 135억원, 업무관리비 35억원 등 총 887억원의 자금이 소요될 것으로 예측되며 투자재원은 권선3지구 택지분양 수입 212억원, 어연 한산단지 분양수입 185억원, 무역매출수입 56억원, 전기이월금 240억원, 과년도 미수금 183억원 등 총 1,393억원이 확보될 것으로 전망되어 자금운영에 큰 어려움은 없을 것으로 예상됩니다.  다만 ''99년도에는 구갈3지구 선수분양 매출액 818억원, 권선3지구 택지분양 매출액 249억원, 무역매출액 153억원, 과년도 미수금 89억원 등 총 1,642억원의 매출수입을 예정하고 있습니다.  지출은 구갈3지구 보상비 1,122억원, 어연 한산단지 공사비 177억원, 부천 상동 용지매입비 130억원, 무역매출 원가 152억원, 업무관리비 64억원 등 2,055억원의 지출을 예정하고 있습니다.  지출 초과분 413억원은 전기이월금으로 보전할 계획으로 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 권선3지구의 분양이 ''98년도 9월에 실시되었는데 ''97년도 716억원 회수사유를 질의하셨습니다.  이는 권선3지구 공동주택지 4만 8,000평을 주택업체에 선수공급하여 선수공급대금으로 회수한 금액이 되겠습니다.  또한 구갈3지구 ''99년 4월 착공계획으로 ''98년도 200억원 대금회수 계획에 대한 것을 질의해 주셨습니다.  구갈3지구는 공사착공이 내년도 4월 계획이나 개발계획 승인시 확정개발방식으로 사업을 추진하여 공동주택지 7만 7,000평을 주택업체에 선수공급함으로써 협약과 동시에 계약금으로 회수할 예정금액이 되겠습니다.  이는 저희가 사업시행방침을 최종 확정짓지 않았기 때문에 향후 검토과정에서 조정이 예상되는 사항이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 경기지방공사의 5개년 손익계산서가 어떠한 과정과 방법으로 산출되었는지에 대해서 물으셨습니다.  답변을 드리기에 앞서 위원님께 양해말씀을 드리고자 합니다.  감사자료로 제출한 자료는 11월 6일 제출한 자료로서 그 후에 사업계획변경으로 추가경정예산을 편성하여 지난 11월 17일자로 도의 승인을 받았습니다.  변경된 자료는 유인물로 제출했습니다.  5개년도 손익계산서 작성은 기업회계기준에 의하여 건설업의 매출인식방법인 공정률에 따라 매출을 인식하였습니다.  추정손익분석 결과 ''98년에는 655억원 매출에 27억원의 순이익이 발생될 것으로 추정되며, ''99년도에는 47억원, 2001년에는 59억원, 2002년에는 43억원의 당기순이익을 전망하고 있습니다.  위원님께서 요청하신 예정 대차대조표, 이익잉여처분계산서 등은 양해해 주신다면 서면으로 답변을 제출하면서 설명을 올리도록 하겠습니다.  중 장기계획상의 재원조달방안이 면밀히 검토되어야 하는데 이에 대한 저의 의견을 물어 주셨습니다.  사업비 분석에는 자체조달, 타인조달, 기채 등 다양한 조달방법에 대하여 저희가 강구를 해야 되겠습니다마는 공사는 단일목적의 사업이 아닌 다양한 사업으로 제조업과는 달리 원가분석과 사업분석 자체가 무한한 견주 속에서 이루어지고 있습니다.  따라서 축령산 사업의 사업분석을 위해서 많은 전문가 그룹이 상당기간 이에 필요한 사업비 조달방안을 검토해야 되는데 지금 외국인투자유치와 관련해 가지고 사업을 확정짓는 데 굉장히 어려운 점이 있습니다.  그래서 금회 중 장기계획은 공사의 위상과 사업 다각화의 방향에 대해서 다양한 의견을 수렴하는 과정으로 이해해 주시고 참고로 중 장기계획상의 투자수익은 사업규모의 10% 정도로 추정된 것으로 이는 수탁사업, 재원절감 및 공정관리하에 이루어질 개념적 수치이익임을 이해해 주시기 바라면서 초기공사는 각종 정책사업과 경기도의 인프라 구축사업의 참여를 통해서 다양한 사업수익 발굴기법을 통해 예산절감 차원의 사업시행 방안들이 검토돼야 될 것으로 사료됩니다.  이는 전액 재원조달의 개념이 아니며 적정수익 발굴을 통해 재원의 적절한 분담체제 하에서 가능할 것으로 판단됩니다.  저희가 각종 사업을 추진함에 있어서는 원칙적으로 자체자금을 확보해서 하는 것이 가장 바람직한 방법이겠습니다마는 자금이 부족할 때는 외자라든가 내자를 동원해서라도 하는 방법이 있겠고 이것이 어려울 때에는 외국인투자유치를 해서 저희가 계획하고 있는 사업들을 시정하는 방법들이 강구되겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 경기지방공사가 수행하고 있는 각종 사업의 수익성이 크게 떨어진다고 질의해 주셨습니다.  이는 우리 공사에서 시행하고 있는 사업과 시행하고자 하는 사업의 수익성을 개략적으로 분석할 때는 용지매수비 조성사업비 등 직접사업비 외에 본사 직원의 인건비 등 업무관리비와 연이율 12%를 계상한 금융비용을 전부 감안해 산출한 것입니다.  따라서 위원님께서 적시한 수치는 추정치입니다마는 순이익을 표시한 수치로 이해해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  마지막으로 대부임해관광지 광역상수도 분담금 예산확보 현황과 ''99년도 지방공사 예산의 포함편성 여부를 물어 주셨습니다.  본 사업은 당초 공영개발사업단에서 추진하던 사업으로 아직 사업시행자는 결정이 되어 있지 않습니다.  그러나 동 지역의 개발을 위해서 경기도가 ''98년 2월에 상수도 비용을 부담하기로 결정한 바가 있습니다.  그래서 ''98년도 부담금은 도 본청 추경예산에 반영하고 ''99년부터 2001년 부담금은 도에서 연차별로 확보할 계획으로 있었습니다마는 ''98년도 부담금은 아직 확보가 되어 있지 않은 걸로 알고 있습니다.  그래서 도 재정기획관실에서는 ''98년도, ''99년도의 예산을 ''99년도 예산편성에 포함하려고 추진하고 있는 걸로 제가 파악하고 있습니다.  따라서 안산시의 처리방법은 도 재정기획관실 예산확보 후 지방공사에 넘겨주어 안산시에 납부하는 방법으로 검토가 되고 있음을 말씀드립니다.  그리고 ''99년도 지방공사 예산에는 상수도 분담금이 아직 반영돼 있지 않은데 그 사유는 저희 공사가 아직 사업시행자로 지정돼 있지 않기 때문임을 설명드립니다.
</p>
<p style="padding-left:1.2em">  다음은 연동현 위원님께서 질의하신 사항에 대해서 답변을 드리도록 하겠습니다.  위원님께서는 업무근린시설 공사와 권선3지구 택지개발사업에 대한 설계변경내용에 대해서 질의를 해 주셨습니다.  먼저 업무근린시설의 설계변경은 공사기간 중 총 3회에 걸쳐 실시하였습니다.  1차 설계변경은 공영개발사업단에서 실시한 것으로 ''96년 12월부터 ''97년 9월까지의 물가상승률 5.32%가 반영된 것이고 2차 설계변경은 우리 공사가 인수하면서 설계도에는 있으나 내역서에 누락된 부분과 과다계상되고 수입대리석 등 불합리한 자재가 설계에 반영돼 있어 이를 조정함에 따른 설계변경이고 제3차 설계변경은 ''97년 9월부터 ''97년 12월까지의 물가상승률 6.13%를 반영하고 총 9억 7,000만원이 증액됐으나 공사비는 총 소요예산 108억원 범위내에서 조정하였습니다.  또한 권선3지구 택지개발사업에 대한 설계변경은 총 4회에 걸쳐 실시한 것으로 제1, 2차는 공영개발사업단에서 물가변동과 일부 수량이 변경됨에 따른 설계변경이었고 3, 4차 변경은 우리 공사가 인수하여 물가상승 변동률 8.4%와 부대공사인 조경부분 추가발주에 따른 것으로 당초보다 약 40억원이 증액된 것으로 보이나 설계변경으로 인하여 약 2억원의 예산절감효과를 거양했음을 부연해서 설명을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 이남형 위원님께서 질의하신 사항에 대해서 답변을 드리도록 하겠습니다.  먼저 외국인들은 안정성, 수익성 등은 따지는데, 예를 들어 축령산 외자유치 대안은 무엇인가에 대해서 답변 올리도록 하겠습니다.  축령산 외자유치대안은 1차 생태계조사와 경제 타당성조사를 한 후 적정한 투자수익률, 회수기간을 보장해 줄 수 있도록 외자유치촉진법상의 인센티브에 추가하여 별도의 프로그램을 발굴코자 하고 있으며 외국인투자자가 유치되고 난 이후에 그들의 필요에 부합되는 사업계획에 의거 기본계획 기본설계를 하여 인 허가를 추진하여 리스크를 줄이고 사업의 안정성을 유지코자 합니다.
</p>
<p style="padding-left:1.2em">  다음 저희 사업계획에 포함돼 있는 용지매출액 622억원에 대한 내역에 대해서 질의해 주셨습니다.  이는 권선3지구 공동주택지 잔금 70억원, 권선3지구 공동주택지 미수금 75억원, 어연 한산 8만평 매각에 따른 180억원, 기흥 구갈 선수공급 50% 가능 예약금 85억원, 광명공단 아파트형공장 매각대금 42억원, 권선1지구 구청사 부지 18억원, 권선1지구 파출소부지 2억원, 권선3지구 단독주택지, 주유소, 학교용지 등 150억원에 대한 내용이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 무역매출액 56억원에 대한 내역에 대해서 물으셨습니다.  이는 이진용 위원님께서 같은 내용으로 질의되어 함께 설명을 드리도록 하겠습니다.  무역매출액은 수출 250만불, 수입 150만불, 합 400만불, 한화로 56억원 상당이 되겠습니다.  환율 1,400원을 가정할 때 약 56억원이 되는 것입니다.  부문별 내용을 보면 수출의 경우는 전기 전자제품 30억 8,000만원, 금속제품 1억 4,000만원, 섬유제품 1억 4,000만원, 농산품 1억 4,000만원이 되겠고 수입의 경우는 섬유원료 11억 6,000만원, 전기 전자제품 4억 2,000만원, 비절금속 5억 2,000만원이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  또한 남한강개발사업 추진에 있어서 골재매장량 추정사업비와 생산 판매 등의 사업추진 방법에 대해서 물으셨습니다.  골재매장량은 경기도로부터 인수받은 관련자료에 의하면 약 3,800만㎥로 매각대금을 1,300억원으로 추정한 것입니다.  본 사업은 하천법에 의해서 매각대금을 전액 동 하천유지 관리시설에 투입하도록 조건이 되어 있습니다.  골재생산 판매 등은 하천정비 시설공사에 골재채취 판매를 포함하는 방법 등 여러 가지 방법이 있겠으나 현재 설계용역을 인수받아 ''99년 8월까지 완료할 예정으로 있습니다.  그 동안 저희가 직접 시행할 것인가 또는 위탁시행하는가에 대해서는 면밀히 검토해서 향후 문제점이 최소화되도록 사업을 추진코자 합니다. 
</p>
<p style="padding-left:1.2em">  다음은 어연 한산 외국인 전용지구내 외국업체 유치 활성화를 위한 인센티브와 사전 내부인프라 구축계획에 대해서 질의해 주셨습니다.  본 단지의 외국인 전용지구내 입주 외국업체에 대하여는 현재 외국인투자유치촉진법 등 관계법령 제정으로 법인세, 소득세 면제, 자본재에 대한 특별소비세 감면 등 세제혜택 등 제도적인 장치가 마련돼 있으며 저희 공사와 도 관련부서에서는 외국인업체 유치에 따른 각종 편의사항 등 원-스톱 서비스체제를 구축해서 적극 지원하고자 하고 있습니다.  내부인프라 구축에 대해서는 용수, 통신 및 전력은 ''99년 상반기에 공급할 예정이며 폐수 및 폐기물 처리시설 등에 대해서도 입주시기에 맞춰 처리될 수 있도록 제반 대책을 강구하고 있습니다.  현재 외국인 전용지구는 일본의 모 기업체에서 투자하려고 상담이 이루어지고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 무역부문의 내부인프라와 외부인프라에 대한 준비가 잘 되어 있는지에 대해서 질의해 주셨습니다.  먼저 내부인프라 구축을 위해서 저희 공사는 무역업 등록을 하고 무역협회에 가입해서 수출입 자격을 구비해 놨으며 이런 수출입을 하기 위해서 한국수출보험공사에 가입이 되어 있습니다.  또한 정보지원체제 구축을 위해서 농산물유통공사, 중기재단, 코트라 등과 긴밀한 협의를 해 가면서 정보체제를 구축해 가고 있고 수출입 지원을 위해서 무역거래 한도를 상업은행에 약 200만불 한도액을  수출해 놓고 업무를 추진하고 있습니다.  또 염려해 주신 업체의 데이터 작성에 대해서는 저희가 경기도에서 선정한 500개 우량 중소기업체에 대해서 방문실사작업을 통해서 계속 업체의 실태를 파악하면서 그 업체의 실태를 파일화시켜서 저희가 수출지원하는 데 계속 도와주고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 외부인프라 구축에 대해서 질의하실신사항은 저희가 해외전시박람회를 그동안 네 차례에 걸쳐서 참여를 했습니다.  지난 8월에 시카고 하드웨어박람회, 9월에는 중동 통상촉진단에 또 자그레브 추계박람회에도 참가했으며, 지난 11월에는 미국 콘덱스에 참가를 했습니다.  또한 사이버 트레이딩에 의한 바이어를 발굴하고 있으며 이의 일환으로 미국 인터넷 쇼핑몰인 아이몰에 인삼제품 등을 등록해서 수출 중에 있고 케이티넷트에 약 97건의 오퍼를 등록해서 인터넷에 의한 바이어를 발굴 중에 있습니다.  지난 11월 2일 외자유치전문직 3명을 채용하면서 외부인프라 구축에 더욱 박차를 가하고 있습니다.  다음 회기 때에는 좋은 결과를 보고할 수 있도록 저희도 노력을 하고 있습니다.  
</p>
<p style="padding-left:1.2em">  그리고 이진용 위원님께서 질의해 주신 사항에 대한 답변을 올리도록 하겠습니다.  먼저 대규모 사업의 자금을 취급하는데 직원채용시 보증인을 세우지 않는 이유가 무엇인가에 대해서 질의를 해주셨습니다.  공사 회계규정제11조에 보면 회계관계직원의 재정보증조항이 있는데 회계관계직원은 재정보증없이는 그 직무를 담당하게 할 수가 없도록 돼 있습니다.  그래서 회계관계직원은 본 규정에 의해서 재정보증보험에 가입이 되어 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 음식물쓰레기 산업화 재활용 기술개발사업에 대해서 설명드리도록 하겠습니다.  통상 음식물쓰레기에 대해서 처리하는 방법은 사료화, 퇴비화, 연료화 여러 가지 방법들이 있습니다.  저희가 지금 추진하고자 하는 사업내용은 러시아공화국에서 개발한 최첨단기술을 국내 실정에 맞도록 기술개발을 해서 음식물쓰레기를 좀더 깨끗하고 또 산업화시킬 수 있는 방법을 개발하고자 하는 내용입니다.  국내 중소업체가 러시아로부터 기술이전협약을 맺어가지고 저희에게 합동개발하자는 제의가 있어서 여기에 참여를 하게 되었습니다.  상세한 내용은 별도로 설명을 올리도록 하겠습니다.  
</p>
<p style="padding-left:1.2em">  마지막으로 폐수 하수처리시설사업 등 유망 환경관련사업에 대한 지방공사의 참여계획에 대해서 질의를 해주셨습니다.  저희가 택지개발사업, 관광지개발 또 산업단지 개발사업을 하고 있습니다마는 사실 환경사업에 대해서는 국민 전체적인 공감대가 모두 이런 사업들을 공공투자부문에서 참여해 주기를 바라고 있는 사항이 되겠습니다.  본 사항에 대해서는 저희 공사의 현행 규정상 참여를 하는 데는 제한적인 요건이 있습니다.  그래서 경기도와 업무협의를 해서 향후 정관개정 등을 통해서 공사의 참여방안을 강구해서 경기도민들이 환경의 질을 높이는 데 적극 기여하도록 노력을 하겠습니다.  이상 답변을 마치겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 다음은 보충질의에 들어가도록 하겠습니다.  보충질의는 일문일답으로 진행하도록 하겠습니다.  보충질의하실 위원 계시면 거수로 신청하여 주시기 바랍니다.  정운천 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 정운천 위원 </b> 자세한 설명에 감사드리겠습니다.  대부분의 질의에 대해서 만족할만한 답변을 들었고 또 자세한 내용은 서면답변을 해주시겠다니까 그 부분에 대해서는 보충질의를 생략하고요, 단지 한 가지 재원조달에 대해서 약간의 이견이 있기 때문에 보충질의를 드리겠습니다.  아까 말씀하실 때 자금흐름에 인플로우와 아웃플로우가 있는데 거기서 자금 지출부분의 금융비용을 10% 계산하였기 때문에 전체개념을 순이익으로 보아주시면 좋겠다 이렇게 말씀하셨습니다.  그말은 맞는 것 같습니다.  왜냐하면 순이익으로 보는데는 아까 제가 말씀드린 현재가치할인에 의한 순이익이 아니고 매년도에 그 순이익을 어느 미래의 일정시점에서 총 현금의 지출과 수입으로 나눠서 수입에서 지출을 뺀 부분이 순이익이기 때문에 기업회계기준상의 순이익개념으로 보면 그 부분은 맞는 말씀인 것 같습니다. 
</p>
<p style="padding-left:1.2em">  그렇지만 그것은 기업회계기준에서의 평가방법이고요.  제가 여쭤본 것은 투자분석을 할 당시에 과연 이것이 투자의 가치가 있느냐를 평가하기 위해서는 미래의 현금흐름을 현재가치로 환원을 해서 평가해야 된다고 생각합니다.  어차피 금융비용도 하나의 지출이기 때문에 그것은 현재가치를 반영한다고 볼 수 없고요.  단지 현금이 지출되는 부분 또 수입이 되는 부분을 현재가치로 할인해서 두 개 중에 수익이 크면 이익이고 지출이 크면 손실이겠죠.  그렇게 판단을 해야 되지 않겠는가 이렇게 전제를 하고요.  자금조달에 대해서 아까 말씀하신 ''98년도, ''99년도 부분에 대해서는 일부 사장님의 말씀에 대해서 동의합니다.  그렇지만 제출해 주신 행정감사자료를 가지고 쭉 분석을 해보니까 ''98년도에는 현금 순지출이 185억원이 됩니다.  이것은 ''97년도에 가지고 있었던 272억원의 현금을 반영하지 않았기 때문에, 물론 아까 사장님께서 말씀하신 바와 같이 ''98년도는 큰 무리없이 넘어갈 수가 있습니다.  그중에 참으로 처분하기 어려운 토지도 처분하시고 그리고 각종 공사에 적극적으로 참여하셔서 수익을 올리신 결과 158억원의 현금지출이 있다하더라도 전년도에 이월된 부분 272억원이 있기 때문에 ''98년도는 큰 문제가 없습니다.  그러나 ''99년도부터는 제가 분석한 바로는 현금의 순지출이 405억원, 2000년에는 341억원, 2001년에는 659억원, 2002년에는 230억원 그리고 2003년에는 무려 3,078억원의 순지출이 생깁니다.  그 이유는 대부관광단지하고 축령산리조트가 2003년 이후에는 아마 엄청난 자금이 들어가기 때문에 이런 결과가 나옵니다.  
</p>
<p style="padding-left:1.2em">  따라서 이런 계획된 모든 사업을 성공적으로 하기 위해서는 올해와 내년은 어느 정도 넘긴다 하더라도 2000년부터 벌어지는 자금의 부담을 과연 아까 말씀드린 현금유출과 유입의 구조로서는 상당히 부담스럽다는 말씀을 드릴 수밖에 없구요.  과연 경기지방공사가 원래의 취지와 목적을 달성하기 위해서는 여기에 필요한 가용재원을 충분히 조달해야만 큰 무리없이 넘어갈 수 있다.  특히 아까도 말씀드렸습니다마는 수익성 뿐만 아니라 공익성을 유지하기 위해서라도 경기지방공사는 순탄하게 발전해 나가야 된다.  그러기 위해서는 재원을 확보하지 않으면 상당히 어려운 지경에 이르게 됐다는 그런 우려감이 생기고요.  그것은 여러 가지 분석자료에서도 나오고 있습니다. 
</p>
<p style="padding-left:1.2em">  그래서 제가 건의하건데 경기도가 100% 출자한 법인이기 때문에 어차피 경기도가 현재로서는 전액 출자의 부담을 안게 됐습니다.  그렇지만 경기도도 현재 각종 자금압박으로 인해서 세수부족과 여러 가지 원인으로 인해서 가용재원이 부족한 상태이기 때문에 현재 부족한 3,000억원 내지는 5,000억원, 앞으로 사업이 더 확장되면 커질 수 있기 때문에 그렇습니다.  재원을 모두 부담하기에는 상당히 역부족이다 이런 생각이 들고요.  그래서 여러 가지 방법을 강구해야 되는데 제가 생각하기로는 복합적인 방법이 필요하지 않겠는가.  말하자면 경기도에서 필요재원 중에 일부를 순차적으로 부담하고 그 재원을 부담함으로 인한 전체의 자금흐름이 여유를 조금 보임으로 인해서 보다 유리한 조건으로 기채를 할 수 있고 또 지분을 유치할 수도 있는 상황이 되기 때문에 여러 가지 다양한 방법으로 파이낸싱할 수 있는 기회가 있다.  
</p>
<p style="padding-left:1.2em">  그래서 이 부분은 아무래도 전문가들하고 의논해야 되지 않겠는가 이런 생각이 듭니다.  따라서 파이낸싱기관 말하자면 증권회사나 전문투자자문기관하고 충분히 숙의해서 대주주 그러니까 전액투자주주입니다.  경기도의 담당자하고 고위 관계공무원하고 충분한 합의를 해서 해결하지 않으면 안되겠다.  이게 가장 선결문제가 아닌가 생각이 듭니다.  그래서 여기에도 지금 경기도 관계공무원이 나오셨으니까 충분히 위원들의 입장을 전달해 주시고요.  이 부분에 대해서 여러 위원님들은 어떤 생각을 가지고 계신지 모르겠지만 저로서는 재원조달문제에 대해서는 좀더 적극적으로 임해야 되지 않나 생각을 합니다.  
</p>
<p style="padding-left:1.2em">  그래서 여기서 재원이 결정돼야만 재무구조가 확정되고 재무구조가 확정돼야만 거기에 소요되는 금융비용에 따라서 자본비용이 계산됩니다.  자본비용이 계산돼야만 아까 말씀드린 캐쉬플로우(cash flow)를 현재가치로 할인하는 할인율을 결정할 수 있기 때문에 먼저 가용재원을 확보하는 방안에 대해서 먼저 충분한 검토가 있어야 되지 않겠는가.  그리고 거기에는 분명히 경기도가 파이낸싱기관에 참여해서 같이 적극적인 방향으로 검토를 해야 되지 않겠나 이런 것을 건의합니다.  그 부분에 대해서 사장님께서 의견을 제시해 주시고요.  
</p>
<p style="padding-left:1.2em">  그리고 아까 쭉 프리젠테이션도 하고 그랬습니다마는 그것으로 인해서 그러한 사업들이 가능해지기 때문에 보다 적극적으로 고려를 하셔야 되지 않겠나 이런 생각이 듭니다.  그리고 더불어서 지금 수익성 부분에 대해서는 아까처럼 현재가치할인을 하면 어떤 경우는 마이너스가 나오는 경우도 생길 것입니다.  그래서 공익성도 중요하지만 지출부분에서의 구조를 다시 한 번 검토하셔서 줄일 수 있는 부분은 줄여서 사업계획을 검토하시는 것이 투자유치에는 유리하지 않겠나 이런 생각이 듭니다.  이상입니다.
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 고맙습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 정운천 위원님 수고하셨습니다.  답변해 주시죠.
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 저희 공사를 걱정해 주시는 데 대해서 정말 책임지고 있는 사장으로서 뭐라고 답변을 드려야 될지 참 어려운 점이 있습니다.  제가 이런 사업을 함에 있어서 사업비 조달이 가장 큰 관건으로 고민을 하고 있습니다.  
</p>
<p style="padding-left:1.2em">  경기도에서 전액 출자해 가지고 공사를 운영하고 있습니다마는 경기도의 자금여건이 넉넉치를 못해서 충분한 출자를 못해주고 있는 걸로 알고 있습니다.  지금 자금지원을 받는 것이 지역개발기금으로 연간 200억원을 받고 있는데 그것을 출자금하고 합해서 공사를 운영하는 어려움이 있습니다.  이 점을 정 위원님께서 먼저 걱정을 해주셔서 앞으로 걱정을 드리지 않도록 노력을 해야 되겠습니다마는 저희가 목표하고 있는 사업을 적정하게 이끌려면 재원조달방안은 첫째, 현재 금융시장이 불안하기 때문에 차입을 한다는 것은 참 어려운 점이 있습니다.
</p>
<p style="padding-left:1.2em">  그래서 대안으로 외국인 투자자를 유치해서 도민들의 복지사업, 공공사업을 추진하고 있다는 것을 이해해 주시기 바라고 그 다음에 구갈3지구의 예를 들었습니다마는 사실 저희가 자금능력이 부족하기 때문에 민간개발자들과 합동개발하는 방법까지 추진을 하고 있습니다.  그래서 정 위원님께서 지적해 주신 사항을 도에 건의해서 앞으로 이 사업을 하는 데 어려움이 없도록 추진해 나가겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 경영의 합리화에 대해서 염려를 해주셨는데 이 또한 저희 자체인력으로 경영진단을 하는 데 어려움이 있으면 외부전문가를 초청해서라도 경영진단을 다시 하면서 경영을 합리화할 수 있도록 추진하겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 또 질의하실 위원님 안 계십니까?  이진용 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이진용 위원 </b> 제가 한 가지만 여쭙겠습니다.  직원 채용시 보증인을 세우는 것이 어떤가 하는 말씀을 드렸는데 지금 내부적으로는 보직이 순환되고 있죠?  
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이진용 위원 </b> 회계관련 공무원이 따로 정해진 것은…….   
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 사실상 보직변경할 수가 있습니다. 
</p>
<p><b>○ 이진용 위원 </b> 그러니까 결국 전체적으로 보증인이 필요한 것이죠.  
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 그런데 회계직으로 보직을 할 때에 보증보험을 드는 것으로 대처를 합니다, 전 직원이 다 드는 것은 아니고요.  
</p>
<p><b>○ 이진용 위원 </b> 그래서 보증인 문제는 여기 열심히 일하는 직원 여러분들한테는 다소 드리기 어려운 질의인데 왜 이런 말씀을 드리냐면 사실 지방공사에서 계속 꾸준히 열심히 일하실 분들한테는 필요가 없지만 하다가 혹시라도 한두 분의 그런 잘못된 부분이 발생된다면 여기서 열심히 근무하시는 다수의 분들한테 피해가 돌아가기 때문에 우려가 돼서 드리는 말씀이고요.  이렇게 순환보직제로 되고 있다면 보증인제도를 도입하는 것이 어떤가 그런 생각이 듭니다.  이상입니다.  
</p>
<p><b>○ 경기지방공사사장 민병균 </b> 저희 상위법하고 내규를 다시 한 번 검토해서 위원님이 염려하시는 사항에 걱정이 되지 않도록 조치를 취하겠습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 이진용 위원님 되셨습니까? 
</p>
<p><b>○ 이진용 위원 </b> 네, 됐습니다. 
</p>
<p><b>○ 위원장 고수복 </b> 또 질의하실 위원님, 없습니까?  그러면 경기지방공사 민병균 사장과 직원 여러분께 경기도의회 기획위원장으로서 한 가지 당부의 말씀을 드리겠습니다.  경기지방공사의 설립목적이 지역의 균형개발과 도민의 복지증진에 기여한다고 돼 있습니다.  또 자본금 1,244억원 전액이 도가 출자한 것으로 돼 있습니다.  새로 설립한 공기업이니만큼 기대하는 바 또한 크다 하겠습니다.  기업이란 이윤추구가 목적이라고 하겠습니다마는 공기업이니만큼 합목적성을 가지고 수혜자도 공감이 갈 수 있도록 기업경영을 해주셨으면 하는 바람입니다.  더 이상 질의하실 위원이 안 계시면 이상으로 경기지방공사에 대한 질의 답변을 모두 마치도록 하겠습니다.
</p>
<p>서면답변서(윤동욱ㆍ이진용ㆍ유영록 의원)
</p>
<p style="padding-left:1.2em">  위원 여러분께서 장시간동안 열의를 갖고 감사에 임해 주신 데 대해 감사의 말씀을 드립니다.  그리고 민병균 사장을 비롯한 지방공사 관계자 여러분께서도 행정사무감사를 위해 자료준비와 위원님들의 질의에 성실히 답변해 주신 데 대해 감사를 드립니다.  오늘 여러 위원님들께서 감사시에 지적해 주신 사항은 도민의 뜻이니만큼 이를 겸허하게 받아들여서 경기지방공사 업무수행에 반영하도록 최선의 노력을 다해 주시기 바랍니다.  여러분 수고 많이 하셨습니다.
</p>
<p style="padding-left:1.2em">  그러면 이것으로 지방공사에 대한 1998년도 행정사무감사를 종료할 것을 선언합니다. 
</p>
<p class=''ar''>(18시48분 감사종료)
</p>
<p><hr /></p>
