<p><p class=''em15''>생활환경연구부장 이정임산업경제연구부장 이상훈도시 지역계획연구부장 이외희</p>
<p><p class=''em15''>교통정책연구부장 조응래국제경제연구부장 이기영수질환경연구소장 성현찬</p>
<p><p class=''em05''>· 경기지방공사</p>
